--
-- Name: accept_membership_invitation(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.accept_membership_invitation(p_invitation_id uuid, p_request_id text) RETURNS TABLE(result_code text, invitation_id uuid, organization_id uuid, project_id uuid, organization_role app.organization_role, project_role app.project_role, accepted_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_user uuid := app.current_user_id();
  invitation app.membership_invitations%ROWTYPE;
  v_now timestamptz := clock_timestamp();
BEGIN
  SELECT candidate.* INTO invitation
  FROM app.membership_invitations candidate
  WHERE candidate.id = p_invitation_id
    AND candidate.invitee_user_id = v_user
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_found', NULL::uuid, NULL::uuid, NULL::uuid,
      NULL::app.organization_role, NULL::app.project_role, NULL::timestamptz;
    RETURN;
  END IF;

  IF invitation.state = 'accepted' THEN
    RETURN QUERY SELECT 'already_accepted', invitation.id, invitation.organization_id,
      invitation.project_id, invitation.organization_role, invitation.project_role,
      invitation.accepted_at;
    RETURN;
  END IF;

  IF invitation.state = 'revoked' THEN
    RETURN QUERY SELECT 'revoked', invitation.id, invitation.organization_id,
      invitation.project_id, invitation.organization_role, invitation.project_role,
      NULL::timestamptz;
    RETURN;
  END IF;

  IF invitation.expires_at <= v_now THEN
    RETURN QUERY SELECT 'expired', invitation.id, invitation.organization_id,
      invitation.project_id, invitation.organization_role, invitation.project_role,
      NULL::timestamptz;
    RETURN;
  END IF;

  INSERT INTO app.organization_memberships
    (organization_id, user_id, role, invited_by)
  VALUES (
    invitation.organization_id,
    v_user,
    invitation.organization_role,
    invitation.invited_by
  )
  ON CONFLICT ON CONSTRAINT organization_memberships_pkey DO NOTHING;

  IF invitation.project_id IS NOT NULL THEN
    INSERT INTO app.project_memberships
      (organization_id, project_id, user_id, role)
    VALUES (
      invitation.organization_id,
      invitation.project_id,
      v_user,
      invitation.project_role
    )
    ON CONFLICT ON CONSTRAINT project_memberships_pkey DO NOTHING;
  END IF;

  UPDATE app.membership_invitations
  SET state = 'accepted', accepted_at = v_now
  WHERE id = invitation.id;

  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type, resource_type,
     resource_id, request_id, payload)
  VALUES (
    invitation.organization_id,
    v_user,
    invitation.project_id,
    'membership.invitation.accepted',
    'membership_invitation',
    invitation.id,
    p_request_id,
    jsonb_build_object(
      'organization_role', invitation.organization_role,
      'project_role', invitation.project_role
    )
  );

  RETURN QUERY SELECT 'accepted', invitation.id, invitation.organization_id,
    invitation.project_id, invitation.organization_role, invitation.project_role, v_now;
END;
$$;


--
-- Name: FUNCTION accept_membership_invitation(p_invitation_id uuid, p_request_id text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.accept_membership_invitation(p_invitation_id uuid, p_request_id text) IS 'Single-use, authenticated-user-bound invitation acceptance with atomic memberships and activity.';


--
-- Name: acquire_kml_network_link_request_slot(uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.acquire_kml_network_link_request_slot(p_request_id uuid, p_project_id uuid, p_user_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_organization_id uuid := app.current_organization_id();
  v_now timestamptz := clock_timestamp();
  v_count integer;
BEGIN
  IF p_request_id IS NULL OR p_project_id IS NULL OR p_user_id IS NULL
    OR p_user_id IS DISTINCT FROM app.current_user_id()
  THEN
    RAISE EXCEPTION 'invalid KML NetworkLink quota request';
  END IF;

  PERFORM 1
  FROM app.projects project
  WHERE project.organization_id = v_organization_id
    AND project.id = p_project_id
    AND project.status = 'active'
    AND app.effective_project_role(project.id, p_user_id) IS NOT NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'KML NetworkLink project access denied'
      USING ERRCODE = '42501';
  END IF;

  -- One fixed row serializes the small global quota decision across Lambda
  -- runtimes. The external fetch happens after this transaction commits.
  PERFORM singleton
  FROM app.kml_network_link_quota_lock
  WHERE singleton
  FOR UPDATE;

  DELETE FROM app.kml_network_link_request_slots slot
  WHERE slot.started_at <= v_now - interval '1 minute'
    AND (slot.released_at IS NOT NULL OR slot.lease_expires_at <= v_now);

  SELECT count(*) INTO v_count
  FROM app.kml_network_link_request_slots slot
  WHERE slot.organization_id = v_organization_id
    AND slot.project_id = p_project_id
    AND slot.user_id = p_user_id
    AND slot.started_at > v_now - interval '1 minute';
  IF v_count >= 60 THEN
    RETURN 'rate_limited';
  END IF;

  SELECT count(*) INTO v_count
  FROM app.kml_network_link_request_slots slot
  WHERE slot.organization_id = v_organization_id
    AND slot.project_id = p_project_id
    AND slot.user_id = p_user_id
    AND slot.released_at IS NULL
    AND slot.lease_expires_at > v_now;
  IF v_count >= 4 THEN
    RETURN 'busy';
  END IF;

  SELECT count(*) INTO v_count
  FROM app.kml_network_link_request_slots slot
  WHERE slot.released_at IS NULL
    AND slot.lease_expires_at > v_now;
  IF v_count >= 8 THEN
    RETURN 'busy';
  END IF;

  INSERT INTO app.kml_network_link_request_slots
    (request_id, organization_id, project_id, user_id, started_at, lease_expires_at)
  VALUES
    (p_request_id, v_organization_id, p_project_id, p_user_id,
     v_now, v_now + interval '15 seconds');
  RETURN 'acquired';
END;
$$;


--
-- Name: FUNCTION acquire_kml_network_link_request_slot(p_request_id uuid, p_project_id uuid, p_user_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.acquire_kml_network_link_request_slot(p_request_id uuid, p_project_id uuid, p_user_id uuid) IS 'Atomically applies fixed 60/minute, four-per-user/project, and eight-platform-wide NetworkLink limits.';


--
-- Name: add_map_render_job_anchor(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.add_map_render_job_anchor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO app.map_render_job_layers
    (organization_id, render_job_id, position, resource_id, profile_id, profile_version_id)
  VALUES
    (NEW.organization_id, NEW.id, 1, NEW.resource_id, NEW.profile_id,
     NEW.profile_version_id);
  RETURN NEW;
END;
$$;


--
-- Name: add_spatial_service_default_style(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.add_spatial_service_default_style() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  style_record record;
BEGIN
  SELECT style.id, style.slug, style_version.id AS style_version_id,
         style_version.version_number AS style_version_number,
         profile.id AS profile_id, profile_version.id AS profile_version_id,
         profile_version.version_number AS profile_version_number
  INTO style_record
  FROM app.map_render_profiles profile
  JOIN app.map_render_profile_versions profile_version
    ON profile_version.organization_id = profile.organization_id
   AND profile_version.profile_id = profile.id
   AND profile_version.id = profile.current_version_id
  JOIN app.governed_resource_styles style
    ON style.organization_id = profile_version.organization_id
   AND style.id = profile_version.style_id
  JOIN app.governed_resource_style_versions style_version
    ON style_version.organization_id = style.organization_id
   AND style_version.style_id = style.id
   AND style_version.id = profile_version.style_version_id
  WHERE profile.organization_id = NEW.organization_id
    AND profile.id = NEW.default_profile_id
    AND profile_version.id = NEW.sealed_profile_version_id;
  IF style_record.id IS NULL THEN
    RAISE EXCEPTION 'spatial service collection default style seal is missing';
  END IF;
  INSERT INTO app.spatial_service_collection_styles
    (organization_id, project_id, service_id, collection_id, style_name,
     style_id, sealed_style_version_id, sealed_style_version_number,
     render_profile_id, sealed_profile_version_id,
     sealed_profile_version_number, is_default, created_by, created_at)
  VALUES (NEW.organization_id, NEW.project_id, NEW.service_id, NEW.id,
          style_record.slug, style_record.id, style_record.style_version_id,
          style_record.style_version_number, style_record.profile_id,
          style_record.profile_version_id, style_record.profile_version_number,
          true, NEW.created_by, NEW.created_at);
  RETURN NEW;
END;
$$;


--
-- Name: attach_spatial_tile_seed_plan_render(uuid, uuid, integer, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.attach_spatial_tile_seed_plan_render(requested_organization_id uuid, requested_plan_id uuid, requested_position integer, requested_render_job_id uuid, requested_by uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
DECLARE
  plan app.spatial_tile_seed_plans%ROWTYPE;
  item app.spatial_tile_seed_plan_items%ROWTYPE;
  binding app.spatial_service_collections%ROWTYPE;
  job app.map_render_jobs%ROWTYPE;
  tile_span double precision;
  expected_bbox double precision[];
  coordinate integer;
  next_state text;
BEGIN
  IF requested_organization_id <> app.current_organization_id()
    OR requested_by <> app.current_user_id()
  THEN
    RAISE EXCEPTION 'spatial tile seed plan actor mismatch';
  END IF;
  SELECT * INTO plan FROM app.spatial_tile_seed_plans candidate
  WHERE candidate.organization_id = requested_organization_id
    AND candidate.id = requested_plan_id FOR UPDATE;
  SELECT * INTO item FROM app.spatial_tile_seed_plan_items candidate
  WHERE candidate.organization_id = requested_organization_id
    AND candidate.plan_id = requested_plan_id
    AND candidate.position = requested_position FOR UPDATE;
  IF plan.id IS NULL OR item.id IS NULL OR plan.state <> 'preparing' THEN
    RAISE EXCEPTION 'spatial tile seed plan is not preparing';
  END IF;
  IF item.render_job_id IS NOT NULL THEN
    IF item.render_job_id <> requested_render_job_id THEN
      RAISE EXCEPTION 'spatial tile seed plan render collision';
    END IF;
    RETURN false;
  END IF;
  SELECT * INTO binding FROM app.spatial_service_collections candidate
  WHERE candidate.organization_id = requested_organization_id
    AND candidate.id = plan.binding_id AND candidate.withdrawn_at IS NULL;
  SELECT * INTO job FROM app.map_render_jobs candidate
  WHERE candidate.organization_id = requested_organization_id
    AND candidate.project_id = plan.project_id
    AND candidate.id = requested_render_job_id;
  IF binding.id IS NULL OR job.id IS NULL
    OR job.resource_id <> binding.resource_id
    OR job.profile_id <> binding.default_profile_id
    OR job.profile_version_id <> binding.sealed_profile_version_id
    OR job.crs <> 'EPSG:3857' OR job.width <> 256 OR job.height <> 256
    OR job.format::text <> 'png' OR job.background_color IS NOT NULL
    OR NOT job.transparent
  THEN
    RAISE EXCEPTION 'spatial tile seed plan render seal mismatch';
  END IF;
  tile_span := 40075016.685578488 / (1::bigint << item.tile_matrix);
  expected_bbox := ARRAY[
    -20037508.342789244 + item.tile_col * tile_span,
    20037508.342789244 - (item.tile_row + 1) * tile_span,
    -20037508.342789244 + (item.tile_col + 1) * tile_span,
    20037508.342789244 - item.tile_row * tile_span
  ];
  FOR coordinate IN 0..3 LOOP
    IF abs((job.bbox ->> coordinate)::double precision - expected_bbox[coordinate + 1]) > 0.000001 THEN
      RAISE EXCEPTION 'spatial tile seed plan render bbox mismatch';
    END IF;
  END LOOP;
  next_state := CASE job.state::text
    WHEN 'queued' THEN 'queued'
    WHEN 'running' THEN 'running'
    WHEN 'completed' THEN 'completed'
    ELSE 'failed'
  END;
  UPDATE app.spatial_tile_seed_plan_items
  SET render_job_id = requested_render_job_id,
      state = next_state,
      error_code = CASE WHEN next_state = 'failed' THEN 'render_failed' END,
      started_at = CASE WHEN next_state IN ('running', 'completed', 'failed')
                        THEN COALESCE(job.started_at, clock_timestamp()) END,
      finished_at = CASE WHEN next_state IN ('completed', 'failed')
                         THEN COALESCE(job.finished_at, clock_timestamp()) END
  WHERE organization_id = requested_organization_id AND id = item.id;
  RETURN true;
END;
$$;


--
-- Name: basemap_connection_origins_are_safe(text[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.basemap_connection_origins_are_safe(p_origins text[]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'app'
    AS $_$
DECLARE
  v_origin text;
  v_port text;
  v_seen text[] := ARRAY[]::text[];
BEGIN
  IF cardinality(p_origins) < 1 OR cardinality(p_origins) > 16 THEN
    RETURN false;
  END IF;
  FOREACH v_origin IN ARRAY p_origins LOOP
    IF v_origin IS NULL
       OR octet_length(v_origin) > 512
       OR v_origin <> btrim(v_origin)
       OR v_origin !~ '^https?://[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?(?::[0-9]{1,5})?$'
       OR v_origin ~ '[[:cntrl:][:space:]]'
       OR lower(v_origin) = ANY(v_seen) THEN
      RETURN false;
    END IF;
    v_port := substring(v_origin FROM ':([0-9]{1,5})$');
    IF v_port IS NOT NULL AND (v_port::integer < 1 OR v_port::integer > 65535) THEN
      RETURN false;
    END IF;
    v_seen := array_append(v_seen, lower(v_origin));
  END LOOP;
  RETURN true;
END;
$_$;


--
-- Name: begin_spatial_tile_seed_plan_dispatch(uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.begin_spatial_tile_seed_plan_dispatch(requested_organization_id uuid, requested_plan_id uuid, requested_by uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
DECLARE
  plan app.spatial_tile_seed_plans%ROWTYPE;
  cache_head app.spatial_tile_caches%ROWTYPE;
  next_state text;
BEGIN
  IF requested_organization_id <> app.current_organization_id()
    OR requested_by <> app.current_user_id()
  THEN
    RAISE EXCEPTION 'spatial tile seed plan actor mismatch';
  END IF;
  SELECT * INTO plan FROM app.spatial_tile_seed_plans candidate
  WHERE candidate.organization_id = requested_organization_id
    AND candidate.id = requested_plan_id FOR UPDATE;
  IF plan.id IS NULL THEN RAISE EXCEPTION 'spatial tile seed plan not found'; END IF;
  IF plan.state <> 'preparing' THEN RETURN plan.state; END IF;
  IF EXISTS (
    SELECT 1 FROM app.spatial_tile_seed_plan_items item
    WHERE item.organization_id = requested_organization_id
      AND item.plan_id = requested_plan_id AND item.state = 'pending'
  ) THEN
    RAISE EXCEPTION 'spatial tile seed plan preparation is incomplete';
  END IF;
  IF EXISTS (
    SELECT 1 FROM app.spatial_tile_seed_plan_items item
    WHERE item.organization_id = requested_organization_id
      AND item.plan_id = requested_plan_id AND item.state = 'failed'
  ) THEN
    UPDATE app.spatial_tile_seed_plans
    SET state = 'failed', error_code = 'render_failed', finished_at = clock_timestamp()
    WHERE organization_id = requested_organization_id AND id = requested_plan_id;
    RETURN 'failed';
  END IF;
  SELECT * INTO cache_head FROM app.spatial_tile_caches cache
  WHERE cache.organization_id = requested_organization_id
    AND cache.id = plan.cache_id FOR UPDATE;
  IF cache_head.current_version_id <> plan.cache_version_id
    OR cache_head.current_version_number <> plan.cache_version_number
  THEN
    UPDATE app.spatial_tile_seed_plans
    SET state = 'failed', error_code = 'cache_version_changed', finished_at = clock_timestamp()
    WHERE organization_id = requested_organization_id AND id = requested_plan_id;
    RETURN 'failed';
  END IF;
  INSERT INTO app.spatial_tile_cache_entries
    (organization_id, project_id, cache_id, cache_version_id,
     cache_version_number, tile_matrix, tile_row, tile_col,
     render_job_id, seeded_by)
  SELECT item.organization_id, plan.project_id, plan.cache_id, plan.cache_version_id,
         plan.cache_version_number, item.tile_matrix, item.tile_row, item.tile_col,
         item.render_job_id, requested_by
  FROM app.spatial_tile_seed_plan_items item
  WHERE item.organization_id = requested_organization_id
    AND item.plan_id = requested_plan_id
  ORDER BY item.position;
  next_state := CASE
    WHEN EXISTS (SELECT 1 FROM app.spatial_tile_seed_plan_items item
                 WHERE item.organization_id = requested_organization_id
                   AND item.plan_id = requested_plan_id AND item.state = 'running')
      THEN 'running'
    WHEN EXISTS (SELECT 1 FROM app.spatial_tile_seed_plan_items item
                 WHERE item.organization_id = requested_organization_id
                   AND item.plan_id = requested_plan_id AND item.state = 'queued')
      THEN 'queued'
    ELSE 'completed'
  END;
  UPDATE app.spatial_tile_seed_plans
  SET state = next_state, dispatch_started_at = clock_timestamp(),
      started_at = CASE WHEN next_state IN ('running', 'completed')
                        THEN clock_timestamp() END,
      finished_at = CASE WHEN next_state = 'completed' THEN clock_timestamp() END
  WHERE organization_id = requested_organization_id AND id = requested_plan_id;
  RETURN next_state;
END;
$$;


--
-- Name: bump_user_dataset_connection_target_revision(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bump_user_dataset_connection_target_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'app'
    AS $$
BEGIN
  IF ROW(
    NEW.provider, NEW.bucket_name, NEW.region_name, NEW.object_prefix,
    NEW.credential_mode, NEW.role_arn
  ) IS DISTINCT FROM ROW(
    OLD.provider, OLD.bucket_name, OLD.region_name, OLD.object_prefix,
    OLD.credential_mode, OLD.role_arn
  ) THEN
    NEW.target_revision := OLD.target_revision + 1;
    IF NEW.status <> 'disabled' THEN
      NEW.status := 'unverified';
    END IF;
    NEW.last_verified_at := NULL;
    NEW.sanitized_error_code := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: cancel_external_connection_verification(uuid, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.cancel_external_connection_verification(p_organization_id uuid, p_project_id uuid, p_connection_id uuid, p_verification_id uuid, p_actor_user_id uuid, p_request_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_cancelled boolean;
BEGIN
  IF p_organization_id IS DISTINCT FROM app.current_organization_id()
    OR p_actor_user_id IS DISTINCT FROM app.current_user_id()
    OR p_request_id IS NULL OR p_request_id <> btrim(p_request_id)
    OR char_length(p_request_id) NOT BETWEEN 1 AND 200
    OR NOT EXISTS (
      SELECT 1
      FROM app.project_memberships membership
      JOIN app.projects project
        ON project.organization_id = membership.organization_id
       AND project.id = membership.project_id
      WHERE membership.organization_id = p_organization_id
        AND membership.project_id = p_project_id
        AND membership.user_id = p_actor_user_id
        AND membership.role = 'owner'
        AND project.status = 'active'
    )
  THEN
    RAISE EXCEPTION 'connection verification cancellation requires project owner';
  END IF;

  UPDATE app.external_connection_verifications verification
  SET state = 'cancelled', worker_token = NULL, lease_expires_at = NULL,
      sanitized_error_code = 'verification_cancelled',
      duration_ms = CASE
        WHEN verification.started_at IS NULL THEN NULL
        ELSE LEAST(20000, GREATEST(0,
          floor(extract(epoch FROM (clock_timestamp() - verification.started_at)) * 1000)::integer))
      END,
      finished_at = clock_timestamp()
  WHERE verification.organization_id = p_organization_id
    AND verification.project_id = p_project_id
    AND verification.connection_id = p_connection_id
    AND verification.id = p_verification_id
    AND verification.state IN ('queued', 'running')
  RETURNING true INTO v_cancelled;

  IF COALESCE(v_cancelled, false) THEN
    INSERT INTO app.activity_events
      (organization_id, actor_user_id, project_id, event_type,
       resource_type, resource_id, request_id, payload)
    VALUES
      (p_organization_id, p_actor_user_id, p_project_id,
       'connection.verification.cancelled', 'connection', p_connection_id,
       p_request_id, jsonb_build_object('verification_id', p_verification_id));
  END IF;
  RETURN COALESCE(v_cancelled, false);
END;
$$;


--
-- Name: cancel_external_source_discovery(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.cancel_external_source_discovery(p_organization_id uuid, p_project_id uuid, p_job_id uuid, p_actor_user_id uuid, p_request_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
BEGIN
  IF p_organization_id <> app.current_organization_id()
    OR p_actor_user_id <> app.current_user_id()
    OR COALESCE(
      app.effective_project_role(p_project_id, p_actor_user_id)::text,
      ''
    ) NOT IN ('owner', 'editor')
    OR p_request_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
  THEN RETURN false; END IF;
  UPDATE app.external_source_discovery_jobs
  SET state = 'cancelled', error_code = 'cancelled_by_user',
      finished_at = clock_timestamp()
  WHERE organization_id = p_organization_id AND project_id = p_project_id
    AND id = p_job_id AND state = 'queued';
  IF NOT FOUND THEN RETURN false; END IF;
  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (p_organization_id, p_actor_user_id, p_project_id,
     'dataset.source.discovery.cancelled', 'project', p_project_id,
     p_request_id, jsonb_build_object('discovery_job_id', p_job_id));
  RETURN true;
END;
$_$;


