    (p_organization_id, p_actor_user_id, p_project_id,
     'spatial_service.coverage.derivative.cancelled', 'spatial_service',
     p_service_id, p_request_id,
     jsonb_build_object(
       'derivative_job_id', p_job_id, 'coverage_id', p_coverage_id
     ));
  RETURN true;
END;
$_$;


--
-- Name: FUNCTION cancel_spatial_coverage_derivative(p_organization_id uuid, p_project_id uuid, p_service_id uuid, p_coverage_id uuid, p_job_id uuid, p_actor_user_id uuid, p_request_id text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.cancel_spatial_coverage_derivative(p_organization_id uuid, p_project_id uuid, p_service_id uuid, p_coverage_id uuid, p_job_id uuid, p_actor_user_id uuid, p_request_id text) IS 'One-way audited cancellation for queued work only; running or terminal work is immutable.';


--
-- Name: cancel_spatial_tile_seed_plan(uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.cancel_spatial_tile_seed_plan(requested_organization_id uuid, requested_plan_id uuid, requested_by uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
DECLARE
  plan_state text;
BEGIN
  IF requested_organization_id <> app.current_organization_id()
    OR requested_by <> app.current_user_id()
  THEN
    RAISE EXCEPTION 'spatial tile seed plan actor mismatch';
  END IF;
  SELECT state INTO plan_state FROM app.spatial_tile_seed_plans
  WHERE organization_id = requested_organization_id AND id = requested_plan_id
  FOR UPDATE;
  IF plan_state IS NULL THEN RAISE EXCEPTION 'spatial tile seed plan not found'; END IF;
  IF plan_state = 'cancelled' THEN RETURN false; END IF;
  IF plan_state <> 'preparing' OR EXISTS (
    SELECT 1 FROM app.spatial_tile_seed_plan_items item
    JOIN app.map_render_jobs job
      ON job.organization_id = item.organization_id AND job.id = item.render_job_id
    WHERE item.organization_id = requested_organization_id
      AND item.plan_id = requested_plan_id
      AND job.state::text <> 'queued'
  ) THEN
    RAISE EXCEPTION 'spatial tile seed plan crossed the dispatch boundary';
  END IF;
  UPDATE app.spatial_tile_seed_plan_items
  SET state = 'cancelled', finished_at = clock_timestamp()
  WHERE organization_id = requested_organization_id AND plan_id = requested_plan_id;
  UPDATE app.spatial_tile_seed_plans
  SET state = 'cancelled', finished_at = clock_timestamp()
  WHERE organization_id = requested_organization_id AND id = requested_plan_id;
  RETURN true;
END;
$$;


--
-- Name: claim_dataset_ingest(text, text, text, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_dataset_ingest(p_bucket text, p_object_key text, p_s3_version_id text, p_worker_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, job_id uuid, organization_id uuid, project_id uuid, dataset_id uuid, dataset_version_id uuid, original_object_id uuid, original_filename text, dataset_format text, content_type text, size_bytes bigint, checksum_sha256 text, attempt_count integer, output_prefix text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job record;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_bucket IS NULL OR p_bucket = '' OR char_length(p_bucket) > 63
    OR p_object_key IS NULL OR p_object_key = '' OR char_length(p_object_key) > 1024
    OR p_s3_version_id IS NULL OR p_s3_version_id IN ('', 'null')
    OR char_length(p_s3_version_id) > 1024
    OR p_worker_token IS NULL
    OR p_lease_seconds NOT BETWEEN 60 AND 3600
  THEN
    RAISE EXCEPTION 'invalid ingestion claim';
  END IF;

  SELECT
    job.id,
    job.organization_id,
    job.project_id,
    job.dataset_id,
    job.dataset_version_id,
    job.state::text AS job_state,
    job.attempt_count,
    job.lease_expires_at,
    version.original_object_id,
    object.content_type,
    object.size_bytes,
    object.checksum_sha256,
    dataset.format::text AS dataset_format,
    intent.original_filename
  INTO v_job
  FROM app.data_objects object
  JOIN app.dataset_versions version
    ON version.organization_id = object.organization_id
   AND version.dataset_id = object.dataset_id
   AND version.original_object_id = object.id
  JOIN app.datasets dataset
    ON dataset.organization_id = version.organization_id
   AND dataset.id = version.dataset_id
  JOIN app.processing_jobs job
    ON job.organization_id = version.organization_id
   AND job.dataset_id = version.dataset_id
   AND job.dataset_version_id = version.id
   AND job.job_type = 'dataset.ingest'
  JOIN app.upload_intents intent
    ON intent.organization_id = object.organization_id
   AND intent.completed_object_id = object.id
   AND intent.state = 'completed'
  WHERE object.bucket = p_bucket
    AND object.object_key = p_object_key
    AND object.s3_version_id = p_s3_version_id
    AND object.role = 'original'
  FOR UPDATE OF job;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      'not_ready', NULL::uuid, NULL::uuid, NULL::uuid, NULL::uuid, NULL::uuid,
      NULL::uuid, NULL::text, NULL::text, NULL::text, NULL::bigint, NULL::text,
      NULL::integer, NULL::text;
    RETURN;
  END IF;

  IF v_job.job_state IN ('completed', 'failed', 'cancelled') THEN
    RETURN QUERY SELECT
      'already_' || v_job.job_state,
      v_job.id,
      v_job.organization_id,
      v_job.project_id,
      v_job.dataset_id,
      v_job.dataset_version_id,
      v_job.original_object_id,
      v_job.original_filename,
      v_job.dataset_format,
      v_job.content_type,
      v_job.size_bytes,
      v_job.checksum_sha256,
      v_job.attempt_count,
      format(
        'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/',
        v_job.organization_id,
        v_job.project_id,
        v_job.dataset_id,
        v_job.dataset_version_id
      );
    RETURN;
  END IF;

  IF v_job.job_state = 'running' AND v_job.lease_expires_at > v_now THEN
    RETURN QUERY SELECT
      'busy',
      v_job.id,
      v_job.organization_id,
      v_job.project_id,
      v_job.dataset_id,
      v_job.dataset_version_id,
      v_job.original_object_id,
      v_job.original_filename,
      v_job.dataset_format,
      v_job.content_type,
      v_job.size_bytes,
      v_job.checksum_sha256,
      v_job.attempt_count,
      format(
        'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/',
        v_job.organization_id,
        v_job.project_id,
        v_job.dataset_id,
        v_job.dataset_version_id
      );
    RETURN;
  END IF;

  UPDATE app.processing_jobs AS target
  SET state = 'running',
      worker_token = p_worker_token,
      lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
      last_heartbeat_at = v_now,
      attempt_count = target.attempt_count + 1,
      started_at = COALESCE(target.started_at, v_now),
      finished_at = NULL,
      error_code = NULL
  WHERE target.id = v_job.id;

  RETURN QUERY SELECT
    'claimed',
    v_job.id,
    v_job.organization_id,
    v_job.project_id,
    v_job.dataset_id,
    v_job.dataset_version_id,
    v_job.original_object_id,
    v_job.original_filename,
    v_job.dataset_format,
    v_job.content_type,
    v_job.size_bytes,
    v_job.checksum_sha256,
    v_job.attempt_count + 1,
    format(
      'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/',
      v_job.organization_id,
      v_job.project_id,
      v_job.dataset_id,
      v_job.dataset_version_id
    );
END;
$$;


--
-- Name: FUNCTION claim_dataset_ingest(p_bucket text, p_object_key text, p_s3_version_id text, p_worker_token uuid, p_lease_seconds integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.claim_dataset_ingest(p_bucket text, p_object_key text, p_s3_version_id text, p_worker_token uuid, p_lease_seconds integer) IS 'Claim only a completed exact S3 object/version job; duplicate and early events return safe status.';


--
-- Name: claim_external_connection_verification(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_external_connection_verification(p_verification_id uuid, p_worker_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, verification_id uuid, organization_id uuid, project_id uuid, connection_id uuid, connection_revision_number bigint, provider text, endpoint_host text, endpoint_port integer, database_name text, tls_mode text, network_mode text, secret_arn text, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job app.external_connection_verifications%ROWTYPE;
  v_connection app.external_connections%ROWTYPE;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_verification_id IS NULL OR p_worker_token IS NULL
    OR p_lease_seconds NOT BETWEEN 10 AND 60
  THEN
    RAISE EXCEPTION 'invalid connection verification claim';
  END IF;

  SELECT verification.* INTO v_job
  FROM app.external_connection_verifications verification
  WHERE verification.id = p_verification_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_found', p_verification_id,
      NULL::uuid, NULL::uuid, NULL::uuid, NULL::bigint,
      NULL::text, NULL::text, NULL::integer, NULL::text,
      NULL::text, NULL::text, NULL::text, NULL::integer;
    RETURN;
  END IF;
  IF v_job.state IN ('succeeded', 'failed', 'cancelled') THEN
    RETURN QUERY SELECT 'already_' || v_job.state::text, v_job.id,
      v_job.organization_id, v_job.project_id, v_job.connection_id,
      v_job.connection_revision_number, NULL::text, NULL::text, NULL::integer,
      NULL::text, NULL::text, NULL::text, NULL::text, v_job.attempt_count;
    RETURN;
  END IF;
  IF v_job.state = 'running' AND v_job.lease_expires_at > v_now THEN
    RETURN QUERY SELECT 'busy', v_job.id,
      v_job.organization_id, v_job.project_id, v_job.connection_id,
      v_job.connection_revision_number, NULL::text, NULL::text, NULL::integer,
      NULL::text, NULL::text, NULL::text, NULL::text, v_job.attempt_count;
    RETURN;
  END IF;
  IF v_job.attempt_count >= 3 THEN
    UPDATE app.external_connection_verifications
    SET state = 'failed', worker_token = NULL, lease_expires_at = NULL,
        sanitized_error_code = 'verification_failed', duration_ms = 0,
        started_at = COALESCE(started_at, v_now), finished_at = v_now
    WHERE id = v_job.id;
    UPDATE app.external_connections AS connection
    SET status = 'degraded', sanitized_error_code = 'verification_failed',
        updated_at = v_now
    WHERE connection.organization_id = v_job.organization_id
      AND connection.project_id = v_job.project_id
      AND connection.id = v_job.connection_id
      AND connection.current_revision_number = v_job.connection_revision_number
      AND connection.status NOT IN ('disabled', 'revoked');
    INSERT INTO app.activity_events
      (organization_id, actor_user_id, project_id, event_type,
       resource_type, resource_id, request_id, payload)
    VALUES
      (v_job.organization_id, v_job.requested_by, v_job.project_id,
       'connection.verification.failed', 'connection', v_job.connection_id,
       'connector:' || v_job.id::text,
       jsonb_build_object(
         'verification_id', v_job.id,
         'connection_revision_number', v_job.connection_revision_number,
         'attempt_count', v_job.attempt_count,
         'duration_ms', 0,
         'network_reachable', false,
         'tls_verified', false,
         'credentials_verified', false,
         'postgis_verified', false,
         'error_code', 'verification_failed'
       ));
    RETURN QUERY SELECT 'attempts_exhausted', v_job.id,
      v_job.organization_id, v_job.project_id, v_job.connection_id,
      v_job.connection_revision_number, NULL::text, NULL::text, NULL::integer,
      NULL::text, NULL::text, NULL::text, NULL::text, v_job.attempt_count;
    RETURN;
  END IF;

  SELECT connection.* INTO v_connection
  FROM app.external_connections connection
  WHERE connection.organization_id = v_job.organization_id
    AND connection.project_id = v_job.project_id
    AND connection.id = v_job.connection_id
    AND connection.current_revision_number = v_job.connection_revision_number
    AND connection.status NOT IN ('disabled', 'revoked');
  IF NOT FOUND THEN
    UPDATE app.external_connection_verifications
    SET state = 'cancelled', worker_token = NULL, lease_expires_at = NULL,
        sanitized_error_code = 'verification_cancelled', finished_at = v_now
    WHERE id = v_job.id;
    RETURN QUERY SELECT 'not_verifiable', v_job.id,
      v_job.organization_id, v_job.project_id, v_job.connection_id,
      v_job.connection_revision_number, NULL::text, NULL::text, NULL::integer,
      NULL::text, NULL::text, NULL::text, NULL::text, v_job.attempt_count;
    RETURN;
  END IF;

  UPDATE app.external_connection_verifications AS verification
  SET state = 'running', worker_token = p_worker_token,
      lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
      attempt_count = verification.attempt_count + 1,
      started_at = COALESCE(verification.started_at, v_now)
  WHERE verification.id = v_job.id;

  RETURN QUERY SELECT 'claimed', v_job.id,
    v_job.organization_id, v_job.project_id, v_job.connection_id,
    v_job.connection_revision_number, v_connection.provider::text,
    v_connection.endpoint_host, v_connection.endpoint_port,
    v_connection.database_name, v_connection.tls_mode::text,
    v_connection.network_mode::text, v_connection.secret_arn,
    v_job.attempt_count + 1;
END;
$$;


--
-- Name: FUNCTION claim_external_connection_verification(p_verification_id uuid, p_worker_token uuid, p_lease_seconds integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.claim_external_connection_verification(p_verification_id uuid, p_worker_token uuid, p_lease_seconds integer) IS 'Connector-only leased claim; the secret ARN is disclosed only to the isolated verifier principal.';


--
-- Name: claim_external_source_discovery(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_external_source_discovery(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, job_id uuid, source_type text, discovery_kind text, service_url text, collection_ref text, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job app.external_source_discovery_jobs%ROWTYPE;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_job_id IS NULL OR p_worker_token IS NULL
    OR p_lease_seconds NOT BETWEEN 30 AND 120
  THEN RAISE EXCEPTION 'invalid source discovery claim'; END IF;
  SELECT * INTO v_job FROM app.external_source_discovery_jobs
  WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_ready', p_job_id, NULL::text, NULL::text,
      NULL::text, NULL::text, NULL::integer;
    RETURN;
  END IF;
  IF v_job.state::text IN ('completed', 'failed', 'cancelled') THEN
    claim_status := 'already_' || v_job.state::text;
  ELSIF v_job.state = 'running' AND v_job.lease_expires_at > v_now THEN
    claim_status := 'busy';
  ELSIF v_job.attempt_count >= 3 THEN
    UPDATE app.external_source_discovery_jobs
    SET state = 'failed', error_code = 'retry_exhausted', worker_token = NULL,
        lease_expires_at = NULL, finished_at = v_now
    WHERE id = v_job.id;
    claim_status := 'already_failed';
  ELSE
    UPDATE app.external_source_discovery_jobs target
    SET state = 'running', worker_token = p_worker_token,
        lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
        attempt_count = target.attempt_count + 1,
        started_at = COALESCE(target.started_at, v_now),
        finished_at = NULL, error_code = NULL
    WHERE target.id = v_job.id
    RETURNING target.attempt_count INTO v_job.attempt_count;
    claim_status := 'claimed';
  END IF;
  RETURN QUERY SELECT claim_status, v_job.id, v_job.source_type,
    v_job.discovery_kind, v_job.service_url, v_job.collection_ref,
    v_job.attempt_count;
END;
$$;


--
-- Name: FUNCTION claim_external_source_discovery(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.claim_external_source_discovery(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer) IS 'Claims one id-only bounded discovery job without granting the archiver table access.';


--
-- Name: claim_external_source_snapshot(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_external_source_snapshot(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, job_id uuid, organization_id uuid, project_id uuid, source_dataset_id uuid, source_revision_number bigint, source_type text, source_url text, source_configuration jsonb, copy_method text, capture_scope jsonb, maximum_requests integer, maximum_output_bytes bigint, output_format text, output_content_type text, attribution text, destination_dataset_id uuid, destination_bucket text, output_object_key text, request_checksum_sha256 text, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job record;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_job_id IS NULL OR p_worker_token IS NULL
    OR p_lease_seconds NOT BETWEEN 60 AND 900
  THEN RAISE EXCEPTION 'invalid source snapshot claim'; END IF;
  SELECT job.*, estimate.copy_method, estimate.capture_scope,
         estimate.maximum_requests, estimate.maximum_output_bytes,
         estimate.output_format::text AS output_format,
         estimate.output_content_type,
         source.source_type::text AS source_type,
         revision.source_url, revision.configuration
  INTO v_job
  FROM app.external_source_snapshot_jobs job
  JOIN app.external_source_copy_estimates estimate
    ON estimate.organization_id = job.organization_id
   AND estimate.id = job.estimate_id
  JOIN app.external_sources source
    ON source.organization_id = job.organization_id
   AND source.dataset_id = job.source_dataset_id
  JOIN app.external_source_revisions revision
    ON revision.organization_id = job.organization_id
   AND revision.dataset_id = job.source_dataset_id
   AND revision.version_number = job.source_revision_number
  WHERE job.id = p_job_id
  FOR UPDATE OF job;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_ready', p_job_id, NULL::uuid, NULL::uuid,
      NULL::uuid, NULL::bigint, NULL::text, NULL::text, NULL::jsonb,
      NULL::text, NULL::jsonb, NULL::integer, NULL::bigint, NULL::text,
      NULL::text, NULL::text, NULL::uuid, NULL::text, NULL::text, NULL::text,
      NULL::integer;
    RETURN;
  END IF;
  IF v_job.state::text IN ('completed', 'failed', 'cancelled') THEN
    claim_status := 'already_' || v_job.state::text;
  ELSIF v_job.state = 'running' AND v_job.lease_expires_at > v_now THEN
    claim_status := 'busy';
  ELSIF v_job.attempt_count >= 3 THEN
    UPDATE app.external_source_snapshot_jobs
    SET state = 'failed', error_code = 'retry_exhausted',
        worker_token = NULL, lease_expires_at = NULL,
        last_heartbeat_at = NULL, finished_at = v_now
    WHERE id = v_job.id;
    claim_status := 'already_failed';
  ELSE
    UPDATE app.external_source_snapshot_jobs target
    SET state = 'running', worker_token = p_worker_token,
        lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
        last_heartbeat_at = v_now,
        attempt_count = target.attempt_count + 1,
        started_at = COALESCE(target.started_at, v_now),
        finished_at = NULL, error_code = NULL
    WHERE target.id = v_job.id
    RETURNING target.attempt_count INTO v_job.attempt_count;
    claim_status := 'claimed';
  END IF;
  RETURN QUERY SELECT claim_status, v_job.id, v_job.organization_id,
    v_job.project_id, v_job.source_dataset_id, v_job.source_revision_number,
    v_job.source_type, v_job.source_url, v_job.configuration,
    v_job.copy_method, v_job.capture_scope, v_job.maximum_requests,
    v_job.maximum_output_bytes, v_job.output_format, v_job.output_content_type,
    v_job.attribution,
    v_job.destination_dataset_id, v_job.destination_bucket,
    format(
      'organizations/%s/projects/%s/datasets/%s/uploads/%s/original/%s',
      v_job.organization_id, v_job.project_id, v_job.destination_dataset_id, v_job.id,
      CASE v_job.output_format
        WHEN 'png' THEN 'snapshot.png'
        WHEN 'geojson' THEN 'snapshot.geojson'
        ELSE 'source.pmtiles'
      END
    ), v_job.request_checksum_sha256, v_job.attempt_count;
END;
$$;


--
-- Name: claim_geonode_harvest(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_geonode_harvest(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, job_id uuid, display_name text, remote_url text, source_fingerprint_sha256 text, source_version text, scheduling_enabled boolean, refresh_interval_minutes integer, maximum_resources integer, credential_mode text, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE v_job app.geonode_harvest_jobs%ROWTYPE;
  v_source app.geonode_federation_sources%ROWTYPE; v_now timestamptz := clock_timestamp();
BEGIN
  IF p_job_id IS NULL OR p_worker_token IS NULL OR p_lease_seconds NOT BETWEEN 30 AND 120
  THEN RAISE EXCEPTION 'invalid GeoNode harvest claim'; END IF;
  SELECT * INTO v_job FROM app.geonode_harvest_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_ready', p_job_id, NULL::text, NULL::text,
      NULL::text, NULL::text, NULL::boolean, NULL::integer, NULL::integer,
      NULL::text, NULL::integer; RETURN;
  END IF;
  SELECT * INTO v_source FROM app.geonode_federation_sources
  WHERE organization_id = v_job.organization_id AND id = v_job.source_id;
  IF v_job.state::text IN ('completed', 'failed', 'cancelled') THEN
    claim_status := 'already_' || v_job.state::text;
  ELSIF v_job.state = 'running' AND v_job.lease_expires_at > v_now THEN
    claim_status := 'busy';
  ELSIF v_source.status <> 'active'
    OR v_source.configuration_checksum_sha256
      <> v_job.source_configuration_checksum_sha256 THEN
    UPDATE app.geonode_harvest_jobs SET state = 'failed',
      error_code = 'geonode_harvest_upstream_unavailable', worker_token = NULL,
      lease_expires_at = NULL, finished_at = v_now WHERE id = v_job.id;
    claim_status := 'already_failed';
  ELSIF v_job.attempt_count >= 3 THEN
    UPDATE app.geonode_harvest_jobs SET state = 'failed', error_code = 'retry_exhausted',
      worker_token = NULL, lease_expires_at = NULL, finished_at = v_now
    WHERE id = v_job.id; claim_status := 'already_failed';
  ELSE
    UPDATE app.geonode_harvest_jobs target SET state = 'running',
      worker_token = p_worker_token,
      lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
      attempt_count = target.attempt_count + 1,
      started_at = COALESCE(target.started_at, v_now), error_code = NULL
    WHERE target.id = v_job.id RETURNING target.attempt_count INTO v_job.attempt_count;
    claim_status := 'claimed';
  END IF;
  RETURN QUERY SELECT claim_status, v_job.id,
    CASE WHEN claim_status = 'claimed' THEN v_source.display_name ELSE NULL END,
    CASE WHEN claim_status = 'claimed' THEN v_source.remote_url ELSE NULL END,
    CASE WHEN claim_status = 'claimed' THEN v_source.source_fingerprint_sha256 ELSE NULL END,
    CASE WHEN claim_status = 'claimed' THEN v_source.source_version ELSE NULL END,
    CASE WHEN claim_status = 'claimed' THEN v_source.scheduling_enabled ELSE NULL END,
    CASE WHEN claim_status = 'claimed' THEN v_source.refresh_interval_minutes ELSE NULL END,
    CASE WHEN claim_status = 'claimed' THEN v_source.maximum_resources ELSE NULL END,
    CASE WHEN claim_status = 'claimed' THEN v_source.credential_mode ELSE NULL END,
    CASE WHEN claim_status = 'claimed' THEN v_job.attempt_count ELSE NULL END;
END;
$$;


--
-- Name: claim_map_render(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_map_render(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, render_job_id uuid, organization_id uuid, project_id uuid, resource_id uuid, dataset_id uuid, dataset_version_id uuid, source_object_id uuid, source_bucket text, source_object_key text, source_s3_version_id text, source_etag text, source_content_type text, source_size_bytes bigint, source_checksum_sha256 text, profile_id uuid, profile_version_id uuid, style_id uuid, style_version_id uuid, configuration jsonb, configuration_checksum_sha256 text, request_bbox jsonb, request_crs text, request_width integer, request_height integer, request_format text, request_checksum_sha256 text, attempt_count integer, output_prefix text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job record;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_job_id IS NULL OR p_worker_token IS NULL
    OR p_lease_seconds NOT BETWEEN 60 AND 3600
  THEN
    RAISE EXCEPTION 'invalid map render claim';
  END IF;

  SELECT
    job.*,
    profile.dataset_id AS snapshot_dataset_id,
    profile.dataset_version_id AS snapshot_dataset_version_id,
    profile.style_id AS snapshot_style_id,
    profile.style_version_id AS snapshot_style_version_id,
    profile.configuration,
    profile.checksum_sha256 AS configuration_checksum,
    source.id AS source_id,
    source.bucket AS source_bucket,
    source.object_key AS source_key,
    source.s3_version_id AS source_version,
    source.etag AS source_etag,
    source.content_type AS source_type,
    source.size_bytes AS source_size,
    source.checksum_sha256 AS source_checksum
  INTO v_job
  FROM app.map_render_jobs job
  JOIN app.map_render_profile_versions profile
    ON profile.organization_id = job.organization_id
   AND profile.profile_id = job.profile_id
   AND profile.id = job.profile_version_id
  LEFT JOIN app.dataset_version_objects link
    ON link.organization_id = profile.organization_id
   AND link.dataset_id = profile.dataset_id
   AND link.dataset_version_id = profile.dataset_version_id
  LEFT JOIN app.data_objects source
    ON source.organization_id = link.organization_id
   AND source.id = link.data_object_id
   AND source.role = 'derived'
   AND source.content_type = 'application/geo+json'
   AND source.object_key LIKE '%/derivatives/preview/preview.geojson'
  WHERE job.id = p_job_id
  ORDER BY source.id
  LIMIT 1
  FOR UPDATE OF job;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      'not_ready', p_job_id, NULL::uuid, NULL::uuid, NULL::uuid,
      NULL::uuid, NULL::uuid, NULL::uuid, NULL::text, NULL::text,
      NULL::text, NULL::text, NULL::text, NULL::bigint, NULL::text,
      NULL::uuid, NULL::uuid, NULL::uuid, NULL::uuid, NULL::jsonb,
      NULL::text, NULL::jsonb, NULL::text, NULL::integer, NULL::integer,
      NULL::text, NULL::text, NULL::integer, NULL::text;
    RETURN;
  END IF;

  IF v_job.state::text IN ('completed', 'failed', 'cancelled') THEN
    RETURN QUERY SELECT
      'already_' || v_job.state::text,
      v_job.id, v_job.organization_id, v_job.project_id, v_job.resource_id,
      v_job.snapshot_dataset_id, v_job.snapshot_dataset_version_id,
      v_job.source_id, v_job.source_bucket, v_job.source_key,
      v_job.source_version, v_job.source_etag, v_job.source_type,
      v_job.source_size, v_job.source_checksum, v_job.profile_id,
      v_job.profile_version_id, v_job.snapshot_style_id,
      v_job.snapshot_style_version_id, v_job.configuration,
      v_job.configuration_checksum, v_job.bbox, v_job.crs,
      v_job.width, v_job.height, v_job.format::text,
      v_job.request_checksum_sha256, v_job.attempt_count,
      format(
        'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/',
        v_job.organization_id, v_job.project_id, v_job.snapshot_dataset_id,
        v_job.snapshot_dataset_version_id
      );
    RETURN;
  END IF;

  IF v_job.source_id IS NULL OR v_job.source_size NOT BETWEEN 1 AND 16777216 THEN
    RETURN QUERY SELECT
      'not_ready', p_job_id, NULL::uuid, NULL::uuid, NULL::uuid,
      NULL::uuid, NULL::uuid, NULL::uuid, NULL::text, NULL::text,
      NULL::text, NULL::text, NULL::text, NULL::bigint, NULL::text,
      NULL::uuid, NULL::uuid, NULL::uuid, NULL::uuid, NULL::jsonb,
      NULL::text, NULL::jsonb, NULL::text, NULL::integer, NULL::integer,
      NULL::text, NULL::text, NULL::integer, NULL::text;
    RETURN;
  END IF;

  IF v_job.state = 'running' AND v_job.lease_expires_at > v_now THEN
    RETURN QUERY SELECT
      'busy', v_job.id, v_job.organization_id, v_job.project_id,
      v_job.resource_id, v_job.snapshot_dataset_id,
      v_job.snapshot_dataset_version_id, v_job.source_id,
      v_job.source_bucket, v_job.source_key, v_job.source_version,
      v_job.source_etag, v_job.source_type, v_job.source_size,
      v_job.source_checksum, v_job.profile_id, v_job.profile_version_id,
      v_job.snapshot_style_id, v_job.snapshot_style_version_id,
      v_job.configuration, v_job.configuration_checksum, v_job.bbox,
      v_job.crs, v_job.width, v_job.height, v_job.format::text,
      v_job.request_checksum_sha256, v_job.attempt_count,
      format(
        'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/',
        v_job.organization_id, v_job.project_id, v_job.snapshot_dataset_id,
        v_job.snapshot_dataset_version_id
      );
    RETURN;
  END IF;

  UPDATE app.map_render_jobs AS target
  SET state = 'running',
      worker_token = p_worker_token,
      lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
      last_heartbeat_at = v_now,
      attempt_count = target.attempt_count + 1,
      started_at = COALESCE(target.started_at, v_now),
      finished_at = NULL,
      error_code = NULL
  WHERE target.id = v_job.id;

  RETURN QUERY SELECT
    'claimed', v_job.id, v_job.organization_id, v_job.project_id,
    v_job.resource_id, v_job.snapshot_dataset_id,
    v_job.snapshot_dataset_version_id, v_job.source_id,
    v_job.source_bucket, v_job.source_key, v_job.source_version,
    v_job.source_etag, v_job.source_type, v_job.source_size,
    v_job.source_checksum, v_job.profile_id, v_job.profile_version_id,
    v_job.snapshot_style_id, v_job.snapshot_style_version_id,
    v_job.configuration, v_job.configuration_checksum, v_job.bbox,
    v_job.crs, v_job.width, v_job.height, v_job.format::text,
    v_job.request_checksum_sha256, v_job.attempt_count + 1,
    format(
      'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/',
      v_job.organization_id, v_job.project_id, v_job.snapshot_dataset_id,
      v_job.snapshot_dataset_version_id
    );
END;
$$;


--
-- Name: claim_observable_build(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_observable_build(p_job_id uuid, p_coordinator_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, build_job_id uuid, organization_id uuid, project_id uuid, source_project_id uuid, source_revision_id uuid, source_revision_number bigint, purpose text, request jsonb, request_checksum_sha256 text, input_manifest jsonb, input_manifest_checksum_sha256 text, output_prefix text, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app', 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job app.observable_build_jobs%ROWTYPE;
  v_revision app.observable_source_revisions%ROWTYPE;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_job_id IS NULL OR p_coordinator_token IS NULL
    OR p_lease_seconds NOT BETWEEN 30 AND 900
  THEN
    RAISE EXCEPTION 'invalid Observable build claim';
  END IF;
  SELECT * INTO v_job
  FROM app.observable_build_jobs
  WHERE id = p_job_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT
      'not_ready', p_job_id, NULL::uuid, NULL::uuid, NULL::uuid, NULL::uuid,
      NULL::bigint, NULL::text, NULL::jsonb, NULL::text, NULL::jsonb, NULL::text,
      NULL::text, NULL::integer;
    RETURN;
  END IF;
  SELECT * INTO v_revision
  FROM app.observable_source_revisions revision
  WHERE revision.organization_id = v_job.organization_id
    AND revision.source_project_id = v_job.source_project_id
    AND revision.id = v_job.source_revision_id;
  IF v_job.state IN ('succeeded', 'failed', 'cancelled') THEN
    RETURN QUERY SELECT
      'already_' || v_job.state::text, v_job.id, v_job.organization_id,
      v_job.project_id, v_job.source_project_id, v_job.source_revision_id,
      v_job.source_revision_number, v_job.purpose::text, v_job.request,
      v_job.request_checksum_sha256,
      v_revision.manifest, v_revision.manifest_checksum_sha256,
      v_job.output_prefix, v_job.attempt_count;
    RETURN;
  END IF;
  IF v_job.state = 'running' AND v_job.lease_expires_at > v_now THEN
    RETURN QUERY SELECT
      'busy', v_job.id, v_job.organization_id, v_job.project_id,
      v_job.source_project_id, v_job.source_revision_id,
      v_job.source_revision_number, v_job.purpose::text, v_job.request,
      v_job.request_checksum_sha256,
      v_revision.manifest, v_revision.manifest_checksum_sha256,
      v_job.output_prefix, v_job.attempt_count;
    RETURN;
  END IF;
  UPDATE app.observable_build_jobs
  SET state = 'running',
      coordinator_token = p_coordinator_token,
      lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
      last_heartbeat_at = v_now,
      attempt_count = v_job.attempt_count + 1,
      started_at = COALESCE(v_job.started_at, v_now),
      finished_at = NULL,
      error_code = NULL,
      updated_at = v_now
  WHERE id = v_job.id;
  RETURN QUERY SELECT
    'claimed', v_job.id, v_job.organization_id, v_job.project_id,
    v_job.source_project_id, v_job.source_revision_id,
    v_job.source_revision_number, v_job.purpose::text, v_job.request,
    v_job.request_checksum_sha256,
    v_revision.manifest, v_revision.manifest_checksum_sha256,
    v_job.output_prefix, v_job.attempt_count + 1;
END;
$$;


--
-- Name: FUNCTION claim_observable_build(p_job_id uuid, p_coordinator_token uuid, p_lease_seconds integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.claim_observable_build(p_job_id uuid, p_coordinator_token uuid, p_lease_seconds integer) IS 'Future coordinator lease boundary. It is intentionally ungranted: a coordinator may stage exact inputs, but the compiler sandbox receives no database, AWS, Cognito or connector credential.';


--
-- Name: claim_observable_build_runtime(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_observable_build_runtime(p_job_id uuid, p_coordinator_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, build_job_id uuid, organization_id uuid, project_id uuid, source_project_id uuid, source_revision_id uuid, source_revision_number bigint, purpose text, request jsonb, request_checksum_sha256 text, input_manifest jsonb, input_manifest_checksum_sha256 text, output_prefix text, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job app.observable_build_jobs%ROWTYPE;
  v_revision app.observable_source_revisions%ROWTYPE;
  v_failed boolean;
BEGIN
  IF p_job_id IS NULL OR p_coordinator_token IS NULL
    OR p_lease_seconds NOT BETWEEN 30 AND 900
  THEN
    RAISE EXCEPTION 'invalid Observable build runtime claim';
  END IF;
  SELECT * INTO v_job
  FROM app.observable_build_jobs
  WHERE id = p_job_id
  FOR UPDATE;
  IF FOUND
    AND v_job.state = 'running'
    AND v_job.lease_expires_at <= clock_timestamp()
    AND v_job.attempt_count >= 3
  THEN
    SELECT * INTO v_revision
    FROM app.observable_source_revisions revision
    WHERE revision.organization_id = v_job.organization_id
      AND revision.source_project_id = v_job.source_project_id
      AND revision.id = v_job.source_revision_id;
    v_failed := app.fail_observable_build(
      v_job.id, v_job.coordinator_token, 'build_retry_exhausted'
    );
    IF NOT v_failed THEN
      RAISE EXCEPTION 'expired Observable build lease could not be sealed';
    END IF;
    RETURN QUERY SELECT
      'already_failed', v_job.id, v_job.organization_id, v_job.project_id,
      v_job.source_project_id, v_job.source_revision_id,
      v_job.source_revision_number, v_job.purpose::text, v_job.request,
      v_job.request_checksum_sha256,
      v_revision.manifest, v_revision.manifest_checksum_sha256,
      v_job.output_prefix, v_job.attempt_count;
    RETURN;
  END IF;
  RETURN QUERY
    SELECT * FROM app.claim_observable_build(
      p_job_id, p_coordinator_token, p_lease_seconds
    );
END;
$$;


--
-- Name: FUNCTION claim_observable_build_runtime(p_job_id uuid, p_coordinator_token uuid, p_lease_seconds integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.claim_observable_build_runtime(p_job_id uuid, p_coordinator_token uuid, p_lease_seconds integer) IS 'Trusted host claim boundary. An expired third lease is sealed failed before another compiler execution can start.';


--
-- Name: claim_pmtiles_derivative(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_pmtiles_derivative(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, job_id uuid, organization_id uuid, project_id uuid, dataset_id uuid, dataset_version_id uuid, source_object_id uuid, source_bucket text, source_object_key text, source_s3_version_id text, source_etag text, source_content_type text, source_size_bytes bigint, source_checksum_sha256 text, bounds jsonb, minimum_zoom smallint, maximum_zoom smallint, source_layer text, request_checksum_sha256 text, attempt_count integer, output_object_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE v_job record; v_now timestamptz := clock_timestamp();
BEGIN
  IF p_job_id IS NULL OR p_worker_token IS NULL
    OR p_lease_seconds NOT BETWEEN 60 AND 3600
  THEN RAISE EXCEPTION 'invalid PMTiles derivative claim'; END IF;
  SELECT job.*, object.bucket, object.object_key, object.s3_version_id,
         object.etag, object.content_type, object.size_bytes,
         object.checksum_sha256
  INTO v_job
  FROM app.pmtiles_derivative_jobs job
  JOIN app.data_objects object
    ON object.organization_id = job.organization_id
   AND object.id = job.source_object_id
  WHERE job.id = p_job_id FOR UPDATE OF job;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_ready', p_job_id, NULL::uuid, NULL::uuid,
      NULL::uuid, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::text,
      NULL::text, NULL::text, NULL::bigint, NULL::text, NULL::jsonb,
      NULL::smallint, NULL::smallint, NULL::text, NULL::text, NULL::integer,
      NULL::text;
    RETURN;
  END IF;
  IF v_job.state::text IN ('completed', 'failed', 'cancelled') THEN
    claim_status := 'already_' || v_job.state::text;
  ELSIF v_job.state = 'running' AND v_job.lease_expires_at > v_now THEN
    claim_status := 'busy';
  ELSIF v_job.attempt_count >= 3 THEN
    UPDATE app.pmtiles_derivative_jobs
    SET state = 'failed', error_code = 'retry_exhausted', worker_token = NULL,
        lease_expires_at = NULL, last_heartbeat_at = NULL, finished_at = v_now
    WHERE id = v_job.id;
    claim_status := 'already_failed';
  ELSE
    UPDATE app.pmtiles_derivative_jobs target
    SET state = 'running', worker_token = p_worker_token,
        lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
        last_heartbeat_at = v_now, attempt_count = target.attempt_count + 1,
        started_at = COALESCE(target.started_at, v_now),
        finished_at = NULL, error_code = NULL
    WHERE target.id = v_job.id
    RETURNING target.attempt_count INTO v_job.attempt_count;
    claim_status := 'claimed';
  END IF;
  RETURN QUERY SELECT claim_status, v_job.id, v_job.organization_id,
    v_job.project_id, v_job.dataset_id, v_job.dataset_version_id,
    v_job.source_object_id, v_job.bucket, v_job.object_key,
    v_job.s3_version_id, v_job.etag, v_job.content_type, v_job.size_bytes,
    v_job.checksum_sha256, v_job.bounds, v_job.minimum_zoom,
    v_job.maximum_zoom, v_job.source_layer, v_job.request_checksum_sha256,
    v_job.attempt_count,
    format(
      'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/tiles/custom/%s.pmtiles',
      v_job.organization_id, v_job.project_id, v_job.dataset_id,
      v_job.dataset_version_id, v_job.id
    );
END;
$$;


--
-- Name: claim_repository_object_copy(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_repository_object_copy(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, job_id uuid, organization_id uuid, project_id uuid, source_dataset_id uuid, source_owner_user_id uuid, connection_id uuid, connection_target_revision bigint, credential_revision bigint, credential_mode text, role_arn text, secret_arn text, source_bucket text, source_region text, source_object_key text, source_version_id text, source_etag text, source_checksum_sha256 text, output_format text, output_content_type text, maximum_output_bytes bigint, destination_dataset_id uuid, destination_bucket text, output_object_key text, request_checksum_sha256 text, attribution text, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job record;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_job_id IS NULL OR p_worker_token IS NULL
    OR p_lease_seconds NOT BETWEEN 60 AND 900
  THEN RAISE EXCEPTION 'invalid repository copy claim'; END IF;
  SELECT job.*, estimate.output_format::text AS output_format,
         estimate.output_content_type, estimate.maximum_output_bytes,
         source.connection_id, source.connection_target_revision,
         source.bucket_name, source.region_name,
         source.object_prefix || source.relative_path AS source_object_key,
         source.provider_version_id, source.etag,
         source.provider_checksum_sha256, source.created_by AS source_owner_user_id,
         connection.credential_revision,
         connection.credential_mode::text AS credential_mode,
         connection.role_arn, connection.secret_arn,
         connection.status::text AS connection_status,
         connection.target_revision AS current_target_revision
  INTO v_job
  FROM app.repository_object_copy_jobs job
  JOIN app.repository_object_copy_estimates estimate
    ON estimate.organization_id = job.organization_id AND estimate.id = job.estimate_id
  JOIN app.repository_object_sources source
    ON source.organization_id = job.organization_id
   AND source.dataset_id = job.source_dataset_id
  JOIN app.user_dataset_connections connection
    ON connection.organization_id = source.organization_id
   AND connection.id = source.connection_id
   AND connection.owner_user_id = source.created_by
  WHERE job.id = p_job_id
  FOR UPDATE OF job;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_ready', p_job_id, NULL::uuid, NULL::uuid,
      NULL::uuid, NULL::uuid, NULL::uuid, NULL::bigint, NULL::bigint,
      NULL::text, NULL::text, NULL::text, NULL::text, NULL::text, NULL::text,
      NULL::text, NULL::text, NULL::text, NULL::text, NULL::text, NULL::bigint,
      NULL::uuid, NULL::text, NULL::text, NULL::text, NULL::text, NULL::integer;
    RETURN;
  END IF;
  IF v_job.state::text IN ('completed', 'failed', 'cancelled') THEN
    claim_status := 'already_' || v_job.state::text;
  ELSIF v_job.connection_status <> 'verified'
    OR v_job.current_target_revision <> v_job.connection_target_revision
    OR (v_job.credential_mode <> 'workload_identity'
      AND (v_job.credential_revision <= 0 OR v_job.secret_arn IS NULL))
  THEN
    UPDATE app.repository_object_copy_jobs
    SET state = 'failed', error_code = 'source_connection_unavailable',
        worker_token = NULL, lease_expires_at = NULL,
        last_heartbeat_at = NULL, finished_at = v_now
    WHERE id = v_job.id;
    claim_status := 'already_failed';
  ELSIF v_job.state = 'running' AND v_job.lease_expires_at > v_now THEN
    claim_status := 'busy';
  ELSIF v_job.attempt_count >= 3 THEN
    UPDATE app.repository_object_copy_jobs
    SET state = 'failed', error_code = 'retry_exhausted',
        worker_token = NULL, lease_expires_at = NULL,
        last_heartbeat_at = NULL, finished_at = v_now
    WHERE id = v_job.id;
    claim_status := 'already_failed';
  ELSE
    UPDATE app.repository_object_copy_jobs target
    SET state = 'running', worker_token = p_worker_token,
        lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
        last_heartbeat_at = v_now, attempt_count = target.attempt_count + 1,
        started_at = COALESCE(target.started_at, v_now),
        finished_at = NULL, error_code = NULL
    WHERE target.id = v_job.id
    RETURNING target.attempt_count INTO v_job.attempt_count;
    claim_status := 'claimed';
  END IF;
  IF claim_status <> 'claimed' THEN
    RETURN QUERY SELECT claim_status, v_job.id, NULL::uuid, NULL::uuid,
      NULL::uuid, NULL::uuid, NULL::uuid, NULL::bigint, NULL::bigint,
      NULL::text, NULL::text, NULL::text, NULL::text, NULL::text, NULL::text,
      NULL::text, NULL::text, NULL::text, NULL::text, NULL::text, NULL::bigint,
      NULL::uuid, NULL::text, NULL::text, NULL::text, NULL::text, NULL::integer;
    RETURN;
  END IF;
  RETURN QUERY SELECT claim_status, v_job.id, v_job.organization_id,
    v_job.project_id, v_job.source_dataset_id, v_job.source_owner_user_id,
    v_job.connection_id, v_job.connection_target_revision,
    v_job.credential_revision, v_job.credential_mode, v_job.role_arn,
    v_job.secret_arn, v_job.bucket_name, v_job.region_name,
    v_job.source_object_key, v_job.provider_version_id, v_job.etag,
    v_job.provider_checksum_sha256, v_job.output_format,
    v_job.output_content_type, v_job.maximum_output_bytes,
    v_job.destination_dataset_id, v_job.destination_bucket,
    format(
      'organizations/%s/projects/%s/datasets/%s/uploads/%s/original/source.%s',
      v_job.organization_id, v_job.project_id, v_job.destination_dataset_id, v_job.id,
      CASE v_job.output_format
        WHEN 'geojson' THEN 'geojson' WHEN 'csv' THEN 'csv'
        WHEN 'shapefile' THEN 'zip' WHEN 'geopackage' THEN 'gpkg'
        WHEN 'geoparquet' THEN 'parquet' WHEN 'cog' THEN 'tif'
        WHEN 'pmtiles' THEN 'pmtiles' WHEN 'png' THEN 'png'
        WHEN 'jpeg' THEN 'jpg' WHEN 'pdf' THEN 'pdf' WHEN 'odt' THEN 'odt'
      END
    ), v_job.request_checksum_sha256, v_job.attribution, v_job.attempt_count;
END;
$$;


--
-- Name: FUNCTION claim_repository_object_copy(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.claim_repository_object_copy(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer) IS 'Function-only repository copier claim. Returns source authority only after current connection and target revision checks.';


--
-- Name: claim_spatial_coverage_derivative(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_spatial_coverage_derivative(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, job_id uuid, organization_id uuid, project_id uuid, service_id uuid, coverage_id uuid, dataset_id uuid, dataset_version_id uuid, source_object_id uuid, source_bucket text, source_object_key text, source_s3_version_id text, source_etag text, source_content_type text, source_size_bytes bigint, source_checksum_sha256 text, source_crs text, source_extent jsonb, source_width integer, source_height integer, source_band_count integer, source_bands jsonb, request_schema_version smallint, band_indexes jsonb, scale_mode text, requested_resolution jsonb, subset_extent jsonb, target_crs text, target_width integer, target_height integer, resampling text, request_checksum_sha256 text, attempt_count integer, output_prefix text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job record;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_job_id IS NULL OR p_worker_token IS NULL
    OR p_lease_seconds NOT BETWEEN 60 AND 3600
  THEN
    RAISE EXCEPTION 'invalid coverage derivative claim';
  END IF;
  SELECT job.*, coverage.dataset_id, coverage.dataset_version_id,
         coverage.data_object_id, coverage.sealed_bucket,
         coverage.sealed_object_key, coverage.sealed_storage_version_id,
         object.etag, coverage.sealed_content_type, coverage.sealed_size_bytes,
         coverage.sealed_checksum_sha256, coverage.sealed_crs,
         coverage.sealed_extent, coverage.sealed_width,
         coverage.sealed_height, coverage.sealed_band_count,
         coverage.sealed_bands
  INTO v_job
  FROM app.spatial_coverage_derivative_jobs job
  JOIN app.spatial_service_coverages coverage
    ON coverage.organization_id = job.organization_id
   AND coverage.id = job.coverage_id
  JOIN app.data_objects object
    ON object.organization_id = coverage.organization_id
   AND object.id = coverage.data_object_id
  WHERE job.id = p_job_id
  FOR UPDATE OF job;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_ready', p_job_id, NULL::uuid, NULL::uuid,
      NULL::uuid, NULL::uuid, NULL::uuid, NULL::uuid, NULL::uuid,
      NULL::text, NULL::text, NULL::text, NULL::text, NULL::text,
      NULL::bigint, NULL::text, NULL::text, NULL::jsonb, NULL::integer,
      NULL::integer, NULL::integer, NULL::jsonb, NULL::smallint, NULL::jsonb,
      NULL::text, NULL::jsonb, NULL::jsonb, NULL::text, NULL::integer,
      NULL::integer, NULL::text, NULL::text, NULL::integer, NULL::text;
    RETURN;
  END IF;
  IF v_job.state::text IN ('completed', 'failed', 'cancelled') THEN
    claim_status := 'already_' || v_job.state::text;
  ELSIF v_job.state = 'running' AND v_job.lease_expires_at > v_now THEN
    claim_status := 'busy';
  ELSE
    UPDATE app.spatial_coverage_derivative_jobs target
    SET state = 'running', worker_token = p_worker_token,
        lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
        last_heartbeat_at = v_now,
        attempt_count = target.attempt_count + 1,
        started_at = COALESCE(target.started_at, v_now),
        finished_at = NULL, error_code = NULL
    WHERE target.id = v_job.id;
    claim_status := 'claimed';
    v_job.attempt_count := v_job.attempt_count + 1;
  END IF;
  RETURN QUERY SELECT claim_status, v_job.id, v_job.organization_id,
    v_job.project_id, v_job.service_id, v_job.coverage_id, v_job.dataset_id,
    v_job.dataset_version_id, v_job.data_object_id, v_job.sealed_bucket,
    v_job.sealed_object_key, v_job.sealed_storage_version_id, v_job.etag,
    v_job.sealed_content_type, v_job.sealed_size_bytes,
    v_job.sealed_checksum_sha256, v_job.sealed_crs, v_job.sealed_extent,
    v_job.sealed_width, v_job.sealed_height, v_job.sealed_band_count,
    v_job.sealed_bands, v_job.request_schema_version, v_job.band_indexes,
    v_job.scale_mode, v_job.requested_resolution, v_job.subset_extent,
    v_job.target_crs, v_job.target_width, v_job.target_height, v_job.resampling,
    v_job.request_checksum_sha256, v_job.attempt_count,
    format(
      'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/',
      v_job.organization_id, v_job.project_id, v_job.dataset_id,
      v_job.dataset_version_id
    );
END;
$$;


--
-- Name: claim_spatial_coverage_derivative_reclamation(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_spatial_coverage_derivative_reclamation(p_reclamation_id uuid, p_worker_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, reclamation_id uuid, derivative_job_id uuid, output_object_id uuid, bucket text, object_key text, storage_version_id text, etag text, content_type text, size_bytes bigint, checksum_sha256 text, delete_started_at timestamp with time zone, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_plan app.spatial_coverage_derivative_reclamations%ROWTYPE;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_reclamation_id IS NULL OR p_worker_token IS NULL
    OR p_lease_seconds NOT BETWEEN 60 AND 3600
  THEN
    RAISE EXCEPTION 'invalid coverage derivative reclamation claim';
  END IF;
  SELECT * INTO v_plan
  FROM app.spatial_coverage_derivative_reclamations
  WHERE id = p_reclamation_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_ready', p_reclamation_id, NULL::uuid, NULL::uuid,
      NULL::text, NULL::text, NULL::text, NULL::text, NULL::text,
      NULL::bigint, NULL::text, NULL::timestamptz, NULL::integer;
    RETURN;
  END IF;
  IF v_plan.state IN ('completed', 'failed') THEN
    claim_status := 'already_' || v_plan.state::text;
  ELSIF v_plan.state = 'running' AND v_plan.lease_expires_at > v_now THEN
    claim_status := 'busy';
  ELSIF app.coverage_derivative_object_is_referenced(
    v_plan.organization_id, v_plan.output_object_id
  ) THEN
    UPDATE app.spatial_coverage_derivative_reclamations
    SET state = 'failed', error_code = 'coverage_derivative_object_referenced',
        worker_token = NULL, lease_expires_at = NULL, last_heartbeat_at = NULL,
        finished_at = v_now
    WHERE id = v_plan.id;
    INSERT INTO app.activity_events
      (organization_id, actor_user_id, project_id, event_type,
       resource_type, resource_id, request_id, payload)
    VALUES
      (v_plan.organization_id, v_plan.created_by, v_plan.project_id,
       'spatial_service.coverage.derivative.reclamation.failed',
       'spatial_service', v_plan.service_id, 'worker:' || v_plan.id::text,
       jsonb_build_object(
         'reclamation_id', v_plan.id,
         'derivative_job_id', v_plan.derivative_job_id,
         'coverage_id', v_plan.coverage_id,
         'output_object_id', v_plan.output_object_id,
         'error_code', 'coverage_derivative_object_referenced'
       ));
    claim_status := 'already_failed';
  ELSE
    UPDATE app.spatial_coverage_derivative_reclamations target
    SET state = 'running', worker_token = p_worker_token,
        lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
        last_heartbeat_at = v_now,
        attempt_count = target.attempt_count + 1,
        started_at = COALESCE(target.started_at, v_now),
        finished_at = NULL, error_code = NULL
    WHERE target.id = v_plan.id;
    claim_status := 'claimed';
    v_plan.attempt_count := v_plan.attempt_count + 1;
  END IF;
  RETURN QUERY SELECT claim_status, v_plan.id, v_plan.derivative_job_id,
    v_plan.output_object_id, v_plan.sealed_bucket, v_plan.sealed_object_key,
    v_plan.sealed_storage_version_id, v_plan.sealed_etag,
    v_plan.sealed_content_type, v_plan.sealed_size_bytes,
    v_plan.sealed_checksum_sha256, v_plan.delete_started_at,
    v_plan.attempt_count;
END;
$$;


--
-- Name: claim_spatial_tile_cache_reclamation(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_spatial_tile_cache_reclamation(p_reclamation_id uuid, p_worker_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, reclamation_id uuid, target_count integer, target_size_bytes bigint, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_plan app.spatial_tile_cache_reclamations%ROWTYPE;
  v_now timestamptz := clock_timestamp();
  v_active integer;
BEGIN
  IF p_reclamation_id IS NULL OR p_worker_token IS NULL
    OR p_lease_seconds NOT BETWEEN 60 AND 3600
  THEN RAISE EXCEPTION 'invalid tile cache reclamation claim'; END IF;
  SELECT * INTO v_plan FROM app.spatial_tile_cache_reclamations
  WHERE id = p_reclamation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_ready', p_reclamation_id, NULL::integer,
      NULL::bigint, NULL::integer;
    RETURN;
  END IF;
  IF v_plan.state IN ('completed', 'failed') THEN
    claim_status := 'already_' || v_plan.state::text;
  ELSIF v_plan.state = 'running' AND v_plan.lease_expires_at > v_now THEN
    claim_status := 'busy';
  ELSE
    UPDATE app.spatial_tile_cache_reclamation_items item
    SET state = 'failed', error_code = 'render_cache_output_referenced',
        finished_at = v_now
    WHERE item.organization_id = v_plan.organization_id
      AND item.reclamation_id = v_plan.id
      AND item.state = 'queued'
      AND app.render_cache_output_is_referenced(
        item.organization_id, item.render_job_id, item.output_object_id
      );
    SELECT count(*)::integer INTO v_active
    FROM app.spatial_tile_cache_reclamation_items item
    WHERE item.organization_id = v_plan.organization_id
      AND item.reclamation_id = v_plan.id
      AND item.state IN ('queued', 'running');
    IF v_active = 0 THEN
      UPDATE app.spatial_tile_cache_reclamations
      SET state = 'failed', error_code = 'render_cache_output_referenced',
          worker_token = NULL, lease_expires_at = NULL,
          last_heartbeat_at = NULL, started_at = COALESCE(started_at, v_now),
          finished_at = v_now
      WHERE id = v_plan.id;
      claim_status := 'already_failed';
    ELSE
      UPDATE app.spatial_tile_cache_reclamations target
      SET state = 'running', worker_token = p_worker_token,
          lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
          last_heartbeat_at = v_now,
          attempt_count = target.attempt_count + 1,
          started_at = COALESCE(target.started_at, v_now),
          finished_at = NULL, error_code = NULL
      WHERE target.id = v_plan.id;
      claim_status := 'claimed';
      v_plan.attempt_count := v_plan.attempt_count + 1;
    END IF;
  END IF;
  RETURN QUERY SELECT claim_status, v_plan.id, v_plan.target_count,
    v_plan.target_size_bytes, v_plan.attempt_count;
END;
$$;


--
-- Name: claim_user_dataset_connection_verification(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.claim_user_dataset_connection_verification(p_verification_id uuid, p_worker_token uuid, p_lease_seconds integer) RETURNS TABLE(claim_status text, verification_id uuid, organization_id uuid, owner_user_id uuid, connection_id uuid, target_revision bigint, credential_revision bigint, bucket_name text, region_name text, object_prefix text, credential_mode text, role_arn text, secret_arn text, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job app.user_dataset_connection_verifications%ROWTYPE;
  v_connection app.user_dataset_connections%ROWTYPE;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_verification_id IS NULL OR p_worker_token IS NULL
    OR p_lease_seconds NOT BETWEEN 10 AND 60
  THEN
    RAISE EXCEPTION 'invalid user dataset verification claim';
  END IF;

  SELECT verification.* INTO v_job
  FROM app.user_dataset_connection_verifications verification
  WHERE verification.id = p_verification_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_found', p_verification_id,
      NULL::uuid, NULL::uuid, NULL::uuid, NULL::bigint, NULL::bigint,
      NULL::text, NULL::text, NULL::text, NULL::text, NULL::text,
      NULL::text, NULL::integer;
    RETURN;
  END IF;
  IF v_job.state IN ('succeeded', 'failed', 'cancelled') THEN
    RETURN QUERY SELECT 'already_' || v_job.state::text, v_job.id,
      v_job.organization_id, v_job.owner_user_id, v_job.connection_id,
      v_job.target_revision, v_job.credential_revision,
      NULL::text, NULL::text, NULL::text, NULL::text, NULL::text,
      NULL::text, v_job.attempt_count;
    RETURN;
  END IF;
  IF v_job.state = 'running' AND v_job.lease_expires_at > v_now THEN
    RETURN QUERY SELECT 'busy', v_job.id,
      v_job.organization_id, v_job.owner_user_id, v_job.connection_id,
      v_job.target_revision, v_job.credential_revision,
      NULL::text, NULL::text, NULL::text, NULL::text, NULL::text,
      NULL::text, v_job.attempt_count;
    RETURN;
  END IF;

  SELECT connection.* INTO v_connection
  FROM app.user_dataset_connections connection
  WHERE connection.organization_id = v_job.organization_id
    AND connection.owner_user_id = v_job.owner_user_id
    AND connection.id = v_job.connection_id
    AND connection.target_revision = v_job.target_revision
    AND connection.credential_revision = v_job.credential_revision
    AND connection.status NOT IN ('draft', 'disabled');

  IF NOT FOUND THEN
    UPDATE app.user_dataset_connection_verifications
    SET state = 'cancelled', worker_token = NULL, lease_expires_at = NULL,
        sanitized_error_code = 'verification_cancelled', finished_at = v_now
    WHERE id = v_job.id;
    RETURN QUERY SELECT 'not_verifiable', v_job.id,
      v_job.organization_id, v_job.owner_user_id, v_job.connection_id,
      v_job.target_revision, v_job.credential_revision,
      NULL::text, NULL::text, NULL::text, NULL::text, NULL::text,
      NULL::text, v_job.attempt_count;
    RETURN;
  END IF;

  IF v_job.attempt_count >= 3 THEN
    UPDATE app.user_dataset_connection_verifications
    SET state = 'failed', worker_token = NULL, lease_expires_at = NULL,
        sanitized_error_code = 'verification_failed', duration_ms = 0,
        started_at = COALESCE(started_at, v_now), finished_at = v_now
    WHERE id = v_job.id;
    UPDATE app.user_dataset_connections
    SET status = 'error', sanitized_error_code = 'verification_failed'
    WHERE organization_id = v_job.organization_id
      AND owner_user_id = v_job.owner_user_id
      AND id = v_job.connection_id
      AND target_revision = v_job.target_revision
      AND credential_revision = v_job.credential_revision
      AND status <> 'disabled';
    RETURN QUERY SELECT 'attempts_exhausted', v_job.id,
      v_job.organization_id, v_job.owner_user_id, v_job.connection_id,
      v_job.target_revision, v_job.credential_revision,
      NULL::text, NULL::text, NULL::text, NULL::text, NULL::text,
      NULL::text, v_job.attempt_count;
    RETURN;
  END IF;

  UPDATE app.user_dataset_connection_verifications verification
  SET state = 'running', worker_token = p_worker_token,
      lease_expires_at = v_now + make_interval(secs => p_lease_seconds),
      attempt_count = verification.attempt_count + 1,
      started_at = COALESCE(verification.started_at, v_now)
  WHERE verification.id = v_job.id;

  RETURN QUERY SELECT 'claimed', v_job.id,
    v_job.organization_id, v_job.owner_user_id, v_job.connection_id,
    v_job.target_revision, v_job.credential_revision,
    v_connection.bucket_name, v_connection.region_name,
    v_connection.object_prefix, v_connection.credential_mode::text,
    v_connection.role_arn, v_connection.secret_arn,
    v_job.attempt_count + 1;
END;
$$;


--
-- Name: commit_user_basemap_connection_credential_rotation(uuid, bigint, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.commit_user_basemap_connection_credential_rotation(p_connection_id uuid, p_expected_revision bigint, p_secret_arn text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
BEGIN
  UPDATE app.user_basemap_connections connection
  SET secret_arn = p_secret_arn,
      configured_secret_fields = ARRAY['api_key']::text[],
      credential_revision = p_expected_revision + 1,
      status = 'configured'
  WHERE connection.organization_id = app.current_organization_id()
    AND connection.owner_user_id = app.current_user_id()
    AND connection.id = p_connection_id
    AND connection.credential_revision = p_expected_revision
    AND connection.status <> 'disabled';
  RETURN FOUND;
END;
$$;


--
-- Name: commit_user_dataset_connection_credential_rotation(uuid, bigint, text, text[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.commit_user_dataset_connection_credential_rotation(p_connection_id uuid, p_expected_revision bigint, p_secret_arn text, p_configured_secret_fields text[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
BEGIN
  UPDATE app.user_dataset_connections connection
  SET secret_arn = p_secret_arn,
      configured_secret_fields = p_configured_secret_fields,
      credential_revision = p_expected_revision + 1,
      status = 'unverified',
      last_verified_at = NULL,
      sanitized_error_code = NULL
  WHERE connection.organization_id = app.current_organization_id()
    AND connection.owner_user_id = app.current_user_id()
    AND connection.id = p_connection_id
    AND connection.credential_revision = p_expected_revision
    AND connection.credential_mode <> 'workload_identity'
    AND connection.status <> 'disabled';
  RETURN FOUND;
END;
$$;


--
-- Name: complete_dataset_ingest(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_dataset_ingest(p_job_id uuid, p_worker_token uuid, p_metadata jsonb, p_artifacts jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_job app.processing_jobs%ROWTYPE;
  v_original app.data_objects%ROWTYPE;
  v_artifact jsonb;
  v_prefix text;
  v_feature_count bigint;
  v_extent jsonb;
  v_crs text;
  v_geometry_type text;
  v_schema jsonb;
  v_quality jsonb;
BEGIN
  IF p_metadata IS NULL OR jsonb_typeof(p_metadata) <> 'object'
    OR octet_length(p_metadata::text) > 1048576
    OR p_artifacts IS NULL OR jsonb_typeof(p_artifacts) <> 'array'
    OR jsonb_array_length(p_artifacts) NOT BETWEEN 1 AND 16
    OR octet_length(p_artifacts::text) > 1048576
  THEN
    RAISE EXCEPTION 'invalid ingestion result';
  END IF;

  SELECT * INTO v_job
  FROM app.processing_jobs
  WHERE id = p_job_id
  FOR UPDATE;

  IF NOT FOUND OR v_job.job_type <> 'dataset.ingest'
    OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token
  THEN
    RETURN false;
  END IF;

  SELECT object.* INTO v_original
  FROM app.data_objects object
  JOIN app.dataset_versions version
    ON version.organization_id = object.organization_id
   AND version.original_object_id = object.id
  WHERE version.organization_id = v_job.organization_id
    AND version.dataset_id = v_job.dataset_id
    AND version.id = v_job.dataset_version_id
    AND object.role = 'original';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ingestion original object is missing';
  END IF;

  v_feature_count := NULLIF(p_metadata->>'feature_count', '')::bigint;
  v_extent := p_metadata->'extent';
  v_crs := NULLIF(p_metadata->>'crs', '');
  v_geometry_type := NULLIF(p_metadata->>'geometry_type', '');
  v_schema := COALESCE(p_metadata->'schema_definition', '{}'::jsonb);
  v_quality := COALESCE(p_metadata->'quality_results', '{}'::jsonb);

  IF (v_feature_count IS NOT NULL AND v_feature_count < 0)
    OR (v_extent IS NOT NULL AND v_extent <> 'null'::jsonb AND (
      jsonb_typeof(v_extent) <> 'array' OR jsonb_array_length(v_extent) <> 4
    ))
    OR (v_crs IS NOT NULL AND char_length(v_crs) > 1024)
    OR (v_geometry_type IS NOT NULL AND char_length(v_geometry_type) > 200)
    OR jsonb_typeof(v_schema) <> 'object'
    OR jsonb_typeof(v_quality) <> 'object'
  THEN
    RAISE EXCEPTION 'invalid ingestion metadata';
  END IF;

  v_prefix := format(
    'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/',
    v_job.organization_id,
    v_job.project_id,
    v_job.dataset_id,
    v_job.dataset_version_id
  );

  FOR v_artifact IN SELECT value FROM jsonb_array_elements(p_artifacts)
  LOOP
    IF jsonb_typeof(v_artifact) <> 'object'
      OR (v_artifact->>'bucket') <> v_original.bucket
      OR (v_artifact->>'object_key') NOT LIKE v_prefix || '%'
      OR (v_artifact->>'object_key') LIKE '%/../%'
      OR (v_artifact->>'object_key') LIKE '%//%'
      OR (v_artifact->>'s3_version_id') IN ('', 'null')
      OR (v_artifact->>'etag') = ''
      OR (v_artifact->>'content_type') = ''
      OR (v_artifact->>'size_bytes')::bigint <= 0
      OR (v_artifact->>'size_bytes')::bigint > 5368709120
      OR (v_artifact->>'checksum_sha256') !~ '^[0-9a-f]{64}$'
      OR (v_artifact->>'role') NOT IN ('working', 'tile', 'derived', 'thumbnail')
    THEN
      RAISE EXCEPTION 'invalid ingestion artifact';
    END IF;

    INSERT INTO app.data_objects
      (id, organization_id, dataset_id, role, bucket, object_key,
       s3_version_id, etag, content_type, size_bytes, checksum_sha256, created_by)
    VALUES
      ((v_artifact->>'id')::uuid,
       v_job.organization_id,
       v_job.dataset_id,
       (v_artifact->>'role')::app.data_object_role,
       v_artifact->>'bucket',
       v_artifact->>'object_key',
       v_artifact->>'s3_version_id',
       v_artifact->>'etag',
       lower(v_artifact->>'content_type'),
       (v_artifact->>'size_bytes')::bigint,
       v_artifact->>'checksum_sha256',
       v_job.created_by);
  END LOOP;

  UPDATE app.dataset_versions
  SET state = 'active',
      feature_count = v_feature_count,
      extent = CASE WHEN v_extent = 'null'::jsonb THEN NULL ELSE v_extent END,
      crs = v_crs,
      geometry_type = v_geometry_type,
      schema_definition = v_schema,
      quality_results = v_quality
  WHERE organization_id = v_job.organization_id
    AND dataset_id = v_job.dataset_id
    AND id = v_job.dataset_version_id;

  UPDATE app.datasets
  SET status = 'active', updated_by = v_job.created_by
  WHERE organization_id = v_job.organization_id
    AND id = v_job.dataset_id
    AND current_version_id = v_job.dataset_version_id;

  UPDATE app.processing_jobs
  SET state = 'completed',
      result = p_metadata || jsonb_build_object('artifacts', p_artifacts),
      error_code = NULL,
      worker_token = NULL,
      lease_expires_at = NULL,
      last_heartbeat_at = NULL,
      finished_at = clock_timestamp()
  WHERE id = v_job.id;

  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (v_job.organization_id, v_job.created_by, v_job.project_id,
     'dataset.ingest.completed', 'dataset', v_job.dataset_id,
     'worker:' || v_job.id::text,
     jsonb_build_object(
       'processing_job_id', v_job.id,
       'dataset_version_id', v_job.dataset_version_id,
       'artifact_count', jsonb_array_length(p_artifacts)
     ));

  RETURN true;
END;
$_$;


--
-- Name: FUNCTION complete_dataset_ingest(p_job_id uuid, p_worker_token uuid, p_metadata jsonb, p_artifacts jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.complete_dataset_ingest(p_job_id uuid, p_worker_token uuid, p_metadata jsonb, p_artifacts jsonb) IS 'Atomically record bounded derivative facts and advance one leased dataset ingestion to active.';


--
-- Name: complete_external_connection_verification(uuid, uuid, boolean, boolean, boolean, boolean, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_external_connection_verification(p_verification_id uuid, p_worker_token uuid, p_network_reachable boolean, p_tls_verified boolean, p_credentials_verified boolean, p_postgis_verified boolean, p_sanitized_error_code text, p_duration_ms integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job app.external_connection_verifications%ROWTYPE;
  v_succeeded boolean := p_sanitized_error_code IS NULL;
BEGIN
  IF p_duration_ms NOT BETWEEN 0 AND 20000
    OR (v_succeeded AND NOT (
      p_network_reachable AND p_tls_verified
      AND p_credentials_verified AND p_postgis_verified
    ))
    OR (NOT v_succeeded AND p_sanitized_error_code NOT IN (
      'credentials_rejected', 'dns_resolution_failed', 'postgis_required',
      'tls_verification_failed', 'unsafe_network_target',
      'verification_cancelled', 'verification_failed', 'verification_timeout'
    ))
  THEN
    RAISE EXCEPTION 'invalid connection verification result';
  END IF;

  SELECT verification.* INTO v_job
  FROM app.external_connection_verifications verification
  WHERE verification.id = p_verification_id
  FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token THEN
    RETURN false;
  END IF;

  UPDATE app.external_connection_verifications
  SET state = CASE WHEN v_succeeded
      THEN 'succeeded'::app.external_connection_verification_state
      ELSE 'failed'::app.external_connection_verification_state END,
      worker_token = NULL, lease_expires_at = NULL,
      network_reachable = p_network_reachable,
      tls_verified = p_tls_verified,
      credentials_verified = p_credentials_verified,
      postgis_verified = p_postgis_verified,
      sanitized_error_code = p_sanitized_error_code,
      duration_ms = p_duration_ms,
      finished_at = clock_timestamp()
  WHERE id = v_job.id;

  UPDATE app.external_connections
  SET status = CASE WHEN v_succeeded
      THEN 'credentials_verified'::app.external_connection_status
      ELSE 'degraded'::app.external_connection_status END,
      last_verified_at = CASE WHEN v_succeeded THEN clock_timestamp() ELSE last_verified_at END,
      sanitized_error_code = p_sanitized_error_code,
      updated_at = clock_timestamp()
  WHERE organization_id = v_job.organization_id
    AND project_id = v_job.project_id
    AND id = v_job.connection_id
    AND current_revision_number = v_job.connection_revision_number
    AND status NOT IN ('disabled', 'revoked');

  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (v_job.organization_id, v_job.requested_by, v_job.project_id,
     CASE WHEN v_succeeded THEN 'connection.verification.succeeded'
          ELSE 'connection.verification.failed' END,
     'connection', v_job.connection_id, 'connector:' || v_job.id::text,
     jsonb_build_object(
       'verification_id', v_job.id,
       'connection_revision_number', v_job.connection_revision_number,
       'attempt_count', v_job.attempt_count,
       'duration_ms', p_duration_ms,
       'network_reachable', p_network_reachable,
       'tls_verified', p_tls_verified,
       'credentials_verified', p_credentials_verified,
       'postgis_verified', p_postgis_verified,
       'error_code', p_sanitized_error_code
     ));
  RETURN true;
END;
$$;


--
-- Name: complete_external_source_discovery(uuid, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_external_source_discovery(p_job_id uuid, p_worker_token uuid, p_result jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_job app.external_source_discovery_jobs%ROWTYPE;
  v_collection jsonb;
  v_limitation jsonb;
BEGIN
  SELECT * INTO v_job FROM app.external_source_discovery_jobs
  WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token
    OR v_job.lease_expires_at <= clock_timestamp()
  THEN RETURN false; END IF;
  IF p_result IS NULL OR jsonb_typeof(p_result) <> 'object'
    OR octet_length(p_result::text) > 524288
    OR (SELECT count(*) FROM jsonb_object_keys(p_result)) <> 7
    OR p_result - ARRAY[
      'schema_version', 'source_type', 'kind', 'service_url', 'collections',
      'source_definition', 'limitations'
    ] <> '{}'::jsonb
    OR p_result->>'schema_version'
      <> 'opengeo.external-source-discovery-result.1.0.0'
    OR p_result->>'source_type' <> v_job.source_type
    OR p_result->>'kind' <> v_job.discovery_kind
    OR p_result->>'service_url' <> v_job.service_url
    OR jsonb_typeof(p_result->'collections') <> 'array'
    OR jsonb_array_length(p_result->'collections') NOT BETWEEN 1 AND 100
    OR jsonb_typeof(p_result->'limitations') <> 'array'
    OR jsonb_array_length(p_result->'limitations') NOT BETWEEN 1 AND 10
    OR (v_job.discovery_kind = 'catalog'
      AND jsonb_typeof(p_result->'source_definition') <> 'null')
    OR (v_job.discovery_kind = 'collection'
      AND (jsonb_typeof(p_result->'source_definition') <> 'object'
        OR jsonb_array_length(p_result->'collections') <> 1
        OR p_result->'collections'->0->>'ref' <> v_job.collection_ref))
  THEN RAISE EXCEPTION 'invalid source discovery result'; END IF;
  FOR v_collection IN SELECT value FROM jsonb_array_elements(p_result->'collections')
  LOOP
    IF jsonb_typeof(v_collection) <> 'object'
      OR (SELECT count(*) FROM jsonb_object_keys(v_collection)) <> 5
      OR v_collection - ARRAY['ref', 'name', 'title', 'geometry_type', 'bounds']
        <> '{}'::jsonb
      OR v_collection->>'ref' !~ '^[A-Za-z0-9_.:-]{1,200}$'
      OR char_length(v_collection->>'name') NOT BETWEEN 1 AND 200
      OR char_length(v_collection->>'title') NOT BETWEEN 1 AND 500
      OR v_collection->>'name' ~ '[[:cntrl:]]'
      OR v_collection->>'title' ~ '[[:cntrl:]]'
      OR jsonb_typeof(v_collection->'geometry_type') NOT IN ('null', 'string')
      OR (jsonb_typeof(v_collection->'geometry_type') = 'string'
        AND v_collection->>'geometry_type' NOT IN (
          'Point', 'MultiPoint', 'LineString', 'MultiLineString',
          'Polygon', 'MultiPolygon'
        ))
      OR jsonb_typeof(v_collection->'bounds') NOT IN ('null', 'array')
      OR (jsonb_typeof(v_collection->'bounds') = 'array'
        AND jsonb_array_length(v_collection->'bounds') <> 4)
    THEN RAISE EXCEPTION 'invalid source discovery collection'; END IF;
    IF jsonb_typeof(v_collection->'bounds') = 'array' THEN
      IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_collection->'bounds') coordinate
        WHERE jsonb_typeof(coordinate) <> 'number'
      ) OR (v_collection->'bounds'->>0)::numeric NOT BETWEEN -180 AND 180
        OR (v_collection->'bounds'->>2)::numeric NOT BETWEEN -180 AND 180
        OR (v_collection->'bounds'->>1)::numeric NOT BETWEEN -90 AND 90
        OR (v_collection->'bounds'->>3)::numeric NOT BETWEEN -90 AND 90
        OR (v_collection->'bounds'->>0)::numeric
          >= (v_collection->'bounds'->>2)::numeric
        OR (v_collection->'bounds'->>1)::numeric
          >= (v_collection->'bounds'->>3)::numeric
      THEN RAISE EXCEPTION 'invalid source discovery bounds'; END IF;
    END IF;
  END LOOP;
  FOR v_limitation IN SELECT value FROM jsonb_array_elements(p_result->'limitations')
  LOOP
    IF jsonb_typeof(v_limitation) <> 'string'
      OR char_length(v_limitation #>> '{}') NOT BETWEEN 1 AND 500
      OR v_limitation #>> '{}' ~ '[[:cntrl:]]'
    THEN RAISE EXCEPTION 'invalid source discovery limitation'; END IF;
  END LOOP;
  UPDATE app.external_source_discovery_jobs
  SET state = 'completed', result = p_result, error_code = NULL,
      worker_token = NULL, lease_expires_at = NULL,
      finished_at = clock_timestamp()
  WHERE id = v_job.id;
  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (v_job.organization_id, v_job.created_by, v_job.project_id,
     'dataset.source.discovery.completed', 'project', v_job.project_id,
     'worker:' || v_job.id::text,
     jsonb_build_object(
       'discovery_job_id', v_job.id,
       'source_type', v_job.source_type,
       'discovery_kind', v_job.discovery_kind,
       'collection_count', jsonb_array_length(p_result->'collections')
     ));
  RETURN true;
END;
$_$;


--
-- Name: complete_external_source_snapshot(uuid, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_external_source_snapshot(p_job_id uuid, p_worker_token uuid, p_artifact jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_job app.external_source_snapshot_jobs%ROWTYPE;
  v_estimate app.external_source_copy_estimates%ROWTYPE;
  v_object_id uuid;
  v_version_id uuid := gen_random_uuid();
  v_processing_job_id uuid := gen_random_uuid();
  v_expected_key text;
  v_filename text;
BEGIN
  SELECT * INTO v_job FROM app.external_source_snapshot_jobs
  WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token
    OR v_job.lease_expires_at <= clock_timestamp()
  THEN RETURN false; END IF;
  SELECT * INTO v_estimate FROM app.external_source_copy_estimates
  WHERE organization_id = v_job.organization_id AND id = v_job.estimate_id;
  v_filename := CASE v_estimate.output_format::text
    WHEN 'png' THEN 'snapshot.png'
    WHEN 'geojson' THEN 'snapshot.geojson'
    ELSE 'source.pmtiles'
  END;
  v_expected_key := format(
    'organizations/%s/projects/%s/datasets/%s/uploads/%s/original/%s',
    v_job.organization_id, v_job.project_id, v_job.destination_dataset_id,
    v_job.id, v_filename
  );
  IF p_artifact IS NULL OR jsonb_typeof(p_artifact) <> 'object'
    OR octet_length(p_artifact::text) > 8192
    OR (p_artifact->>'role') <> 'original'
    OR (p_artifact->>'bucket') <> v_job.destination_bucket
    OR (p_artifact->>'object_key') <> v_expected_key
    OR (p_artifact->>'s3_version_id') IN ('', 'null')
    OR char_length(p_artifact->>'s3_version_id') > 1024
    OR (p_artifact->>'etag') !~ '^[A-Fa-f0-9]{16,128}$'
    OR (p_artifact->>'content_type') <> v_estimate.output_content_type
    OR (p_artifact->>'size_bytes')::bigint NOT BETWEEN 1 AND v_estimate.maximum_output_bytes
    OR (p_artifact->>'checksum_sha256') !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'invalid source snapshot artifact'; END IF;
  v_object_id := (p_artifact->>'id')::uuid;
  INSERT INTO app.data_objects
    (id, organization_id, dataset_id, role, bucket, object_key,
     s3_version_id, etag, content_type, size_bytes, checksum_sha256, created_by)
  VALUES
    (v_object_id, v_job.organization_id, v_job.destination_dataset_id,
     'original', p_artifact->>'bucket', p_artifact->>'object_key',
     p_artifact->>'s3_version_id', lower(p_artifact->>'etag'),
     p_artifact->>'content_type', (p_artifact->>'size_bytes')::bigint,
     p_artifact->>'checksum_sha256', v_job.created_by);
  INSERT INTO app.upload_intents
    (id, organization_id, project_id, dataset_id, created_by,
     original_filename, content_type, expected_size_bytes, expected_sha256,
     bucket, object_key, state, expires_at, completed_at, completed_object_id)
  VALUES
    (v_job.id, v_job.organization_id, v_job.project_id,
     v_job.destination_dataset_id, v_job.created_by, v_filename,
     p_artifact->>'content_type', (p_artifact->>'size_bytes')::bigint,
     p_artifact->>'checksum_sha256', p_artifact->>'bucket',
     p_artifact->>'object_key', 'completed', clock_timestamp() + interval '1 day',
     clock_timestamp(), v_object_id);
  INSERT INTO app.dataset_versions
    (id, organization_id, dataset_id, version_number, parent_version_id,
     original_object_id, state, change_message, created_by)
  VALUES
    (v_version_id, v_job.organization_id, v_job.destination_dataset_id, 1, NULL,
     v_object_id, 'queued', 'Protected copy of external source revision',
     v_job.created_by);
  UPDATE app.datasets
  SET status = 'processing', current_version_id = v_version_id,
      updated_by = v_job.created_by
  WHERE organization_id = v_job.organization_id
    AND id = v_job.destination_dataset_id AND status = 'draft'
    AND current_version_id IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'source snapshot destination changed'; END IF;
  INSERT INTO app.processing_jobs
    (id, organization_id, project_id, dataset_id, dataset_version_id,
     job_type, parameters, created_by)
  VALUES
    (v_processing_job_id, v_job.organization_id, v_job.project_id,
     v_job.destination_dataset_id, v_version_id, 'dataset.ingest',
     jsonb_build_object(
       'upload_id', v_job.id,
       'object_id', v_object_id,
       's3_version_id', p_artifact->>'s3_version_id',
       'source_snapshot_job_id', v_job.id
     ), v_job.created_by);
  INSERT INTO app.dataset_version_external_source_lineage
    (organization_id, destination_dataset_id, destination_dataset_version_id,
     source_dataset_id, source_revision_number, snapshot_job_id, retrieved_at)
  VALUES
    (v_job.organization_id, v_job.destination_dataset_id, v_version_id,
     v_job.source_dataset_id, v_job.source_revision_number, v_job.id,
     clock_timestamp());
  UPDATE app.external_source_snapshot_jobs
  SET state = 'completed', output_object_id = v_object_id,
      output_dataset_version_id = v_version_id, error_code = NULL,
      worker_token = NULL, lease_expires_at = NULL, last_heartbeat_at = NULL,
      finished_at = clock_timestamp()
  WHERE id = v_job.id;
  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (v_job.organization_id, v_job.created_by, v_job.project_id,
     'dataset.source.snapshot.completed', 'dataset', v_job.destination_dataset_id,
     'source-archiver:' || v_job.id::text,
     jsonb_build_object(
       'snapshot_job_id', v_job.id,
       'source_dataset_id', v_job.source_dataset_id,
       'source_revision_number', v_job.source_revision_number,
       'dataset_version_id', v_version_id,
       'processing_job_id', v_processing_job_id,
       'output_object_id', v_object_id,
       'checksum_sha256', p_artifact->>'checksum_sha256'
     ));
  RETURN true;
END;
$_$;


--
-- Name: complete_geonode_harvest(uuid, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_geonode_harvest(p_job_id uuid, p_worker_token uuid, p_snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE v_job app.geonode_harvest_jobs%ROWTYPE;
  v_source app.geonode_federation_sources%ROWTYPE;
  v_resource jsonb; v_prior app.geonode_federated_identities%ROWTYPE;
  v_observed timestamptz; v_fresh_until timestamptz; v_identifier text;
  v_type text; v_title text; v_checksum text; v_modified timestamptz;
  v_version integer; v_added integer := 0; v_updated integer := 0;
  v_unchanged integer := 0; v_withdrawn integer := 0;
BEGIN
  SELECT * INTO v_job FROM app.geonode_harvest_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token
    OR v_job.lease_expires_at <= clock_timestamp() THEN RETURN false; END IF;
  SELECT * INTO v_source FROM app.geonode_federation_sources
  WHERE organization_id = v_job.organization_id AND id = v_job.source_id;
  IF v_source.status <> 'active'
    OR v_source.configuration_checksum_sha256
      <> v_job.source_configuration_checksum_sha256
    OR p_snapshot IS NULL OR jsonb_typeof(p_snapshot) <> 'object'
    OR octet_length(p_snapshot::text) > 2097152
    OR p_snapshot - ARRAY['schema_version','source','observed_at','fresh_until',
      'remote_total','truncated','resources','snapshot_sha256'] <> '{}'::jsonb
    OR (SELECT count(*) FROM jsonb_object_keys(p_snapshot)) <> 8
    OR p_snapshot->>'schema_version' <> 'opengeo.geonode-harvest-snapshot.1.0.0'
    OR jsonb_typeof(p_snapshot->'source') <> 'object'
    OR (p_snapshot->'source') - ARRAY['product','version','commit','url',
      'fingerprint_sha256'] <> '{}'::jsonb
    OR (SELECT count(*) FROM jsonb_object_keys(p_snapshot->'source')) <> 5
    OR p_snapshot->'source'->>'product' <> 'geonode'
    OR p_snapshot->'source'->>'version' <> '5.1.0'
    OR p_snapshot->'source'->>'commit'
      <> 'a1db97e81dfc26c16bb4ee1a5d2b408877af66c9'
    OR p_snapshot->'source'->>'url' <> v_source.remote_url
    OR p_snapshot->'source'->>'fingerprint_sha256'
      <> v_source.source_fingerprint_sha256
    OR jsonb_typeof(p_snapshot->'resources') <> 'array'
    OR jsonb_array_length(p_snapshot->'resources') NOT BETWEEN 0 AND v_source.maximum_resources
    OR jsonb_typeof(p_snapshot->'remote_total') <> 'number'
    OR (p_snapshot->>'remote_total')::bigint < jsonb_array_length(p_snapshot->'resources')
    OR (p_snapshot->>'remote_total')::bigint > 1000000000
    OR jsonb_typeof(p_snapshot->'truncated') <> 'boolean'
    OR (p_snapshot->>'truncated')::boolean
      <> ((p_snapshot->>'remote_total')::bigint > jsonb_array_length(p_snapshot->'resources'))
    OR p_snapshot->>'snapshot_sha256' !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'invalid GeoNode harvest snapshot'; END IF;
  BEGIN
    v_observed := (p_snapshot->>'observed_at')::timestamptz;
    v_fresh_until := (p_snapshot->>'fresh_until')::timestamptz;
  EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'invalid GeoNode harvest timestamps'; END;
  IF v_observed > clock_timestamp() + interval '5 minutes'
    OR v_fresh_until <> v_observed
      + make_interval(mins => v_source.refresh_interval_minutes)
  THEN RAISE EXCEPTION 'invalid GeoNode harvest freshness'; END IF;

  FOR v_resource IN SELECT value FROM jsonb_array_elements(p_snapshot->'resources') LOOP
    IF jsonb_typeof(v_resource) <> 'object'
      OR v_resource - ARRAY['remote_identifier','resource_type','title',
        'remote_modified_at','payload_sha256','payload'] <> '{}'::jsonb
      OR (SELECT count(*) FROM jsonb_object_keys(v_resource)) <> 6
      OR jsonb_typeof(v_resource->'payload') <> 'object'
      OR octet_length((v_resource->'payload')::text) > 131072
      OR v_resource->>'payload_sha256' !~ '^[0-9a-f]{64}$'
    THEN RAISE EXCEPTION 'invalid GeoNode harvest resource'; END IF;
    v_identifier := v_resource->>'remote_identifier';
    BEGIN
      IF v_identifier::uuid::text <> v_identifier
      THEN RAISE EXCEPTION 'invalid GeoNode remote identity'; END IF;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'invalid GeoNode remote identity';
    END;
    v_type := v_resource->>'resource_type'; v_title := v_resource->>'title';
    v_checksum := v_resource->>'payload_sha256';
    IF v_type NOT IN ('dataset','document','map','geoapp','service')
      OR char_length(v_title) NOT BETWEEN 1 AND 500 OR v_title <> btrim(v_title)
      OR v_title ~ '[[:cntrl:]]'
      OR v_resource->'payload'->>'uuid' <> v_identifier
      OR lower(v_resource->'payload'->>'resource_type') <> v_type
      OR v_resource->'payload'->>'title' <> v_title
    THEN RAISE EXCEPTION 'invalid GeoNode harvest resource identity'; END IF;
    v_modified := NULL;
    IF jsonb_typeof(v_resource->'remote_modified_at') = 'string' THEN
      BEGIN v_modified := (v_resource->>'remote_modified_at')::timestamptz;
      EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'invalid GeoNode modified time'; END;
    ELSIF jsonb_typeof(v_resource->'remote_modified_at') <> 'null' THEN
      RAISE EXCEPTION 'invalid GeoNode modified time';
    END IF;
    IF EXISTS (
      SELECT 1 FROM app.governed_resource_external_identifiers identifier
      WHERE identifier.organization_id = v_job.organization_id
        AND identifier.namespace = 'geonode' AND identifier.identifier = v_identifier
        AND identifier.source_url IS DISTINCT FROM v_source.remote_url
    ) THEN RAISE EXCEPTION 'GeoNode local identity collision'; END IF;
    SELECT * INTO v_prior FROM app.geonode_federated_identities identity
    WHERE identity.organization_id = v_job.organization_id
      AND identity.remote_identifier = v_identifier FOR UPDATE;
    IF v_prior.remote_identifier IS NOT NULL AND v_prior.source_id <> v_source.id
    THEN RAISE EXCEPTION 'GeoNode source identity collision'; END IF;
    IF v_prior.remote_identifier IS NULL THEN
      INSERT INTO app.geonode_federated_identities
        (organization_id, project_id, source_id, remote_identifier, resource_type,
         title, status, current_version_number, current_payload_sha256,
         remote_modified_at, first_seen_at, last_refreshed_at)
      VALUES (v_job.organization_id, v_job.project_id, v_source.id, v_identifier,
        v_type, v_title, 'current', 1, v_checksum, v_modified,
        v_observed, v_observed);
      INSERT INTO app.geonode_federated_identity_versions
        (organization_id, source_id, remote_identifier, version_number,
         harvest_job_id, action, resource_type, title, payload_sha256,
         payload, remote_modified_at, observed_at)
      VALUES (v_job.organization_id, v_source.id, v_identifier, 1, v_job.id,
        'added', v_type, v_title, v_checksum, v_resource->'payload',
        v_modified, v_observed); v_added := v_added + 1;
    ELSIF v_prior.current_payload_sha256 = v_checksum AND v_prior.status = 'current' THEN
      UPDATE app.geonode_federated_identities SET last_refreshed_at = v_observed,
        remote_modified_at = v_modified WHERE organization_id = v_job.organization_id
        AND remote_identifier = v_identifier; v_unchanged := v_unchanged + 1;
    ELSE
      v_version := v_prior.current_version_number + 1;
      UPDATE app.geonode_federated_identities SET resource_type = v_type,
        title = v_title, status = 'current', current_version_number = v_version,
        current_payload_sha256 = v_checksum, remote_modified_at = v_modified,
        last_refreshed_at = v_observed, withdrawn_at = NULL
      WHERE organization_id = v_job.organization_id AND remote_identifier = v_identifier;
      INSERT INTO app.geonode_federated_identity_versions
        (organization_id, source_id, remote_identifier, version_number,
         harvest_job_id, action, resource_type, title, payload_sha256,
         payload, remote_modified_at, observed_at)
      VALUES (v_job.organization_id, v_source.id, v_identifier, v_version, v_job.id,
        CASE WHEN v_prior.status = 'withdrawn' THEN 'added' ELSE 'updated' END,
        v_type, v_title, v_checksum, v_resource->'payload', v_modified, v_observed);
      IF v_prior.status = 'withdrawn' THEN v_added := v_added + 1;
      ELSE v_updated := v_updated + 1; END IF;
    END IF;
  END LOOP;

  FOR v_prior IN SELECT * FROM app.geonode_federated_identities identity
    WHERE identity.organization_id = v_job.organization_id
      AND identity.source_id = v_source.id AND identity.status = 'current'
      AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_snapshot->'resources') resource
        WHERE resource->>'remote_identifier' = identity.remote_identifier)
    FOR UPDATE
  LOOP
    v_version := v_prior.current_version_number + 1;
    UPDATE app.geonode_federated_identities SET status = 'withdrawn',
      current_version_number = v_version, last_refreshed_at = v_observed,
      withdrawn_at = v_observed WHERE organization_id = v_job.organization_id
      AND remote_identifier = v_prior.remote_identifier;
    INSERT INTO app.geonode_federated_identity_versions
      (organization_id, source_id, remote_identifier, version_number,
       harvest_job_id, action, resource_type, title, payload_sha256,
       payload, remote_modified_at, observed_at)
    VALUES (v_job.organization_id, v_source.id, v_prior.remote_identifier, v_version,
      v_job.id, 'withdrawn', v_prior.resource_type, v_prior.title,
      v_prior.current_payload_sha256, NULL, v_prior.remote_modified_at, v_observed);
    v_withdrawn := v_withdrawn + 1;
  END LOOP;

  UPDATE app.geonode_harvest_jobs SET state = 'completed', error_code = NULL,
    worker_token = NULL, lease_expires_at = NULL, finished_at = clock_timestamp(),
    result = p_snapshot || jsonb_build_object('reconciliation', jsonb_build_object(
      'added', v_added, 'updated', v_updated, 'unchanged', v_unchanged,
      'withdrawn', v_withdrawn)) WHERE id = v_job.id;
  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES (v_job.organization_id, v_job.created_by, v_job.project_id,
    'federation.geonode.harvest.completed', 'project', v_job.project_id,
    'source-archiver:' || v_job.id::text, jsonb_build_object(
      'source_id', v_source.id, 'harvest_job_id', v_job.id,
      'snapshot_sha256', p_snapshot->>'snapshot_sha256',
      'added', v_added, 'updated', v_updated, 'unchanged', v_unchanged,
      'withdrawn', v_withdrawn));
  RETURN true;
END;
$_$;


--
-- Name: complete_map_render(uuid, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_map_render(p_job_id uuid, p_worker_token uuid, p_artifact jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_job app.map_render_jobs%ROWTYPE;
  v_profile app.map_render_profile_versions%ROWTYPE;
  v_bucket text;
  v_prefix text;
  v_extension text;
  v_content_type text;
  v_expected_key text;
BEGIN
  SELECT * INTO v_job FROM app.map_render_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token THEN
    RETURN false;
  END IF;
  SELECT * INTO v_profile
  FROM app.map_render_profile_versions
  WHERE organization_id = v_job.organization_id
    AND profile_id = v_job.profile_id
    AND id = v_job.profile_version_id;
  SELECT object.bucket INTO v_bucket
  FROM app.dataset_version_objects link
  JOIN app.data_objects object
    ON object.organization_id = link.organization_id
   AND object.id = link.data_object_id
  WHERE link.organization_id = v_job.organization_id
    AND link.dataset_id = v_profile.dataset_id
    AND link.dataset_version_id = v_profile.dataset_version_id
  ORDER BY object.id
  LIMIT 1;

  v_prefix := format(
    'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/',
    v_job.organization_id, v_job.project_id, v_profile.dataset_id,
    v_profile.dataset_version_id
  );
  v_extension := CASE v_job.format::text WHEN 'svg' THEN 'svg' WHEN 'png' THEN 'png' END;
  v_content_type := CASE v_job.format::text
    WHEN 'svg' THEN 'image/svg+xml'
    WHEN 'png' THEN 'image/png'
  END;
  IF v_extension IS NULL OR v_content_type IS NULL THEN
    RAISE EXCEPTION 'invalid map render format';
  END IF;
  v_expected_key := v_prefix || 'renders/' || v_job.id::text || '.' || v_extension;
  IF v_bucket IS NULL
    OR p_artifact IS NULL OR jsonb_typeof(p_artifact) <> 'object'
    OR octet_length(p_artifact::text) > 8192
    OR (p_artifact->>'id') IS NULL
    OR (p_artifact->>'role') <> 'derived'
    OR (p_artifact->>'bucket') <> v_bucket
    OR (p_artifact->>'object_key') <> v_expected_key
    OR (p_artifact->>'content_type') <> v_content_type
    OR (p_artifact->>'s3_version_id') IN ('', 'null')
    OR (p_artifact->>'etag') = ''
    OR (p_artifact->>'size_bytes')::bigint NOT BETWEEN 1 AND 20971520
    OR (p_artifact->>'checksum_sha256') !~ '^[0-9a-f]{64}$'
  THEN
    RAISE EXCEPTION 'invalid map render artifact';
  END IF;

  INSERT INTO app.data_objects
    (id, organization_id, dataset_id, role, bucket, object_key,
     s3_version_id, etag, content_type, size_bytes, checksum_sha256, created_by)
  VALUES
    ((p_artifact->>'id')::uuid, v_job.organization_id, v_profile.dataset_id,
     'derived', p_artifact->>'bucket', p_artifact->>'object_key',
     p_artifact->>'s3_version_id', p_artifact->>'etag',
     p_artifact->>'content_type', (p_artifact->>'size_bytes')::bigint,
     p_artifact->>'checksum_sha256', v_job.created_by);
  INSERT INTO app.dataset_version_objects
    (organization_id, dataset_id, dataset_version_id, data_object_id)
  VALUES
    (v_job.organization_id, v_profile.dataset_id,
     v_profile.dataset_version_id, (p_artifact->>'id')::uuid);

  UPDATE app.map_render_jobs
  SET state = 'completed', output_object_id = (p_artifact->>'id')::uuid,
      error_code = NULL, worker_token = NULL, lease_expires_at = NULL,
      last_heartbeat_at = NULL, finished_at = clock_timestamp()
  WHERE id = v_job.id;

  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (v_job.organization_id, v_job.created_by, v_job.project_id,
     'map.render.completed', 'resource', v_job.resource_id,
     'worker:' || v_job.id::text,
     jsonb_build_object(
       'render_job_id', v_job.id,
       'profile_version_id', v_job.profile_version_id,
       'format', v_job.format::text,
       'crs', v_job.crs,
       'output_object_id', (p_artifact->>'id')::uuid,
       'output_checksum_sha256', p_artifact->>'checksum_sha256'
     ));
  RETURN true;
END;
$_$;


--
-- Name: complete_observable_build(uuid, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_observable_build(p_job_id uuid, p_coordinator_token uuid, p_result jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app', 'public'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_job app.observable_build_jobs%ROWTYPE;
  v_file jsonb;
  v_file_count integer := 0;
  v_total_bytes bigint := 0;
  v_case_count integer;
  v_expected_bucket text;
BEGIN
  SELECT * INTO v_job
  FROM app.observable_build_jobs
  WHERE id = p_job_id
  FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running'
    OR v_job.coordinator_token <> p_coordinator_token
  THEN
    RETURN false;
  END IF;
  SELECT object.bucket INTO v_expected_bucket
  FROM app.observable_source_revision_files file
  JOIN app.observable_source_objects object
    ON object.organization_id = file.organization_id
   AND object.source_project_id = file.source_project_id
   AND object.id = file.source_object_id
  WHERE file.organization_id = v_job.organization_id
    AND file.source_revision_id = v_job.source_revision_id
  ORDER BY file.position
  LIMIT 1;
  IF p_result IS NULL
    OR jsonb_typeof(p_result) <> 'object'
    OR octet_length(p_result::text) > 262144
    OR p_result->>'schemaVersion' <> 'opengeo.observable-build-result.1.0.0'
    OR p_result->>'buildJobId' <> v_job.id::text
    OR p_result->>'requestChecksumSha256' <> v_job.request_checksum_sha256
    OR p_result->>'compilerImageDigest' <> v_job.request->>'compilerImageDigest'
    OR p_result->>'inputManifestChecksumSha256'
      <> v_job.request->>'sourceManifestChecksumSha256'
    OR p_result->>'outputPrefix' <> v_job.output_prefix
    OR p_result->>'outputTreeChecksumSha256' !~ '^[0-9a-f]{64}$'
    OR p_result->'sandbox' IS DISTINCT FROM jsonb_build_object(
      'credentialMode', 'none',
      'networkPolicy', 'deny_all',
      'readOnlyInputs', true,
      'readOnlyBaseImage', true,
      'unprivilegedUser', true,
      'dockerSocket', false
    )
    OR p_result->'networkRequests' IS DISTINCT FROM '[]'::jsonb
    OR jsonb_typeof(p_result->'validationReport') <> 'object'
    OR octet_length((p_result->'validationReport')::text) > 65536
    OR jsonb_typeof(p_result->'routeManifest') <> 'array'
    OR jsonb_array_length(p_result->'routeManifest') > 128
    OR jsonb_typeof(p_result->'outputManifest') <> 'object'
    OR jsonb_typeof(p_result->'outputManifest'->'files') <> 'array'
    OR jsonb_array_length(p_result->'outputManifest'->'files') NOT BETWEEN 1 AND 512
  THEN
    RAISE EXCEPTION 'invalid Observable build result envelope';
  END IF;

  FOR v_file IN
    SELECT value FROM jsonb_array_elements(p_result->'outputManifest'->'files')
  LOOP
    v_file_count := v_file_count + 1;
    IF NOT app.observable_output_path_is_safe(v_file->>'path')
      OR (v_file->>'contentType') NOT IN (
        'text/html', 'text/css', 'text/javascript', 'application/json',
        'text/plain', 'text/csv', 'application/geo+json',
        'image/svg+xml', 'image/png', 'image/jpeg',
        'application/octet-stream', 'application/zip'
      )
      OR (v_file->>'sizeBytes')::bigint NOT BETWEEN 1 AND 16777216
      OR (v_file->>'checksumSha256') !~ '^[0-9a-f]{64}$'
      OR v_file->>'bucket' IS DISTINCT FROM v_expected_bucket
      OR v_file->>'objectKey'
        <> v_job.output_prefix || substring(v_file->>'path' FROM 6)
      OR (v_file->>'s3VersionId') IS NULL
      OR char_length(v_file->>'s3VersionId') NOT BETWEEN 1 AND 1024
      OR (v_file->>'etag') IS NULL
      OR char_length(v_file->>'etag') NOT BETWEEN 1 AND 512
    THEN
      RAISE EXCEPTION 'invalid Observable build output file';
    END IF;
    v_total_bytes := v_total_bytes + (v_file->>'sizeBytes')::bigint;
  END LOOP;
  SELECT count(DISTINCT lower(value->>'path'))::integer INTO v_case_count
  FROM jsonb_array_elements(p_result->'outputManifest'->'files');
  IF v_file_count <> v_case_count OR v_total_bytes > 33554432 THEN
    RAISE EXCEPTION 'Observable build output exceeds file or size limits';
  END IF;

  UPDATE app.observable_build_jobs
  SET state = 'succeeded', result = p_result, error_code = NULL,
      coordinator_token = NULL, lease_expires_at = NULL,
      last_heartbeat_at = NULL, finished_at = clock_timestamp(),
      updated_at = clock_timestamp()
  WHERE id = v_job.id;
  RETURN true;
END;
$_$;


--
-- Name: complete_pmtiles_derivative(uuid, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_pmtiles_derivative(p_job_id uuid, p_worker_token uuid, p_artifact jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_completed boolean;
  v_job app.pmtiles_derivative_jobs%ROWTYPE;
  v_software jsonb := jsonb_build_object(
    'workerBaseImage',
    'ghcr.io/osgeo/gdal:ubuntu-full-3.13.0@sha256:83d114a6891ae18aa175d81a14c92a96d23944667b36fde9c15c4a10215d8939',
    'gdal', '3.13.0',
    'tippecanoe', '2.79.0',
    'projNetwork', 'disabled'
  );
  v_logs jsonb := jsonb_build_array(
    'Immutable request and source seals matched.',
    'Network-disabled GDAL and Tippecanoe PMTiles output validated.',
    'Output object and derivative lineage committed atomically.'
  );
BEGIN
  v_completed := app.complete_pmtiles_derivative_without_execution_receipt(
    p_job_id, p_worker_token, p_artifact
  );
  IF NOT v_completed THEN RETURN false; END IF;

  SELECT * INTO v_job
  FROM app.pmtiles_derivative_jobs
  WHERE id = p_job_id AND state = 'completed';

  INSERT INTO app.processing_execution_receipts
    (organization_id, project_id, job_kind, pmtiles_job_id, tool_id,
     tool_version, request_checksum_sha256, source_object_id, output_object_id,
     output_checksum_sha256, software, logs, verification_status,
     receipt_checksum_sha256, initiated_by, recorded_at)
  VALUES
    (v_job.organization_id, v_job.project_id, 'pmtiles-derivative', v_job.id,
     'vector-to-pmtiles', '1.0.0', v_job.request_checksum_sha256,
     v_job.source_object_id, v_job.output_object_id,
     v_job.output_checksum_sha256, v_software, v_logs, 'pinned',
     app.processing_execution_receipt_checksum(
       'pmtiles-derivative', NULL, v_job.id, 'vector-to-pmtiles', '1.0.0',
       v_job.request_checksum_sha256, v_job.source_object_id,
       v_job.output_object_id, v_job.output_checksum_sha256,
       v_software, v_logs, 'pinned'
     ),
     v_job.created_by, v_job.finished_at);
  RETURN true;
END;
$$;


--
-- Name: FUNCTION complete_pmtiles_derivative(p_job_id uuid, p_worker_token uuid, p_artifact jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.complete_pmtiles_derivative(p_job_id uuid, p_worker_token uuid, p_artifact jsonb) IS 'Completes one validated PMTiles derivative and atomically records a pinned, checksum-linked execution receipt.';


--
-- Name: complete_pmtiles_derivative_without_execution_receipt(uuid, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_pmtiles_derivative_without_execution_receipt(p_job_id uuid, p_worker_token uuid, p_artifact jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE v_job app.pmtiles_derivative_jobs%ROWTYPE; v_source app.data_objects%ROWTYPE;
  v_expected_key text; v_object_id uuid;
BEGIN
  SELECT * INTO v_job FROM app.pmtiles_derivative_jobs
  WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token
    OR v_job.lease_expires_at <= clock_timestamp()
  THEN RETURN false; END IF;
  SELECT * INTO v_source FROM app.data_objects
  WHERE organization_id = v_job.organization_id AND id = v_job.source_object_id;
  v_expected_key := format(
    'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/tiles/custom/%s.pmtiles',
    v_job.organization_id, v_job.project_id, v_job.dataset_id,
    v_job.dataset_version_id, v_job.id
  );
  IF p_artifact IS NULL OR jsonb_typeof(p_artifact) <> 'object'
    OR octet_length(p_artifact::text) > 8192 OR (p_artifact->>'role') <> 'tile'
    OR (p_artifact->>'bucket') <> v_source.bucket
    OR (p_artifact->>'object_key') <> v_expected_key
    OR (p_artifact->>'s3_version_id') IN ('', 'null')
    OR char_length(p_artifact->>'s3_version_id') > 1024
    OR (p_artifact->>'etag') !~ '^[A-Fa-f0-9]{16,128}$'
    OR (p_artifact->>'content_type') <> 'application/vnd.pmtiles'
    OR (p_artifact->>'size_bytes')::bigint NOT BETWEEN 1 AND 2147483648
    OR (p_artifact->>'checksum_sha256') !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'invalid PMTiles derivative artifact'; END IF;
  v_object_id := (p_artifact->>'id')::uuid;
  INSERT INTO app.data_objects
    (id, organization_id, dataset_id, role, bucket, object_key,
     s3_version_id, etag, content_type, size_bytes, checksum_sha256, created_by)
  VALUES
    (v_object_id, v_job.organization_id, v_job.dataset_id, 'tile',
     p_artifact->>'bucket', p_artifact->>'object_key',
     p_artifact->>'s3_version_id', lower(p_artifact->>'etag'),
     p_artifact->>'content_type', (p_artifact->>'size_bytes')::bigint,
     p_artifact->>'checksum_sha256', v_job.created_by);
  INSERT INTO app.dataset_version_objects
    (organization_id, dataset_id, dataset_version_id, data_object_id)
  VALUES
    (v_job.organization_id, v_job.dataset_id,
     v_job.dataset_version_id, v_object_id);
  INSERT INTO app.dataset_version_derivative_lineage
    (organization_id, dataset_id, dataset_version_id, source_object_id,
     output_object_id, pmtiles_job_id, recipe)
  VALUES
    (v_job.organization_id, v_job.dataset_id, v_job.dataset_version_id,
     v_job.source_object_id, v_object_id, v_job.id, 'gdal-pmtiles-v1');
  UPDATE app.pmtiles_derivative_jobs
  SET state = 'completed', output_object_id = v_object_id,
      output_size_bytes = (p_artifact->>'size_bytes')::bigint,
      output_checksum_sha256 = p_artifact->>'checksum_sha256', error_code = NULL,
      worker_token = NULL, lease_expires_at = NULL, last_heartbeat_at = NULL,
      finished_at = clock_timestamp()
  WHERE id = v_job.id;
  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (v_job.organization_id, v_job.created_by, v_job.project_id,
     'dataset.pmtiles.derivative.completed', 'dataset', v_job.dataset_id,
     'worker:' || v_job.id::text,
     jsonb_build_object(
       'pmtiles_job_id', v_job.id,
       'dataset_version_id', v_job.dataset_version_id,
       'source_object_id', v_job.source_object_id,
       'output_object_id', v_object_id,
       'checksum_sha256', p_artifact->>'checksum_sha256'
     ));
  RETURN true;
END;
$_$;


--
-- Name: complete_repository_object_copy(uuid, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_repository_object_copy(p_job_id uuid, p_worker_token uuid, p_artifact jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_job app.repository_object_copy_jobs%ROWTYPE;
  v_estimate app.repository_object_copy_estimates%ROWTYPE;
  v_object_id uuid;
  v_version_id uuid := gen_random_uuid();
  v_processing_job_id uuid := gen_random_uuid();
  v_expected_key text;
  v_filename text;
BEGIN
  SELECT * INTO v_job FROM app.repository_object_copy_jobs
  WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token
    OR v_job.lease_expires_at <= clock_timestamp()
  THEN RETURN false; END IF;
  SELECT * INTO v_estimate FROM app.repository_object_copy_estimates
  WHERE organization_id = v_job.organization_id AND id = v_job.estimate_id;
  v_filename := 'source.' || CASE v_estimate.output_format::text
    WHEN 'geojson' THEN 'geojson' WHEN 'csv' THEN 'csv'
    WHEN 'shapefile' THEN 'zip' WHEN 'geopackage' THEN 'gpkg'
    WHEN 'geoparquet' THEN 'parquet' WHEN 'cog' THEN 'tif'
    WHEN 'pmtiles' THEN 'pmtiles' WHEN 'png' THEN 'png'
    WHEN 'jpeg' THEN 'jpg' WHEN 'pdf' THEN 'pdf' WHEN 'odt' THEN 'odt'
  END;
  v_expected_key := format(
    'organizations/%s/projects/%s/datasets/%s/uploads/%s/original/%s',
    v_job.organization_id, v_job.project_id, v_job.destination_dataset_id,
    v_job.id, v_filename
  );
  IF p_artifact IS NULL OR jsonb_typeof(p_artifact) <> 'object'
    OR octet_length(p_artifact::text) > 8192
    OR (p_artifact->>'role') <> 'original'
    OR (p_artifact->>'bucket') <> v_job.destination_bucket
    OR (p_artifact->>'object_key') <> v_expected_key
    OR (p_artifact->>'s3_version_id') IN ('', 'null')
    OR char_length(p_artifact->>'s3_version_id') > 1024
    OR (p_artifact->>'etag') !~ '^[A-Fa-f0-9]{16,128}$'
    OR (p_artifact->>'content_type') <> v_estimate.output_content_type
    OR (p_artifact->>'size_bytes')::bigint <> v_estimate.maximum_output_bytes
    OR (p_artifact->>'checksum_sha256') !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'invalid repository copy artifact'; END IF;
  v_object_id := (p_artifact->>'id')::uuid;
  INSERT INTO app.data_objects
    (id, organization_id, dataset_id, role, bucket, object_key,
     s3_version_id, etag, content_type, size_bytes, checksum_sha256, created_by)
  VALUES
    (v_object_id, v_job.organization_id, v_job.destination_dataset_id,
     'original', p_artifact->>'bucket', p_artifact->>'object_key',
     p_artifact->>'s3_version_id', lower(p_artifact->>'etag'),
     p_artifact->>'content_type', (p_artifact->>'size_bytes')::bigint,
     p_artifact->>'checksum_sha256', v_job.created_by);
  INSERT INTO app.upload_intents
    (id, organization_id, project_id, dataset_id, created_by,
     original_filename, content_type, expected_size_bytes, expected_sha256,
     bucket, object_key, state, expires_at, completed_at, completed_object_id)
  VALUES
    (v_job.id, v_job.organization_id, v_job.project_id,
     v_job.destination_dataset_id, v_job.created_by, v_filename,
     p_artifact->>'content_type', (p_artifact->>'size_bytes')::bigint,
     p_artifact->>'checksum_sha256', p_artifact->>'bucket',
     p_artifact->>'object_key', 'completed', clock_timestamp() + interval '1 day',
     clock_timestamp(), v_object_id);
  INSERT INTO app.dataset_versions
    (id, organization_id, dataset_id, version_number, parent_version_id,
     original_object_id, state, change_message, created_by)
  VALUES
    (v_version_id, v_job.organization_id, v_job.destination_dataset_id, 1, NULL,
     v_object_id, 'queued', 'Protected copy of exact repository object version',
     v_job.created_by);
  UPDATE app.datasets
  SET status = 'processing', current_version_id = v_version_id,
      updated_by = v_job.created_by, updated_at = clock_timestamp()
  WHERE organization_id = v_job.organization_id
    AND id = v_job.destination_dataset_id AND status = 'draft'
    AND current_version_id IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'repository copy destination changed'; END IF;
  INSERT INTO app.processing_jobs
    (id, organization_id, project_id, dataset_id, dataset_version_id,
     job_type, parameters, created_by)
  VALUES
    (v_processing_job_id, v_job.organization_id, v_job.project_id,
     v_job.destination_dataset_id, v_version_id, 'dataset.ingest',
     jsonb_build_object(
       'upload_id', v_job.id, 'object_id', v_object_id,
       's3_version_id', p_artifact->>'s3_version_id',
       'repository_object_copy_job_id', v_job.id
     ), v_job.created_by);
  INSERT INTO app.dataset_version_repository_object_lineage
    (organization_id, destination_dataset_id, destination_dataset_version_id,
     source_dataset_id, copy_job_id, retrieved_at)
  VALUES
    (v_job.organization_id, v_job.destination_dataset_id, v_version_id,
     v_job.source_dataset_id, v_job.id, clock_timestamp());
  UPDATE app.repository_object_copy_jobs
  SET state = 'completed', output_object_id = v_object_id,
      output_dataset_version_id = v_version_id, error_code = NULL,
      worker_token = NULL, lease_expires_at = NULL,
      last_heartbeat_at = NULL, finished_at = clock_timestamp()
  WHERE id = v_job.id;
  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (v_job.organization_id, v_job.created_by, v_job.project_id,
     'dataset.repository.copy.completed', 'dataset', v_job.destination_dataset_id,
     v_job.request_id, jsonb_build_object(
       'copy_job_id', v_job.id, 'source_dataset_id', v_job.source_dataset_id,
       'destination_dataset_version_id', v_version_id,
       'output_checksum_sha256', p_artifact->>'checksum_sha256'
     ));
  RETURN true;
END;
$_$;


--
-- Name: complete_spatial_coverage_derivative(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_spatial_coverage_derivative(p_job_id uuid, p_worker_token uuid, p_artifact jsonb, p_metadata jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_completed boolean;
  v_job record;
  v_software jsonb := jsonb_build_object(
    'workerBaseImage',
    'ghcr.io/osgeo/gdal:ubuntu-full-3.13.0@sha256:83d114a6891ae18aa175d81a14c92a96d23944667b36fde9c15c4a10215d8939',
    'gdal', '3.13.0',
    'projNetwork', 'disabled'
  );
  v_logs jsonb := jsonb_build_array(
    'Immutable request and source seals matched.',
    'Network-disabled GDAL output metadata and checksum validated.',
    'Output object and derivative result committed atomically.'
  );
BEGIN
  v_completed := app.complete_spatial_coverage_derivative_without_execution_receipt(
    p_job_id, p_worker_token, p_artifact, p_metadata
  );
  IF NOT v_completed THEN RETURN false; END IF;

  SELECT
    job.organization_id, job.project_id, job.id,
    job.request_checksum_sha256, coverage.data_object_id AS source_object_id,
    job.output_object_id, job.output_checksum_sha256, job.created_by,
    job.finished_at
  INTO v_job
  FROM app.spatial_coverage_derivative_jobs job
  JOIN app.spatial_service_coverages coverage
    ON coverage.organization_id = job.organization_id
   AND coverage.id = job.coverage_id
  WHERE job.id = p_job_id AND job.state = 'completed';

  INSERT INTO app.processing_execution_receipts
    (organization_id, project_id, job_kind, coverage_job_id, tool_id,
     tool_version, request_checksum_sha256, source_object_id, output_object_id,
     output_checksum_sha256, software, logs, verification_status,
     receipt_checksum_sha256, initiated_by, recorded_at)
  VALUES
    (v_job.organization_id, v_job.project_id, 'coverage-derivative', v_job.id,
     'raster-to-cog', '1.0.0', v_job.request_checksum_sha256,
     v_job.source_object_id, v_job.output_object_id,
     v_job.output_checksum_sha256, v_software, v_logs, 'pinned',
     app.processing_execution_receipt_checksum(
       'coverage-derivative', v_job.id, NULL, 'raster-to-cog', '1.0.0',
       v_job.request_checksum_sha256, v_job.source_object_id,
       v_job.output_object_id, v_job.output_checksum_sha256,
       v_software, v_logs, 'pinned'
     ),
     v_job.created_by, v_job.finished_at);
  RETURN true;
END;
$$;


--
-- Name: FUNCTION complete_spatial_coverage_derivative(p_job_id uuid, p_worker_token uuid, p_artifact jsonb, p_metadata jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.complete_spatial_coverage_derivative(p_job_id uuid, p_worker_token uuid, p_artifact jsonb, p_metadata jsonb) IS 'Completes one validated coverage derivative and atomically records a pinned, checksum-linked execution receipt.';


--
-- Name: complete_spatial_coverage_derivative_reclamation(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_spatial_coverage_derivative_reclamation(p_reclamation_id uuid, p_worker_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_plan app.spatial_coverage_derivative_reclamations%ROWTYPE;
  v_deleted integer;
BEGIN
  SELECT * INTO v_plan
  FROM app.spatial_coverage_derivative_reclamations
  WHERE id = p_reclamation_id FOR UPDATE;
  IF NOT FOUND OR v_plan.state <> 'running'
    OR v_plan.worker_token <> p_worker_token
    OR v_plan.lease_expires_at <= clock_timestamp()
    OR v_plan.delete_started_at IS NULL
    OR app.coverage_derivative_object_is_referenced(
      v_plan.organization_id, v_plan.output_object_id
    )
  THEN
    RETURN false;
  END IF;
  PERFORM 1
  FROM app.data_objects
  WHERE organization_id = v_plan.organization_id
    AND id = v_plan.output_object_id
    AND bucket = v_plan.sealed_bucket
    AND object_key = v_plan.sealed_object_key
    AND s3_version_id = v_plan.sealed_storage_version_id
    AND lower(etag) = v_plan.sealed_etag
    AND content_type = v_plan.sealed_content_type
    AND size_bytes = v_plan.sealed_size_bytes
    AND checksum_sha256 = v_plan.sealed_checksum_sha256
  FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  DELETE FROM app.dataset_version_objects
  WHERE organization_id = v_plan.organization_id
    AND data_object_id = v_plan.output_object_id;
  DELETE FROM app.data_objects
  WHERE organization_id = v_plan.organization_id
    AND id = v_plan.output_object_id
    AND bucket = v_plan.sealed_bucket
    AND object_key = v_plan.sealed_object_key
    AND s3_version_id = v_plan.sealed_storage_version_id
    AND lower(etag) = v_plan.sealed_etag
    AND content_type = v_plan.sealed_content_type
    AND size_bytes = v_plan.sealed_size_bytes
    AND checksum_sha256 = v_plan.sealed_checksum_sha256;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  IF v_deleted <> 1 THEN RETURN false; END IF;
  UPDATE app.spatial_coverage_derivative_reclamations
  SET state = 'completed', error_code = NULL, worker_token = NULL,
      lease_expires_at = NULL, last_heartbeat_at = NULL,
      finished_at = clock_timestamp()
  WHERE id = v_plan.id;
  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (v_plan.organization_id, v_plan.created_by, v_plan.project_id,
     'spatial_service.coverage.derivative.reclamation.completed',
     'spatial_service', v_plan.service_id, 'worker:' || v_plan.id::text,
     jsonb_build_object(
       'reclamation_id', v_plan.id,
       'derivative_job_id', v_plan.derivative_job_id,
       'coverage_id', v_plan.coverage_id,
       'output_object_id', v_plan.output_object_id,
       'size_bytes', v_plan.sealed_size_bytes,
       'checksum_sha256', v_plan.sealed_checksum_sha256
     ));
  RETURN true;
END;
$$;


--
-- Name: complete_spatial_coverage_derivative_without_execution_receipt(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_spatial_coverage_derivative_without_execution_receipt(p_job_id uuid, p_worker_token uuid, p_artifact jsonb, p_metadata jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_job app.spatial_coverage_derivative_jobs%ROWTYPE;
  v_coverage app.spatial_service_coverages%ROWTYPE;
  v_expected_key text;
  v_position integer;
  v_source_index integer;
BEGIN
  SELECT * INTO v_job FROM app.spatial_coverage_derivative_jobs
  WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token
    OR v_job.lease_expires_at <= clock_timestamp()
  THEN RETURN false; END IF;
  SELECT * INTO v_coverage FROM app.spatial_service_coverages
  WHERE organization_id = v_job.organization_id AND id = v_job.coverage_id;
  v_expected_key := format(
    'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/coverages/%s.tif',
    v_job.organization_id, v_job.project_id, v_coverage.dataset_id,
    v_coverage.dataset_version_id, v_job.id
  );
  IF p_artifact IS NULL OR jsonb_typeof(p_artifact) <> 'object'
    OR octet_length(p_artifact::text) > 8192
    OR (p_artifact->>'role') <> 'derived'
    OR (p_artifact->>'bucket') <> v_coverage.sealed_bucket
    OR (p_artifact->>'object_key') <> v_expected_key
    OR (p_artifact->>'s3_version_id') IN ('', 'null')
    OR (p_artifact->>'etag') !~ '^[A-Fa-f0-9]{16,128}$'
    OR (p_artifact->>'content_type') <> 'image/tiff'
    OR (p_artifact->>'size_bytes')::bigint NOT BETWEEN 1 AND 536870912
    OR (p_artifact->>'checksum_sha256') !~ '^[0-9a-f]{64}$'
    OR p_metadata IS NULL OR jsonb_typeof(p_metadata) <> 'object'
    OR octet_length(p_metadata::text) > 65536
    OR (p_metadata->>'cog_layout_verified')::boolean IS NOT TRUE
    OR (p_metadata->>'crs') <> v_job.target_crs
    OR (p_metadata->>'width')::integer <> v_job.target_width
    OR (p_metadata->>'height')::integer <> v_job.target_height
    OR (p_metadata->>'band_count')::integer <> jsonb_array_length(v_job.band_indexes)
    OR jsonb_typeof(p_metadata->'extent') <> 'array'
    OR jsonb_array_length(p_metadata->'extent') <> 4
    OR jsonb_typeof(p_metadata->'bands') <> 'array'
    OR jsonb_array_length(p_metadata->'bands') <> jsonb_array_length(v_job.band_indexes)
  THEN RAISE EXCEPTION 'invalid coverage derivative artifact'; END IF;
  FOR v_position IN 0..jsonb_array_length(v_job.band_indexes) - 1 LOOP
    v_source_index := (v_job.band_indexes->>v_position)::integer;
    IF jsonb_typeof(p_metadata->'bands'->v_position) <> 'object'
      OR (p_metadata->'bands'->v_position->>'index')::integer
         IS DISTINCT FROM v_position + 1
      OR (p_metadata->'bands'->v_position->>'source_index')::integer
         IS DISTINCT FROM v_source_index
      OR (p_metadata->'bands'->v_position->>'data_type')
         IS DISTINCT FROM
         (v_coverage.sealed_bands->(v_source_index - 1)->>'data_type')
    THEN RAISE EXCEPTION 'invalid coverage derivative range lineage'; END IF;
  END LOOP;
  INSERT INTO app.data_objects
    (id, organization_id, dataset_id, role, bucket, object_key,
     s3_version_id, etag, content_type, size_bytes, checksum_sha256, created_by)
  VALUES
    ((p_artifact->>'id')::uuid, v_job.organization_id, v_coverage.dataset_id,
     'derived', p_artifact->>'bucket', p_artifact->>'object_key',
     p_artifact->>'s3_version_id', lower(p_artifact->>'etag'),
     p_artifact->>'content_type', (p_artifact->>'size_bytes')::bigint,
     p_artifact->>'checksum_sha256', v_job.created_by);
  INSERT INTO app.dataset_version_objects
    (organization_id, dataset_id, dataset_version_id, data_object_id)
  VALUES
    (v_job.organization_id, v_coverage.dataset_id,
     v_coverage.dataset_version_id, (p_artifact->>'id')::uuid);
  UPDATE app.spatial_coverage_derivative_jobs
  SET state = 'completed', output_object_id = (p_artifact->>'id')::uuid,
      output_crs = p_metadata->>'crs', output_extent = p_metadata->'extent',
      output_width = (p_metadata->>'width')::integer,
      output_height = (p_metadata->>'height')::integer,
      output_band_count = (p_metadata->>'band_count')::integer,
      output_bands = p_metadata->'bands', output_content_type = 'image/tiff',
      output_size_bytes = (p_artifact->>'size_bytes')::bigint,
      output_checksum_sha256 = p_artifact->>'checksum_sha256',
      error_code = NULL, worker_token = NULL, lease_expires_at = NULL,
      last_heartbeat_at = NULL, finished_at = clock_timestamp()
  WHERE id = v_job.id;
  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (v_job.organization_id, v_job.created_by, v_job.project_id,
     'spatial_service.coverage.derivative.completed', 'spatial_service',
     v_job.service_id, 'worker:' || v_job.id::text,
     jsonb_build_object(
       'derivative_job_id', v_job.id, 'coverage_id', v_job.coverage_id,
       'output_object_id', (p_artifact->>'id')::uuid,
       'output_checksum_sha256', p_artifact->>'checksum_sha256'
     ));
  RETURN true;
END;
$_$;


--
-- Name: complete_spatial_tile_cache_reclamation_item(uuid, integer, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_spatial_tile_cache_reclamation_item(p_reclamation_id uuid, p_item_position integer, p_worker_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_item app.spatial_tile_cache_reclamation_items%ROWTYPE;
  v_deleted integer;
BEGIN
  SELECT item.* INTO v_item
  FROM app.spatial_tile_cache_reclamations reclamation
  JOIN app.spatial_tile_cache_reclamation_items item
    ON item.organization_id = reclamation.organization_id
   AND item.reclamation_id = reclamation.id
  WHERE reclamation.id = p_reclamation_id
    AND reclamation.state = 'running'
    AND reclamation.worker_token = p_worker_token
    AND reclamation.lease_expires_at > clock_timestamp()
    AND item.position = p_item_position
    AND item.state = 'running' AND item.delete_started_at IS NOT NULL
  FOR UPDATE OF reclamation, item;
  IF NOT FOUND OR app.render_cache_output_is_referenced(
    v_item.organization_id, v_item.render_job_id, v_item.output_object_id
  ) THEN RETURN false; END IF;
  PERFORM 1 FROM app.data_objects object
  WHERE object.organization_id = v_item.organization_id
    AND object.id = v_item.output_object_id
    AND object.bucket = v_item.sealed_bucket
    AND object.object_key = v_item.sealed_object_key
    AND object.s3_version_id = v_item.sealed_storage_version_id
    AND lower(object.etag) = v_item.sealed_etag
    AND object.content_type = v_item.sealed_content_type
    AND object.size_bytes = v_item.sealed_size_bytes
    AND object.checksum_sha256 = v_item.sealed_checksum_sha256
  FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  DELETE FROM app.dataset_version_objects
  WHERE organization_id = v_item.organization_id
    AND data_object_id = v_item.output_object_id;
  DELETE FROM app.data_objects object
  WHERE object.organization_id = v_item.organization_id
    AND object.id = v_item.output_object_id
    AND object.bucket = v_item.sealed_bucket
    AND object.object_key = v_item.sealed_object_key
    AND object.s3_version_id = v_item.sealed_storage_version_id
    AND lower(object.etag) = v_item.sealed_etag
    AND object.content_type = v_item.sealed_content_type
    AND object.size_bytes = v_item.sealed_size_bytes
    AND object.checksum_sha256 = v_item.sealed_checksum_sha256;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  IF v_deleted <> 1 THEN RETURN false; END IF;
  UPDATE app.spatial_tile_cache_reclamation_items
  SET state = 'completed', finished_at = clock_timestamp()
  WHERE organization_id = v_item.organization_id
    AND reclamation_id = v_item.reclamation_id
    AND position = v_item.position;
  RETURN true;
END;
$$;


--
-- Name: complete_user_dataset_connection_verification(uuid, uuid, boolean, boolean, boolean, integer, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.complete_user_dataset_connection_verification(p_verification_id uuid, p_worker_token uuid, p_bucket_access_confirmed boolean, p_object_access_confirmed boolean, p_deny_canaries_confirmed boolean, p_objects_observed integer, p_sanitized_error_code text, p_duration_ms integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job app.user_dataset_connection_verifications%ROWTYPE;
  v_succeeded boolean := p_sanitized_error_code IS NULL;
BEGIN
  IF p_duration_ms NOT BETWEEN 0 AND 25000
    OR p_objects_observed NOT BETWEEN 0 AND 1
    OR (v_succeeded AND NOT (
      p_bucket_access_confirmed AND p_object_access_confirmed
      AND p_deny_canaries_confirmed AND p_objects_observed = 1
    ))
    OR (NOT v_succeeded AND p_sanitized_error_code NOT IN (
      'assume_role_denied', 'bucket_access_denied', 'credentials_rejected',
      'deny_canary_failed', 'object_access_denied', 'region_mismatch',
      'secret_invalid', 'verification_cancelled', 'verification_failed',
      'verification_timeout'
    ))
  THEN
    RAISE EXCEPTION 'invalid user dataset verification result';
  END IF;

  SELECT verification.* INTO v_job
  FROM app.user_dataset_connection_verifications verification
  WHERE verification.id = p_verification_id
  FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token THEN
    RETURN false;
  END IF;

  UPDATE app.user_dataset_connection_verifications
  SET state = CASE WHEN v_succeeded
      THEN 'succeeded'::app.user_dataset_verification_state
      ELSE 'failed'::app.user_dataset_verification_state END,
      worker_token = NULL, lease_expires_at = NULL,
      bucket_access_confirmed = p_bucket_access_confirmed,
      object_access_confirmed = p_object_access_confirmed,
      deny_canaries_confirmed = p_deny_canaries_confirmed,
      objects_observed = p_objects_observed,
      sanitized_error_code = p_sanitized_error_code,
      duration_ms = p_duration_ms,
      finished_at = clock_timestamp()
  WHERE id = v_job.id;

  UPDATE app.user_dataset_connections
  SET status = CASE WHEN v_succeeded
      THEN 'verified'::app.dataset_connection_status
      ELSE 'error'::app.dataset_connection_status END,
      last_verified_at = CASE WHEN v_succeeded THEN clock_timestamp() ELSE NULL END,
      sanitized_error_code = p_sanitized_error_code
  WHERE organization_id = v_job.organization_id
    AND owner_user_id = v_job.owner_user_id
    AND id = v_job.connection_id
    AND target_revision = v_job.target_revision
    AND credential_revision = v_job.credential_revision
    AND status <> 'disabled';

  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type, resource_type,
     resource_id, request_id, payload)
  VALUES
    (v_job.organization_id, v_job.requested_by, NULL,
     CASE WHEN v_succeeded
       THEN 'dataset_connection.verification.succeeded'
       ELSE 'dataset_connection.verification.failed' END,
     'dataset_connection', v_job.connection_id,
     'dataset-verifier:' || v_job.id::text,
     jsonb_build_object(
       'verification_id', v_job.id,
       'target_revision', v_job.target_revision,
       'credential_revision', v_job.credential_revision,
       'attempt_count', v_job.attempt_count,
       'duration_ms', p_duration_ms,
       'bucket_access_confirmed', p_bucket_access_confirmed,
       'object_access_confirmed', p_object_access_confirmed,
       'deny_canaries_confirmed', p_deny_canaries_confirmed,
       'objects_observed', p_objects_observed,
       'error_code', p_sanitized_error_code
     ));
  RETURN true;
END;
$$;


--
-- Name: consume_observable_preview_capability(uuid, uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.consume_observable_preview_capability(p_capability_id uuid, p_organization_id uuid, p_user_id uuid, p_token_checksum_sha256 text) RETURNS TABLE(output_prefix text, entry_file text, cookie_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app', 'public'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_capability app.observable_preview_capabilities%ROWTYPE;
  v_build app.observable_build_jobs%ROWTYPE;
  v_entry_file text;
BEGIN
  IF p_capability_id IS NULL OR p_organization_id IS NULL OR p_user_id IS NULL
    OR p_token_checksum_sha256 !~ '^[0-9a-f]{64}$'
    OR p_organization_id IS DISTINCT FROM app.current_organization_id()
    OR p_user_id IS DISTINCT FROM app.current_user_id()
  THEN
    RETURN;
  END IF;
  SELECT * INTO v_capability
  FROM app.observable_preview_capabilities capability
  WHERE capability.id = p_capability_id
    AND capability.organization_id = p_organization_id
    AND capability.requested_by = p_user_id
    AND capability.token_checksum_sha256 = p_token_checksum_sha256
  FOR UPDATE;
  IF NOT FOUND OR v_capability.consumed_at IS NOT NULL
    OR v_capability.expires_at <= clock_timestamp()
  THEN
    RETURN;
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM app.organization_memberships membership
    WHERE membership.organization_id = v_capability.organization_id
      AND membership.user_id = v_capability.requested_by
      AND (
        membership.role = 'admin'
        OR EXISTS (
          SELECT 1
          FROM app.project_memberships project_membership
          WHERE project_membership.organization_id = v_capability.organization_id
            AND project_membership.project_id = v_capability.project_id
            AND project_membership.user_id = v_capability.requested_by
            AND project_membership.role IN ('owner', 'editor', 'reviewer', 'viewer')
        )
      )
  ) THEN
    RETURN;
  END IF;
  SELECT * INTO v_build
  FROM app.observable_build_jobs build
  WHERE build.organization_id = v_capability.organization_id
    AND build.project_id = v_capability.project_id
    AND build.id = v_capability.build_job_id
    AND build.state = 'succeeded'
  FOR SHARE;
  IF NOT FOUND OR v_build.result IS NULL THEN
    RETURN;
  END IF;
  SELECT route->>'file' INTO v_entry_file
  FROM jsonb_array_elements(v_build.result->'routeManifest') route
  WHERE route->>'path' = '/'
  LIMIT 1;
  IF v_entry_file IS NULL
    OR NOT app.observable_output_path_is_safe(v_entry_file)
    OR NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_build.result->'outputManifest'->'files') file
      WHERE file->>'path' = v_entry_file
        AND file->>'contentType' = 'text/html'
        AND file->>'objectKey'
          = v_build.output_prefix || substring(v_entry_file FROM 6)
    )
  THEN
    RETURN;
  END IF;
  UPDATE app.observable_preview_capabilities capability
  SET consumed_at = clock_timestamp()
  WHERE capability.id = v_capability.id;
  RETURN QUERY SELECT
    v_build.output_prefix,
    v_entry_file,
    clock_timestamp() + interval '15 minutes';
END;
$_$;


--
-- Name: FUNCTION consume_observable_preview_capability(p_capability_id uuid, p_organization_id uuid, p_user_id uuid, p_token_checksum_sha256 text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.consume_observable_preview_capability(p_capability_id uuid, p_organization_id uuid, p_user_id uuid, p_token_checksum_sha256 text) IS 'Consume one exact unexpired capability only while requester authorization and successful immutable build output still match.';


--
-- Name: coverage_derivative_object_is_referenced(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.coverage_derivative_object_is_referenced(p_organization_id uuid, p_object_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_referenced boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM app.governed_resource_versions version
    WHERE version.organization_id = p_organization_id
      AND version.content::text LIKE '%' || p_object_id::text || '%'
  ) INTO v_referenced;
  IF v_referenced OR to_regclass('app.project_site_editions') IS NULL THEN
    RETURN v_referenced;
  END IF;
  EXECUTE
    'SELECT EXISTS (
       SELECT 1 FROM app.project_site_editions edition
       WHERE edition.organization_id = $1
         AND edition.manifest::text LIKE ''%'' || $2::text || ''%''
     )'
  INTO v_referenced
  USING p_organization_id, p_object_id;
  RETURN v_referenced;
END;
$_$;


--
-- Name: create_project_site_publication_destination(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.create_project_site_publication_destination() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO app.project_site_publication_destinations
    (organization_id, project_id, site_id, revision, reach, listed_slug,
     is_primary, configured_by)
  VALUES
    (NEW.organization_id, NEW.project_id, NEW.id, 1, 'unpublished',
     lower(NEW.slug), false, NEW.created_by);
  RETURN NEW;
END;
$$;


