--
-- Name: disable_geonode_federation_source(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.disable_geonode_federation_source(p_organization_id uuid, p_project_id uuid, p_source_id uuid, p_actor_user_id uuid, p_request_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE v_source app.geonode_federation_sources%ROWTYPE; v_cancelled integer := 0;
BEGIN
  IF p_organization_id <> app.current_organization_id()
    OR p_actor_user_id <> app.current_user_id()
    OR COALESCE(app.effective_project_role(p_project_id, p_actor_user_id)::text, '')
      NOT IN ('owner', 'editor')
    OR p_request_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
  THEN RETURN false; END IF;
  UPDATE app.geonode_federation_sources SET status = 'disabled',
    disabled_at = clock_timestamp()
  WHERE organization_id = p_organization_id AND project_id = p_project_id
    AND id = p_source_id AND status = 'active'
  RETURNING * INTO v_source;
  IF NOT FOUND THEN
    RETURN EXISTS (
      SELECT 1 FROM app.geonode_federation_sources source
      WHERE source.organization_id = p_organization_id
        AND source.project_id = p_project_id AND source.id = p_source_id
        AND source.status = 'disabled');
  END IF;
  UPDATE app.geonode_harvest_jobs SET state = 'cancelled',
    error_code = 'cancelled_by_user', worker_token = NULL,
    lease_expires_at = NULL, finished_at = clock_timestamp()
  WHERE organization_id = p_organization_id AND project_id = p_project_id
    AND source_id = p_source_id AND state IN ('queued', 'running');
  GET DIAGNOSTICS v_cancelled = ROW_COUNT;
  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES (v_source.organization_id, p_actor_user_id, v_source.project_id,
    'federation.geonode.source.disabled', 'geonode_federation_source', v_source.id,
    p_request_id, jsonb_build_object(
      'source_fingerprint_sha256', v_source.source_fingerprint_sha256,
      'cancelled_harvest_jobs', v_cancelled));
  RETURN true;
END;
$_$;


--
-- Name: discard_page_working_draft(uuid, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.discard_page_working_draft(p_organization_id uuid, p_project_id uuid, p_resource_id uuid, p_owner_user_id uuid, p_expected_base_resource_version bigint, p_expected_revision_number bigint DEFAULT NULL::bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_revision bigint;
BEGIN
  IF p_organization_id IS DISTINCT FROM app.current_organization_id()
    OR p_owner_user_id IS DISTINCT FROM app.current_user_id()
  THEN
    RAISE EXCEPTION 'page working draft discard scope is invalid';
  END IF;
  SELECT current_revision_number INTO v_revision
  FROM app.page_working_drafts
  WHERE organization_id = p_organization_id
    AND project_id = p_project_id
    AND resource_id = p_resource_id
    AND owner_user_id = p_owner_user_id
    AND base_resource_version = p_expected_base_resource_version
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  IF p_expected_revision_number IS NOT NULL
    AND p_expected_revision_number <> v_revision
  THEN
    RAISE EXCEPTION 'page working draft revision conflict';
  END IF;
  DELETE FROM app.page_working_drafts
  WHERE organization_id = p_organization_id
    AND project_id = p_project_id
    AND resource_id = p_resource_id
    AND owner_user_id = p_owner_user_id
    AND base_resource_version = p_expected_base_resource_version;
  RETURN true;
END;
$$;


--
-- Name: FUNCTION discard_page_working_draft(p_organization_id uuid, p_project_id uuid, p_resource_id uuid, p_owner_user_id uuid, p_expected_base_resource_version bigint, p_expected_revision_number bigint); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.discard_page_working_draft(p_organization_id uuid, p_project_id uuid, p_resource_id uuid, p_owner_user_id uuid, p_expected_base_resource_version bigint, p_expected_revision_number bigint) IS 'Deletes only the current user draft after an explicit CAS discard or matching page checkpoint.';


--
-- Name: effective_project_role(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.effective_project_role(p_project_id uuid, p_user_id uuid DEFAULT app.current_user_id()) RETURNS app.project_role
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'app'
    AS $$
  SELECT candidate.role
  FROM (
    SELECT direct_membership.role
    FROM app.project_memberships direct_membership
    WHERE direct_membership.organization_id = app.current_organization_id()
      AND direct_membership.project_id = p_project_id
      AND direct_membership.user_id = p_user_id

    UNION ALL

    SELECT team_grant.role
    FROM app.project_team_grants team_grant
    JOIN app.teams team
      ON team.organization_id = team_grant.organization_id
     AND team.id = team_grant.team_id
     AND team.status = 'active'
    JOIN app.team_memberships team_membership
      ON team_membership.organization_id = team_grant.organization_id
     AND team_membership.team_id = team_grant.team_id
     AND team_membership.user_id = p_user_id
    WHERE team_grant.organization_id = app.current_organization_id()
      AND team_grant.project_id = p_project_id
  ) candidate
  ORDER BY CASE candidate.role
    WHEN 'owner' THEN 1
    WHEN 'editor' THEN 2
    WHEN 'reviewer' THEN 3
    WHEN 'viewer' THEN 4
  END
  LIMIT 1
$$;


--
-- Name: FUNCTION effective_project_role(p_project_id uuid, p_user_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.effective_project_role(p_project_id uuid, p_user_id uuid) IS 'Strongest direct or active-team project role for one user inside the current tenant.';


--
-- Name: enforce_external_connection_revision(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_external_connection_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  expected_configuration jsonb;
  expected_revision bigint;
BEGIN
  SELECT
    jsonb_build_object(
      'provider', connection.provider::text,
      'endpointHost', connection.endpoint_host,
      'endpointPort', connection.endpoint_port,
      'databaseName', connection.database_name,
      'allowedSchemas', to_jsonb(connection.allowed_schemas),
      'readOnly', connection.read_only,
      'tlsMode', connection.tls_mode::text,
      'networkMode', connection.network_mode::text
    ),
    connection.current_revision_number
  INTO expected_configuration, expected_revision
  FROM app.external_connections connection
  WHERE connection.organization_id = NEW.organization_id
    AND connection.project_id = NEW.project_id
    AND connection.id = NEW.connection_id;

  IF expected_configuration IS NULL
    OR NEW.revision_number <> expected_revision
    OR NEW.configuration <> expected_configuration
  THEN
    RAISE EXCEPTION 'external connection revision must match its governed connection';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_external_source_copy_estimate_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_external_source_copy_estimate_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_source_type text;
  v_source_format text;
  v_source_page_size integer;
  v_maximum_features integer;
  v_page_size integer;
BEGIN
  IF NEW.created_by <> app.current_user_id() THEN
    RAISE EXCEPTION 'source-copy estimate actor mismatch';
  END IF;
  IF COALESCE(
    app.effective_project_role(NEW.project_id, NEW.created_by)::text,
    ''
  ) NOT IN ('owner', 'editor') THEN
    RAISE EXCEPTION 'source-copy estimate requires project edit access';
  END IF;
  SELECT source.source_type::text,
         revision.configuration->>'format',
         CASE
           WHEN jsonb_typeof(revision.configuration->'page_size') = 'number'
           THEN (revision.configuration->>'page_size')::integer
           ELSE NULL
         END
    INTO v_source_type, v_source_format, v_source_page_size
  FROM app.external_sources source
  JOIN app.external_source_revisions revision
    ON revision.organization_id = source.organization_id
   AND revision.dataset_id = source.dataset_id
   AND revision.version_number = NEW.source_revision_number
  JOIN app.project_datasets project_dataset
    ON project_dataset.organization_id = source.organization_id
   AND project_dataset.dataset_id = source.dataset_id
   AND project_dataset.project_id = NEW.project_id
  WHERE source.organization_id = NEW.organization_id
    AND source.dataset_id = NEW.source_dataset_id;

  IF NEW.copy_method = 'bounded_feature_capture'
    AND jsonb_typeof(NEW.capture_scope->'maximum_features') = 'number'
    AND jsonb_typeof(NEW.capture_scope->'page_size') = 'number'
  THEN
    v_maximum_features := (NEW.capture_scope->>'maximum_features')::integer;
    v_page_size := (NEW.capture_scope->>'page_size')::integer;
  END IF;

  IF NOT FOUND OR NOT (
    (v_source_type = 'pmtiles' AND NEW.copy_method = 'exact_object_copy'
      AND NEW.capture_scope = '{"kind":"exact_object"}'::jsonb
      AND NEW.maximum_requests = 1 AND NEW.output_format = 'pmtiles')
    OR (v_source_type = 'wms' AND v_source_format = 'image/png'
      AND NEW.copy_method = 'bounded_map_capture'
      AND NEW.capture_scope->>'kind' = 'bounded_image'
      AND NEW.capture_scope - ARRAY['kind', 'bounds', 'width', 'height'] = '{}'::jsonb
      AND jsonb_typeof(NEW.capture_scope->'bounds') = 'array'
      AND jsonb_array_length(NEW.capture_scope->'bounds') = 4
      AND jsonb_typeof(NEW.capture_scope->'bounds'->0) = 'number'
      AND jsonb_typeof(NEW.capture_scope->'bounds'->1) = 'number'
      AND jsonb_typeof(NEW.capture_scope->'bounds'->2) = 'number'
      AND jsonb_typeof(NEW.capture_scope->'bounds'->3) = 'number'
      AND (NEW.capture_scope->'bounds'->>0)::numeric BETWEEN -180 AND 180
      AND (NEW.capture_scope->'bounds'->>1)::numeric
        BETWEEN -85.0511287798066 AND 85.0511287798066
      AND (NEW.capture_scope->'bounds'->>2)::numeric BETWEEN -180 AND 180
      AND (NEW.capture_scope->'bounds'->>3)::numeric
        BETWEEN -85.0511287798066 AND 85.0511287798066
      AND (NEW.capture_scope->'bounds'->>0)::numeric
        < (NEW.capture_scope->'bounds'->>2)::numeric
      AND (NEW.capture_scope->'bounds'->>1)::numeric
        < (NEW.capture_scope->'bounds'->>3)::numeric
      AND jsonb_typeof(NEW.capture_scope->'width') = 'number'
      AND jsonb_typeof(NEW.capture_scope->'height') = 'number'
      AND (NEW.capture_scope->>'width')::integer BETWEEN 1 AND 4096
      AND (NEW.capture_scope->>'height')::integer BETWEEN 1 AND 4096
      AND (NEW.capture_scope->>'width')::bigint
        * (NEW.capture_scope->>'height')::bigint <= 16777216
      AND NEW.maximum_requests = 1
      AND NEW.maximum_output_bytes <= 134217728
      AND NEW.output_format = 'png')
    OR (v_source_type IN ('arcgis', 'wfs')
      AND NEW.copy_method = 'bounded_feature_capture'
      AND NEW.capture_scope->>'kind' = 'bounded_features'
      AND NEW.capture_scope
        - ARRAY['kind', 'bounds', 'maximum_features', 'page_size'] = '{}'::jsonb
      AND jsonb_typeof(NEW.capture_scope->'bounds') = 'array'
      AND jsonb_array_length(NEW.capture_scope->'bounds') = 4
      AND jsonb_typeof(NEW.capture_scope->'bounds'->0) = 'number'
      AND jsonb_typeof(NEW.capture_scope->'bounds'->1) = 'number'
      AND jsonb_typeof(NEW.capture_scope->'bounds'->2) = 'number'
      AND jsonb_typeof(NEW.capture_scope->'bounds'->3) = 'number'
      AND (NEW.capture_scope->'bounds'->>0)::numeric BETWEEN -180 AND 180
      AND (NEW.capture_scope->'bounds'->>1)::numeric BETWEEN -90 AND 90
      AND (NEW.capture_scope->'bounds'->>2)::numeric BETWEEN -180 AND 180
      AND (NEW.capture_scope->'bounds'->>3)::numeric BETWEEN -90 AND 90
      AND (NEW.capture_scope->'bounds'->>0)::numeric
        < (NEW.capture_scope->'bounds'->>2)::numeric
      AND (NEW.capture_scope->'bounds'->>1)::numeric
        < (NEW.capture_scope->'bounds'->>3)::numeric
      AND jsonb_typeof(NEW.capture_scope->'maximum_features') = 'number'
      AND jsonb_typeof(NEW.capture_scope->'page_size') = 'number'
      AND (NEW.capture_scope->>'maximum_features')::numeric
        = trunc((NEW.capture_scope->>'maximum_features')::numeric)
      AND (NEW.capture_scope->>'page_size')::numeric
        = trunc((NEW.capture_scope->>'page_size')::numeric)
      AND v_maximum_features BETWEEN 1 AND 50000
      AND v_page_size BETWEEN 1 AND CASE
        WHEN v_source_type = 'arcgis' THEN 2000 ELSE 1000 END
      AND v_page_size <= v_source_page_size
      AND NEW.maximum_requests
        = ceil(v_maximum_features::numeric / v_page_size::numeric)::integer
      AND NEW.maximum_requests BETWEEN 1 AND 64
      AND NEW.maximum_output_bytes BETWEEN 1 AND 134217728
      AND NEW.output_format = 'geojson')
  ) THEN
    RAISE EXCEPTION 'source-copy estimate does not match the project source';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_external_source_dataset(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_external_source_dataset() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  dataset_source_type app.dataset_source_type;
  dataset_format app.dataset_format;
BEGIN
  SELECT source_type, format
  INTO dataset_source_type, dataset_format
  FROM app.datasets
  WHERE organization_id = NEW.organization_id AND id = NEW.dataset_id;

  IF dataset_source_type IS NULL
    OR dataset_source_type <> NEW.source_type
    OR dataset_format::text <> NEW.source_type::text
  THEN
    RAISE EXCEPTION
      'external source identity must match an XYZ, WMS, PMTiles, GeoJSON, ArcGIS, or WFS dataset';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_external_source_discovery_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_external_source_discovery_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_expected_checksum text;
BEGIN
  IF NEW.created_by <> app.current_user_id() OR NEW.state <> 'queued'
    OR NEW.result IS NOT NULL OR NEW.error_code IS NOT NULL
    OR NEW.worker_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL
    OR NEW.attempt_count <> 0 OR NEW.started_at IS NOT NULL
    OR NEW.finished_at IS NOT NULL
  THEN RAISE EXCEPTION 'source discovery creator or initial state mismatch'; END IF;
  IF COALESCE(
    app.effective_project_role(NEW.project_id, NEW.created_by)::text,
    ''
  ) NOT IN ('owner', 'editor') THEN
    RAISE EXCEPTION 'source discovery requires project edit access';
  END IF;
  v_expected_checksum := encode(public.digest(convert_to(
    NEW.source_type || chr(31) || NEW.discovery_kind || chr(31)
      || NEW.service_url || chr(31) || COALESCE(NEW.collection_ref, ''),
    'UTF8'
  ), 'sha256'), 'hex');
  IF NEW.request_checksum_sha256 <> v_expected_checksum THEN
    RAISE EXCEPTION 'source discovery checksum mismatch';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'opengeo:source-discovery-quota:' || NEW.organization_id::text, 0
  ));
  IF (SELECT count(*) FROM app.external_source_discovery_jobs job
      WHERE job.organization_id = NEW.organization_id
        AND job.state IN ('queued', 'running')) >= 4
    OR (SELECT count(*) FROM app.external_source_discovery_jobs job
        WHERE job.organization_id = NEW.organization_id
          AND job.project_id = NEW.project_id
          AND job.created_by = NEW.created_by
          AND job.created_at >= clock_timestamp() - interval '24 hours') >= 64
  THEN RAISE EXCEPTION 'source discovery quota exceeded'; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_external_source_discovery_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_external_source_discovery_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id OR NEW.source_type <> OLD.source_type
    OR NEW.discovery_kind <> OLD.discovery_kind
    OR NEW.service_url <> OLD.service_url
    OR NEW.collection_ref IS DISTINCT FROM OLD.collection_ref
    OR NEW.request_checksum_sha256 <> OLD.request_checksum_sha256
    OR NEW.idempotency_key <> OLD.idempotency_key
    OR NEW.request_id <> OLD.request_id OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at OR NEW.attempt_count < OLD.attempt_count
    OR (OLD.started_at IS NOT NULL AND NEW.started_at IS DISTINCT FROM OLD.started_at)
  THEN RAISE EXCEPTION 'source discovery request seal is immutable'; END IF;
  IF OLD.state IN ('completed', 'failed', 'cancelled') THEN
    RAISE EXCEPTION 'source discovery terminal state is immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_external_source_snapshot_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_external_source_snapshot_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_estimate app.external_source_copy_estimates%ROWTYPE;
  v_destination app.datasets%ROWTYPE;
BEGIN
  IF NEW.created_by <> app.current_user_id() OR NEW.state <> 'queued'
    OR NEW.output_object_id IS NOT NULL OR NEW.output_dataset_version_id IS NOT NULL
    OR NEW.error_code IS NOT NULL OR NEW.worker_token IS NOT NULL
    OR NEW.attempt_count <> 0 OR NEW.started_at IS NOT NULL OR NEW.finished_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'source snapshot creator or initial state mismatch';
  END IF;
  IF COALESCE(
    app.effective_project_role(NEW.project_id, NEW.created_by)::text,
    ''
  ) NOT IN ('owner', 'editor') THEN
    RAISE EXCEPTION 'source snapshot requires project edit access';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'opengeo:data-preservation-quota:' || NEW.organization_id::text, 0
  ));
  SELECT * INTO v_estimate FROM app.external_source_copy_estimates
  WHERE organization_id = NEW.organization_id AND id = NEW.estimate_id;
  SELECT * INTO v_destination FROM app.datasets
  WHERE organization_id = NEW.organization_id AND id = NEW.destination_dataset_id;
  IF NOT FOUND OR v_estimate.project_id <> NEW.project_id
    OR v_estimate.source_dataset_id <> NEW.source_dataset_id
    OR v_estimate.source_revision_number <> NEW.source_revision_number
    OR v_estimate.created_by <> NEW.created_by
    OR v_estimate.expires_at <= clock_timestamp()
    OR v_destination.source_type <> 'upload'
    OR v_destination.format <> v_estimate.output_format
    OR v_destination.status <> 'draft' OR v_destination.current_version_id IS NOT NULL
    OR v_destination.owner_user_id <> NEW.created_by
    OR NOT EXISTS (
      SELECT 1 FROM app.project_datasets link
      WHERE link.organization_id = NEW.organization_id
        AND link.project_id = NEW.project_id
        AND link.dataset_id = NEW.destination_dataset_id
    )
  THEN
    RAISE EXCEPTION 'source snapshot does not match its sealed estimate and destination';
  END IF;
  IF (SELECT count(*) FROM app.external_source_snapshot_jobs job
      WHERE job.organization_id = NEW.organization_id
        AND job.state IN ('queued', 'running')) >= 4
    OR (SELECT count(*) FROM app.external_source_snapshot_jobs job
        WHERE job.organization_id = NEW.organization_id
          AND job.source_dataset_id = NEW.source_dataset_id
          AND job.created_at >= clock_timestamp() - interval '24 hours') >= 64
    OR COALESCE((
      SELECT sum(estimate.maximum_output_bytes)
      FROM app.external_source_snapshot_jobs job
      JOIN app.external_source_copy_estimates estimate
        ON estimate.organization_id = job.organization_id
       AND estimate.id = job.estimate_id
      WHERE job.organization_id = NEW.organization_id
        AND job.created_at >= clock_timestamp() - interval '24 hours'
        AND job.state <> 'cancelled'
    ), 0) + v_estimate.maximum_output_bytes > 10737418240
  THEN
    RAISE EXCEPTION 'source snapshot quota exceeded';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_external_source_snapshot_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_external_source_snapshot_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id OR NEW.estimate_id <> OLD.estimate_id
    OR NEW.source_dataset_id <> OLD.source_dataset_id
    OR NEW.source_revision_number <> OLD.source_revision_number
    OR NEW.destination_dataset_id <> OLD.destination_dataset_id
    OR NEW.destination_bucket <> OLD.destination_bucket
    OR NEW.rights_basis <> OLD.rights_basis OR NEW.attribution <> OLD.attribution
    OR NEW.request_checksum_sha256 <> OLD.request_checksum_sha256
    OR NEW.idempotency_key <> OLD.idempotency_key
    OR NEW.request_id <> OLD.request_id OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at OR NEW.attempt_count < OLD.attempt_count
    OR (OLD.started_at IS NOT NULL AND NEW.started_at IS DISTINCT FROM OLD.started_at)
  THEN RAISE EXCEPTION 'source snapshot request seal is immutable'; END IF;
  IF OLD.state IN ('completed', 'failed', 'cancelled') THEN
    RAISE EXCEPTION 'source snapshot terminal state is immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_feature_collection_revision(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_feature_collection_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.organization_id IS DISTINCT FROM NEW.organization_id
    OR OLD.dataset_id IS DISTINCT FROM NEW.dataset_id
    OR OLD.geometry_type IS DISTINCT FROM NEW.geometry_type
    OR OLD.schema_definition IS DISTINCT FROM NEW.schema_definition
    OR OLD.created_by IS DISTINCT FROM NEW.created_by
    OR OLD.created_at IS DISTINCT FROM NEW.created_at
  THEN
    RAISE EXCEPTION 'feature collection identity and schema are immutable';
  END IF;

  IF NEW.generation <> OLD.generation + 1 THEN
    RAISE EXCEPTION 'feature collection generation must increase exactly once';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_feature_head_revision(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_feature_head_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.organization_id IS DISTINCT FROM NEW.organization_id
    OR OLD.dataset_id IS DISTINCT FROM NEW.dataset_id
    OR OLD.id IS DISTINCT FROM NEW.id
    OR OLD.geometry_type IS DISTINCT FROM NEW.geometry_type
    OR OLD.created_by IS DISTINCT FROM NEW.created_by
    OR OLD.created_at IS DISTINCT FROM NEW.created_at
  THEN
    RAISE EXCEPTION 'feature identity, type, and creation attribution are immutable';
  END IF;

  IF NEW.version_number <> OLD.version_number + 1 THEN
    RAISE EXCEPTION 'feature version must increase exactly once';
  END IF;

  IF OLD.deleted_at IS NOT NULL
    AND NOT (NEW.deleted_at IS NULL AND NEW.deleted_by IS NULL)
  THEN
    RAISE EXCEPTION 'a deleted feature head can only transition to a live restored version';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_feature_head_revision(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.enforce_feature_head_revision() IS 'Allows exact one-version live edits, tombstones, or explicit tombstone restoration while preserving feature identity.';


