--
-- Name: enforce_invitation_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_invitation_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.id IS DISTINCT FROM NEW.id
    OR OLD.organization_id IS DISTINCT FROM NEW.organization_id
    OR OLD.invitee_user_id IS DISTINCT FROM NEW.invitee_user_id
    OR OLD.email IS DISTINCT FROM NEW.email
    OR OLD.organization_role IS DISTINCT FROM NEW.organization_role
    OR OLD.project_id IS DISTINCT FROM NEW.project_id
    OR OLD.project_role IS DISTINCT FROM NEW.project_role
    OR OLD.invited_by IS DISTINCT FROM NEW.invited_by
    OR OLD.expires_at IS DISTINCT FROM NEW.expires_at
    OR OLD.created_at IS DISTINCT FROM NEW.created_at
  THEN
    RAISE EXCEPTION 'invitation identity, scope, role, and expiry are immutable';
  END IF;

  IF OLD.state <> 'pending' OR NEW.state NOT IN ('accepted', 'revoked') THEN
    RAISE EXCEPTION 'invitation transitions are forward-only';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_map_render_composition_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_map_render_composition_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count integer;
  v_min smallint;
  v_max smallint;
BEGIN
  IF OLD.composition_sealed AND NOT NEW.composition_sealed THEN
    RAISE EXCEPTION 'map render composition cannot be reopened';
  END IF;
  IF NOT OLD.composition_sealed AND NEW.composition_sealed THEN
    SELECT count(*), min(position), max(position)
    INTO v_count, v_min, v_max
    FROM app.map_render_job_layers
    WHERE organization_id = NEW.organization_id AND render_job_id = NEW.id;
    IF v_count NOT BETWEEN 2 AND 16 OR v_min <> 1 OR v_max <> v_count THEN
      RAISE EXCEPTION 'map render composition is incomplete';
    END IF;
  END IF;
  IF NEW.state <> 'queued' AND NOT NEW.composition_sealed THEN
    RAISE EXCEPTION 'unsealed map render composition cannot transition';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_map_render_job_layer_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_map_render_job_layer_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_job app.map_render_jobs%ROWTYPE;
BEGIN
  SELECT * INTO v_job
  FROM app.map_render_jobs
  WHERE organization_id = NEW.organization_id AND id = NEW.render_job_id;
  IF NOT FOUND OR v_job.state <> 'queued' THEN
    RAISE EXCEPTION 'map render composition is not open';
  END IF;
  IF v_job.created_by <> app.current_user_id() THEN
    RAISE EXCEPTION 'map render composition creator mismatch';
  END IF;
  IF NEW.position = 1 THEN
    IF NEW.resource_id <> v_job.resource_id
      OR NEW.profile_id <> v_job.profile_id
      OR NEW.profile_version_id <> v_job.profile_version_id
    THEN
      RAISE EXCEPTION 'map render composition anchor mismatch';
    END IF;
  ELSIF v_job.composition_sealed THEN
    RAISE EXCEPTION 'map render composition is sealed';
  END IF;
  RETURN NEW;
END;
$$;


