--
-- Name: enforce_observable_build_job_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_observable_build_job_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_project app.observable_source_projects%ROWTYPE;
  v_revision app.observable_source_revisions%ROWTYPE;
  v_lock_checksum text;
  v_expected jsonb;
  v_expected_prefix text;
BEGIN
  SELECT * INTO v_project
  FROM app.observable_source_projects
  WHERE organization_id = NEW.organization_id
    AND project_id = NEW.project_id
    AND id = NEW.source_project_id;
  SELECT * INTO v_revision
  FROM app.observable_source_revisions
  WHERE organization_id = NEW.organization_id
    AND source_project_id = NEW.source_project_id
    AND id = NEW.source_revision_id
    AND revision_number = NEW.source_revision_number;
  SELECT object.checksum_sha256 INTO v_lock_checksum
  FROM app.observable_source_revision_files file
  JOIN app.observable_source_objects object
    ON object.organization_id = file.organization_id
   AND object.source_project_id = file.source_project_id
   AND object.id = file.source_object_id
  WHERE file.organization_id = NEW.organization_id
    AND file.source_revision_id = NEW.source_revision_id
    AND file.relative_path = v_revision.lockfile_path;

  v_expected := jsonb_build_object(
    'schemaVersion', 'opengeo.observable-build-request.1.0.0',
    'sourceProjectId', NEW.source_project_id,
    'sourceRevisionId', NEW.source_revision_id,
    'sourceRevisionNumber', NEW.source_revision_number,
    'sourceManifestChecksumSha256', v_revision.manifest_checksum_sha256,
    'purpose', NEW.purpose::text,
    'compilerImageDigest', v_project.compiler_image_digest,
    'frameworkVersion', v_project.framework_version,
    'lockfileFormat', v_project.lockfile_format,
    'lockfileChecksumSha256', v_lock_checksum,
    'networkPolicy', v_project.network_policy,
    'resourceLimits', v_project.resource_limits
  );
  v_expected_prefix := format(
    'organizations/%s/projects/%s/source-projects/%s/builds/%s/output/',
    NEW.organization_id, NEW.project_id, NEW.source_project_id, NEW.id
  );
  IF v_project.id IS NULL
    OR v_revision.id IS NULL
    OR NEW.created_by IS DISTINCT FROM app.current_user_id()
    OR NEW.source_revision_number <> v_revision.revision_number
    OR NEW.request IS DISTINCT FROM v_expected
    OR NEW.output_prefix <> v_expected_prefix
    OR NEW.state <> 'pending'
    OR NEW.attempt_count <> 0
    OR NEW.result IS NOT NULL
    OR (NEW.purpose = 'release_candidate' AND v_revision.rights_status <> 'approved')
  THEN
    RAISE EXCEPTION 'Observable build job does not seal an eligible exact source revision';
  END IF;
  NEW.request_checksum_sha256 := encode(
    digest(convert_to(NEW.request::text, 'UTF8'), 'sha256'),
    'hex'
  );
  RETURN NEW;
END;
$$;


--
-- Name: enforce_observable_build_job_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_observable_build_job_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.source_project_id <> OLD.source_project_id
    OR NEW.source_revision_id <> OLD.source_revision_id
    OR NEW.source_revision_number <> OLD.source_revision_number
    OR NEW.purpose <> OLD.purpose
    OR NEW.request <> OLD.request
    OR NEW.request_checksum_sha256 <> OLD.request_checksum_sha256
    OR NEW.output_prefix <> OLD.output_prefix
    OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
    OR NEW.attempt_count < OLD.attempt_count
    OR NEW.attempt_count > OLD.attempt_count + 1
    OR NOT (
      (OLD.state = 'pending' AND NEW.state IN ('running', 'cancelled'))
      OR (OLD.state = 'running'
        AND NEW.state IN ('running', 'pending', 'succeeded', 'failed'))
    )
  THEN
    RAISE EXCEPTION 'Observable build job transition is invalid';
  END IF;
  IF NEW.result IS NOT NULL THEN
    NEW.result_checksum_sha256 := encode(
      digest(convert_to(NEW.result::text, 'UTF8'), 'sha256'),
      'hex'
    );
  ELSE
    NEW.result_checksum_sha256 := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_observable_preview_capability_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_observable_preview_capability_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_build app.observable_build_jobs%ROWTYPE;
  v_active_count integer;
  v_recent_count integer;
  v_entry_file text;
BEGIN
  IF NEW.organization_id IS DISTINCT FROM app.current_organization_id()
    OR NEW.requested_by IS DISTINCT FROM app.current_user_id()
    OR NEW.consumed_at IS NOT NULL
    OR NEW.expires_at <= clock_timestamp()
  THEN
    RAISE EXCEPTION 'Observable preview capability actor is invalid';
  END IF;
  SELECT * INTO v_build
  FROM app.observable_build_jobs
  WHERE organization_id = NEW.organization_id
    AND project_id = NEW.project_id
    AND id = NEW.build_job_id;
  IF NOT FOUND OR v_build.state <> 'succeeded' OR v_build.result IS NULL THEN
    RAISE EXCEPTION 'Observable preview requires one successful exact build';
  END IF;
  SELECT route->>'file' INTO v_entry_file
  FROM jsonb_array_elements(v_build.result->'routeManifest') route
  WHERE route->>'path' = '/'
  LIMIT 1;
  IF v_entry_file IS NULL
    OR NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_build.result->'outputManifest'->'files') file
      WHERE file->>'path' = v_entry_file
        AND file->>'contentType' = 'text/html'
        AND file->>'objectKey'
          = v_build.output_prefix || substring(v_entry_file FROM 6)
    )
  THEN
    RAISE EXCEPTION 'Observable preview build has no exact root document';
  END IF;
  SELECT count(*)::integer INTO v_active_count
  FROM app.observable_preview_capabilities capability
  WHERE capability.organization_id = NEW.organization_id
    AND capability.build_job_id = NEW.build_job_id
    AND capability.requested_by = NEW.requested_by
    AND capability.consumed_at IS NULL
    AND capability.expires_at > clock_timestamp();
  SELECT count(*)::integer INTO v_recent_count
  FROM app.observable_preview_capabilities capability
  WHERE capability.organization_id = NEW.organization_id
    AND capability.requested_by = NEW.requested_by
    AND capability.created_at > clock_timestamp() - interval '24 hours';
  IF v_active_count >= 8 OR v_recent_count >= 256 THEN
    RAISE EXCEPTION 'Observable preview capability quota exceeded';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_observable_preview_capability_update(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_observable_preview_capability_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.build_job_id <> OLD.build_job_id
    OR NEW.requested_by <> OLD.requested_by
    OR NEW.token_checksum_sha256 <> OLD.token_checksum_sha256
    OR NEW.created_at <> OLD.created_at
    OR NEW.expires_at <> OLD.expires_at
    OR OLD.consumed_at IS NOT NULL
    OR NEW.consumed_at IS NULL
    OR NEW.consumed_at < NEW.created_at
    OR NEW.consumed_at > NEW.expires_at
  THEN
    RAISE EXCEPTION 'Observable preview capability is immutable or already consumed';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_observable_source_object_binding(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_observable_source_object_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_intent app.observable_source_file_upload_intents%ROWTYPE;
BEGIN
  SELECT * INTO v_intent
  FROM app.observable_source_file_upload_intents
  WHERE organization_id = NEW.organization_id
    AND source_project_id = NEW.source_project_id
    AND id = NEW.upload_intent_id
  FOR UPDATE;
  IF NOT FOUND
    OR v_intent.state <> 'pending'
    OR v_intent.expires_at <= clock_timestamp()
    OR v_intent.project_id <> NEW.project_id
    OR v_intent.relative_path <> NEW.relative_path
    OR v_intent.expected_content_type <> NEW.content_type
    OR v_intent.expected_size_bytes <> NEW.size_bytes
    OR v_intent.expected_sha256 <> NEW.checksum_sha256
    OR v_intent.bucket <> NEW.bucket
    OR v_intent.object_key <> NEW.object_key
    OR v_intent.created_by <> NEW.created_by
    OR NEW.created_by IS DISTINCT FROM app.current_user_id()
  THEN
    RAISE EXCEPTION 'Observable source object does not match its active upload intent';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_observable_source_project_head(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_observable_source_project_head() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_revision app.observable_source_revisions%ROWTYPE;
  v_files jsonb;
  v_expected_manifest jsonb;
  v_file_count integer;
  v_total_bytes bigint;
  v_case_count integer;
  v_positions_sorted boolean;
  v_entry_type text;
  v_lock_type text;
BEGIN
  IF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.site_id <> OLD.site_id
    OR NEW.route_namespace <> OLD.route_namespace
    OR NEW.owner_user_id <> OLD.owner_user_id
    OR NEW.compiler_image_digest <> OLD.compiler_image_digest
    OR NEW.framework_version <> OLD.framework_version
    OR NEW.lockfile_format <> OLD.lockfile_format
    OR NEW.network_policy <> OLD.network_policy
    OR NEW.resource_limits <> OLD.resource_limits
    OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
    OR NEW.updated_by IS DISTINCT FROM app.current_user_id()
    OR NEW.current_revision_number <> OLD.current_revision_number + 1
  THEN
    RAISE EXCEPTION 'Observable source project head may only advance to one exact revision';
  END IF;

  SELECT * INTO v_revision
  FROM app.observable_source_revisions
  WHERE organization_id = NEW.organization_id
    AND source_project_id = NEW.id
    AND id = NEW.current_revision_id
    AND revision_number = NEW.current_revision_number;
  IF NOT FOUND
    OR v_revision.title <> NEW.title
    OR v_revision.rights_status <> NEW.rights_status
  THEN
    RAISE EXCEPTION 'Observable source project head does not match its revision';
  END IF;

  SELECT
    jsonb_agg(
      jsonb_build_object(
        'path', file.relative_path,
        'objectId', object.id,
        'bucket', object.bucket,
        'objectKey', object.object_key,
        's3VersionId', object.s3_version_id,
        'etag', object.etag,
        'contentType', object.content_type,
        'sizeBytes', object.size_bytes,
        'checksumSha256', object.checksum_sha256
      ) ORDER BY file.relative_path
    ),
    count(*)::integer,
    COALESCE(sum(object.size_bytes), 0),
    count(DISTINCT lower(file.relative_path))::integer,
    bool_and(
      file.position = (
        SELECT count(*)::integer - 1
        FROM app.observable_source_revision_files earlier
        WHERE earlier.organization_id = file.organization_id
          AND earlier.source_revision_id = file.source_revision_id
          AND earlier.relative_path <= file.relative_path
      )
    ),
    max(object.content_type) FILTER (
      WHERE file.relative_path = v_revision.entry_path
    ),
    max(object.content_type) FILTER (
      WHERE file.relative_path = v_revision.lockfile_path
    )
  INTO v_files, v_file_count, v_total_bytes, v_case_count, v_positions_sorted,
       v_entry_type, v_lock_type
  FROM app.observable_source_revision_files file
  JOIN app.observable_source_objects object
    ON object.organization_id = file.organization_id
   AND object.source_project_id = file.source_project_id
   AND object.id = file.source_object_id
   AND object.relative_path = file.relative_path
  WHERE file.organization_id = NEW.organization_id
    AND file.source_project_id = NEW.id
    AND file.source_revision_id = v_revision.id;

  IF v_file_count NOT BETWEEN 1 AND 128
    OR v_file_count <> v_case_count
    OR NOT v_positions_sorted
    OR v_total_bytes > 16777216
    OR v_entry_type <> 'text/markdown'
    OR (v_revision.lockfile_path IS NOT NULL AND v_lock_type <> 'application/json')
    OR (
      EXISTS (
        SELECT 1 FROM app.observable_source_revision_files file
        WHERE file.organization_id = NEW.organization_id
          AND file.source_revision_id = v_revision.id
          AND file.relative_path = 'package.json'
      )
      AND v_revision.lockfile_path IS NULL
    )
  THEN
    RAISE EXCEPTION 'Observable source revision file set is invalid or incomplete';
  END IF;

  v_expected_manifest := jsonb_build_object(
    'schemaVersion', 'opengeo.observable-source-revision.1.0.0',
    'sourceProjectId', v_revision.source_project_id,
    'revisionId', v_revision.id,
    'revisionNumber', v_revision.revision_number,
    'entryPath', v_revision.entry_path,
    'lockfilePath', v_revision.lockfile_path,
    'files', v_files
  );
  IF v_revision.manifest IS DISTINCT FROM v_expected_manifest THEN
    RAISE EXCEPTION 'Observable source revision manifest does not match exact file objects';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_observable_source_project_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_observable_source_project_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_site_slug text;
BEGIN
  IF NEW.organization_id IS DISTINCT FROM app.current_organization_id()
    OR NEW.owner_user_id IS DISTINCT FROM app.current_user_id()
    OR NEW.created_by IS DISTINCT FROM app.current_user_id()
    OR NEW.updated_by IS DISTINCT FROM app.current_user_id()
    OR NEW.current_revision_number <> 0
    OR NEW.current_revision_id IS NOT NULL
  THEN
    RAISE EXCEPTION 'Observable source project insert scope is invalid';
  END IF;
  SELECT slug INTO v_site_slug
  FROM app.project_sites
  WHERE organization_id = NEW.organization_id
    AND project_id = NEW.project_id
    AND id = NEW.site_id;
  IF NOT FOUND OR NEW.route_namespace <> v_site_slug THEN
    RAISE EXCEPTION 'Observable source project must bind the exact governed site route';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_observable_source_revision_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_observable_source_revision_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_project app.observable_source_projects%ROWTYPE;
BEGIN
  SELECT * INTO v_project
  FROM app.observable_source_projects
  WHERE organization_id = NEW.organization_id
    AND project_id = NEW.project_id
    AND id = NEW.source_project_id
  FOR UPDATE;
  IF NOT FOUND
    OR NEW.created_by IS DISTINCT FROM app.current_user_id()
    OR NEW.revision_number <> v_project.current_revision_number + 1
    OR (
      v_project.current_revision_number = 0
      AND NEW.parent_revision_id IS NOT NULL
    )
    OR (
      v_project.current_revision_number > 0
      AND NEW.parent_revision_id IS DISTINCT FROM v_project.current_revision_id
    )
  THEN
    RAISE EXCEPTION 'Observable source revision must append to the exact current head';
  END IF;
  NEW.manifest_checksum_sha256 := encode(
    digest(convert_to(NEW.manifest::text, 'UTF8'), 'sha256'),
    'hex'
  );
  RETURN NEW;
END;
$$;


--
-- Name: enforce_observable_source_upload_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_observable_source_upload_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_expected_key text;
BEGIN
  v_expected_key := format(
    'organizations/%s/projects/%s/source-projects/%s/uploads/%s/files/%s',
    NEW.organization_id, NEW.project_id, NEW.source_project_id,
    NEW.id, NEW.relative_path
  );
  IF NEW.organization_id IS DISTINCT FROM app.current_organization_id()
    OR NEW.created_by IS DISTINCT FROM app.current_user_id()
    OR NEW.object_key <> v_expected_key
    OR NEW.state <> 'pending'
    OR NEW.completed_object_id IS NOT NULL
    OR NEW.completed_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'Observable source upload must bind the current actor and exact private path';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_observable_source_upload_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_observable_source_upload_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.state <> 'pending'
    OR NEW.state <> 'committed'
    OR NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.source_project_id <> OLD.source_project_id
    OR NEW.relative_path <> OLD.relative_path
    OR NEW.expected_content_type <> OLD.expected_content_type
    OR NEW.expected_size_bytes <> OLD.expected_size_bytes
    OR NEW.expected_sha256 <> OLD.expected_sha256
    OR NEW.bucket <> OLD.bucket
    OR NEW.object_key <> OLD.object_key
    OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
    OR NEW.expires_at <> OLD.expires_at
    OR NEW.completed_object_id IS NULL
    OR NEW.completed_at IS NULL
  THEN
    RAISE EXCEPTION 'Observable source upload identity and completion are immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_page_renderer_identity(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_page_renderer_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_page jsonb;
  v_source app.page_source_objects%ROWTYPE;
  v_expected jsonb;
BEGIN
  IF NEW.manifest->>'rendererVersion'
    IS DISTINCT FROM 'opengeo-page-renderer-1.1.0'
  THEN
    RAISE EXCEPTION 'site edition renderer identity is missing or unsupported';
  END IF;

  FOR v_page IN
    SELECT value FROM jsonb_array_elements(COALESCE(NEW.manifest->'pages', '[]'::jsonb))
  LOOP
    SELECT * INTO v_source
    FROM app.page_source_objects source
    WHERE source.organization_id = NEW.organization_id
      AND source.resource_id = (v_page->>'resourceId')::uuid
      AND source.resource_version_id = (v_page->>'resourceVersionId')::uuid;
    IF FOUND THEN
      v_expected := jsonb_build_object(
        'sourceId', v_source.id,
        'sourceBlockId', v_source.source_block_id,
        's3VersionId', v_source.s3_version_id,
        'etag', v_source.etag,
        'contentType', v_source.content_type,
        'sizeBytes', v_source.size_bytes,
        'checksumSha256', v_source.checksum_sha256,
        'dialect', v_source.dialect,
        'dialectVersion', v_source.dialect_version,
        'compilerVersion', v_source.compiler_version
      );
      IF v_page->'pageSource' IS DISTINCT FROM v_expected THEN
        RAISE EXCEPTION 'site edition page source seal is missing or mismatched';
      END IF;
    ELSIF COALESCE(v_page->'pageSource', 'null'::jsonb) <> 'null'::jsonb THEN
      RAISE EXCEPTION 'site edition page source seal has no governed source';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_page_source_object_binding(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_page_source_object_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_intent app.page_source_upload_intents%ROWTYPE;
  v_kind app.governed_resource_kind;
  v_version bigint;
BEGIN
  SELECT * INTO v_intent
  FROM app.page_source_upload_intents
  WHERE organization_id = NEW.organization_id AND id = NEW.upload_intent_id
  FOR UPDATE;
  IF NOT FOUND
    OR v_intent.state <> 'pending'
    OR v_intent.expires_at <= clock_timestamp()
    OR v_intent.project_id <> NEW.project_id
    OR v_intent.resource_id <> NEW.resource_id
    OR v_intent.source_block_id <> NEW.source_block_id
    OR v_intent.bucket <> NEW.bucket
    OR v_intent.object_key <> NEW.object_key
    OR v_intent.expected_size_bytes <> NEW.size_bytes
    OR v_intent.expected_sha256 <> NEW.checksum_sha256
    OR v_intent.created_by <> NEW.created_by
  THEN
    RAISE EXCEPTION 'page source object does not match its active upload intent';
  END IF;

  SELECT resource.kind, version.version_number INTO v_kind, v_version
  FROM app.governed_resources resource
  JOIN app.governed_resource_versions version
    ON version.organization_id = resource.organization_id
   AND version.resource_id = resource.id
   AND version.id = NEW.resource_version_id
  WHERE resource.organization_id = NEW.organization_id
    AND resource.project_id = NEW.project_id
    AND resource.id = NEW.resource_id;
  IF NOT FOUND
    OR v_kind NOT IN ('document', 'story', 'dashboard')
    OR v_version <> v_intent.expected_resource_version + 1
  THEN
    RAISE EXCEPTION 'page source object must bind the intended page resource version';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_page_source_upload_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_page_source_upload_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.state <> 'pending'
    OR NEW.state <> 'completed'
    OR NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.resource_id <> OLD.resource_id
    OR NEW.expected_resource_version <> OLD.expected_resource_version
    OR NEW.source_block_id <> OLD.source_block_id
    OR NEW.expected_size_bytes <> OLD.expected_size_bytes
    OR NEW.expected_sha256 <> OLD.expected_sha256
    OR NEW.bucket <> OLD.bucket
    OR NEW.object_key <> OLD.object_key
    OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
    OR NEW.expires_at <> OLD.expires_at
    OR NEW.completed_source_object_id IS NULL
    OR NEW.completed_at IS NULL
  THEN
    RAISE EXCEPTION 'page source upload identity and completion are immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_page_working_draft_head(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_page_working_draft_head() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_kind app.governed_resource_kind;
  v_resource_version bigint;
BEGIN
  IF NEW.organization_id IS DISTINCT FROM app.current_organization_id()
    OR NEW.owner_user_id IS DISTINCT FROM app.current_user_id()
  THEN
    RAISE EXCEPTION 'page working draft must belong to the current tenant and user';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.current_revision_number <> 0
      OR NEW.current_document_checksum_sha256 IS NOT NULL
    THEN
      RAISE EXCEPTION 'page working draft must begin before its first revision';
    END IF;
    SELECT resource.kind, version.version_number INTO v_kind, v_resource_version
    FROM app.governed_resources resource
    JOIN app.governed_resource_versions version
      ON version.organization_id = resource.organization_id
     AND version.resource_id = resource.id
     AND version.id = resource.current_version_id
    WHERE resource.organization_id = NEW.organization_id
      AND resource.project_id = NEW.project_id
      AND resource.id = NEW.resource_id;
    IF NOT FOUND
      OR v_kind NOT IN ('document', 'story', 'dashboard')
      OR v_resource_version <> NEW.base_resource_version
    THEN
      RAISE EXCEPTION 'page working draft must target the current page resource version';
    END IF;
  ELSIF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.resource_id <> OLD.resource_id
    OR NEW.owner_user_id <> OLD.owner_user_id
    OR NEW.base_resource_version <> OLD.base_resource_version
    OR NEW.created_at <> OLD.created_at
    OR NEW.current_revision_number <> OLD.current_revision_number + 1
    OR NOT EXISTS (
      SELECT 1
      FROM app.page_working_draft_revisions revision
      WHERE revision.organization_id = NEW.organization_id
        AND revision.draft_id = NEW.id
        AND revision.revision_number = NEW.current_revision_number
        AND revision.document_checksum_sha256 = NEW.current_document_checksum_sha256
    )
  THEN
    RAISE EXCEPTION 'page working draft head must advance to its exact next revision';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_page_working_draft_revision(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_page_working_draft_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_current_revision bigint;
BEGIN
  IF NEW.organization_id IS DISTINCT FROM app.current_organization_id()
    OR NEW.owner_user_id IS DISTINCT FROM app.current_user_id()
  THEN
    RAISE EXCEPTION 'page working draft revision must belong to the current tenant and user';
  END IF;
  SELECT current_revision_number INTO v_current_revision
  FROM app.page_working_drafts draft
  WHERE draft.organization_id = NEW.organization_id
    AND draft.project_id = NEW.project_id
    AND draft.resource_id = NEW.resource_id
    AND draft.id = NEW.draft_id
    AND draft.owner_user_id = NEW.owner_user_id
    AND draft.base_resource_version = NEW.base_resource_version
  FOR UPDATE;
  IF NOT FOUND OR NEW.revision_number <> v_current_revision + 1 THEN
    RAISE EXCEPTION 'page working draft revision must append exactly once';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_pmtiles_derivative_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_pmtiles_derivative_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'opengeo:data-preservation-quota:' || NEW.organization_id::text, 0
  ));
  IF NEW.created_by <> app.current_user_id() OR NEW.state <> 'queued'
    OR NEW.output_object_id IS NOT NULL OR NEW.error_code IS NOT NULL
    OR NEW.worker_token IS NOT NULL OR NEW.attempt_count <> 0
    OR NEW.started_at IS NOT NULL OR NEW.finished_at IS NOT NULL
    OR NOT EXISTS (
      SELECT 1
      FROM app.project_datasets project_dataset
      JOIN app.datasets dataset
        ON dataset.organization_id = project_dataset.organization_id
       AND dataset.id = project_dataset.dataset_id
      JOIN app.dataset_versions version
        ON version.organization_id = dataset.organization_id
       AND version.dataset_id = dataset.id
       AND version.id = NEW.dataset_version_id
      JOIN app.dataset_version_objects link
        ON link.organization_id = version.organization_id
       AND link.dataset_id = version.dataset_id
       AND link.dataset_version_id = version.id
       AND link.data_object_id = NEW.source_object_id
      JOIN app.data_objects object
        ON object.organization_id = link.organization_id
       AND object.dataset_id = link.dataset_id
       AND object.id = link.data_object_id
      WHERE project_dataset.organization_id = NEW.organization_id
        AND project_dataset.project_id = NEW.project_id
        AND project_dataset.dataset_id = NEW.dataset_id
        AND dataset.status = 'active' AND version.state = 'active'
        AND object.role IN ('original', 'working')
        AND object.content_type IN (
          'application/geo+json', 'application/geopackage+sqlite3',
          'application/vnd.apache.parquet', 'application/zip', 'text/csv'
        )
        AND object.size_bytes <= 2147483648
    )
  THEN RAISE EXCEPTION 'PMTiles job must target an exact active managed vector object'; END IF;
  IF COALESCE(
    app.effective_project_role(NEW.project_id, NEW.created_by)::text,
    ''
  ) NOT IN ('owner', 'editor') THEN
    RAISE EXCEPTION 'PMTiles derivative requires project edit access';
  END IF;
  IF (SELECT count(*) FROM app.pmtiles_derivative_jobs job
      WHERE job.organization_id = NEW.organization_id
        AND job.dataset_id = NEW.dataset_id
        AND job.state IN ('queued', 'running')) >= 4
    OR (SELECT count(*) FROM app.pmtiles_derivative_jobs job
        WHERE job.organization_id = NEW.organization_id
          AND job.dataset_version_id = NEW.dataset_version_id
          AND job.created_at >= clock_timestamp() - interval '24 hours') >= 64
  THEN RAISE EXCEPTION 'PMTiles derivative quota exceeded'; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_pmtiles_derivative_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_pmtiles_derivative_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id OR NEW.dataset_id <> OLD.dataset_id
    OR NEW.dataset_version_id <> OLD.dataset_version_id
    OR NEW.source_object_id <> OLD.source_object_id OR NEW.bounds <> OLD.bounds
    OR NEW.minimum_zoom <> OLD.minimum_zoom OR NEW.maximum_zoom <> OLD.maximum_zoom
    OR NEW.source_layer <> OLD.source_layer
    OR NEW.request_checksum_sha256 <> OLD.request_checksum_sha256
    OR NEW.idempotency_key <> OLD.idempotency_key
    OR NEW.request_id <> OLD.request_id OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at OR NEW.attempt_count < OLD.attempt_count
    OR (OLD.started_at IS NOT NULL AND NEW.started_at IS DISTINCT FROM OLD.started_at)
  THEN RAISE EXCEPTION 'PMTiles derivative request seal is immutable'; END IF;
  IF OLD.state IN ('completed', 'failed', 'cancelled') THEN
    RAISE EXCEPTION 'PMTiles derivative terminal state is immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_discussion_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_discussion_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_state_changed boolean := NEW.state IS DISTINCT FROM OLD.state;
  v_assignment_changed boolean := NEW.assigned_to IS DISTINCT FROM OLD.assigned_to;
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
    OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
    OR NEW.project_id IS DISTINCT FROM OLD.project_id
    OR NEW.initial_comment_id IS DISTINCT FROM OLD.initial_comment_id
    OR NEW.title IS DISTINCT FROM OLD.title
    OR NEW.created_by IS DISTINCT FROM OLD.created_by
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.target_kind IS DISTINCT FROM OLD.target_kind
    OR NEW.target_map_id IS DISTINCT FROM OLD.target_map_id
    OR NEW.target_map_version IS DISTINCT FROM OLD.target_map_version
    OR NEW.target_layer_id IS DISTINCT FROM OLD.target_layer_id
    OR NEW.target_dataset_id IS DISTINCT FROM OLD.target_dataset_id
    OR NEW.target_feature_id IS DISTINCT FROM OLD.target_feature_id
    OR NEW.target_object_id IS DISTINCT FROM OLD.target_object_id
    OR NEW.target_object_version IS DISTINCT FROM OLD.target_object_version
  THEN
    RAISE EXCEPTION 'project discussion identity, initial content, and target are immutable';
  END IF;

  IF NEW.version_number <> OLD.version_number + 1 THEN
    RAISE EXCEPTION 'project discussion transition requires the next version';
  END IF;
  IF v_state_changed = v_assignment_changed THEN
    RAISE EXCEPTION 'project discussion transition must change exactly one state or assignment';
  END IF;

  IF v_state_changed THEN
    IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to
      OR NEW.assigned_by IS DISTINCT FROM OLD.assigned_by
      OR NEW.assigned_at IS DISTINCT FROM OLD.assigned_at
    THEN
      RAISE EXCEPTION 'state transition cannot change assignment';
    END IF;
    IF NEW.state = 'resolved' THEN
      IF NEW.resolved_by IS DISTINCT FROM app.current_user_id()
        OR NEW.resolved_at IS NULL
      THEN
        RAISE EXCEPTION 'project discussion resolution requires current-user attribution';
      END IF;
    ELSIF NEW.resolved_by IS NOT NULL OR NEW.resolved_at IS NOT NULL THEN
      RAISE EXCEPTION 'open project discussion cannot retain resolution attribution';
    END IF;
  ELSE
    IF NEW.state IS DISTINCT FROM OLD.state
      OR NEW.resolved_by IS DISTINCT FROM OLD.resolved_by
      OR NEW.resolved_at IS DISTINCT FROM OLD.resolved_at
    THEN
      RAISE EXCEPTION 'assignment transition cannot change discussion state';
    END IF;
    IF NEW.assigned_to IS NULL THEN
      IF NEW.assigned_by IS NOT NULL OR NEW.assigned_at IS NOT NULL THEN
        RAISE EXCEPTION 'unassigned discussion cannot retain assignment attribution';
      END IF;
    ELSIF NEW.assigned_by IS DISTINCT FROM app.current_user_id()
      OR NEW.assigned_at IS NULL
    THEN
      RAISE EXCEPTION 'assignment transition requires current-user attribution';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_import_item_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_import_item_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.organization_id <> OLD.organization_id
    OR NEW.import_id <> OLD.import_id
    OR NEW.import_ref <> OLD.import_ref
    OR NEW.kind <> OLD.kind
    OR NEW.expected_source_type <> OLD.expected_source_type
    OR NEW.expected_format <> OLD.expected_format
    OR NEW.candidate <> OLD.candidate
    OR NEW.created_at <> OLD.created_at
  THEN
    RAISE EXCEPTION 'project import item plan is immutable';
  END IF;
  IF OLD.state = 'bound'
    OR NEW.state <> 'bound'
    OR OLD.dataset_id IS NOT NULL
    OR NEW.dataset_id IS NULL
  THEN
    RAISE EXCEPTION 'project import item binding is single-assignment';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_import_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_import_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.map_id <> OLD.map_id
    OR NEW.idempotency_key <> OLD.idempotency_key
    OR NEW.source_product <> OLD.source_product
    OR NEW.source_version <> OLD.source_version
    OR NEW.source_sha256 <> OLD.source_sha256
    OR NEW.plan_digest <> OLD.plan_digest
    OR NEW.expected_map_version <> OLD.expected_map_version
    OR NEW.map_definition <> OLD.map_definition
    OR NEW.conversion_report <> OLD.conversion_report
    OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
  THEN
    RAISE EXCEPTION 'project import identity and plan are immutable';
  END IF;
  IF OLD.state = 'completed' OR NEW.state < OLD.state THEN
    RAISE EXCEPTION 'project import transitions are forward-only';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_notification_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_notification_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
    OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
    OR NEW.project_id IS DISTINCT FROM OLD.project_id
    OR NEW.recipient_user_id IS DISTINCT FROM OLD.recipient_user_id
    OR NEW.actor_user_id IS DISTINCT FROM OLD.actor_user_id
    OR NEW.discussion_id IS DISTINCT FROM OLD.discussion_id
    OR NEW.discussion_version IS DISTINCT FROM OLD.discussion_version
    OR NEW.comment_id IS DISTINCT FROM OLD.comment_id
    OR NEW.kind IS DISTINCT FROM OLD.kind
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
  THEN
    RAISE EXCEPTION 'project notification identity and cause are immutable';
  END IF;
  IF OLD.read_at IS NOT NULL
    OR NEW.read_at IS NULL
    OR NEW.version_number <> OLD.version_number + 1
    OR NEW.recipient_user_id IS DISTINCT FROM app.current_user_id()
  THEN
    RAISE EXCEPTION 'project notification permits one recipient-attributed read transition';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_asset_seal_v14(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_asset_seal_v14() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  expected_count bigint;
  sealed_count bigint;
  sealed_print_layout jsonb;
BEGIN
  IF NEW.manifest->>'schemaVersion' <> 'opengeo.site-edition.1.4.0' THEN
    IF EXISTS (
      SELECT 1
      FROM app.project_site_pages page
      JOIN app.governed_resource_versions version
        ON version.organization_id = page.organization_id
       AND version.resource_id = page.resource_id
       AND version.id = page.resource_version_id
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE WHEN jsonb_typeof(version.content->'blocks') = 'array'
          THEN version.content->'blocks' ELSE '[]'::jsonb END
      ) block
      WHERE page.organization_id = NEW.organization_id
        AND page.project_id = NEW.project_id
        AND page.site_id = NEW.site_id
        AND page.site_version_id = NEW.site_version_id
        AND block->>'type' = 'document'
    ) OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(NEW.manifest->'assets') = 'array'
          THEN NEW.manifest->'assets' ELSE '[]'::jsonb END
      ) asset
      WHERE asset->>'kind' = 'document'
    ) THEN
      RAISE EXCEPTION 'public document blocks require site edition schema 1.4';
    END IF;
    RETURN NEW;
  END IF;

  SELECT version.print_layout INTO sealed_print_layout
  FROM app.project_site_versions version
  WHERE version.organization_id = NEW.organization_id
    AND version.project_id = NEW.project_id
    AND version.site_id = NEW.site_id
    AND version.id = NEW.site_version_id;
  IF NEW.manifest->'printLayout' IS DISTINCT FROM sealed_print_layout THEN
    RAISE EXCEPTION 'project site edition print layout seal mismatch';
  END IF;

  IF jsonb_typeof(NEW.manifest->'assets') <> 'array'
    OR jsonb_array_length(NEW.manifest->'assets') > 16
  THEN
    RAISE EXCEPTION 'project site edition asset manifest is invalid';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(NEW.manifest->'assets') asset
    WHERE asset->>'kind' NOT IN ('image', 'file', 'document')
      OR asset->>'datasetId' !~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      OR asset->>'datasetVersionId' !~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      OR asset->>'objectId' !~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      OR asset->>'storageVersionId' IS NULL
      OR asset->>'checksumSha256' !~ '^[0-9a-f]{64}$'
      OR asset->>'sizeBytes' !~ '^[1-9][0-9]{0,7}$'
      OR asset->>'contentType' IS NULL
      OR asset->>'filename' IS NULL
  ) THEN
    RAISE EXCEPTION 'project site edition asset identity is invalid';
  END IF;

  SELECT count(*), count(DISTINCT asset->>'objectId')
  INTO sealed_count, expected_count
  FROM jsonb_array_elements(NEW.manifest->'assets') asset;
  IF sealed_count <> expected_count THEN
    RAISE EXCEPTION 'project site edition asset identities must be unique';
  END IF;

  WITH expected_asset AS (
    SELECT DISTINCT
      block->>'type' AS kind,
      block->>'dataset_id' AS dataset_id,
      block->>'dataset_version_id' AS dataset_version_id,
      block->>'object_id' AS object_id
    FROM app.project_site_pages page
    JOIN app.governed_resource_versions version
      ON version.organization_id = page.organization_id
     AND version.resource_id = page.resource_id
     AND version.id = page.resource_version_id
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE WHEN jsonb_typeof(version.content->'blocks') = 'array'
        THEN version.content->'blocks' ELSE '[]'::jsonb END
    ) block
    WHERE page.organization_id = NEW.organization_id
      AND page.project_id = NEW.project_id
      AND page.site_id = NEW.site_id
      AND page.site_version_id = NEW.site_version_id
      AND block->>'type' IN ('image', 'file', 'document')
  )
  SELECT count(*) INTO expected_count FROM expected_asset;
  IF expected_count <> sealed_count OR EXISTS (
    WITH expected_asset AS (
      SELECT DISTINCT
        block->>'type' AS kind,
        block->>'dataset_id' AS dataset_id,
        block->>'dataset_version_id' AS dataset_version_id,
        block->>'object_id' AS object_id
      FROM app.project_site_pages page
      JOIN app.governed_resource_versions version
        ON version.organization_id = page.organization_id
       AND version.resource_id = page.resource_id
       AND version.id = page.resource_version_id
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE WHEN jsonb_typeof(version.content->'blocks') = 'array'
          THEN version.content->'blocks' ELSE '[]'::jsonb END
      ) block
      WHERE page.organization_id = NEW.organization_id
        AND page.project_id = NEW.project_id
        AND page.site_id = NEW.site_id
        AND page.site_version_id = NEW.site_version_id
        AND block->>'type' IN ('image', 'file', 'document')
    )
    SELECT 1
    FROM expected_asset expected
    WHERE NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(NEW.manifest->'assets') asset
      WHERE asset->>'kind' = expected.kind
        AND asset->>'datasetId' = expected.dataset_id
        AND asset->>'datasetVersionId' = expected.dataset_version_id
        AND asset->>'objectId' = expected.object_id
    )
  ) THEN
    RAISE EXCEPTION 'project site edition content asset seal mismatch';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(NEW.manifest->'assets') asset
    LEFT JOIN app.datasets dataset
      ON dataset.organization_id = NEW.organization_id
     AND dataset.id = (asset->>'datasetId')::uuid
    LEFT JOIN app.project_datasets project_dataset
      ON project_dataset.organization_id = dataset.organization_id
     AND project_dataset.dataset_id = dataset.id
     AND project_dataset.project_id = NEW.project_id
    LEFT JOIN app.dataset_versions version
      ON version.organization_id = dataset.organization_id
     AND version.dataset_id = dataset.id
     AND version.id = (asset->>'datasetVersionId')::uuid
    LEFT JOIN app.dataset_version_objects link
      ON link.organization_id = version.organization_id
     AND link.dataset_id = version.dataset_id
     AND link.dataset_version_id = version.id
     AND link.data_object_id = (asset->>'objectId')::uuid
    LEFT JOIN app.data_objects object
      ON object.organization_id = link.organization_id
     AND object.dataset_id = link.dataset_id
     AND object.id = link.data_object_id
    WHERE project_dataset.dataset_id IS NULL
      OR dataset.classification <> 'public'
      OR dataset.status <> 'active'
      OR version.state <> 'active'
      OR object.id IS NULL
      OR object.s3_version_id IS DISTINCT FROM asset->>'storageVersionId'
      OR object.content_type IS DISTINCT FROM asset->>'contentType'
      OR object.size_bytes::text IS DISTINCT FROM asset->>'sizeBytes'
      OR object.checksum_sha256 IS DISTINCT FROM asset->>'checksumSha256'
      OR (asset->>'kind' = 'image' AND (
        object.content_type <> 'image/png'
        OR object.role::text NOT IN ('derived', 'published', 'thumbnail')
        OR object.size_bytes NOT BETWEEN 1 AND 4194304
      ))
      OR (asset->>'kind' = 'document' AND (
        version.geometry_type IS DISTINCT FROM 'document'
        OR object.role::text IS DISTINCT FROM 'derived'
        OR object.content_type IS DISTINCT FROM 'application/json'
        OR NOT coalesce(
          (
            dataset.format::text = 'odt'
            AND object.object_key LIKE '%/document/accessible-preview.json'
            AND object.size_bytes BETWEEN 1 AND 524288
            AND version.schema_definition #>> '{document,kind}' = 'odf_text'
            AND version.schema_definition #>> '{document,source_format}' = 'odt'
            AND version.schema_definition #>> '{document,accessible_preview_schema}' =
              'opengeo.document-preview.1.0.0'
          ) OR (
            dataset.format::text = 'pdf'
            AND app.pdf_document_publication_facts_valid_v1(
              version.schema_definition,
              object.object_key,
              object.size_bytes
            )
          ),
          false
        )
        OR version.quality_results #>> '{safety_scan,status}' IS DISTINCT FROM 'passed'
        OR version.quality_results #>> '{safety_scan,engine}' IS DISTINCT FROM 'ClamAV'
        OR version.quality_results #>> '{safety_scan,comprehensive_malware_scan}'
          IS DISTINCT FROM 'true'
        OR coalesce(version.quality_results #>> '{safety_scan,engine_version}', '') = ''
        OR coalesce(version.quality_results #>> '{safety_scan,signature_version}', '')
          !~ '^[1-9][0-9]*$'
      ))
  ) THEN
    RAISE EXCEPTION 'project site edition governed asset is invalid';
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION enforce_project_site_asset_seal_v14(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.enforce_project_site_asset_seal_v14() IS 'Seals exact governed page assets and permits scan-evidenced ODT or bounded PDF semantic, OCR, and visual presentations.';


--
-- Name: enforce_project_site_edition_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_edition_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  current_site app.project_sites%ROWTYPE;
  page_count bigint;
  home_count bigint;
  sealed_theme_options jsonb;
BEGIN
  IF NEW.published_by <> app.current_user_id()
    OR NEW.revoked_by IS NOT NULL
    OR NEW.revoked_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'project site edition publisher mismatch';
  END IF;
  SELECT * INTO current_site
  FROM app.project_sites site
  WHERE site.organization_id = NEW.organization_id
    AND site.project_id = NEW.project_id
    AND site.id = NEW.site_id
  FOR UPDATE;
  IF NOT FOUND
    OR current_site.state <> 'review'
    OR current_site.current_version_id <> NEW.site_version_id
    OR current_site.current_version_number <> NEW.site_version_number
  THEN
    RAISE EXCEPTION 'project site edition must publish the reviewed head';
  END IF;
  SELECT count(*), count(*) FILTER (WHERE page.is_home)
  INTO page_count, home_count
  FROM app.project_site_pages page
  WHERE page.organization_id = NEW.organization_id
    AND page.project_id = NEW.project_id
    AND page.site_id = NEW.site_id
    AND page.site_version_id = NEW.site_version_id;
  IF page_count NOT BETWEEN 1 AND 64 OR home_count <> 1 THEN
    RAISE EXCEPTION 'project site edition requires one to 64 pages and exactly one home page';
  END IF;
  SELECT version.theme_options INTO sealed_theme_options
  FROM app.project_site_versions version
  WHERE version.organization_id = NEW.organization_id
    AND version.project_id = NEW.project_id
    AND version.site_id = NEW.site_id
    AND version.id = NEW.site_version_id;
  IF NEW.manifest->>'schemaVersion' NOT IN (
       'opengeo.site-edition.1.0.0',
       'opengeo.site-edition.1.1.0',
       'opengeo.site-edition.1.2.0',
       'opengeo.site-edition.1.3.0',
       'opengeo.site-edition.1.4.0'
     )
    OR (
      NEW.manifest->>'schemaVersion' IN (
        'opengeo.site-edition.1.3.0', 'opengeo.site-edition.1.4.0'
      )
      AND NEW.manifest->'themeOptions' IS DISTINCT FROM sealed_theme_options
    )
    OR NEW.manifest->>'organizationId' <> NEW.organization_id::text
    OR NEW.manifest->>'projectId' <> NEW.project_id::text
    OR NEW.manifest->>'siteId' <> NEW.site_id::text
    OR NEW.manifest->>'siteVersionId' <> NEW.site_version_id::text
    OR NEW.manifest->>'siteVersionNumber' <> NEW.site_version_number::text
    OR NEW.manifest->>'editionId' <> NEW.id::text
    OR NEW.manifest->>'editionNumber' <> NEW.edition_number::text
    OR jsonb_typeof(NEW.manifest->'pages') <> 'array'
    OR jsonb_array_length(NEW.manifest->'pages') <> page_count
    OR jsonb_typeof(NEW.manifest->'references') <> 'array'
  THEN
    RAISE EXCEPTION 'project site edition manifest identity or shape mismatch';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM app.project_site_pages page
    WHERE page.organization_id = NEW.organization_id
      AND page.site_version_id = NEW.site_version_id
      AND NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(NEW.manifest->'pages') manifest_page
        WHERE manifest_page->>'slug' = page.page_slug
          AND manifest_page->>'navigationLabel' = page.navigation_label
          AND manifest_page->>'position' = page.position::text
          AND manifest_page->>'home' = lower(page.is_home::text)
          AND manifest_page->>'resourceId' = page.resource_id::text
          AND manifest_page->>'resourceVersionId' = page.resource_version_id::text
          AND manifest_page->>'resourceVersionNumber' = page.resource_version_number::text
      )
  ) THEN
    RAISE EXCEPTION 'project site edition manifest page seal mismatch';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM app.project_site_pages page
    JOIN app.governed_resources resource
      ON resource.organization_id = page.organization_id
     AND resource.project_id = page.project_id
     AND resource.id = page.resource_id
    WHERE page.organization_id = NEW.organization_id
      AND page.site_version_id = NEW.site_version_id
      AND (resource.state <> 'published' OR resource.visibility <> 'public')
  ) THEN
    RAISE EXCEPTION 'project site edition pages must be published and public';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM app.project_site_pages page
    JOIN app.governed_resource_versions version
      ON version.organization_id = page.organization_id
     AND version.resource_id = page.resource_id
     AND version.id = page.resource_version_id
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(version.content->'blocks') = 'array'
          THEN version.content->'blocks'
        ELSE '[]'::jsonb
      END
    ) block
    WHERE page.organization_id = NEW.organization_id
      AND page.site_version_id = NEW.site_version_id
      AND block->>'type' IN ('map', 'dataset')
      AND NOT EXISTS (
        SELECT 1
        FROM app.governed_resources referenced
        WHERE referenced.organization_id = NEW.organization_id
          AND referenced.project_id = NEW.project_id
          AND referenced.id = CASE
            WHEN block->>'resource_id' ~
              '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
              THEN (block->>'resource_id')::uuid
            ELSE NULL
          END
          AND referenced.state = 'published'
          AND referenced.visibility = 'public'
      )
  ) THEN
    RAISE EXCEPTION 'project site edition references must be published and public';
  END IF;
  IF (
    WITH expected_reference AS (
      SELECT page.resource_id
      FROM app.project_site_pages page
      JOIN app.governed_resources resource
        ON resource.organization_id = page.organization_id
       AND resource.project_id = page.project_id
       AND resource.id = page.resource_id
      WHERE page.organization_id = NEW.organization_id
        AND page.site_version_id = NEW.site_version_id
        AND resource.kind = 'map'
      UNION
      SELECT CASE
        WHEN block->>'resource_id' ~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
          THEN (block->>'resource_id')::uuid
        ELSE NULL
      END
      FROM app.project_site_pages page
      JOIN app.governed_resource_versions version
        ON version.organization_id = page.organization_id
       AND version.resource_id = page.resource_id
       AND version.id = page.resource_version_id
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(version.content->'blocks') = 'array'
            THEN version.content->'blocks'
          ELSE '[]'::jsonb
        END
      ) block
      WHERE page.organization_id = NEW.organization_id
        AND page.site_version_id = NEW.site_version_id
        AND block->>'type' IN ('map', 'dataset')
    )
    SELECT count(*) FROM expected_reference
  ) <> jsonb_array_length(NEW.manifest->'references')
    OR EXISTS (
      WITH expected_reference AS (
        SELECT page.resource_id
        FROM app.project_site_pages page
        JOIN app.governed_resources resource
          ON resource.organization_id = page.organization_id
         AND resource.project_id = page.project_id
         AND resource.id = page.resource_id
        WHERE page.organization_id = NEW.organization_id
          AND page.site_version_id = NEW.site_version_id
          AND resource.kind = 'map'
        UNION
        SELECT CASE
          WHEN block->>'resource_id' ~
            '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
            THEN (block->>'resource_id')::uuid
          ELSE NULL
        END
        FROM app.project_site_pages page
        JOIN app.governed_resource_versions version
          ON version.organization_id = page.organization_id
         AND version.resource_id = page.resource_id
         AND version.id = page.resource_version_id
        CROSS JOIN LATERAL jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(version.content->'blocks') = 'array'
              THEN version.content->'blocks'
            ELSE '[]'::jsonb
          END
        ) block
        WHERE page.organization_id = NEW.organization_id
          AND page.site_version_id = NEW.site_version_id
          AND block->>'type' IN ('map', 'dataset')
      )
      SELECT 1
      FROM expected_reference expected
      JOIN app.governed_resources resource
        ON resource.organization_id = NEW.organization_id
       AND resource.project_id = NEW.project_id
       AND resource.id = expected.resource_id
      JOIN app.governed_resource_versions version
        ON version.organization_id = resource.organization_id
       AND version.resource_id = resource.id
       AND version.id = resource.current_version_id
      WHERE NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(NEW.manifest->'references') manifest_reference
        WHERE manifest_reference->>'resourceId' = resource.id::text
          AND manifest_reference->>'versionId' = version.id::text
          AND manifest_reference->>'versionNumber' = version.version_number::text
          AND manifest_reference->>'kind' = resource.kind::text
      )
    )
  THEN
    RAISE EXCEPTION 'project site edition manifest reference seal mismatch';
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: enforce_project_site_edition_publication_destination_immutable(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_edition_publication_destination_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.publication_reach <> OLD.publication_reach
    OR NEW.listed_slug IS DISTINCT FROM OLD.listed_slug
    OR NEW.unlisted_token IS DISTINCT FROM OLD.unlisted_token
    OR NEW.is_primary <> OLD.is_primary
  THEN
    RAISE EXCEPTION 'project site edition publication destination is immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_edition_publication_destination_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_edition_publication_destination_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  destination app.project_site_publication_destinations%ROWTYPE;
BEGIN
  SELECT * INTO destination
  FROM app.project_site_publication_destinations current_destination
  WHERE current_destination.organization_id = NEW.organization_id
    AND current_destination.project_id = NEW.project_id
    AND current_destination.site_id = NEW.site_id;
  IF NOT FOUND
    OR NEW.publication_reach <> destination.reach
    OR (NEW.publication_reach = 'listed'
      AND NEW.listed_slug IS DISTINCT FROM destination.listed_slug)
    OR (NEW.publication_reach <> 'listed' AND NEW.listed_slug IS NOT NULL)
    OR NEW.is_primary <> destination.is_primary
    OR (NEW.manifest->'publication'->>'reach') IS DISTINCT FROM NEW.publication_reach::text
    OR (NEW.manifest->'publication'->>'listedSlug') IS DISTINCT FROM NEW.listed_slug
    OR (NEW.manifest->'publication'->>'unlistedToken') IS DISTINCT FROM NEW.unlisted_token
    OR (NEW.manifest->'publication'->>'primary') IS DISTINCT FROM lower(NEW.is_primary::text)
  THEN
    RAISE EXCEPTION 'project site edition publication destination seal mismatch';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_edition_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_edition_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.site_id <> OLD.site_id
    OR NEW.site_version_id <> OLD.site_version_id
    OR NEW.site_version_number <> OLD.site_version_number
    OR NEW.edition_number <> OLD.edition_number
    OR NEW.manifest <> OLD.manifest
    OR NEW.manifest_checksum_sha256 <> OLD.manifest_checksum_sha256
    OR NEW.published_by <> OLD.published_by
    OR NEW.published_at <> OLD.published_at
    OR OLD.revoked_at IS NOT NULL
    OR NEW.revoked_at IS NULL
    OR NEW.revoked_by IS NULL
    OR NEW.revoked_by <> app.current_user_id()
  THEN
    RAISE EXCEPTION 'project site edition revocation is one-way and actor-bound';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.created_by <> app.current_user_id()
    OR NEW.updated_by <> app.current_user_id()
    OR NEW.current_version_number <> 1
    OR NEW.state <> 'draft'
  THEN
    RAISE EXCEPTION 'project site creator or initial state mismatch';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_page_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_page_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.created_by <> app.current_user_id() THEN
    RAISE EXCEPTION 'project site page creator mismatch';
  END IF;
  PERFORM 1
  FROM app.governed_resources resource
  JOIN app.governed_resource_versions version
    ON version.organization_id = resource.organization_id
   AND version.resource_id = resource.id
  WHERE resource.organization_id = NEW.organization_id
    AND resource.project_id = NEW.project_id
    AND resource.id = NEW.resource_id
    AND resource.kind IN ('document', 'story', 'dashboard', 'map')
    AND version.id = NEW.resource_version_id
    AND version.version_number = NEW.resource_version_number;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'project site page must pin an editorial or map resource version';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_print_layout_seal(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_print_layout_seal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  sealed_print_layout jsonb;
BEGIN
  SELECT version.print_layout INTO sealed_print_layout
  FROM app.project_site_versions version
  WHERE version.organization_id = NEW.organization_id
    AND version.project_id = NEW.project_id
    AND version.site_id = NEW.site_id
    AND version.id = NEW.site_version_id;
  IF NEW.manifest->>'schemaVersion' = 'opengeo.site-edition.1.3.0'
    AND NEW.manifest->'printLayout' IS DISTINCT FROM sealed_print_layout
  THEN
    RAISE EXCEPTION 'project site edition print layout seal mismatch';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(sealed_print_layout->'pages') layout_page
    WHERE NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(NEW.manifest->'pages') = 'array'
          THEN NEW.manifest->'pages' ELSE '[]'::jsonb END
      ) manifest_page
      WHERE manifest_page->>'slug' = layout_page->>'sitePageSlug'
    )
  ) THEN
    RAISE EXCEPTION 'project site edition print layout page seal mismatch';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(sealed_print_layout->'pages') layout_page
    CROSS JOIN LATERAL jsonb_array_elements(layout_page->'elements') element
    WHERE element->>'type' = 'map_frame'
      AND NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(
          CASE WHEN jsonb_typeof(NEW.manifest->'references') = 'array'
            THEN NEW.manifest->'references' ELSE '[]'::jsonb END
        ) manifest_reference
        WHERE manifest_reference->>'resourceId' = element->>'resourceId'
          AND manifest_reference->>'kind' = 'map'
          AND jsonb_typeof(manifest_reference->'snapshot') = 'object'
      )
  ) THEN
    RAISE EXCEPTION 'project site edition print layout snapshot seal mismatch';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_publication_destination_event_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_publication_destination_event_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  destination app.project_site_publication_destinations%ROWTYPE;
  previous_event app.project_site_publication_destination_events%ROWTYPE;
  site_slug text;
BEGIN
  IF NEW.actor_user_id <> app.current_user_id() THEN
    RAISE EXCEPTION 'project site publication destination event actor mismatch';
  END IF;
  SELECT * INTO destination
  FROM app.project_site_publication_destinations current_destination
  WHERE current_destination.organization_id = NEW.organization_id
    AND current_destination.project_id = NEW.project_id
    AND current_destination.site_id = NEW.site_id;
  IF NOT FOUND
    OR destination.revision <> NEW.destination_revision
    OR destination.reach <> NEW.target_reach
    OR destination.listed_slug IS DISTINCT FROM NEW.target_listed_slug
    OR destination.is_primary <> NEW.target_is_primary
  THEN
    RAISE EXCEPTION 'project site publication destination event does not match head';
  END IF;
  IF NEW.destination_revision = 2 THEN
    SELECT lower(site.slug) INTO site_slug
    FROM app.project_sites site
    WHERE site.organization_id = NEW.organization_id
      AND site.project_id = NEW.project_id
      AND site.id = NEW.site_id;
    IF NEW.source_reach <> 'unpublished'
      OR NEW.source_is_primary
      OR (
        NEW.source_listed_slug IS NOT NULL
        AND NEW.source_listed_slug IS DISTINCT FROM site_slug
      )
    THEN
      RAISE EXCEPTION 'project site publication destination event source mismatch';
    END IF;
  ELSE
    SELECT * INTO previous_event
    FROM app.project_site_publication_destination_events event
    WHERE event.organization_id = NEW.organization_id
      AND event.project_id = NEW.project_id
      AND event.site_id = NEW.site_id
      AND event.destination_revision = NEW.destination_revision - 1;
    IF NOT FOUND
      OR NEW.source_reach <> previous_event.target_reach
      OR NEW.source_listed_slug IS DISTINCT FROM previous_event.target_listed_slug
      OR NEW.source_is_primary <> previous_event.target_is_primary
    THEN
      RAISE EXCEPTION 'project site publication destination event source mismatch';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_publication_destination_event_recorded(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_publication_destination_event_recorded() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM 1
  FROM app.project_site_publication_destination_events event
  WHERE event.organization_id = NEW.organization_id
    AND event.project_id = NEW.project_id
    AND event.site_id = NEW.site_id
    AND event.destination_revision = NEW.revision
    AND event.target_reach = NEW.reach
    AND event.target_listed_slug IS NOT DISTINCT FROM NEW.listed_slug
    AND event.target_is_primary = NEW.is_primary
    AND event.actor_user_id = NEW.configured_by;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'project site publication destination update must record its event';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_publication_destination_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_publication_destination_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.revision <> 1
    OR NEW.reach <> 'unpublished'
    OR NEW.is_primary
    OR NEW.configured_by <> app.current_user_id()
  THEN
    RAISE EXCEPTION 'project site publication destination initial state mismatch';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_publication_destination_update(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_publication_destination_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.listed_slug IS DISTINCT FROM OLD.listed_slug
    AND OLD.listed_slug IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM app.project_site_editions edition
      WHERE edition.organization_id = OLD.organization_id
        AND edition.project_id = OLD.project_id
        AND edition.site_id = OLD.site_id
        AND edition.publication_reach = 'listed'
    )
  THEN
    RAISE EXCEPTION 'published listed project site path is immutable';
  END IF;
  IF NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.site_id <> OLD.site_id
    OR NEW.revision <> OLD.revision + 1
    OR NEW.configured_by <> app.current_user_id()
    OR NEW.configured_at < OLD.configured_at
  THEN
    RAISE EXCEPTION 'project site publication destination revision mismatch';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_rich_print_layout_seal(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_rich_print_layout_seal() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  sealed_print_layout jsonb;
  layout_page jsonb;
  element jsonb;
  map_element jsonb;
  content_block jsonb;
  page_content jsonb;
BEGIN
  SELECT version.print_layout INTO sealed_print_layout
  FROM app.project_site_versions version
  WHERE version.organization_id = NEW.organization_id
    AND version.project_id = NEW.project_id
    AND version.site_id = NEW.site_id
    AND version.id = NEW.site_version_id;

  IF sealed_print_layout->>'schemaVersion' <> 'opengeo.print-layout.1.1.0' THEN
    RETURN NEW;
  END IF;

  FOR layout_page IN
    SELECT item FROM jsonb_array_elements(sealed_print_layout->'pages') item
  LOOP
    SELECT resource_version.content INTO page_content
    FROM app.project_site_pages page
    JOIN app.governed_resource_versions resource_version
      ON resource_version.organization_id = page.organization_id
     AND resource_version.resource_id = page.resource_id
     AND resource_version.id = page.resource_version_id
    WHERE page.organization_id = NEW.organization_id
      AND page.project_id = NEW.project_id
      AND page.site_id = NEW.site_id
      AND page.site_version_id = NEW.site_version_id
      AND page.page_slug = layout_page->>'sitePageSlug';
    IF page_content IS NULL THEN
      RAISE EXCEPTION 'project site edition rich layout page seal mismatch';
    END IF;

    FOR element IN SELECT item FROM jsonb_array_elements(layout_page->'elements') item LOOP
      IF element->>'type' = 'legend_frame' THEN
        SELECT item INTO map_element
        FROM jsonb_array_elements(layout_page->'elements') item
        WHERE item->>'type' = 'map_frame'
          AND item->>'id' = element->>'mapFrameId';
        IF map_element IS NULL OR NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements(
            CASE WHEN jsonb_typeof(NEW.manifest->'references') = 'array'
              THEN NEW.manifest->'references' ELSE '[]'::jsonb END
          ) reference
          WHERE reference->>'resourceId' = map_element->>'resourceId'
            AND jsonb_typeof(reference->'snapshot'->'legend') = 'object'
            AND jsonb_typeof(reference->'snapshot'->'legend'->'items') = 'array'
            AND jsonb_array_length(reference->'snapshot'->'legend'->'items') BETWEEN 1 AND 17
            AND reference->'snapshot'->'legend'->>'profileChecksumSha256' ~ '^[0-9a-f]{64}$'
        ) THEN
          RAISE EXCEPTION 'project site edition style legend seal mismatch';
        END IF;
      ELSIF element->>'type' IN ('image_frame', 'table_frame', 'chart_frame') THEN
        SELECT item INTO content_block
        FROM jsonb_array_elements(
          CASE WHEN jsonb_typeof(page_content->'blocks') = 'array'
            THEN page_content->'blocks' ELSE '[]'::jsonb END
        ) item
        WHERE item->>'id' = element->>'blockId';
        IF content_block IS NULL OR content_block->>'type' <>
          (CASE element->>'type'
            WHEN 'image_frame' THEN 'image'
            WHEN 'table_frame' THEN 'table'
            ELSE 'chart'
          END)
        THEN
          RAISE EXCEPTION 'project site edition content frame seal mismatch';
        END IF;
        IF element->>'type' = 'image_frame' AND NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements(
            CASE WHEN jsonb_typeof(NEW.manifest->'assets') = 'array'
              THEN NEW.manifest->'assets' ELSE '[]'::jsonb END
          ) asset
          WHERE asset->>'kind' = 'image'
            AND asset->>'objectId' = content_block->>'object_id'
            AND asset->>'contentType' = 'image/png'
        ) THEN
          RAISE EXCEPTION 'project site edition image frame seal mismatch';
        END IF;
      END IF;
    END LOOP;
  END LOOP;
  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION enforce_project_site_rich_print_layout_seal(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.enforce_project_site_rich_print_layout_seal() IS 'Requires style-derived legends and image/table/chart frames to resolve through the exact edition.';


--
-- Name: enforce_project_site_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  version_changed boolean;
  state_changed boolean;
BEGIN
  IF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.slug <> OLD.slug
    OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
    OR NEW.updated_by <> app.current_user_id()
    OR NEW.updated_at <= OLD.updated_at
  THEN
    RAISE EXCEPTION 'project site identity or update actor mismatch';
  END IF;
  version_changed := NEW.current_version_id <> OLD.current_version_id;
  state_changed := NEW.state <> OLD.state;
  IF version_changed THEN
    IF NEW.current_version_number <> OLD.current_version_number + 1
      OR NEW.state <> 'draft'
    THEN
      RAISE EXCEPTION 'project site revision must advance once and return to draft';
    END IF;
  ELSIF state_changed THEN
    IF NEW.current_version_number <> OLD.current_version_number
      OR NOT (
        (OLD.state = 'draft' AND NEW.state = 'review')
        OR (OLD.state = 'review' AND NEW.state = 'published')
      )
    THEN
      RAISE EXCEPTION 'project site editorial transition is invalid';
    END IF;
  ELSE
    RAISE EXCEPTION 'project site update must create a revision or editorial transition';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_version_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_version_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  current_site app.project_sites%ROWTYPE;
BEGIN
  IF NEW.created_by <> app.current_user_id() THEN
    RAISE EXCEPTION 'project site version creator mismatch';
  END IF;
  SELECT * INTO current_site
  FROM app.project_sites site
  WHERE site.organization_id = NEW.organization_id
    AND site.project_id = NEW.project_id
    AND site.id = NEW.site_id
  FOR UPDATE;
  IF NOT FOUND
    OR NOT (
      (NEW.version_number = 1
       AND current_site.current_version_number = 1
       AND current_site.current_version_id = NEW.id)
      OR NEW.version_number = current_site.current_version_number + 1
    )
  THEN
    RAISE EXCEPTION 'project site version must follow the current head';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_site_workflow_event_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_project_site_workflow_event_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.actor_user_id <> app.current_user_id() THEN
    RAISE EXCEPTION 'project site workflow actor mismatch';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_public_wms_service_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_public_wms_service_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.created_by <> app.current_user_id()
    OR NEW.disabled_by IS NOT NULL
    OR NEW.disabled_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'public WMS service creator mismatch';
  END IF;

  PERFORM 1
  FROM app.wms_layer_publications publication
  JOIN app.governed_resources resource
    ON resource.organization_id = publication.organization_id
   AND resource.project_id = publication.project_id
   AND resource.id = publication.resource_id
  WHERE publication.organization_id = NEW.organization_id
    AND publication.project_id = NEW.project_id
    AND publication.withdrawn_at IS NULL
    AND resource.kind IN ('dataset', 'service')
    AND resource.state = 'published'
    AND resource.visibility = 'public';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'public WMS service requires an active public layer publication';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_public_wms_service_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_public_wms_service_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.title <> OLD.title
    OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
  THEN
    RAISE EXCEPTION 'public WMS service identity is immutable';
  END IF;
  IF OLD.disabled_at IS NOT NULL
    OR NEW.disabled_at IS NULL
    OR NEW.disabled_by IS NULL
    OR NEW.disabled_by <> app.current_user_id()
    OR NEW.disabled_at < OLD.created_at
  THEN
    RAISE EXCEPTION 'public WMS service disable is one-way and actor-bound';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_repository_copy_estimate_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_repository_copy_estimate_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_source record;
BEGIN
  SELECT dataset.format::text AS format, source.size_bytes,
         source.content_type, source.created_by
  INTO v_source
  FROM app.repository_object_sources source
  JOIN app.datasets dataset
    ON dataset.organization_id = source.organization_id
   AND dataset.id = source.dataset_id
  JOIN app.project_datasets link
    ON link.organization_id = source.organization_id
   AND link.dataset_id = source.dataset_id
   AND link.project_id = NEW.project_id
  WHERE source.organization_id = NEW.organization_id
    AND source.dataset_id = NEW.source_dataset_id;
  IF NEW.created_by <> app.current_user_id()
    OR COALESCE(app.effective_project_role(NEW.project_id, NEW.created_by)::text, '')
      NOT IN ('owner', 'editor')
    OR v_source.format IS NULL
    OR v_source.format <> NEW.output_format::text
    OR v_source.size_bytes <> NEW.maximum_output_bytes
    OR v_source.size_bytes > 536870912
    OR v_source.content_type IS NULL
    OR lower(v_source.content_type) <> NEW.output_content_type
  THEN
    RAISE EXCEPTION 'repository copy estimate does not match an exact project source';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_repository_copy_job_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_repository_copy_job_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_estimate app.repository_object_copy_estimates%ROWTYPE;
  v_destination app.datasets%ROWTYPE;
BEGIN
  IF NEW.created_by <> app.current_user_id() OR NEW.state <> 'queued'
    OR NEW.output_object_id IS NOT NULL OR NEW.output_dataset_version_id IS NOT NULL
    OR NEW.error_code IS NOT NULL OR NEW.worker_token IS NOT NULL
    OR NEW.attempt_count <> 0 OR NEW.started_at IS NOT NULL OR NEW.finished_at IS NOT NULL
  THEN RAISE EXCEPTION 'repository copy creator or initial state mismatch'; END IF;
  IF COALESCE(app.effective_project_role(NEW.project_id, NEW.created_by)::text, '')
    NOT IN ('owner', 'editor')
  THEN RAISE EXCEPTION 'repository copy requires project edit access'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'opengeo:repository-copy-quota:' || NEW.organization_id::text, 0
  ));
  SELECT * INTO v_estimate FROM app.repository_object_copy_estimates
  WHERE organization_id = NEW.organization_id AND id = NEW.estimate_id;
  SELECT * INTO v_destination FROM app.datasets
  WHERE organization_id = NEW.organization_id AND id = NEW.destination_dataset_id;
  IF v_estimate.id IS NULL OR v_estimate.project_id <> NEW.project_id
    OR v_estimate.source_dataset_id <> NEW.source_dataset_id
    OR v_estimate.created_by <> NEW.created_by
    OR v_estimate.expires_at <= clock_timestamp()
    OR v_destination.source_type <> 'upload'
    OR v_destination.format <> v_estimate.output_format
    OR v_destination.status <> 'draft' OR v_destination.current_version_id IS NOT NULL
    OR v_destination.owner_user_id <> NEW.created_by
    OR NOT EXISTS (
      SELECT 1 FROM app.project_datasets link
      WHERE link.organization_id = NEW.organization_id
        AND link.project_id = NEW.project_id
        AND link.dataset_id = NEW.destination_dataset_id
    )
  THEN RAISE EXCEPTION 'repository copy does not match its estimate and destination'; END IF;
  IF (SELECT count(*) FROM app.repository_object_copy_jobs job
      WHERE job.organization_id = NEW.organization_id
        AND job.state IN ('queued', 'running')) >= 4
    OR (SELECT count(*) FROM app.repository_object_copy_jobs job
        WHERE job.organization_id = NEW.organization_id
          AND job.source_dataset_id = NEW.source_dataset_id
          AND job.created_at >= clock_timestamp() - interval '24 hours') >= 64
    OR COALESCE((
      SELECT sum(estimate.maximum_output_bytes)
      FROM app.repository_object_copy_jobs job
      JOIN app.repository_object_copy_estimates estimate
        ON estimate.organization_id = job.organization_id
       AND estimate.id = job.estimate_id
      WHERE job.organization_id = NEW.organization_id
        AND job.created_at >= clock_timestamp() - interval '24 hours'
        AND job.state <> 'cancelled'
    ), 0) + v_estimate.maximum_output_bytes > 10737418240
  THEN RAISE EXCEPTION 'repository copy quota exceeded'; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_repository_copy_job_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_repository_copy_job_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id OR NEW.estimate_id <> OLD.estimate_id
    OR NEW.source_dataset_id <> OLD.source_dataset_id
    OR NEW.destination_dataset_id <> OLD.destination_dataset_id
    OR NEW.destination_bucket <> OLD.destination_bucket
    OR NEW.rights_basis <> OLD.rights_basis OR NEW.attribution <> OLD.attribution
    OR NEW.request_checksum_sha256 <> OLD.request_checksum_sha256
    OR NEW.idempotency_key <> OLD.idempotency_key
    OR NEW.request_id <> OLD.request_id OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at OR NEW.attempt_count < OLD.attempt_count
    OR (OLD.started_at IS NOT NULL AND NEW.started_at IS DISTINCT FROM OLD.started_at)
  THEN RAISE EXCEPTION 'repository copy request seal is immutable'; END IF;
  IF OLD.state IN ('completed', 'failed', 'cancelled') THEN
    RAISE EXCEPTION 'repository copy terminal state is immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_repository_object_source_dataset(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_repository_object_source_dataset() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_source_type text;
BEGIN
  SELECT source_type::text INTO v_source_type
  FROM app.datasets
  WHERE organization_id = NEW.organization_id AND id = NEW.dataset_id;

  IF v_source_type IS NULL OR v_source_type <> 'repository' THEN
    RAISE EXCEPTION 'repository object source must identify a repository dataset';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_coverage_derivative_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_coverage_derivative_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_coverage app.spatial_service_coverages%ROWTYPE;
  v_total integer;
  v_active integer;
  v_expected_width integer;
  v_expected_height integer;
  v_all_bands jsonb;
BEGIN
  IF NEW.created_by <> app.current_user_id() OR NEW.state <> 'queued'
    OR NEW.output_object_id IS NOT NULL OR NEW.worker_token IS NOT NULL
  THEN RAISE EXCEPTION 'coverage derivative creator or initial state mismatch'; END IF;
  SELECT coverage.* INTO v_coverage
  FROM app.spatial_service_coverages coverage
  JOIN app.spatial_services service ON service.organization_id = coverage.organization_id
    AND service.project_id = coverage.project_id AND service.id = coverage.service_id
  JOIN app.datasets dataset ON dataset.organization_id = coverage.organization_id
    AND dataset.id = coverage.dataset_id AND dataset.current_version_id = coverage.dataset_version_id
    AND dataset.status = 'active' AND dataset.format = 'cog'
  JOIN app.dataset_versions version ON version.organization_id = coverage.organization_id
    AND version.dataset_id = coverage.dataset_id AND version.id = coverage.dataset_version_id
    AND version.version_number = coverage.sealed_dataset_version_number
    AND version.state = 'active' AND version.geometry_type = 'raster'
  JOIN app.data_objects object ON object.organization_id = coverage.organization_id
    AND object.dataset_id = coverage.dataset_id AND object.id = coverage.data_object_id
    AND object.bucket = coverage.sealed_bucket AND object.object_key = coverage.sealed_object_key
    AND object.s3_version_id = coverage.sealed_storage_version_id
    AND object.content_type = coverage.sealed_content_type
    AND object.size_bytes = coverage.sealed_size_bytes
    AND object.checksum_sha256 = coverage.sealed_checksum_sha256
  WHERE coverage.organization_id = NEW.organization_id
    AND coverage.project_id = NEW.project_id AND coverage.service_id = NEW.service_id
    AND coverage.id = NEW.coverage_id AND coverage.withdrawn_at IS NULL
    AND service.disabled_at IS NULL AND object.role = 'original'
    AND object.size_bytes <= 536870912
  FOR UPDATE OF coverage;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'coverage derivative must target a fresh active exact COG seal';
  END IF;
  SELECT count(*) FILTER (WHERE NOT EXISTS (
           SELECT 1 FROM app.spatial_coverage_derivative_reclamations reclamation
           WHERE reclamation.organization_id = job.organization_id
             AND reclamation.derivative_job_id = job.id
             AND reclamation.state = 'completed'))::integer,
         count(*) FILTER (WHERE job.state IN ('queued', 'running'))::integer
  INTO v_total, v_active
  FROM app.spatial_coverage_derivative_jobs job
  WHERE job.organization_id = NEW.organization_id AND job.coverage_id = NEW.coverage_id;
  IF v_total >= 64 THEN RAISE EXCEPTION 'coverage derivative retained-job quota exceeded'; END IF;
  IF v_active >= 4 THEN RAISE EXCEPTION 'coverage derivative active-job quota exceeded'; END IF;
  SELECT jsonb_agg(index ORDER BY index) INTO v_all_bands
  FROM generate_series(1, v_coverage.sealed_band_count) AS index;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(NEW.band_indexes) item
             WHERE item::integer > v_coverage.sealed_band_count)
    OR (NEW.request_schema_version = 1 AND NEW.band_indexes <> v_all_bands)
  THEN RAISE EXCEPTION 'coverage derivative range subset is invalid'; END IF;
  IF (NEW.subset_extent->>0)::numeric < (v_coverage.sealed_extent->>0)::numeric
    OR (NEW.subset_extent->>1)::numeric < (v_coverage.sealed_extent->>1)::numeric
    OR (NEW.subset_extent->>2)::numeric > (v_coverage.sealed_extent->>2)::numeric
    OR (NEW.subset_extent->>3)::numeric > (v_coverage.sealed_extent->>3)::numeric
    OR NEW.target_width::bigint * NEW.target_height::bigint
       * jsonb_array_length(NEW.band_indexes)::bigint > 67108864
  THEN RAISE EXCEPTION 'coverage derivative request exceeds the sealed raster bounds'; END IF;
  IF NEW.scale_mode = 'resolution' THEN
    IF NEW.target_crs <> v_coverage.sealed_crs THEN
      RAISE EXCEPTION 'coverage derivative resolution scaling requires source CRS';
    END IF;
    v_expected_width := ceil(((NEW.subset_extent->>2)::numeric
      - (NEW.subset_extent->>0)::numeric) / (NEW.requested_resolution->>0)::numeric)::integer;
    v_expected_height := ceil(((NEW.subset_extent->>3)::numeric
      - (NEW.subset_extent->>1)::numeric) / (NEW.requested_resolution->>1)::numeric)::integer;
    IF v_expected_width <> NEW.target_width OR v_expected_height <> NEW.target_height THEN
      RAISE EXCEPTION 'coverage derivative resolution grid mismatch';
    END IF;
  END IF;
  IF NEW.subset_extent = v_coverage.sealed_extent
    AND NEW.target_crs = v_coverage.sealed_crs
    AND NEW.target_width = v_coverage.sealed_width
    AND NEW.target_height = v_coverage.sealed_height
    AND NEW.band_indexes = v_all_bands
  THEN RAISE EXCEPTION 'coverage derivative request is identical to the exact source'; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_coverage_derivative_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_coverage_derivative_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.service_id <> OLD.service_id
    OR NEW.coverage_id <> OLD.coverage_id
    OR NEW.subset_extent <> OLD.subset_extent
    OR NEW.target_crs <> OLD.target_crs
    OR NEW.target_width <> OLD.target_width
    OR NEW.target_height <> OLD.target_height
    OR NEW.resampling <> OLD.resampling
    OR NEW.request_schema_version <> OLD.request_schema_version
    OR NEW.band_indexes <> OLD.band_indexes
    OR NEW.scale_mode <> OLD.scale_mode
    OR NEW.requested_resolution IS DISTINCT FROM OLD.requested_resolution
    OR NEW.request_checksum_sha256 <> OLD.request_checksum_sha256
    OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
    OR NEW.attempt_count < OLD.attempt_count
    OR NEW.started_at IS DISTINCT FROM OLD.started_at AND OLD.started_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'coverage derivative request seal is immutable';
  END IF;
  IF OLD.state IN ('completed', 'failed', 'cancelled') THEN
    RAISE EXCEPTION 'coverage derivative terminal state is immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_service_collection_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_service_collection_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.created_by <> app.current_user_id()
    OR NEW.withdrawn_by IS NOT NULL OR NEW.withdrawn_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'spatial service collection creator mismatch';
  END IF;

  IF NEW.store_id IS NULL THEN
    SELECT store.id INTO NEW.store_id
    FROM app.spatial_service_stores store
    WHERE store.organization_id = NEW.organization_id
      AND store.service_id = NEW.service_id
      AND store.kind = 'managed_project'
      AND store.disabled_at IS NULL
    ORDER BY store.created_at, store.id
    LIMIT 1;
  END IF;

  PERFORM 1
  FROM app.spatial_services service
  JOIN app.spatial_service_stores store
    ON store.organization_id = service.organization_id
   AND store.project_id = service.project_id
   AND store.service_id = service.id
   AND store.id = NEW.store_id
   AND store.disabled_at IS NULL
  JOIN app.datasets dataset
    ON dataset.organization_id = service.organization_id
   AND dataset.id = NEW.dataset_id
  JOIN app.feature_collections feature_collection
    ON feature_collection.organization_id = dataset.organization_id
   AND feature_collection.dataset_id = dataset.id
  JOIN app.governed_resources resource
    ON resource.organization_id = service.organization_id
   AND resource.project_id = service.project_id
   AND resource.id = NEW.resource_id
   AND resource.dataset_id = dataset.id
  JOIN app.map_render_profiles profile
    ON profile.organization_id = resource.organization_id
   AND profile.project_id = resource.project_id
   AND profile.resource_id = resource.id
   AND profile.id = NEW.default_profile_id
  JOIN app.map_render_profile_versions profile_version
    ON profile_version.organization_id = profile.organization_id
   AND profile_version.profile_id = profile.id
   AND profile_version.id = profile.current_version_id
   AND profile_version.id = NEW.sealed_profile_version_id
   AND profile_version.version_number = NEW.sealed_profile_version_number
   AND profile_version.dataset_id = dataset.id
   AND profile_version.dataset_version_id = dataset.current_version_id
  WHERE service.organization_id = NEW.organization_id
    AND service.project_id = NEW.project_id AND service.id = NEW.service_id
    AND service.disabled_at IS NULL AND dataset.status = 'active'
    AND dataset.format IN ('geojson', 'shapefile', 'geopackage', 'geoparquet')
    AND feature_collection.generation = NEW.sealed_feature_generation
    AND resource.kind IN ('dataset', 'service') AND resource.state = 'published'
    AND (
      store.kind = 'managed_project'
      OR (store.kind = 'external_source' AND store.dataset_id = dataset.id)
    );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'spatial service collection must seal current governed targets in an active compatible store';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_service_collection_style_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_service_collection_style_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.created_by <> app.current_user_id()
    OR NEW.withdrawn_by IS NOT NULL OR NEW.withdrawn_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'spatial service collection style creator mismatch';
  END IF;
  PERFORM 1
  FROM app.spatial_service_collections collection
  JOIN app.governed_resource_styles style
    ON style.organization_id = collection.organization_id
   AND style.project_id = collection.project_id
   AND style.resource_id = collection.resource_id
   AND style.id = NEW.style_id
  JOIN app.governed_resource_style_versions style_version
    ON style_version.organization_id = style.organization_id
   AND style_version.style_id = style.id
   AND style_version.id = style.current_version_id
   AND style_version.id = NEW.sealed_style_version_id
   AND style_version.version_number = NEW.sealed_style_version_number
  LEFT JOIN app.map_render_profiles profile
    ON profile.organization_id = collection.organization_id
   AND profile.project_id = collection.project_id
   AND profile.resource_id = collection.resource_id
   AND profile.id = NEW.render_profile_id
  LEFT JOIN app.map_render_profile_versions profile_version
    ON profile_version.organization_id = profile.organization_id
   AND profile_version.profile_id = profile.id
   AND profile_version.id = profile.current_version_id
   AND profile_version.id = NEW.sealed_profile_version_id
   AND profile_version.version_number = NEW.sealed_profile_version_number
   AND profile_version.style_id = NEW.style_id
   AND profile_version.style_version_id = NEW.sealed_style_version_id
  WHERE collection.organization_id = NEW.organization_id
    AND collection.project_id = NEW.project_id
    AND collection.service_id = NEW.service_id
    AND collection.id = NEW.collection_id
    AND collection.withdrawn_at IS NULL
    AND (
      (NEW.render_profile_id IS NULL AND NOT NEW.is_default)
      OR profile_version.id IS NOT NULL
    );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'spatial service collection style must seal current same-resource style and profile revisions';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_service_collection_style_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_service_collection_style_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id OR NEW.service_id <> OLD.service_id
    OR NEW.collection_id <> OLD.collection_id OR NEW.style_name <> OLD.style_name
    OR NEW.style_id <> OLD.style_id
    OR NEW.sealed_style_version_id <> OLD.sealed_style_version_id
    OR NEW.sealed_style_version_number <> OLD.sealed_style_version_number
    OR NEW.render_profile_id IS DISTINCT FROM OLD.render_profile_id
    OR NEW.sealed_profile_version_id IS DISTINCT FROM OLD.sealed_profile_version_id
    OR NEW.sealed_profile_version_number IS DISTINCT FROM OLD.sealed_profile_version_number
    OR NEW.is_default <> OLD.is_default OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
  THEN
    RAISE EXCEPTION 'spatial service collection style seal is immutable';
  END IF;
  IF OLD.withdrawn_at IS NOT NULL OR NEW.withdrawn_at IS NULL
    OR NEW.withdrawn_by <> app.current_user_id()
  THEN
    RAISE EXCEPTION 'spatial service collection style withdrawal is one-way and actor-bound';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_service_collection_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_service_collection_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id OR NEW.service_id <> OLD.service_id
    OR NEW.store_id <> OLD.store_id OR NEW.collection_name <> OLD.collection_name
    OR NEW.dataset_id <> OLD.dataset_id OR NEW.resource_id <> OLD.resource_id
    OR NEW.default_profile_id <> OLD.default_profile_id
    OR NEW.sealed_feature_generation <> OLD.sealed_feature_generation
    OR NEW.sealed_profile_version_id <> OLD.sealed_profile_version_id
    OR NEW.sealed_profile_version_number <> OLD.sealed_profile_version_number
    OR NEW.title <> OLD.title OR NEW.description IS DISTINCT FROM OLD.description
    OR NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at
  THEN
    RAISE EXCEPTION 'spatial service collection seal is immutable';
  END IF;
  IF OLD.withdrawn_at IS NOT NULL OR NEW.withdrawn_at IS NULL
    OR NEW.withdrawn_by <> app.current_user_id()
  THEN
    RAISE EXCEPTION 'spatial service collection withdrawal is one-way and actor-bound';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_service_coverage_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_service_coverage_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.created_by <> app.current_user_id()
    OR NEW.withdrawn_by IS NOT NULL
    OR NEW.withdrawn_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'spatial service coverage creator mismatch';
  END IF;

  PERFORM 1
  FROM app.spatial_services service
  JOIN app.datasets dataset
    ON dataset.organization_id = service.organization_id
   AND dataset.id = NEW.dataset_id
  JOIN app.dataset_versions version
    ON version.organization_id = dataset.organization_id
   AND version.dataset_id = dataset.id
   AND version.id = dataset.current_version_id
   AND version.id = NEW.dataset_version_id
  JOIN app.dataset_version_objects link
    ON link.organization_id = version.organization_id
   AND link.dataset_id = version.dataset_id
   AND link.dataset_version_id = version.id
   AND link.data_object_id = NEW.data_object_id
  JOIN app.data_objects object
    ON object.organization_id = link.organization_id
   AND object.dataset_id = link.dataset_id
   AND object.id = link.data_object_id
  WHERE service.organization_id = NEW.organization_id
    AND service.project_id = NEW.project_id
    AND service.id = NEW.service_id
    AND service.disabled_at IS NULL
    AND dataset.status = 'active'
    AND dataset.source_type = 'upload'
    AND dataset.format = 'cog'
    AND version.state = 'active'
    AND version.version_number = NEW.sealed_dataset_version_number
    AND version.original_object_id = object.id
    AND version.geometry_type = 'raster'
    AND version.crs = NEW.sealed_crs
    AND version.extent = NEW.sealed_extent
    AND jsonb_typeof(version.extent) = 'array'
    AND jsonb_array_length(version.extent) = 4
    AND version.schema_definition #>> '{raster,width}' = NEW.sealed_width::text
    AND version.schema_definition #>> '{raster,height}' = NEW.sealed_height::text
    AND version.schema_definition #>> '{raster,band_count}' = NEW.sealed_band_count::text
    AND version.schema_definition #> '{raster,bands}' = NEW.sealed_bands
    AND version.quality_results @> '{"valid":true,"checks":[{"code":"cog_layout_verified","status":"passed"}]}'::jsonb
    AND object.role = 'original'
    AND object.bucket = NEW.sealed_bucket
    AND object.object_key = NEW.sealed_object_key
    AND object.s3_version_id = NEW.sealed_storage_version_id
    AND object.content_type = NEW.sealed_content_type
    AND object.content_type IN ('image/tiff', 'image/geotiff')
    AND object.size_bytes = NEW.sealed_size_bytes
    AND object.checksum_sha256 = NEW.sealed_checksum_sha256;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'spatial service coverage must seal current validated COG original';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_service_coverage_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_service_coverage_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.service_id <> OLD.service_id
    OR NEW.coverage_name <> OLD.coverage_name
    OR NEW.dataset_id <> OLD.dataset_id
    OR NEW.dataset_version_id <> OLD.dataset_version_id
    OR NEW.data_object_id <> OLD.data_object_id
    OR NEW.sealed_dataset_version_number <> OLD.sealed_dataset_version_number
    OR NEW.sealed_crs <> OLD.sealed_crs
    OR NEW.sealed_extent <> OLD.sealed_extent
    OR NEW.sealed_width <> OLD.sealed_width
    OR NEW.sealed_height <> OLD.sealed_height
    OR NEW.sealed_band_count <> OLD.sealed_band_count
    OR NEW.sealed_bands <> OLD.sealed_bands
    OR NEW.sealed_bucket <> OLD.sealed_bucket
    OR NEW.sealed_object_key <> OLD.sealed_object_key
    OR NEW.sealed_storage_version_id <> OLD.sealed_storage_version_id
    OR NEW.sealed_content_type <> OLD.sealed_content_type
    OR NEW.sealed_size_bytes <> OLD.sealed_size_bytes
    OR NEW.sealed_checksum_sha256 <> OLD.sealed_checksum_sha256
    OR NEW.title <> OLD.title
    OR NEW.description IS DISTINCT FROM OLD.description
    OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
  THEN
    RAISE EXCEPTION 'spatial service coverage seal is immutable';
  END IF;
  IF OLD.withdrawn_at IS NOT NULL
    OR NEW.withdrawn_at IS NULL
    OR NEW.withdrawn_by IS NULL
    OR NEW.withdrawn_by <> app.current_user_id()
    OR NEW.withdrawn_at < OLD.created_at
  THEN
    RAISE EXCEPTION 'spatial service coverage withdrawal is one-way and actor-bound';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_service_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_service_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.created_by <> app.current_user_id()
    OR NEW.disabled_by IS NOT NULL
    OR NEW.disabled_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'spatial service creator mismatch';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_service_layer_group_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_service_layer_group_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  version_changed boolean;
  disable_changed boolean;
BEGIN
  IF NEW.id <> OLD.id OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id OR NEW.service_id <> OLD.service_id
    OR NEW.slug <> OLD.slug OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
  THEN
    RAISE EXCEPTION 'spatial service layer group identity is immutable';
  END IF;
  version_changed := NEW.current_version_id <> OLD.current_version_id
    OR NEW.current_version_number <> OLD.current_version_number;
  disable_changed := NEW.disabled_by IS DISTINCT FROM OLD.disabled_by
    OR NEW.disabled_at IS DISTINCT FROM OLD.disabled_at;
  IF version_changed THEN
    IF disable_changed OR OLD.disabled_at IS NOT NULL
      OR NEW.current_version_number <> OLD.current_version_number + 1
      OR NEW.updated_by <> app.current_user_id() OR NEW.updated_at <= OLD.updated_at
    THEN
      RAISE EXCEPTION 'spatial service layer group head transition is invalid';
    END IF;
  ELSIF disable_changed THEN
    IF OLD.disabled_at IS NOT NULL OR NEW.disabled_at IS NULL
      OR NEW.disabled_by <> app.current_user_id()
      OR NEW.updated_by <> OLD.updated_by OR NEW.updated_at <> OLD.updated_at
    THEN
      RAISE EXCEPTION 'spatial service layer group disable is one-way and actor-bound';
    END IF;
  ELSE
    RAISE EXCEPTION 'spatial service layer group update has no valid transition';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_service_layer_group_version(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_service_layer_group_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  member_id uuid;
BEGIN
  IF NEW.created_by <> app.current_user_id() THEN
    RAISE EXCEPTION 'spatial service layer group revision creator mismatch';
  END IF;
  FOREACH member_id IN ARRAY NEW.member_collection_ids LOOP
    PERFORM 1 FROM app.spatial_service_collections binding
    WHERE binding.organization_id = NEW.organization_id
      AND binding.project_id = NEW.project_id
      AND binding.service_id = NEW.service_id
      AND binding.id = member_id
      AND binding.withdrawn_at IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'spatial service layer group member is not an active same-service collection';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_service_store_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_service_store_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  active_store_count bigint;
BEGIN
  IF NEW.created_by <> app.current_user_id()
    OR NEW.disabled_by IS NOT NULL OR NEW.disabled_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'spatial service store creator mismatch';
  END IF;
  PERFORM 1 FROM app.spatial_services service
  WHERE service.organization_id = NEW.organization_id
    AND service.project_id = NEW.project_id
    AND service.id = NEW.service_id
    AND service.disabled_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'spatial service store requires an active service';
  END IF;
  SELECT count(*) INTO active_store_count
  FROM app.spatial_service_stores store
  WHERE store.organization_id = NEW.organization_id
    AND store.service_id = NEW.service_id
    AND store.disabled_at IS NULL;
  IF active_store_count >= 16 THEN
    RAISE EXCEPTION 'spatial service store limit reached';
  END IF;
  IF NEW.kind = 'external_source' THEN
    PERFORM 1
    FROM app.external_sources source
    JOIN app.external_source_revisions revision
      ON revision.organization_id = source.organization_id
     AND revision.dataset_id = source.dataset_id
     AND revision.version_number = NEW.sealed_source_revision_number
    JOIN app.datasets dataset
      ON dataset.organization_id = source.organization_id
     AND dataset.id = source.dataset_id
     AND dataset.status = 'active'
    WHERE source.organization_id = NEW.organization_id
      AND source.dataset_id = NEW.dataset_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'external source store must seal an active source revision';
    END IF;
  ELSIF NEW.kind = 'postgresql_connection' THEN
    PERFORM 1
    FROM app.external_connections connection
    JOIN app.external_connection_verifications verification
      ON verification.organization_id = connection.organization_id
     AND verification.project_id = connection.project_id
     AND verification.connection_id = connection.id
     AND verification.connection_revision_number = connection.current_revision_number
     AND verification.state = 'succeeded'
     AND verification.network_reachable
     AND verification.tls_verified
     AND verification.credentials_verified
     AND verification.postgis_verified
    WHERE connection.organization_id = NEW.organization_id
      AND connection.project_id = NEW.project_id
      AND connection.id = NEW.external_connection_id
      AND connection.provider = 'postgresql'
      AND connection.read_only
      AND connection.status = 'credentials_verified'
      AND connection.current_revision_number = NEW.sealed_connection_revision_number;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'PostgreSQL store must seal a verified read-only PostGIS connection';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_service_store_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_service_store_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id OR NEW.service_id <> OLD.service_id
    OR NEW.slug <> OLD.slug OR NEW.title <> OLD.title
    OR NEW.description IS DISTINCT FROM OLD.description OR NEW.kind <> OLD.kind
    OR NEW.dataset_id IS DISTINCT FROM OLD.dataset_id
    OR NEW.external_connection_id IS DISTINCT FROM OLD.external_connection_id
    OR NEW.sealed_source_revision_number IS DISTINCT FROM OLD.sealed_source_revision_number
    OR NEW.sealed_connection_revision_number IS DISTINCT FROM OLD.sealed_connection_revision_number
    OR NEW.configuration <> OLD.configuration OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
  THEN
    RAISE EXCEPTION 'spatial service store identity and seal are immutable';
  END IF;
  IF OLD.disabled_at IS NOT NULL OR NEW.disabled_at IS NULL
    OR NEW.disabled_by <> app.current_user_id()
  THEN
    RAISE EXCEPTION 'spatial service store disable is one-way and actor-bound';
  END IF;
  PERFORM 1 FROM app.spatial_service_collections binding
  WHERE binding.organization_id = OLD.organization_id
    AND binding.project_id = OLD.project_id
    AND binding.service_id = OLD.service_id
    AND binding.store_id = OLD.id
    AND binding.withdrawn_at IS NULL;
  IF FOUND THEN
    RAISE EXCEPTION 'spatial service store with active collections cannot be disabled';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_service_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_service_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  metadata_changed boolean;
  disable_changed boolean;
BEGIN
  IF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.slug <> OLD.slug
    OR NEW.title <> OLD.title
    OR NEW.description IS DISTINCT FROM OLD.description
    OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
  THEN
    RAISE EXCEPTION 'spatial service identity and initial description are immutable';
  END IF;

  metadata_changed :=
    NEW.current_metadata_version_id <> OLD.current_metadata_version_id
    OR NEW.current_metadata_version_number <> OLD.current_metadata_version_number;
  disable_changed :=
    NEW.disabled_by IS DISTINCT FROM OLD.disabled_by
    OR NEW.disabled_at IS DISTINCT FROM OLD.disabled_at;

  IF metadata_changed THEN
    IF disable_changed
      OR OLD.disabled_at IS NOT NULL
      OR NEW.current_metadata_version_number <> OLD.current_metadata_version_number + 1
      OR NEW.updated_by <> app.current_user_id()
      OR NEW.updated_at <= OLD.updated_at
    THEN
      RAISE EXCEPTION 'spatial service metadata head transition is invalid';
    END IF;
  ELSIF disable_changed THEN
    IF OLD.disabled_at IS NOT NULL
      OR NEW.disabled_at IS NULL
      OR NEW.disabled_by IS NULL
      OR NEW.disabled_by <> app.current_user_id()
      OR NEW.disabled_at < OLD.created_at
      OR NEW.current_metadata_version_id <> OLD.current_metadata_version_id
      OR NEW.current_metadata_version_number <> OLD.current_metadata_version_number
      OR NEW.updated_by <> OLD.updated_by
      OR NEW.updated_at <> OLD.updated_at
    THEN
      RAISE EXCEPTION 'spatial service disable is one-way and actor-bound';
    END IF;
  ELSE
    IF NEW.updated_by <> OLD.updated_by OR NEW.updated_at <> OLD.updated_at THEN
      RAISE EXCEPTION 'spatial service update has no valid transition';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_tile_cache_entry_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_tile_cache_entry_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  current_cache app.spatial_tile_caches%ROWTYPE;
  current_version app.spatial_tile_cache_versions%ROWTYPE;
  binding app.spatial_service_collections%ROWTYPE;
  job app.map_render_jobs%ROWTYPE;
  matrix_width bigint;
  entry_count bigint;
  tile_span double precision;
  expected_bbox double precision[];
  coordinate integer;
BEGIN
  IF NEW.seeded_by <> app.current_user_id() THEN
    RAISE EXCEPTION 'spatial tile cache entry actor mismatch';
  END IF;
  SELECT * INTO current_cache
  FROM app.spatial_tile_caches cache
  WHERE cache.organization_id = NEW.organization_id
    AND cache.project_id = NEW.project_id
    AND cache.id = NEW.cache_id
  FOR UPDATE;
  IF NOT FOUND
    OR NEW.cache_version_id <> current_cache.current_version_id
    OR NEW.cache_version_number <> current_cache.current_version_number
  THEN
    RAISE EXCEPTION 'spatial tile cache entry must target the current version';
  END IF;
  SELECT * INTO current_version
  FROM app.spatial_tile_cache_versions version
  WHERE version.organization_id = NEW.organization_id
    AND version.cache_id = NEW.cache_id
    AND version.id = NEW.cache_version_id
    AND version.version_number = NEW.cache_version_number;
  IF NOT FOUND
    OR NEW.tile_matrix NOT BETWEEN current_version.minimum_tile_matrix
                               AND current_version.maximum_tile_matrix
  THEN
    RAISE EXCEPTION 'spatial tile cache entry is outside the policy';
  END IF;
  matrix_width := (1::bigint << NEW.tile_matrix);
  IF NEW.tile_row >= matrix_width OR NEW.tile_col >= matrix_width THEN
    RAISE EXCEPTION 'spatial tile cache coordinate is outside the matrix';
  END IF;
  SELECT count(*) INTO entry_count
  FROM app.spatial_tile_cache_entries entry
  WHERE entry.organization_id = NEW.organization_id
    AND entry.cache_id = NEW.cache_id
    AND entry.cache_version_number = NEW.cache_version_number;
  IF entry_count >= current_version.maximum_entries THEN
    RAISE EXCEPTION 'spatial tile cache entry limit reached';
  END IF;
  SELECT * INTO binding
  FROM app.spatial_service_collections candidate
  WHERE candidate.organization_id = NEW.organization_id
    AND candidate.id = current_cache.binding_id
    AND candidate.withdrawn_at IS NULL;
  SELECT * INTO job
  FROM app.map_render_jobs candidate
  WHERE candidate.organization_id = NEW.organization_id
    AND candidate.project_id = NEW.project_id
    AND candidate.id = NEW.render_job_id;
  IF binding.id IS NULL OR job.id IS NULL
    OR job.resource_id <> binding.resource_id
    OR job.profile_id <> binding.default_profile_id
    OR job.profile_version_id <> binding.sealed_profile_version_id
    OR job.crs <> 'EPSG:3857'
    OR job.width <> 256 OR job.height <> 256
    OR job.format::text <> 'png'
    OR job.background_color IS NOT NULL OR NOT job.transparent
  THEN
    RAISE EXCEPTION 'spatial tile cache entry render seal mismatch';
  END IF;
  tile_span := 40075016.685578488 / matrix_width;
  expected_bbox := ARRAY[
    -20037508.342789244 + NEW.tile_col * tile_span,
    20037508.342789244 - (NEW.tile_row + 1) * tile_span,
    -20037508.342789244 + (NEW.tile_col + 1) * tile_span,
    20037508.342789244 - NEW.tile_row * tile_span
  ];
  FOR coordinate IN 0..3 LOOP
    IF abs((job.bbox ->> coordinate)::double precision - expected_bbox[coordinate + 1]) > 0.000001
    THEN
      RAISE EXCEPTION 'spatial tile cache entry bbox mismatch';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_tile_cache_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_tile_cache_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.created_by <> app.current_user_id()
    OR NEW.updated_by <> app.current_user_id()
    OR NEW.current_version_number <> 1
  THEN
    RAISE EXCEPTION 'spatial tile cache creator or initial version mismatch';
  END IF;
  PERFORM 1
  FROM app.spatial_service_collections binding
  JOIN app.spatial_services service
    ON service.organization_id = binding.organization_id
   AND service.project_id = binding.project_id
   AND service.id = binding.service_id
  WHERE binding.organization_id = NEW.organization_id
    AND binding.project_id = NEW.project_id
    AND binding.service_id = NEW.service_id
    AND binding.id = NEW.binding_id
    AND binding.withdrawn_at IS NULL
    AND service.disabled_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'spatial tile cache must target an active binding';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_tile_cache_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_tile_cache_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.service_id <> OLD.service_id
    OR NEW.binding_id <> OLD.binding_id
    OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
    OR NEW.current_version_number <> OLD.current_version_number + 1
    OR NEW.current_version_id = OLD.current_version_id
    OR NEW.updated_by <> app.current_user_id()
    OR NEW.updated_at <= OLD.updated_at
  THEN
    RAISE EXCEPTION 'spatial tile cache advances one immutable version at a time';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_spatial_tile_cache_version_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_spatial_tile_cache_version_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  current_cache app.spatial_tile_caches%ROWTYPE;
BEGIN
  IF NEW.created_by <> app.current_user_id() THEN
    RAISE EXCEPTION 'spatial tile cache version creator mismatch';
  END IF;
  SELECT * INTO current_cache
  FROM app.spatial_tile_caches cache
  WHERE cache.organization_id = NEW.organization_id
    AND cache.id = NEW.cache_id
  FOR UPDATE;
  IF NOT FOUND
    OR NOT (
      (NEW.version_number = 1
       AND current_cache.current_version_number = 1
       AND current_cache.current_version_id = NEW.id)
      OR NEW.version_number = current_cache.current_version_number + 1
    )
  THEN
    RAISE EXCEPTION 'spatial tile cache version must follow the current head';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_upload_intent_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_upload_intent_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.id IS DISTINCT FROM NEW.id
    OR OLD.organization_id IS DISTINCT FROM NEW.organization_id
    OR OLD.project_id IS DISTINCT FROM NEW.project_id
    OR OLD.dataset_id IS DISTINCT FROM NEW.dataset_id
    OR OLD.created_by IS DISTINCT FROM NEW.created_by
    OR OLD.original_filename IS DISTINCT FROM NEW.original_filename
    OR OLD.content_type IS DISTINCT FROM NEW.content_type
    OR OLD.expected_size_bytes IS DISTINCT FROM NEW.expected_size_bytes
    OR OLD.expected_sha256 IS DISTINCT FROM NEW.expected_sha256
    OR OLD.bucket IS DISTINCT FROM NEW.bucket
    OR OLD.object_key IS DISTINCT FROM NEW.object_key
    OR OLD.expires_at IS DISTINCT FROM NEW.expires_at
    OR OLD.created_at IS DISTINCT FROM NEW.created_at
  THEN
    RAISE EXCEPTION 'upload intent identity, scope, object, and expectations are immutable';
  END IF;

  IF OLD.state <> 'pending' OR NEW.state <> 'completed' THEN
    RAISE EXCEPTION 'upload intent transitions are forward-only';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_wms_layer_publication_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_wms_layer_publication_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.created_by <> app.current_user_id()
    OR NEW.withdrawn_by IS NOT NULL
    OR NEW.withdrawn_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'WMS publication creator mismatch';
  END IF;

  PERFORM 1
  FROM app.governed_resources resource
  JOIN app.map_render_profiles profile
    ON profile.organization_id = resource.organization_id
   AND profile.project_id = resource.project_id
   AND profile.resource_id = resource.id
   AND profile.id = NEW.default_profile_id
  WHERE resource.organization_id = NEW.organization_id
    AND resource.project_id = NEW.project_id
    AND resource.id = NEW.resource_id
    AND resource.kind IN ('dataset', 'service')
    AND resource.state = 'published';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'WMS publication target must be a published map resource';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_wms_layer_publication_transition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_wms_layer_publication_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id <> OLD.id
    OR NEW.organization_id <> OLD.organization_id
    OR NEW.project_id <> OLD.project_id
    OR NEW.resource_id <> OLD.resource_id
    OR NEW.wms_name <> OLD.wms_name
    OR NEW.default_profile_id <> OLD.default_profile_id
    OR NEW.created_by <> OLD.created_by
    OR NEW.created_at <> OLD.created_at
  THEN
    RAISE EXCEPTION 'WMS publication identity is immutable';
  END IF;
  IF OLD.withdrawn_at IS NOT NULL
    OR NEW.withdrawn_at IS NULL
    OR NEW.withdrawn_by IS NULL
    OR NEW.withdrawn_by <> app.current_user_id()
    OR NEW.withdrawn_at < OLD.created_at
  THEN
    RAISE EXCEPTION 'WMS publication withdrawal is one-way and actor-bound';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: ensure_feature_head_has_revision(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ensure_feature_head_has_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_required_operation app.feature_revision_operation;
BEGIN
  v_required_operation := CASE
    WHEN TG_OP = 'INSERT' THEN 'create'::app.feature_revision_operation
    WHEN OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL
      THEN 'delete'::app.feature_revision_operation
    WHEN OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL
      THEN 'restore'::app.feature_revision_operation
    ELSE 'update'::app.feature_revision_operation
  END;

  IF NOT EXISTS (
    SELECT 1
    FROM app.dataset_feature_revisions revision
    WHERE revision.organization_id = NEW.organization_id
      AND revision.dataset_id = NEW.dataset_id
      AND revision.feature_id = NEW.id
      AND revision.version_number = NEW.version_number
      AND revision.operation = v_required_operation
      AND revision.geometry_type = NEW.geometry_type
      AND revision.properties = NEW.properties
      AND revision.geometry_geojson = NEW.geometry_geojson
      AND ST_Equals(revision.geometry, NEW.geometry)
  ) THEN
    RAISE EXCEPTION 'feature head mutation requires one matching immutable revision';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION ensure_feature_head_has_revision(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.ensure_feature_head_has_revision() IS 'Requires the exact create, update, delete, or restore revision matching each feature-head transition.';


--
-- Name: ensure_field_submission_has_event(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ensure_field_submission_has_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM app.field_submission_events event
    WHERE event.organization_id = NEW.organization_id
      AND event.dataset_id = NEW.dataset_id
      AND event.submission_id = NEW.id
      AND event.submission_version = NEW.review_version
      AND event.from_state IS NOT DISTINCT FROM (
        CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.state END
      )
      AND event.to_state = NEW.state
      AND event.actor_user_id = (
        CASE WHEN TG_OP = 'INSERT' THEN NEW.submitted_by ELSE NEW.reviewed_by END
      )
  ) THEN
    RAISE EXCEPTION 'field submission mutation requires one matching immutable event';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: external_connection_schemas_are_safe(text[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.external_connection_schemas_are_safe(p_schemas text[]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $_$
DECLARE
  schema_name text;
  seen text[] := ARRAY[]::text[];
BEGIN
  IF p_schemas IS NULL OR cardinality(p_schemas) NOT BETWEEN 1 AND 16 THEN
    RETURN false;
  END IF;
  FOREACH schema_name IN ARRAY p_schemas LOOP
    IF schema_name IS NULL
      OR schema_name !~ '^[A-Za-z_][A-Za-z0-9_$]{0,62}$'
      OR schema_name = ANY(seen)
    THEN
      RETURN false;
    END IF;
    seen := array_append(seen, schema_name);
  END LOOP;
  RETURN true;
END;
$_$;


--
-- Name: fail_dataset_ingest(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.fail_dataset_ingest(p_job_id uuid, p_worker_token uuid, p_error_code text, p_quality_results jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_job app.processing_jobs%ROWTYPE;
BEGIN
  IF p_error_code IS NULL OR p_error_code !~ '^[a-z0-9]+(?:[._-][a-z0-9]+)*$'
    OR char_length(p_error_code) > 100
    OR p_quality_results IS NULL OR jsonb_typeof(p_quality_results) <> 'object'
    OR octet_length(p_quality_results::text) > 262144
  THEN
    RAISE EXCEPTION 'invalid ingestion failure';
  END IF;

  SELECT * INTO v_job
  FROM app.processing_jobs
  WHERE id = p_job_id
  FOR UPDATE;

  IF NOT FOUND OR v_job.job_type <> 'dataset.ingest'
    OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token
  THEN
    RETURN false;
  END IF;

  UPDATE app.dataset_versions
  SET state = 'failed', quality_results = p_quality_results
  WHERE organization_id = v_job.organization_id
    AND dataset_id = v_job.dataset_id
    AND id = v_job.dataset_version_id;

  UPDATE app.datasets
  SET status = 'failed', updated_by = v_job.created_by
  WHERE organization_id = v_job.organization_id
    AND id = v_job.dataset_id
    AND current_version_id = v_job.dataset_version_id;

  UPDATE app.processing_jobs
  SET state = 'failed',
      result = jsonb_build_object('quality_results', p_quality_results),
      error_code = p_error_code,
      worker_token = NULL,
      lease_expires_at = NULL,
      last_heartbeat_at = NULL,
      finished_at = clock_timestamp()
  WHERE id = v_job.id;

  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (v_job.organization_id, v_job.created_by, v_job.project_id,
     'dataset.ingest.failed', 'dataset', v_job.dataset_id,
     'worker:' || v_job.id::text,
     jsonb_build_object(
       'processing_job_id', v_job.id,
       'dataset_version_id', v_job.dataset_version_id,
       'error_code', p_error_code
     ));

  RETURN true;
END;
$_$;


--
-- Name: fail_external_source_discovery(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.fail_external_source_discovery(p_job_id uuid, p_worker_token uuid, p_error_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
BEGIN
  IF p_error_code NOT IN (
    'destination_unavailable', 'discovery_collection_missing',
    'discovery_collection_unsupported', 'discovery_geometry_unsupported',
    'discovery_identity_unsupported', 'discovery_no_collections',
    'discovery_response_invalid', 'discovery_response_too_large',
    'discovery_schema_unsupported', 'discovery_upstream_rejected',
    'discovery_version_unsupported', 'redirect_rejected', 'response_invalid',
    'response_media_rejected', 'response_too_large', 'source_contract_invalid',
    'tls_verification_failed', 'unsafe_network_target', 'upstream_rejected'
  ) THEN RETURN false; END IF;
  UPDATE app.external_source_discovery_jobs
  SET state = 'failed', error_code = p_error_code, worker_token = NULL,
      lease_expires_at = NULL, finished_at = clock_timestamp()
  WHERE id = p_job_id AND state = 'running' AND worker_token = p_worker_token;
  RETURN FOUND;
END;
$$;


--
-- Name: fail_external_source_snapshot(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.fail_external_source_snapshot(p_job_id uuid, p_worker_token uuid, p_error_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_organization_id uuid;
  v_project_id uuid;
  v_destination_dataset_id uuid;
  v_created_by uuid;
BEGIN
  IF p_error_code !~ '^[a-z0-9]+(?:[._-][a-z0-9]+)*$'
    OR char_length(p_error_code) > 100 THEN RETURN false; END IF;
  UPDATE app.external_source_snapshot_jobs
  SET state = 'failed', error_code = p_error_code, worker_token = NULL,
      lease_expires_at = NULL, last_heartbeat_at = NULL,
      finished_at = clock_timestamp()
  WHERE id = p_job_id AND state = 'running' AND worker_token = p_worker_token
  RETURNING organization_id, project_id, destination_dataset_id, created_by
    INTO v_organization_id, v_project_id, v_destination_dataset_id, v_created_by;
  IF NOT FOUND THEN RETURN false; END IF;
  UPDATE app.datasets
  SET status = 'failed', updated_by = v_created_by, updated_at = clock_timestamp()
  WHERE organization_id = v_organization_id AND id = v_destination_dataset_id
    AND status = 'draft' AND current_version_id IS NULL;
  DELETE FROM app.project_datasets
  WHERE organization_id = v_organization_id AND project_id = v_project_id
    AND dataset_id = v_destination_dataset_id;
  RETURN true;
END;
$_$;


