--
-- Name: fail_spatial_tile_cache_reclamation_item(uuid, integer, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.fail_spatial_tile_cache_reclamation_item(p_reclamation_id uuid, p_item_position integer, p_worker_token uuid, p_error_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
BEGIN
  IF p_error_code !~ '^[a-z0-9]+(?:[._-][a-z0-9]+)*$'
    OR char_length(p_error_code) > 200
  THEN RETURN false; END IF;
  UPDATE app.spatial_tile_cache_reclamation_items item
  SET state = 'failed', error_code = p_error_code,
      finished_at = clock_timestamp()
  FROM app.spatial_tile_cache_reclamations reclamation
  WHERE reclamation.organization_id = item.organization_id
    AND reclamation.id = item.reclamation_id
    AND reclamation.id = p_reclamation_id
    AND reclamation.state = 'running'
    AND reclamation.worker_token = p_worker_token
    AND reclamation.lease_expires_at > clock_timestamp()
    AND item.position = p_item_position
    AND item.state = 'queued' AND item.delete_started_at IS NULL;
  RETURN FOUND;
END;
$_$;


--
-- Name: finish_spatial_tile_cache_reclamation(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.finish_spatial_tile_cache_reclamation(p_reclamation_id uuid, p_worker_token uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_plan app.spatial_tile_cache_reclamations%ROWTYPE;
  v_active integer;
  v_completed integer;
  v_failed integer;
  v_state text;
BEGIN
  SELECT * INTO v_plan FROM app.spatial_tile_cache_reclamations
  WHERE id = p_reclamation_id AND state = 'running'
    AND worker_token = p_worker_token
    AND lease_expires_at > clock_timestamp()
  FOR UPDATE;
  IF NOT FOUND THEN RETURN 'lost'; END IF;
  SELECT count(*) FILTER (WHERE state IN ('queued', 'running')),
         count(*) FILTER (WHERE state = 'completed'),
         count(*) FILTER (WHERE state = 'failed')
  INTO v_active, v_completed, v_failed
  FROM app.spatial_tile_cache_reclamation_items
  WHERE organization_id = v_plan.organization_id
    AND reclamation_id = v_plan.id;
  IF v_active <> 0 OR v_completed + v_failed <> v_plan.target_count THEN
    RETURN 'not_ready';
  END IF;
  v_state := CASE WHEN v_failed = 0 THEN 'completed' ELSE 'failed' END;
  UPDATE app.spatial_tile_cache_reclamations
  SET state = v_state::app.processing_job_state,
      error_code = CASE WHEN v_failed = 0 THEN NULL
                        ELSE 'render_cache_reclamation_partial_failure' END,
      worker_token = NULL, lease_expires_at = NULL,
      last_heartbeat_at = NULL, finished_at = clock_timestamp()
  WHERE id = v_plan.id;
  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (v_plan.organization_id, v_plan.created_by, v_plan.project_id,
     'spatial_service.tile_cache.reclamation.' || v_state,
     'spatial_service', v_plan.service_id, 'worker:' || v_plan.id::text,
     jsonb_build_object(
       'reclamation_id', v_plan.id, 'binding_id', v_plan.binding_id,
       'cache_id', v_plan.cache_id,
       'cache_version_number', v_plan.cache_version_number,
       'completed_target_count', v_completed,
       'failed_target_count', v_failed,
       'target_size_bytes', v_plan.target_size_bytes
     ));
  RETURN v_state;
END;
$$;


--
-- Name: get_completed_external_source_snapshot_artifact(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.get_completed_external_source_snapshot_artifact(p_job_id uuid) RETURNS TABLE(snapshot_job_id uuid, bucket text, object_key text, s3_version_id text, etag text, content_type text, size_bytes bigint, checksum_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
BEGIN
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'invalid completed source snapshot lookup';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM app.external_source_snapshot_jobs job
    WHERE job.id = p_job_id AND job.state = 'completed'
  ) THEN
    RETURN;
  END IF;
  RETURN QUERY
  SELECT job.id, object.bucket, object.object_key, object.s3_version_id,
         object.etag, object.content_type, object.size_bytes,
         object.checksum_sha256
  FROM app.external_source_snapshot_jobs job
  JOIN app.external_source_copy_estimates estimate
    ON estimate.organization_id = job.organization_id
   AND estimate.id = job.estimate_id
  JOIN app.data_objects object
    ON object.organization_id = job.organization_id
   AND object.id = job.output_object_id
   AND object.dataset_id = job.destination_dataset_id
   AND object.role = 'original'
  WHERE job.id = p_job_id AND job.state = 'completed'
    AND object.bucket = job.destination_bucket
    AND object.object_key = format(
      'organizations/%s/projects/%s/datasets/%s/uploads/%s/original/%s',
      job.organization_id, job.project_id, job.destination_dataset_id, job.id,
      CASE estimate.output_format::text
        WHEN 'png' THEN 'snapshot.png'
        WHEN 'geojson' THEN 'snapshot.geojson'
        ELSE 'source.pmtiles'
      END
    )
    AND object.content_type = estimate.output_content_type
    AND object.size_bytes BETWEEN 1 AND estimate.maximum_output_bytes;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'completed source snapshot artifact is inconsistent';
  END IF;
END;
$$;


--
-- Name: FUNCTION get_completed_external_source_snapshot_artifact(p_job_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.get_completed_external_source_snapshot_artifact(p_job_id uuid) IS 'Returns exact persisted object facts only for retry-safe post-completion ingestion dispatch.';


