--
-- Name: get_spatial_tile_cache_reclamation_targets(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.get_spatial_tile_cache_reclamation_targets(p_reclamation_id uuid, p_worker_token uuid) RETURNS TABLE(item_position smallint, render_job_id uuid, output_object_id uuid, bucket text, object_key text, storage_version_id text, etag text, content_type text, size_bytes bigint, checksum_sha256 text, delete_started_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
  SELECT item.position, item.render_job_id, item.output_object_id,
         item.sealed_bucket, item.sealed_object_key,
         item.sealed_storage_version_id, item.sealed_etag,
         item.sealed_content_type, item.sealed_size_bytes,
         item.sealed_checksum_sha256, item.delete_started_at
  FROM app.spatial_tile_cache_reclamations reclamation
  JOIN app.spatial_tile_cache_reclamation_items item
    ON item.organization_id = reclamation.organization_id
   AND item.reclamation_id = reclamation.id
  WHERE reclamation.id = p_reclamation_id
    AND reclamation.state = 'running'
    AND reclamation.worker_token = p_worker_token
    AND reclamation.lease_expires_at > clock_timestamp()
    AND item.state IN ('queued', 'running')
  ORDER BY item.position;
$$;


--
-- Name: heartbeat_dataset_ingest(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.heartbeat_dataset_ingest(p_job_id uuid, p_worker_token uuid, p_lease_seconds integer) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
  WITH heartbeat AS (
    UPDATE app.processing_jobs
    SET last_heartbeat_at = clock_timestamp(),
        lease_expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds)
    WHERE id = p_job_id
      AND state = 'running'
      AND worker_token = p_worker_token
      AND p_lease_seconds BETWEEN 60 AND 3600
    RETURNING id
  )
  SELECT EXISTS (SELECT 1 FROM heartbeat)
$$;


