--
-- Name: link_completed_dataset_artifacts(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.link_completed_dataset_artifacts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_expected integer;
  v_linked integer;
BEGIN
  IF NEW.state <> 'completed' OR OLD.state = 'completed' THEN
    RETURN NEW;
  END IF;

  IF jsonb_typeof(NEW.result->'artifacts') <> 'array' THEN
    RAISE EXCEPTION 'completed ingestion job has no artifact array';
  END IF;

  v_expected := jsonb_array_length(NEW.result->'artifacts');
  INSERT INTO app.dataset_version_objects
    (organization_id, dataset_id, dataset_version_id, data_object_id)
  SELECT
    NEW.organization_id,
    NEW.dataset_id,
    NEW.dataset_version_id,
    object.id
  FROM jsonb_array_elements(NEW.result->'artifacts') artifact
  JOIN app.data_objects object
    ON object.organization_id = NEW.organization_id
   AND object.dataset_id = NEW.dataset_id
   AND object.id = (artifact->>'id')::uuid
   AND object.role <> 'original';

  SELECT count(*)::integer INTO v_linked
  FROM app.dataset_version_objects link
  JOIN app.data_objects object
    ON object.organization_id = link.organization_id
   AND object.id = link.data_object_id
  WHERE link.organization_id = NEW.organization_id
    AND link.dataset_id = NEW.dataset_id
    AND link.dataset_version_id = NEW.dataset_version_id
    AND object.role <> 'original';

  IF v_linked <> v_expected THEN
    RAISE EXCEPTION 'completed ingestion artifacts do not match stored objects';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: link_dataset_version_original(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.link_dataset_version_original() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
BEGIN
  INSERT INTO app.dataset_version_objects
    (organization_id, dataset_id, dataset_version_id, data_object_id)
  VALUES
    (NEW.organization_id, NEW.dataset_id, NEW.id, NEW.original_object_id);
  RETURN NEW;
END;
$$;


--
-- Name: list_pending_membership_invitations(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.list_pending_membership_invitations() RETURNS TABLE(invitation_id uuid, organization_id uuid, organization_name text, project_id uuid, project_name text, organization_role app.organization_role, project_role app.project_role, expires_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
  SELECT
    invitation.id,
    invitation.organization_id,
    organization.name,
    invitation.project_id,
    project.name,
    invitation.organization_role,
    invitation.project_role,
    invitation.expires_at,
    invitation.created_at
  FROM app.membership_invitations invitation
  JOIN app.organizations organization ON organization.id = invitation.organization_id
  LEFT JOIN app.projects project
    ON project.organization_id = invitation.organization_id
   AND project.id = invitation.project_id
  WHERE invitation.invitee_user_id = app.current_user_id()
    AND invitation.state = 'pending'
    AND invitation.expires_at > clock_timestamp()
  ORDER BY invitation.created_at, invitation.id
  LIMIT 100
$$;


