--
-- Name: prevent_active_preservation_dataset_detach(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.prevent_active_preservation_dataset_detach() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'opengeo:data-preservation-quota:' || OLD.organization_id::text, 0
  ));
  IF EXISTS (
    SELECT 1
    FROM app.external_source_snapshot_jobs job
    WHERE job.organization_id = OLD.organization_id
      AND job.project_id = OLD.project_id
      AND (job.source_dataset_id = OLD.dataset_id
        OR job.destination_dataset_id = OLD.dataset_id)
      AND job.state IN ('queued', 'running')
  ) OR EXISTS (
    SELECT 1
    FROM app.pmtiles_derivative_jobs job
    WHERE job.organization_id = OLD.organization_id
      AND job.project_id = OLD.project_id
      AND job.dataset_id = OLD.dataset_id
      AND job.state IN ('queued', 'running')
  ) THEN
    RAISE EXCEPTION 'project dataset has active preservation work';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: prevent_active_repository_copy_detach(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.prevent_active_repository_copy_detach() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM app.repository_object_copy_jobs job
    WHERE job.organization_id = OLD.organization_id
      AND job.project_id = OLD.project_id
      AND (job.source_dataset_id = OLD.dataset_id
        OR job.destination_dataset_id = OLD.dataset_id)
      AND job.state IN ('queued', 'running')
  ) THEN RAISE EXCEPTION 'project dataset has active repository copy work'; END IF;
  RETURN OLD;
END;
$$;


--
-- Name: processing_execution_receipt_checksum(text, uuid, uuid, text, text, text, uuid, uuid, text, jsonb, jsonb, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.processing_execution_receipt_checksum(p_job_kind text, p_coverage_job_id uuid, p_pmtiles_job_id uuid, p_tool_id text, p_tool_version text, p_request_checksum_sha256 text, p_source_object_id uuid, p_output_object_id uuid, p_output_checksum_sha256 text, p_software jsonb, p_logs jsonb, p_verification_status text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT encode(
    sha256(
      convert_to(
        jsonb_build_object(
          'jobKind', p_job_kind,
          'coverageJobId', p_coverage_job_id,
          'pmtilesJobId', p_pmtiles_job_id,
          'toolId', p_tool_id,
          'toolVersion', p_tool_version,
          'requestChecksumSha256', p_request_checksum_sha256,
          'sourceObjectId', p_source_object_id,
          'outputObjectId', p_output_object_id,
          'outputChecksumSha256', p_output_checksum_sha256,
          'software', p_software,
          'logs', p_logs,
          'verificationStatus', p_verification_status
        )::text,
        'UTF8'
      )
    ),
    'hex'
  )
$$;


--
-- Name: processing_receipt_logs_valid(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.processing_receipt_logs_valid(p_logs jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT jsonb_typeof(p_logs) = 'array'
    AND jsonb_array_length(p_logs) BETWEEN 1 AND 20
    AND octet_length(p_logs::text) <= 8192
    AND NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_logs) AS item(value)
      WHERE jsonb_typeof(item.value) <> 'string'
        OR char_length(item.value #>> '{}') NOT BETWEEN 1 AND 240
        OR (item.value #>> '{}') ~ '[[:cntrl:]]'
    )
$$;


--
-- Name: project_discussion_user_has_access(uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_discussion_user_has_access(p_organization_id uuid, p_project_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'app'
    AS $$
  SELECT p_organization_id = app.current_organization_id()
    AND (
      app.effective_project_role(p_project_id, p_user_id) IS NOT NULL
      OR EXISTS (
        SELECT 1
        FROM app.organization_memberships membership
        WHERE membership.organization_id = p_organization_id
          AND membership.user_id = p_user_id
          AND membership.role = 'admin'
      )
    )
$$;


--
-- Name: project_site_print_layout_v11_valid(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_site_print_layout_v11_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $_$
DECLARE
  layout_page jsonb;
  element jsonb;
  kind text;
  x_value integer;
  y_value integer;
  width_value integer;
  height_value integer;
  rotation_value integer;
  page_slugs text[] := ARRAY[]::text[];
  element_ids text[];
  map_frame_ids text[];
  map_resource_ids uuid[] := ARRAY[]::uuid[];
  element_total integer := 0;
BEGIN
  IF jsonb_typeof(value) <> 'object'
    OR (SELECT count(*) FROM jsonb_object_keys(value)) <> 2
    OR value->>'schemaVersion' <> 'opengeo.print-layout.1.1.0'
    OR jsonb_typeof(value->'pages') <> 'array'
    OR jsonb_array_length(value->'pages') > 64
    OR octet_length(value::text) > 32768
  THEN
    RETURN false;
  END IF;

  FOR layout_page IN SELECT item FROM jsonb_array_elements(value->'pages') item LOOP
    IF jsonb_typeof(layout_page) <> 'object'
      OR (SELECT count(*) FROM jsonb_object_keys(layout_page)) <> 2
      OR NOT layout_page ?& ARRAY['sitePageSlug', 'elements']
      OR layout_page->>'sitePageSlug' !~ '^[a-z0-9](?:[a-z0-9-]{0,158}[a-z0-9])?$'
      OR layout_page->>'sitePageSlug' = ANY(page_slugs)
      OR jsonb_typeof(layout_page->'elements') <> 'array'
      OR jsonb_array_length(layout_page->'elements') NOT BETWEEN 1 AND 32
    THEN
      RETURN false;
    END IF;
    page_slugs := array_append(page_slugs, layout_page->>'sitePageSlug');
    element_total := element_total + jsonb_array_length(layout_page->'elements');
    IF element_total > 256 THEN
      RETURN false;
    END IF;
    element_ids := ARRAY[]::text[];
    map_frame_ids := ARRAY[]::text[];

    FOR element IN SELECT item FROM jsonb_array_elements(layout_page->'elements') item LOOP
      kind := element->>'type';
      IF jsonb_typeof(element) <> 'object'
        OR kind NOT IN (
          'map_frame', 'text', 'source_panel', 'north_arrow', 'scale_bar',
          'legend_frame', 'image_frame', 'table_frame', 'chart_frame'
        )
        OR NOT element ?& ARRAY[
          'id', 'type', 'x', 'y', 'width', 'height', 'rotation', 'clip'
        ]
        OR element->>'id' !~ '^[a-z][a-z0-9_-]{0,63}$'
        OR element->>'id' = ANY(element_ids)
        OR jsonb_typeof(element->'x') <> 'number'
        OR jsonb_typeof(element->'y') <> 'number'
        OR jsonb_typeof(element->'width') <> 'number'
        OR jsonb_typeof(element->'height') <> 'number'
        OR jsonb_typeof(element->'rotation') <> 'number'
        OR jsonb_typeof(element->'clip') <> 'boolean'
        OR element->>'x' !~ '^(0|[1-9][0-9]{0,3})$'
        OR element->>'y' !~ '^(0|[1-9][0-9]{0,3})$'
        OR element->>'width' !~ '^(0|[1-9][0-9]{0,3})$'
        OR element->>'height' !~ '^(0|[1-9][0-9]{0,3})$'
        OR element->>'rotation' !~ '^-?(0|[1-9][0-9]{0,2})$'
      THEN
        RETURN false;
      END IF;
      x_value := (element->>'x')::integer;
      y_value := (element->>'y')::integer;
      width_value := (element->>'width')::integer;
      height_value := (element->>'height')::integer;
      rotation_value := (element->>'rotation')::integer;
      IF x_value > 1000 OR y_value > 1000
        OR width_value NOT BETWEEN 10 AND 1000
        OR height_value NOT BETWEEN 10 AND 1000
        OR x_value + width_value > 1000
        OR y_value + height_value > 1000
        OR rotation_value NOT BETWEEN -180 AND 180
      THEN
        RETURN false;
      END IF;
      element_ids := array_append(element_ids, element->>'id');

      IF kind = 'map_frame' THEN
        IF (SELECT count(*) FROM jsonb_object_keys(element)) <> 10
          OR NOT element ?& ARRAY['resourceId', 'fit']
          OR element->>'resourceId' !~
            '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
          OR element->>'fit' NOT IN ('contain', 'cover')
        THEN
          RETURN false;
        END IF;
        map_frame_ids := array_append(map_frame_ids, element->>'id');
        IF NOT ((element->>'resourceId')::uuid = ANY(map_resource_ids)) THEN
          map_resource_ids := array_append(map_resource_ids, (element->>'resourceId')::uuid);
          IF cardinality(map_resource_ids) > 16 THEN
            RETURN false;
          END IF;
        END IF;
      ELSIF kind = 'text' THEN
        IF (SELECT count(*) FROM jsonb_object_keys(element)) <> 10
          OR NOT element ?& ARRAY['text', 'style']
          OR jsonb_typeof(element->'text') <> 'string'
          OR element->>'text' <> btrim(element->>'text')
          OR char_length(element->>'text') NOT BETWEEN 1 AND 1000
          OR element->>'style' NOT IN ('title', 'heading', 'body', 'note', 'attribution')
        THEN
          RETURN false;
        END IF;
      ELSIF kind IN ('image_frame', 'table_frame', 'chart_frame') THEN
        IF (SELECT count(*) FROM jsonb_object_keys(element)) <>
             (CASE WHEN kind = 'image_frame' THEN 10 ELSE 9 END)
          OR NOT element ? 'blockId'
          OR element->>'blockId' !~ '^[a-z][a-z0-9_-]{0,63}$'
          OR (kind = 'image_frame' AND (
            NOT element ? 'fit' OR element->>'fit' NOT IN ('contain', 'cover')
          ))
        THEN
          RETURN false;
        END IF;
      ELSE
        IF (SELECT count(*) FROM jsonb_object_keys(element)) <> 9
          OR NOT element ? 'mapFrameId'
          OR element->>'mapFrameId' !~ '^[a-z][a-z0-9_-]{0,63}$'
        THEN
          RETURN false;
        END IF;
      END IF;
    END LOOP;

    FOR element IN SELECT item FROM jsonb_array_elements(layout_page->'elements') item LOOP
      IF element->>'type' IN (
        'source_panel', 'north_arrow', 'scale_bar', 'legend_frame'
      ) AND NOT element->>'mapFrameId' = ANY(map_frame_ids)
      THEN
        RETURN false;
      END IF;
    END LOOP;
  END LOOP;
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$_$;


--
-- Name: FUNCTION project_site_print_layout_v11_valid(value jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.project_site_print_layout_v11_valid(value jsonb) IS 'Validates portable rich print frames, integer-degree rotation, clipping, and contain/cover fitting.';


--
-- Name: project_site_print_layout_v1_valid(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_site_print_layout_v1_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $_$
DECLARE
  layout_page jsonb;
  element jsonb;
  kind text;
  x_value integer;
  y_value integer;
  width_value integer;
  height_value integer;
  page_slugs text[] := ARRAY[]::text[];
  element_ids text[];
  map_frame_ids text[];
  map_resource_ids uuid[] := ARRAY[]::uuid[];
  element_total integer := 0;
BEGIN
  IF jsonb_typeof(value) <> 'object'
    OR (SELECT count(*) FROM jsonb_object_keys(value)) <> 2
    OR value->>'schemaVersion' <> 'opengeo.print-layout.1.0.0'
    OR jsonb_typeof(value->'pages') <> 'array'
    OR jsonb_array_length(value->'pages') > 64
    OR octet_length(value::text) > 32768
  THEN
    RETURN false;
  END IF;

  FOR layout_page IN SELECT item FROM jsonb_array_elements(value->'pages') item LOOP
    IF jsonb_typeof(layout_page) <> 'object'
      OR (SELECT count(*) FROM jsonb_object_keys(layout_page)) <> 2
      OR NOT layout_page ?& ARRAY['sitePageSlug', 'elements']
      OR layout_page->>'sitePageSlug' !~ '^[a-z0-9](?:[a-z0-9-]{0,158}[a-z0-9])?$'
      OR layout_page->>'sitePageSlug' = ANY(page_slugs)
      OR jsonb_typeof(layout_page->'elements') <> 'array'
      OR jsonb_array_length(layout_page->'elements') NOT BETWEEN 1 AND 32
    THEN
      RETURN false;
    END IF;
    page_slugs := array_append(page_slugs, layout_page->>'sitePageSlug');
    element_total := element_total + jsonb_array_length(layout_page->'elements');
    IF element_total > 256 THEN
      RETURN false;
    END IF;
    element_ids := ARRAY[]::text[];
    map_frame_ids := ARRAY[]::text[];

    FOR element IN SELECT item FROM jsonb_array_elements(layout_page->'elements') item LOOP
      kind := element->>'type';
      IF jsonb_typeof(element) <> 'object'
        OR kind NOT IN ('map_frame', 'text', 'source_panel', 'north_arrow', 'scale_bar')
        OR NOT element ?& ARRAY['id', 'type', 'x', 'y', 'width', 'height']
        OR element->>'id' !~ '^[a-z][a-z0-9_-]{0,63}$'
        OR element->>'id' = ANY(element_ids)
        OR jsonb_typeof(element->'x') <> 'number'
        OR jsonb_typeof(element->'y') <> 'number'
        OR jsonb_typeof(element->'width') <> 'number'
        OR jsonb_typeof(element->'height') <> 'number'
        OR element->>'x' !~ '^(0|[1-9][0-9]{0,3})$'
        OR element->>'y' !~ '^(0|[1-9][0-9]{0,3})$'
        OR element->>'width' !~ '^(0|[1-9][0-9]{0,3})$'
        OR element->>'height' !~ '^(0|[1-9][0-9]{0,3})$'
      THEN
        RETURN false;
      END IF;
      x_value := (element->>'x')::integer;
      y_value := (element->>'y')::integer;
      width_value := (element->>'width')::integer;
      height_value := (element->>'height')::integer;
      IF x_value > 1000 OR y_value > 1000
        OR width_value NOT BETWEEN 10 AND 1000
        OR height_value NOT BETWEEN 10 AND 1000
        OR x_value + width_value > 1000
        OR y_value + height_value > 1000
      THEN
        RETURN false;
      END IF;
      element_ids := array_append(element_ids, element->>'id');

      IF kind = 'map_frame' THEN
        IF (SELECT count(*) FROM jsonb_object_keys(element)) <> 7
          OR NOT element ? 'resourceId'
          OR element->>'resourceId' !~
            '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
        THEN
          RETURN false;
        END IF;
        map_frame_ids := array_append(map_frame_ids, element->>'id');
        IF NOT ((element->>'resourceId')::uuid = ANY(map_resource_ids)) THEN
          map_resource_ids := array_append(map_resource_ids, (element->>'resourceId')::uuid);
          IF cardinality(map_resource_ids) > 16 THEN
            RETURN false;
          END IF;
        END IF;
      ELSIF kind = 'text' THEN
        IF (SELECT count(*) FROM jsonb_object_keys(element)) <> 8
          OR NOT element ?& ARRAY['text', 'style']
          OR jsonb_typeof(element->'text') <> 'string'
          OR element->>'text' <> btrim(element->>'text')
          OR char_length(element->>'text') NOT BETWEEN 1 AND 1000
          OR element->>'style' NOT IN ('title', 'heading', 'body', 'note', 'attribution')
        THEN
          RETURN false;
        END IF;
      ELSE
        IF (SELECT count(*) FROM jsonb_object_keys(element)) <> 7
          OR NOT element ? 'mapFrameId'
          OR element->>'mapFrameId' !~ '^[a-z][a-z0-9_-]{0,63}$'
        THEN
          RETURN false;
        END IF;
      END IF;
    END LOOP;

    FOR element IN SELECT item FROM jsonb_array_elements(layout_page->'elements') item LOOP
      IF element->>'type' IN ('source_panel', 'north_arrow', 'scale_bar')
        AND NOT element->>'mapFrameId' = ANY(map_frame_ids)
      THEN
        RETURN false;
      END IF;
    END LOOP;
  END LOOP;
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$_$;


--
-- Name: FUNCTION project_site_print_layout_v1_valid(value jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.project_site_print_layout_v1_valid(value jsonb) IS 'Validates bounded multi-frame print pages without remote dependencies or executable content.';


--
-- Name: project_site_print_layout_valid(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_site_print_layout_valid(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE value->>'schemaVersion'
    WHEN 'opengeo.print-layout.1.0.0' THEN app.project_site_print_layout_v1_valid(value)
    WHEN 'opengeo.print-layout.1.1.0' THEN app.project_site_print_layout_v11_valid(value)
    ELSE false
  END;
$$;


--
-- Name: project_site_theme_options_valid(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_site_theme_options_valid(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT jsonb_typeof(value) = 'object'
    AND (SELECT count(*) FROM jsonb_object_keys(value)) <= 8
    AND NOT EXISTS (
      SELECT 1
      FROM jsonb_object_keys(value) option_name
      WHERE option_name NOT IN (
        'accentColor',
        'footerText',
        'printPageSize',
        'printOrientation',
        'printLayout',
        'printLegend',
        'printNorthArrow',
        'printScaleBar'
      )
    )
    AND (
      NOT value ? 'accentColor'
      OR (
        jsonb_typeof(value->'accentColor') = 'string'
        AND value->>'accentColor' ~ '^#[0-9a-fA-F]{6}$'
      )
    )
    AND (
      NOT value ? 'footerText'
      OR (
        jsonb_typeof(value->'footerText') = 'string'
        AND value->>'footerText' = btrim(value->>'footerText')
        AND char_length(value->>'footerText') BETWEEN 1 AND 500
      )
    )
    AND (
      NOT value ? 'printPageSize'
      OR (
        jsonb_typeof(value->'printPageSize') = 'string'
        AND value->>'printPageSize' IN (
          'letter', 'legal', 'tabloid', 'a4', 'a3', 'a2', 'a1', 'a0'
        )
      )
    )
    AND (
      NOT value ? 'printOrientation'
      OR (
        jsonb_typeof(value->'printOrientation') = 'string'
        AND value->>'printOrientation' IN ('portrait', 'landscape')
      )
    )
    AND (
      NOT value ? 'printLayout'
      OR (
        jsonb_typeof(value->'printLayout') = 'string'
        AND value->>'printLayout' IN ('flow', 'map-sheet')
      )
    )
    AND (
      NOT value ? 'printLegend'
      OR (
        jsonb_typeof(value->'printLegend') = 'string'
        AND value->>'printLegend' IN ('true', 'false')
      )
    )
    AND (
      NOT value ? 'printNorthArrow'
      OR (
        jsonb_typeof(value->'printNorthArrow') = 'string'
        AND value->>'printNorthArrow' IN ('true', 'false')
      )
    )
    AND (
      NOT value ? 'printScaleBar'
      OR (
        jsonb_typeof(value->'printScaleBar') = 'string'
        AND value->>'printScaleBar' IN ('true', 'false')
      )
    );
$_$;


--
-- Name: FUNCTION project_site_theme_options_valid(value jsonb); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.project_site_theme_options_valid(value jsonb) IS 'Validates the closed, bounded, dependency-free site theme and print option contract.';


--
-- Name: provision_invited_user(text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.provision_invited_user(p_cognito_subject text, p_email text, p_display_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_actor uuid := app.current_user_id();
  v_organization uuid := app.current_organization_id();
  v_subject_user uuid;
  v_email_user uuid;
BEGIN
  IF p_email <> lower(p_email) OR p_email = '' OR p_cognito_subject = '' OR p_display_name = '' THEN
    RAISE EXCEPTION 'invalid invited identity';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM app.organization_memberships membership
    WHERE membership.organization_id = v_organization
      AND membership.user_id = v_actor
      AND membership.role = 'admin'
  ) THEN
    RAISE EXCEPTION 'organization administrator required';
  END IF;

  SELECT identity.id INTO v_subject_user
  FROM app.users identity
  WHERE identity.cognito_subject = p_cognito_subject;

  SELECT identity.id INTO v_email_user
  FROM app.users identity
  WHERE identity.email = p_email;

  IF v_subject_user IS NOT NULL AND v_email_user IS NOT NULL
     AND v_subject_user <> v_email_user THEN
    RAISE EXCEPTION 'invited identity conflicts with an existing email';
  END IF;

  IF v_subject_user IS NOT NULL THEN
    IF v_email_user IS NULL THEN
      RAISE EXCEPTION 'invited identity email does not match';
    END IF;
    RETURN v_subject_user;
  END IF;

  IF v_email_user IS NOT NULL THEN
    RAISE EXCEPTION 'invited email belongs to a different identity';
  END IF;

  INSERT INTO app.users (cognito_subject, email, display_name)
  VALUES (p_cognito_subject, p_email, p_display_name)
  RETURNING id INTO v_subject_user;
  RETURN v_subject_user;
END;
$$;


--
-- Name: FUNCTION provision_invited_user(p_cognito_subject text, p_email text, p_display_name text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.provision_invited_user(p_cognito_subject text, p_email text, p_display_name text) IS 'Admin-gated identity reconciliation for a Cognito subject established by the invitation service.';


--
-- Name: queue_spatial_coverage_derivative_reclamation(uuid, uuid, uuid, uuid, uuid, text, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.queue_spatial_coverage_derivative_reclamation(p_organization_id uuid, p_project_id uuid, p_service_id uuid, p_coverage_id uuid, p_derivative_job_id uuid, p_preview_checksum_sha256 text, p_preview_expires_at timestamp with time zone, p_actor_user_id uuid, p_request_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_target record;
  v_existing app.spatial_coverage_derivative_reclamations%ROWTYPE;
  v_id uuid := gen_random_uuid();
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_organization_id <> app.current_organization_id()
    OR p_actor_user_id <> app.current_user_id()
    OR p_preview_checksum_sha256 !~ '^[0-9a-f]{64}$'
    OR p_preview_expires_at <= v_now
    OR p_preview_expires_at > v_now + interval '15 minutes'
    OR p_request_id IS NULL OR char_length(p_request_id) NOT BETWEEN 1 AND 200
  THEN
    RAISE EXCEPTION 'invalid coverage derivative reclamation confirmation';
  END IF;

  SELECT reclamation.* INTO v_existing
  FROM app.spatial_coverage_derivative_reclamations reclamation
  WHERE reclamation.organization_id = p_organization_id
    AND reclamation.derivative_job_id = p_derivative_job_id
    AND reclamation.state IN ('queued', 'running', 'completed')
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing.preview_checksum_sha256 <> p_preview_checksum_sha256 THEN
      RAISE EXCEPTION 'coverage derivative reclamation preview changed';
    END IF;
    RETURN v_existing.id;
  END IF;

  SELECT job.organization_id, job.project_id, job.service_id, job.coverage_id,
         job.finished_at, job.output_object_id, object.bucket, object.object_key,
         object.s3_version_id, object.etag, object.content_type,
         object.size_bytes, object.checksum_sha256, object.role::text
  INTO v_target
  FROM app.spatial_coverage_derivative_jobs job
  JOIN app.data_objects object
    ON object.organization_id = job.organization_id
   AND object.id = job.output_object_id
  WHERE job.organization_id = p_organization_id
    AND job.project_id = p_project_id
    AND job.service_id = p_service_id
    AND job.coverage_id = p_coverage_id
    AND job.id = p_derivative_job_id
    AND job.state = 'completed'
  FOR UPDATE OF job, object;
  IF NOT FOUND
    OR v_target.finished_at > v_now - interval '24 hours'
    OR v_target.role <> 'derived'
    OR v_target.object_key <> format(
      'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/coverages/%s.tif',
      v_target.organization_id, v_target.project_id,
      (SELECT coverage.dataset_id FROM app.spatial_service_coverages coverage
       WHERE coverage.organization_id = p_organization_id
         AND coverage.id = p_coverage_id),
      (SELECT coverage.dataset_version_id FROM app.spatial_service_coverages coverage
       WHERE coverage.organization_id = p_organization_id
         AND coverage.id = p_coverage_id),
      p_derivative_job_id
    )
  THEN
    RAISE EXCEPTION 'coverage derivative is not reclaimable';
  END IF;
  IF app.coverage_derivative_object_is_referenced(
    p_organization_id, v_target.output_object_id
  ) THEN
    RAISE EXCEPTION 'coverage derivative object is still referenced';
  END IF;

  INSERT INTO app.spatial_coverage_derivative_reclamations
    (id, organization_id, project_id, service_id, coverage_id,
     derivative_job_id, output_object_id, sealed_bucket, sealed_object_key,
     sealed_storage_version_id, sealed_etag, sealed_content_type,
     sealed_size_bytes, sealed_checksum_sha256, preview_checksum_sha256,
     preview_expires_at, created_by, created_at)
  VALUES
    (v_id, p_organization_id, p_project_id, p_service_id, p_coverage_id,
     p_derivative_job_id, v_target.output_object_id, v_target.bucket,
     v_target.object_key, v_target.s3_version_id, lower(v_target.etag),
     v_target.content_type, v_target.size_bytes, v_target.checksum_sha256,
     p_preview_checksum_sha256, p_preview_expires_at, p_actor_user_id, v_now);

  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (p_organization_id, p_actor_user_id, p_project_id,
     'spatial_service.coverage.derivative.reclamation.requested',
     'spatial_service', p_service_id, p_request_id,
     jsonb_build_object(
       'reclamation_id', v_id, 'derivative_job_id', p_derivative_job_id,
       'coverage_id', p_coverage_id, 'output_object_id', v_target.output_object_id,
       'size_bytes', v_target.size_bytes,
       'checksum_sha256', v_target.checksum_sha256
     ));
  RETURN v_id;
END;
$_$;


--
-- Name: queue_spatial_tile_cache_reclamation(uuid, uuid, uuid, uuid, uuid, uuid[], text, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.queue_spatial_tile_cache_reclamation(p_organization_id uuid, p_project_id uuid, p_service_id uuid, p_binding_id uuid, p_cache_version_id uuid, p_render_job_ids uuid[], p_preview_checksum_sha256 text, p_preview_expires_at timestamp with time zone, p_actor_user_id uuid, p_request_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_cache record;
  v_existing app.spatial_tile_cache_reclamations%ROWTYPE;
  v_candidate_ids uuid[];
  v_target_count integer;
  v_target_size bigint;
  v_inserted integer;
  v_id uuid := gen_random_uuid();
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_organization_id <> app.current_organization_id()
    OR p_actor_user_id <> app.current_user_id()
    OR cardinality(p_render_job_ids) NOT BETWEEN 1 AND 64
    OR p_preview_checksum_sha256 !~ '^[0-9a-f]{64}$'
    OR p_preview_expires_at <= v_now
    OR p_preview_expires_at > v_now + interval '15 minutes'
    OR p_request_id IS NULL OR char_length(p_request_id) NOT BETWEEN 1 AND 200
  THEN
    RAISE EXCEPTION 'invalid tile cache reclamation confirmation';
  END IF;

  SELECT reclamation.* INTO v_existing
  FROM app.spatial_tile_cache_reclamations reclamation
  WHERE reclamation.organization_id = p_organization_id
    AND reclamation.project_id = p_project_id
    AND reclamation.service_id = p_service_id
    AND reclamation.binding_id = p_binding_id
    AND reclamation.cache_version_id = p_cache_version_id
    AND reclamation.preview_checksum_sha256 = p_preview_checksum_sha256
    AND reclamation.preview_expires_at = p_preview_expires_at
  FOR UPDATE;
  IF FOUND THEN RETURN v_existing.id; END IF;

  SELECT cache.id, version.version_number
  INTO v_cache
  FROM app.spatial_tile_caches cache
  JOIN app.spatial_tile_cache_versions version
    ON version.organization_id = cache.organization_id
   AND version.cache_id = cache.id
   AND version.id = p_cache_version_id
  WHERE cache.organization_id = p_organization_id
    AND cache.project_id = p_project_id
    AND cache.service_id = p_service_id
    AND cache.binding_id = p_binding_id
    AND version.id <> cache.current_version_id
    AND version.version_number < cache.current_version_number
  FOR UPDATE OF cache;
  IF NOT FOUND THEN RAISE EXCEPTION 'tile cache generation is not retired'; END IF;

  SELECT array_agg(candidate.render_job_id ORDER BY candidate.finished_at, candidate.render_job_id),
         count(*)::integer, sum(candidate.size_bytes)::bigint
  INTO v_candidate_ids, v_target_count, v_target_size
  FROM (
    SELECT * FROM app.render_cache_reclamation_candidate_targets(
      p_organization_id, p_project_id, p_service_id, p_binding_id,
      p_cache_version_id
    )
    LIMIT 64
  ) candidate;
  IF v_candidate_ids IS NULL OR v_candidate_ids <> p_render_job_ids THEN
    RAISE EXCEPTION 'tile cache reclamation preview changed';
  END IF;

  PERFORM object.id
  FROM app.map_render_jobs job
  JOIN app.data_objects object
    ON object.organization_id = job.organization_id
   AND object.id = job.output_object_id
  WHERE job.organization_id = p_organization_id
    AND job.id = ANY(p_render_job_ids)
  ORDER BY job.id
  FOR UPDATE OF job, object;

  INSERT INTO app.spatial_tile_cache_reclamations
    (id, organization_id, project_id, service_id, binding_id, cache_id,
     cache_version_id, cache_version_number, target_count, target_size_bytes,
     preview_checksum_sha256, preview_expires_at, created_by, created_at)
  VALUES
    (v_id, p_organization_id, p_project_id, p_service_id, p_binding_id,
     v_cache.id, p_cache_version_id, v_cache.version_number, v_target_count,
     v_target_size, p_preview_checksum_sha256, p_preview_expires_at,
     p_actor_user_id, v_now);

  INSERT INTO app.spatial_tile_cache_reclamation_items
    (organization_id, reclamation_id, position, render_job_id,
     output_object_id, sealed_bucket, sealed_object_key,
     sealed_storage_version_id, sealed_etag, sealed_content_type,
     sealed_size_bytes, sealed_checksum_sha256)
  SELECT p_organization_id, v_id,
         row_number() OVER (ORDER BY candidate.finished_at, candidate.render_job_id),
         candidate.render_job_id, candidate.output_object_id, candidate.bucket,
         candidate.object_key, candidate.storage_version_id, candidate.etag,
         candidate.content_type, candidate.size_bytes, candidate.checksum_sha256
  FROM app.render_cache_reclamation_candidate_targets(
    p_organization_id, p_project_id, p_service_id, p_binding_id,
    p_cache_version_id
  ) candidate
  WHERE candidate.render_job_id = ANY(p_render_job_ids)
  ORDER BY candidate.finished_at, candidate.render_job_id;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted <> v_target_count THEN
    RAISE EXCEPTION 'tile cache reclamation target changed';
  END IF;

  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (p_organization_id, p_actor_user_id, p_project_id,
     'spatial_service.tile_cache.reclamation.requested',
     'spatial_service', p_service_id, p_request_id,
     jsonb_build_object(
       'reclamation_id', v_id, 'binding_id', p_binding_id,
       'cache_id', v_cache.id, 'cache_version_id', p_cache_version_id,
       'cache_version_number', v_cache.version_number,
       'target_count', v_target_count, 'target_size_bytes', v_target_size,
       'preview_checksum_sha256', p_preview_checksum_sha256
     ));
  RETURN v_id;
END;
$_$;


--
-- Name: queue_spatial_tile_seed_plan(uuid, uuid, uuid, uuid, bigint, text, double precision[], integer, integer, integer[], integer[], integer[], integer, integer, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.queue_spatial_tile_seed_plan(requested_organization_id uuid, requested_project_id uuid, requested_service_id uuid, requested_binding_id uuid, requested_cache_version bigint, requested_mode text, requested_bbox double precision[], requested_minimum_tile_matrix integer, requested_maximum_tile_matrix integer, requested_matrices integer[], requested_rows integer[], requested_cols integer[], requested_count integer, requested_existing_count integer, requested_preview_checksum text, requested_preview_expires_at timestamp with time zone, requested_by uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $_$
DECLARE
  cache_head app.spatial_tile_caches%ROWTYPE;
  policy app.spatial_tile_cache_versions%ROWTYPE;
  plan_id uuid;
  coordinate_count integer;
  current_count bigint;
  reserved_count bigint;
  active_count bigint;
  retained_count bigint;
  coordinate record;
  matrix_width bigint;
BEGIN
  IF requested_organization_id <> app.current_organization_id()
    OR requested_by <> app.current_user_id()
    OR requested_mode NOT IN ('tiles', 'bbox')
    OR requested_preview_expires_at <= clock_timestamp()
    OR requested_preview_expires_at > clock_timestamp() + interval '15 minutes'
    OR requested_preview_checksum !~ '^[0-9a-f]{64}$'
  THEN
    RAISE EXCEPTION 'invalid spatial tile seed plan request';
  END IF;
  coordinate_count := COALESCE(array_length(requested_matrices, 1), 0);
  IF coordinate_count NOT BETWEEN 1 AND 64
    OR coordinate_count <> COALESCE(array_length(requested_rows, 1), 0)
    OR coordinate_count <> COALESCE(array_length(requested_cols, 1), 0)
    OR requested_count <> requested_existing_count + coordinate_count
  THEN
    RAISE EXCEPTION 'spatial tile seed plan batch is invalid';
  END IF;
  SELECT * INTO cache_head
  FROM app.spatial_tile_caches cache
  WHERE cache.organization_id = requested_organization_id
    AND cache.project_id = requested_project_id
    AND cache.service_id = requested_service_id
    AND cache.binding_id = requested_binding_id
    AND cache.current_version_number = requested_cache_version
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'spatial tile seed plan cache version changed';
  END IF;
  SELECT * INTO policy
  FROM app.spatial_tile_cache_versions version
  WHERE version.organization_id = cache_head.organization_id
    AND version.cache_id = cache_head.id
    AND version.id = cache_head.current_version_id
    AND version.version_number = cache_head.current_version_number;
  PERFORM 1
  FROM app.spatial_service_collections binding
  JOIN app.spatial_services service
    ON service.organization_id = binding.organization_id
   AND service.id = binding.service_id
  JOIN app.feature_collections features
    ON features.organization_id = binding.organization_id
   AND features.dataset_id = binding.dataset_id
  JOIN app.map_render_profiles profile
    ON profile.organization_id = binding.organization_id
   AND profile.id = binding.default_profile_id
  WHERE binding.organization_id = requested_organization_id
    AND binding.id = requested_binding_id
    AND binding.withdrawn_at IS NULL
    AND service.disabled_at IS NULL
    AND features.generation = binding.sealed_feature_generation
    AND profile.current_version_id = binding.sealed_profile_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'spatial tile seed plan binding is not fresh';
  END IF;
  SELECT existing.id INTO plan_id
  FROM app.spatial_tile_seed_plans existing
  WHERE existing.organization_id = requested_organization_id
    AND existing.project_id = requested_project_id
    AND existing.service_id = requested_service_id
    AND existing.binding_id = requested_binding_id
    AND existing.preview_checksum_sha256 = requested_preview_checksum
    AND existing.preview_expires_at = requested_preview_expires_at;
  IF plan_id IS NOT NULL THEN
    RETURN plan_id;
  END IF;
  FOR coordinate IN
    SELECT matrix, row_number, col_number, ordinal
    FROM unnest(requested_matrices, requested_rows, requested_cols)
         WITH ORDINALITY AS item(matrix, row_number, col_number, ordinal)
    ORDER BY ordinal
  LOOP
    IF coordinate.matrix NOT BETWEEN policy.minimum_tile_matrix AND policy.maximum_tile_matrix
      OR coordinate.matrix <> requested_matrices[coordinate.ordinal]
      OR coordinate.row_number < 0 OR coordinate.col_number < 0
    THEN
      RAISE EXCEPTION 'spatial tile seed plan coordinate is outside the policy';
    END IF;
    matrix_width := (1::bigint << coordinate.matrix);
    IF coordinate.row_number >= matrix_width OR coordinate.col_number >= matrix_width THEN
      RAISE EXCEPTION 'spatial tile seed plan coordinate is outside the matrix';
    END IF;
    IF coordinate.ordinal > 1 AND ROW(
      coordinate.matrix, coordinate.row_number, coordinate.col_number
    ) <= ROW(
      requested_matrices[coordinate.ordinal - 1],
      requested_rows[coordinate.ordinal - 1],
      requested_cols[coordinate.ordinal - 1]
    ) THEN
      RAISE EXCEPTION 'spatial tile seed plan coordinates must be unique and sorted';
    END IF;
    PERFORM 1 FROM app.spatial_tile_cache_entries entry
    WHERE entry.organization_id = requested_organization_id
      AND entry.cache_id = cache_head.id
      AND entry.cache_version_number = cache_head.current_version_number
      AND entry.tile_matrix = coordinate.matrix
      AND entry.tile_row = coordinate.row_number
      AND entry.tile_col = coordinate.col_number;
    IF FOUND THEN
      RAISE EXCEPTION 'spatial tile seed plan target already exists';
    END IF;
  END LOOP;
  SELECT count(*) INTO active_count
  FROM app.spatial_tile_seed_plans plan
  WHERE plan.organization_id = requested_organization_id
    AND plan.cache_id = cache_head.id
    AND plan.cache_version_number = cache_head.current_version_number
    AND plan.state IN ('preparing', 'queued', 'running');
  SELECT count(*) INTO retained_count
  FROM app.spatial_tile_seed_plans plan
  WHERE plan.organization_id = requested_organization_id
    AND plan.cache_id = cache_head.id
    AND plan.cache_version_number = cache_head.current_version_number;
  IF active_count >= 4 OR retained_count >= 64 THEN
    RAISE EXCEPTION 'spatial tile seed plan limit reached';
  END IF;
  SELECT count(*) INTO current_count
  FROM app.spatial_tile_cache_entries entry
  WHERE entry.organization_id = requested_organization_id
    AND entry.cache_id = cache_head.id
    AND entry.cache_version_number = cache_head.current_version_number;
  SELECT COALESCE(sum(plan.target_count), 0) INTO reserved_count
  FROM app.spatial_tile_seed_plans plan
  WHERE plan.organization_id = requested_organization_id
    AND plan.cache_id = cache_head.id
    AND plan.cache_version_number = cache_head.current_version_number
    AND plan.state = 'preparing';
  IF current_count + reserved_count + coordinate_count > policy.maximum_entries THEN
    RAISE EXCEPTION 'spatial tile seed plan exceeds cache quota';
  END IF;
  plan_id := gen_random_uuid();
  INSERT INTO app.spatial_tile_seed_plans
    (id, organization_id, project_id, service_id, binding_id, cache_id,
     cache_version_id, cache_version_number, mode, request_bbox,
     minimum_tile_matrix, maximum_tile_matrix, requested_count, existing_count,
     target_count, preview_checksum_sha256, preview_expires_at, created_by)
  VALUES
    (plan_id, requested_organization_id, requested_project_id, requested_service_id,
     requested_binding_id, cache_head.id, cache_head.current_version_id,
     cache_head.current_version_number, requested_mode, requested_bbox,
     requested_minimum_tile_matrix, requested_maximum_tile_matrix,
     requested_count, requested_existing_count, coordinate_count,
     requested_preview_checksum, requested_preview_expires_at, requested_by);
  INSERT INTO app.spatial_tile_seed_plan_items
    (organization_id, plan_id, cache_id, cache_version_number, position,
     tile_matrix, tile_row, tile_col)
  SELECT requested_organization_id, plan_id, cache_head.id,
         cache_head.current_version_number, ordinal, matrix, row_number, col_number
  FROM unnest(requested_matrices, requested_rows, requested_cols)
       WITH ORDINALITY AS item(matrix, row_number, col_number, ordinal);
  RETURN plan_id;
END;
$_$;


--
-- Name: record_geonode_federation_source_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_geonode_federation_source_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES (NEW.organization_id, NEW.created_by, NEW.project_id,
    'federation.geonode.source.registered', 'geonode_federation_source', NEW.id,
    'geonode-source:' || NEW.id::text, jsonb_build_object(
      'source_fingerprint_sha256', NEW.source_fingerprint_sha256,
      'configuration_checksum_sha256', NEW.configuration_checksum_sha256,
      'source_version', NEW.source_version,
      'credential_mode', NEW.credential_mode,
      'scheduling_enabled', NEW.scheduling_enabled,
      'refresh_interval_minutes', NEW.refresh_interval_minutes,
      'maximum_resources', NEW.maximum_resources));
  RETURN NEW;
END;
$$;


