--
-- Name: release_dataset_ingest(uuid, uuid, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.release_dataset_ingest(p_job_id uuid, p_worker_token uuid, p_error_code text, p_max_attempts integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_job app.processing_jobs%ROWTYPE;
  v_failed boolean;
BEGIN
  IF p_error_code IS NULL OR p_error_code !~ '^[a-z0-9]+(?:[._-][a-z0-9]+)*$'
    OR char_length(p_error_code) > 100
    OR p_max_attempts NOT BETWEEN 1 AND 10
  THEN
    RAISE EXCEPTION 'invalid ingestion release';
  END IF;

  SELECT * INTO v_job
  FROM app.processing_jobs
  WHERE id = p_job_id
  FOR UPDATE;

  IF NOT FOUND OR v_job.job_type <> 'dataset.ingest'
    OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token
  THEN
    RETURN 'lost';
  END IF;

  IF v_job.attempt_count >= p_max_attempts THEN
    v_failed := app.fail_dataset_ingest(
      p_job_id,
      p_worker_token,
      'processing_retry_exhausted',
      jsonb_build_object(
        'errors', jsonb_build_array(jsonb_build_object('code', p_error_code)),
        'attempt_count', v_job.attempt_count
      )
    );
    RETURN CASE WHEN v_failed THEN 'failed' ELSE 'lost' END;
  END IF;

  UPDATE app.processing_jobs
  SET state = 'queued',
      result = jsonb_build_object('last_transient_error', p_error_code),
      error_code = p_error_code,
      worker_token = NULL,
      lease_expires_at = NULL,
      last_heartbeat_at = NULL
  WHERE id = v_job.id;

  RETURN 'queued';
END;
$_$;


--
-- Name: release_external_connection_verification(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.release_external_connection_verification(p_verification_id uuid, p_worker_token uuid, p_max_attempts integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job app.external_connection_verifications%ROWTYPE;
  v_duration_ms integer;
  v_completed boolean;
BEGIN
  IF p_verification_id IS NULL OR p_worker_token IS NULL
    OR p_max_attempts NOT BETWEEN 1 AND 3
  THEN
    RAISE EXCEPTION 'invalid connection verification release';
  END IF;
  SELECT verification.* INTO v_job
  FROM app.external_connection_verifications verification
  WHERE verification.id = p_verification_id
  FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token THEN
    RETURN 'lost';
  END IF;

  IF v_job.attempt_count >= p_max_attempts THEN
    v_duration_ms := LEAST(20000, GREATEST(0,
      floor(extract(epoch FROM (clock_timestamp() - v_job.started_at)) * 1000)::integer));
    v_completed := app.complete_external_connection_verification(
      p_verification_id, p_worker_token,
      false, false, false, false, 'verification_failed', v_duration_ms
    );
    RETURN CASE WHEN v_completed THEN 'failed' ELSE 'lost' END;
  END IF;

  UPDATE app.external_connection_verifications
  SET state = 'queued', worker_token = NULL, lease_expires_at = NULL,
      started_at = NULL
  WHERE id = v_job.id;
  RETURN 'queued';
END;
$$;


--
-- Name: release_external_source_discovery(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.release_external_source_discovery(p_job_id uuid, p_worker_token uuid, p_error_code text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE v_attempt integer; v_state text;
BEGIN
  IF p_error_code NOT IN (
    'archive_cancelled', 'archive_timeout', 'destination_unavailable',
    'dns_resolution_failed', 'tls_verification_failed',
    'upstream_unavailable'
  ) THEN RETURN 'lost'; END IF;
  SELECT attempt_count INTO v_attempt FROM app.external_source_discovery_jobs
  WHERE id = p_job_id AND state = 'running' AND worker_token = p_worker_token
  FOR UPDATE;
  IF NOT FOUND THEN RETURN 'lost'; END IF;
  v_state := CASE WHEN v_attempt >= 3 THEN 'failed' ELSE 'queued' END;
  UPDATE app.external_source_discovery_jobs
  SET state = v_state::app.processing_job_state,
      error_code = CASE WHEN v_state = 'failed' THEN 'retry_exhausted'
        ELSE p_error_code END,
      worker_token = NULL, lease_expires_at = NULL,
      finished_at = CASE WHEN v_state = 'failed' THEN clock_timestamp() ELSE NULL END
  WHERE id = p_job_id;
  RETURN v_state;
END;
$$;


--
-- Name: release_external_source_snapshot(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.release_external_source_snapshot(p_job_id uuid, p_worker_token uuid, p_error_code text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE v_attempt integer; v_state text;
BEGIN
  IF p_error_code !~ '^[a-z0-9]+(?:[._-][a-z0-9]+)*$'
    OR char_length(p_error_code) > 100 THEN RETURN 'lost'; END IF;
  SELECT attempt_count INTO v_attempt FROM app.external_source_snapshot_jobs
  WHERE id = p_job_id AND state = 'running' AND worker_token = p_worker_token
  FOR UPDATE;
  IF NOT FOUND THEN RETURN 'lost'; END IF;
  v_state := CASE WHEN v_attempt >= 3 THEN 'failed' ELSE 'queued' END;
  UPDATE app.external_source_snapshot_jobs
  SET state = v_state::app.processing_job_state, error_code = p_error_code,
      worker_token = NULL, lease_expires_at = NULL, last_heartbeat_at = NULL,
      finished_at = CASE WHEN v_state = 'failed' THEN clock_timestamp() ELSE NULL END
  WHERE id = p_job_id;
  IF v_state = 'failed' THEN
    UPDATE app.datasets destination
    SET status = 'failed', updated_by = job.created_by,
        updated_at = clock_timestamp()
    FROM app.external_source_snapshot_jobs job
    WHERE job.id = p_job_id
      AND destination.organization_id = job.organization_id
      AND destination.id = job.destination_dataset_id
      AND destination.status = 'draft'
      AND destination.current_version_id IS NULL;
    DELETE FROM app.project_datasets link
    USING app.external_source_snapshot_jobs job
    WHERE job.id = p_job_id
      AND link.organization_id = job.organization_id
      AND link.project_id = job.project_id
      AND link.dataset_id = job.destination_dataset_id;
  END IF;
  RETURN v_state;
END;
$_$;


