--
-- Name: release_kml_network_link_request_slot(uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.release_kml_network_link_request_slot(p_request_id uuid, p_project_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
BEGIN
  IF p_request_id IS NULL OR p_project_id IS NULL OR p_user_id IS NULL
    OR p_user_id IS DISTINCT FROM app.current_user_id()
  THEN
    RAISE EXCEPTION 'invalid KML NetworkLink quota release';
  END IF;

  UPDATE app.kml_network_link_request_slots slot
  SET released_at = COALESCE(slot.released_at, clock_timestamp())
  WHERE slot.request_id = p_request_id
    AND slot.organization_id = app.current_organization_id()
    AND slot.project_id = p_project_id
    AND slot.user_id = p_user_id;
  RETURN FOUND;
END;
$$;


--
-- Name: release_map_render(uuid, uuid, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.release_map_render(p_job_id uuid, p_worker_token uuid, p_error_code text, p_max_attempts integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_job app.map_render_jobs%ROWTYPE;
  v_failed boolean;
BEGIN
  IF p_error_code IS NULL
    OR p_error_code !~ '^[a-z0-9]+(?:[._-][a-z0-9]+)*$'
    OR char_length(p_error_code) > 100
    OR p_max_attempts NOT BETWEEN 1 AND 10
  THEN
    RAISE EXCEPTION 'invalid map render release';
  END IF;
  SELECT * INTO v_job FROM app.map_render_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token THEN
    RETURN 'lost';
  END IF;
  IF v_job.attempt_count >= p_max_attempts THEN
    v_failed := app.fail_map_render(
      p_job_id, p_worker_token, 'render_retry_exhausted'
    );
    RETURN CASE WHEN v_failed THEN 'failed' ELSE 'lost' END;
  END IF;
  UPDATE app.map_render_jobs
  SET state = 'queued', error_code = p_error_code, worker_token = NULL,
      lease_expires_at = NULL, last_heartbeat_at = NULL,
      started_at = NULL
  WHERE id = v_job.id;
  RETURN 'queued';
END;
$_$;


--
-- Name: release_observable_build(uuid, uuid, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.release_observable_build(p_job_id uuid, p_coordinator_token uuid, p_error_code text, p_max_attempts integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_job app.observable_build_jobs%ROWTYPE;
  v_failed boolean;
BEGIN
  IF p_error_code IS NULL
    OR p_error_code !~ '^[a-z0-9]+(?:[._-][a-z0-9]+)*$'
    OR char_length(p_error_code) > 100
    OR p_max_attempts NOT BETWEEN 1 AND 10
  THEN
    RAISE EXCEPTION 'invalid Observable build release';
  END IF;
  SELECT * INTO v_job
  FROM app.observable_build_jobs
  WHERE id = p_job_id
  FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running'
    OR v_job.coordinator_token <> p_coordinator_token
  THEN
    RETURN 'lost';
  END IF;
  IF v_job.attempt_count >= p_max_attempts THEN
    v_failed := app.fail_observable_build(
