--
-- Name: release_spatial_coverage_derivative_reclamation(uuid, uuid, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.release_spatial_coverage_derivative_reclamation(p_reclamation_id uuid, p_worker_token uuid, p_error_code text, p_max_attempts integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_plan app.spatial_coverage_derivative_reclamations%ROWTYPE;
  v_state text;
BEGIN
  IF p_error_code !~ '^[a-z0-9]+(?:[._-][a-z0-9]+)*$'
    OR char_length(p_error_code) > 200 OR p_max_attempts NOT BETWEEN 1 AND 10
  THEN RETURN 'lost'; END IF;
  SELECT * INTO v_plan FROM app.spatial_coverage_derivative_reclamations
  WHERE id = p_reclamation_id AND state = 'running'
    AND worker_token = p_worker_token FOR UPDATE;
  IF NOT FOUND THEN RETURN 'lost'; END IF;
  v_state := CASE
    WHEN v_plan.delete_started_at IS NOT NULL THEN 'queued'
    WHEN v_plan.attempt_count >= p_max_attempts THEN 'failed'
    ELSE 'queued'
  END;
  UPDATE app.spatial_coverage_derivative_reclamations
  SET state = v_state::app.processing_job_state, error_code = p_error_code,
      worker_token = NULL, lease_expires_at = NULL, last_heartbeat_at = NULL,
      finished_at = CASE WHEN v_state = 'failed' THEN clock_timestamp() ELSE NULL END
  WHERE id = v_plan.id;
  IF v_state = 'failed' THEN
    INSERT INTO app.activity_events
      (organization_id, actor_user_id, project_id, event_type,
       resource_type, resource_id, request_id, payload)
    VALUES
      (v_plan.organization_id, v_plan.created_by, v_plan.project_id,
       'spatial_service.coverage.derivative.reclamation.failed',
       'spatial_service', v_plan.service_id, 'worker:' || v_plan.id::text,
       jsonb_build_object(
         'reclamation_id', v_plan.id,
         'derivative_job_id', v_plan.derivative_job_id,
         'coverage_id', v_plan.coverage_id,
         'output_object_id', v_plan.output_object_id,
         'error_code', p_error_code
       ));
  END IF;
  RETURN v_state;
END;
$_$;


--
-- Name: release_spatial_tile_cache_reclamation(uuid, uuid, text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.release_spatial_tile_cache_reclamation(p_reclamation_id uuid, p_worker_token uuid, p_error_code text, p_max_attempts integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_plan app.spatial_tile_cache_reclamations%ROWTYPE;
  v_ambiguous boolean;
  v_state text;
BEGIN
  IF p_error_code !~ '^[a-z0-9]+(?:[._-][a-z0-9]+)*$'
    OR char_length(p_error_code) > 200 OR p_max_attempts NOT BETWEEN 1 AND 100
  THEN RETURN 'lost'; END IF;
  SELECT * INTO v_plan FROM app.spatial_tile_cache_reclamations
  WHERE id = p_reclamation_id AND state = 'running'
    AND worker_token = p_worker_token FOR UPDATE;
  IF NOT FOUND THEN RETURN 'lost'; END IF;
  SELECT EXISTS (
    SELECT 1 FROM app.spatial_tile_cache_reclamation_items item
    WHERE item.organization_id = v_plan.organization_id
      AND item.reclamation_id = v_plan.id
      AND item.state = 'running' AND item.delete_started_at IS NOT NULL
  ) INTO v_ambiguous;
  v_state := CASE WHEN v_ambiguous OR v_plan.attempt_count < p_max_attempts
                  THEN 'queued' ELSE 'failed' END;
  IF v_state = 'failed' THEN
    UPDATE app.spatial_tile_cache_reclamation_items
    SET state = 'failed', error_code = p_error_code,
        finished_at = clock_timestamp()
    WHERE organization_id = v_plan.organization_id
      AND reclamation_id = v_plan.id AND state = 'queued';
  END IF;
  UPDATE app.spatial_tile_cache_reclamations
  SET state = v_state::app.processing_job_state, error_code = p_error_code,
      worker_token = NULL, lease_expires_at = NULL,
      last_heartbeat_at = NULL,
      finished_at = CASE WHEN v_state = 'failed' THEN clock_timestamp() ELSE NULL END
  WHERE id = v_plan.id;
  RETURN v_state;
END;
$_$;


--
-- Name: release_user_dataset_connection_verification(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.release_user_dataset_connection_verification(p_verification_id uuid, p_worker_token uuid, p_max_attempts integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_job app.user_dataset_connection_verifications%ROWTYPE;
BEGIN
  IF p_max_attempts <> 3 THEN
    RAISE EXCEPTION 'invalid user dataset verification release';
  END IF;
  SELECT verification.* INTO v_job
  FROM app.user_dataset_connection_verifications verification
  WHERE verification.id = p_verification_id
  FOR UPDATE;
  IF NOT FOUND OR v_job.state <> 'running' OR v_job.worker_token <> p_worker_token THEN
    RETURN 'unchanged';
  END IF;
  IF v_job.attempt_count < p_max_attempts THEN
    UPDATE app.user_dataset_connection_verifications
    SET state = 'queued', worker_token = NULL, lease_expires_at = NULL,
        started_at = NULL
    WHERE id = v_job.id;
    RETURN 'queued';
  END IF;
  PERFORM app.complete_user_dataset_connection_verification(
    v_job.id, p_worker_token, false, false, false, 0,
    'verification_failed', 0
  );
  RETURN 'failed';
END;
$$;


--
-- Name: render_cache_output_is_referenced(uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.render_cache_output_is_referenced(p_organization_id uuid, p_render_job_id uuid, p_object_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_referenced boolean;
BEGIN
  -- Current cache heads and current render-profile generations remain reusable.
  SELECT EXISTS (
    SELECT 1
    FROM app.spatial_tile_caches cache
    JOIN app.spatial_tile_cache_entries entry
      ON entry.organization_id = cache.organization_id
     AND entry.cache_id = cache.id
     AND entry.cache_version_id = cache.current_version_id
     AND entry.cache_version_number = cache.current_version_number
    WHERE cache.organization_id = p_organization_id
      AND entry.render_job_id = p_render_job_id
    UNION ALL
    SELECT 1
    FROM app.map_render_job_layers layer
    JOIN app.map_render_profiles profile
      ON profile.organization_id = layer.organization_id
     AND profile.id = layer.profile_id
     AND profile.current_version_id = layer.profile_version_id
    WHERE layer.organization_id = p_organization_id
      AND layer.render_job_id = p_render_job_id
    UNION ALL
    SELECT 1
    FROM app.map_render_jobs other_job
    WHERE other_job.organization_id = p_organization_id
      AND other_job.output_object_id = p_object_id
      AND other_job.id <> p_render_job_id
    UNION ALL
    SELECT 1
    FROM app.governed_resource_versions version
    WHERE version.organization_id = p_organization_id
      AND (
        version.content::text LIKE '%' || p_object_id::text || '%'
        OR version.content::text LIKE '%' || p_render_job_id::text || '%'
      )
  ) INTO v_referenced;
  IF v_referenced OR to_regclass('app.project_site_editions') IS NULL THEN
    RETURN v_referenced;
  END IF;
  EXECUTE
    'SELECT EXISTS (
       SELECT 1 FROM app.project_site_editions edition
       WHERE edition.organization_id = $1
         AND (
           edition.manifest::text LIKE ''%'' || $2::text || ''%''
           OR edition.manifest::text LIKE ''%'' || $3::text || ''%''
         )
     )'
  INTO v_referenced
  USING p_organization_id, p_object_id, p_render_job_id;
  RETURN v_referenced;
END;
$_$;


--
-- Name: render_cache_reclamation_candidate_facts(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.render_cache_reclamation_candidate_facts(p_organization_id uuid, p_project_id uuid, p_service_id uuid, p_binding_id uuid, p_cache_version_id uuid) RETURNS TABLE(render_job_id uuid, output_object_id uuid, size_bytes bigint, checksum_sha256 text, finished_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
  SELECT candidate.render_job_id, candidate.output_object_id,
         candidate.size_bytes, candidate.checksum_sha256,
         candidate.finished_at
  FROM app.render_cache_reclamation_candidate_targets(
    p_organization_id, p_project_id, p_service_id, p_binding_id,
    p_cache_version_id
  ) candidate
  WHERE p_organization_id = app.current_organization_id()
  ORDER BY candidate.finished_at, candidate.render_job_id;
$$;


--
-- Name: render_cache_reclamation_candidate_targets(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.render_cache_reclamation_candidate_targets(p_organization_id uuid, p_project_id uuid, p_service_id uuid, p_binding_id uuid, p_cache_version_id uuid) RETURNS TABLE(render_job_id uuid, output_object_id uuid, bucket text, object_key text, storage_version_id text, etag text, content_type text, size_bytes bigint, checksum_sha256 text, finished_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $_$
  SELECT job.id, object.id, object.bucket, object.object_key,
         object.s3_version_id, lower(object.etag), object.content_type,
         object.size_bytes, object.checksum_sha256, job.finished_at
  FROM app.spatial_tile_caches cache
  JOIN app.spatial_tile_cache_versions version
    ON version.organization_id = cache.organization_id
   AND version.cache_id = cache.id
   AND version.id = p_cache_version_id
  JOIN LATERAL (
    SELECT min(successor.created_at) AS retired_at
    FROM app.spatial_tile_cache_versions successor
    WHERE successor.organization_id = version.organization_id
      AND successor.cache_id = version.cache_id
      AND successor.version_number > version.version_number
  ) retirement ON true
  JOIN app.spatial_tile_cache_entries entry
    ON entry.organization_id = version.organization_id
   AND entry.cache_id = version.cache_id
   AND entry.cache_version_id = version.id
   AND entry.cache_version_number = version.version_number
  JOIN app.map_render_jobs job
    ON job.organization_id = entry.organization_id
   AND job.id = entry.render_job_id
   AND job.project_id = p_project_id
   AND job.state = 'completed'
   AND job.composition_sealed
  JOIN app.map_render_profile_versions profile_version
    ON profile_version.organization_id = job.organization_id
   AND profile_version.profile_id = job.profile_id
   AND profile_version.id = job.profile_version_id
  JOIN app.data_objects object
    ON object.organization_id = job.organization_id
   AND object.id = job.output_object_id
  WHERE cache.organization_id = p_organization_id
    AND cache.project_id = p_project_id
    AND cache.service_id = p_service_id
    AND cache.binding_id = p_binding_id
    AND version.id <> cache.current_version_id
    AND version.version_number < cache.current_version_number
    AND retirement.retired_at <= clock_timestamp() - interval '24 hours'
    AND entry.seeded_at <= clock_timestamp() - interval '24 hours'
    AND job.finished_at <= clock_timestamp() - interval '24 hours'
    AND object.role = 'derived'
    AND object.content_type = CASE job.format::text
      WHEN 'svg' THEN 'image/svg+xml' WHEN 'png' THEN 'image/png' END
    AND object.size_bytes BETWEEN 1 AND 20971520
    AND object.object_key = format(
      'organizations/%s/projects/%s/datasets/%s/versions/%s/derivatives/renders/%s.%s',
      job.organization_id, job.project_id, profile_version.dataset_id,
      profile_version.dataset_version_id, job.id,
      CASE job.format::text WHEN 'svg' THEN 'svg' WHEN 'png' THEN 'png' END
    )
    AND object.s3_version_id NOT IN ('', 'null')
    AND object.etag ~ '^[A-Fa-f0-9]{16,128}$'
    AND object.checksum_sha256 ~ '^[0-9a-f]{64}$'
    AND NOT EXISTS (
      SELECT 1 FROM app.map_render_job_layers extra_layer
      WHERE extra_layer.organization_id = job.organization_id
        AND extra_layer.render_job_id = job.id
        AND extra_layer.position > 1
    )
    AND NOT app.render_cache_output_is_referenced(
      job.organization_id, job.id, object.id
    )
    AND NOT EXISTS (
      SELECT 1 FROM app.spatial_tile_cache_reclamation_items item
      WHERE item.organization_id = object.organization_id
        AND item.output_object_id = object.id
        AND item.state IN ('queued', 'running', 'completed')
    )
  ORDER BY job.finished_at, job.id;
$_$;


--
-- Name: request_external_connection_verification(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.request_external_connection_verification(p_organization_id uuid, p_project_id uuid, p_connection_id uuid, p_actor_user_id uuid, p_request_id text) RETURNS TABLE(verification_id uuid, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_connection app.external_connections%ROWTYPE;
  v_existing uuid;
  v_verification_id uuid;
BEGIN
  IF p_organization_id IS NULL OR p_project_id IS NULL OR p_connection_id IS NULL
    OR p_actor_user_id IS NULL OR p_request_id IS NULL
    OR p_request_id <> btrim(p_request_id)
    OR char_length(p_request_id) NOT BETWEEN 1 AND 200
    OR p_organization_id IS DISTINCT FROM app.current_organization_id()
    OR p_actor_user_id IS DISTINCT FROM app.current_user_id()
  THEN
    RAISE EXCEPTION 'invalid connection verification request';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM app.organization_memberships membership
    JOIN app.project_memberships project_membership
      ON project_membership.organization_id = membership.organization_id
     AND project_membership.user_id = membership.user_id
     AND project_membership.project_id = p_project_id
    JOIN app.projects project
      ON project.organization_id = project_membership.organization_id
     AND project.id = project_membership.project_id
    WHERE membership.organization_id = p_organization_id
      AND membership.user_id = p_actor_user_id
      AND project_membership.role = 'owner'
      AND project.status = 'active'
  ) THEN
    RAISE EXCEPTION 'connection verification requires project owner';
  END IF;

  SELECT connection.* INTO v_connection
  FROM app.external_connections connection
  WHERE connection.organization_id = p_organization_id
    AND connection.project_id = p_project_id
    AND connection.id = p_connection_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'external connection not found';
  END IF;
  IF v_connection.status IN ('disabled', 'revoked') THEN
    RAISE EXCEPTION 'external connection is not verifiable';
  END IF;

  SELECT verification.id INTO v_existing
  FROM app.external_connection_verifications verification
  WHERE verification.organization_id = p_organization_id
    AND verification.connection_id = p_connection_id
    AND verification.state IN ('queued', 'running')
  ORDER BY verification.created_at DESC
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN QUERY SELECT v_existing, false;
    RETURN;
  END IF;

  INSERT INTO app.external_connection_verifications
    (organization_id, project_id, connection_id, connection_revision_number,
     requested_by, request_id)
  VALUES
    (p_organization_id, p_project_id, p_connection_id,
     v_connection.current_revision_number, p_actor_user_id, p_request_id)
  RETURNING id INTO v_verification_id;

  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type,
     resource_type, resource_id, request_id, payload)
  VALUES
    (p_organization_id, p_actor_user_id, p_project_id,
     'connection.verification.requested', 'connection', p_connection_id,
     p_request_id,
     jsonb_build_object(
       'verification_id', v_verification_id,
       'provider', v_connection.provider::text,
       'connection_revision_number', v_connection.current_revision_number
     ));

  RETURN QUERY SELECT v_verification_id, true;
END;
$$;


--
-- Name: request_user_dataset_connection_verification(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.request_user_dataset_connection_verification(p_connection_id uuid, p_actor_user_id uuid, p_request_id text) RETURNS TABLE(verification_id uuid, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_connection app.user_dataset_connections%ROWTYPE;
  v_existing uuid;
  v_verification_id uuid;
BEGIN
  IF p_connection_id IS NULL OR p_actor_user_id IS NULL OR p_request_id IS NULL
    OR p_actor_user_id IS DISTINCT FROM app.current_user_id()
    OR p_request_id <> btrim(p_request_id)
    OR char_length(p_request_id) NOT BETWEEN 1 AND 200
  THEN
    RAISE EXCEPTION 'invalid user dataset verification request';
  END IF;

  SELECT connection.* INTO v_connection
  FROM app.user_dataset_connections connection
  WHERE connection.organization_id = app.current_organization_id()
    AND connection.owner_user_id = p_actor_user_id
    AND connection.id = p_connection_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'user dataset connection not found';
  END IF;
  IF v_connection.status IN ('draft', 'disabled')
    OR (v_connection.credential_mode = 'assume_role'
      AND (v_connection.secret_arn IS NULL
        OR v_connection.configured_secret_fields <> ARRAY['external_id']::text[]))
    OR (v_connection.credential_mode = 'access_key'
      AND (v_connection.secret_arn IS NULL OR v_connection.credential_revision = 0))
  THEN
    RAISE EXCEPTION 'user dataset connection is not verifiable';
  END IF;

  SELECT verification.id INTO v_existing
  FROM app.user_dataset_connection_verifications verification
  WHERE verification.organization_id = v_connection.organization_id
    AND verification.connection_id = v_connection.id
    AND verification.state IN ('queued', 'running')
  ORDER BY verification.created_at DESC
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN QUERY SELECT v_existing, false;
    RETURN;
  END IF;

  INSERT INTO app.user_dataset_connection_verifications
    (organization_id, owner_user_id, connection_id, target_revision,
     credential_revision, requested_by, request_id)
  VALUES
    (v_connection.organization_id, v_connection.owner_user_id,
     v_connection.id, v_connection.target_revision,
     v_connection.credential_revision, p_actor_user_id, p_request_id)
  RETURNING id INTO v_verification_id;

  INSERT INTO app.activity_events
    (organization_id, actor_user_id, project_id, event_type, resource_type,
     resource_id, request_id, payload)
  VALUES
    (v_connection.organization_id, p_actor_user_id, NULL,
     'dataset_connection.verification.requested', 'dataset_connection',
     v_connection.id, p_request_id,
     jsonb_build_object(
       'verification_id', v_verification_id,
       'target_revision', v_connection.target_revision,
       'credential_revision', v_connection.credential_revision
     ));

  RETURN QUERY SELECT v_verification_id, true;
END;
$$;


--
-- Name: reserve_spatial_service_collection_id(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reserve_spatial_service_collection_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_identifier text;
  v_kind text;
BEGIN
  IF TG_TABLE_NAME = 'spatial_service_collections' THEN
    v_identifier := lower(NEW.collection_name);
    v_kind := 'feature';
  ELSIF TG_TABLE_NAME = 'spatial_service_coverages' THEN
    v_identifier := lower(NEW.coverage_name);
    v_kind := 'coverage';
  ELSE
    RAISE EXCEPTION 'unsupported spatial service collection registry source';
  END IF;
  INSERT INTO app.spatial_service_collection_ids
    (organization_id, project_id, service_id, collection_id,
     resource_kind, resource_id, reserved_by, reserved_at)
  VALUES
    (NEW.organization_id, NEW.project_id, NEW.service_id, v_identifier,
     v_kind, NEW.id, NEW.created_by, NEW.created_at);
  RETURN NEW;
END;
$$;


--
-- Name: resolve_principal(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_principal(p_cognito_subject text) RETURNS TABLE(user_id uuid, email text, display_name text, organization_id uuid, organization_role app.organization_role)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
  SELECT
    identity.id,
    identity.email,
    identity.display_name,
    membership.organization_id,
    membership.role
  FROM app.users identity
  LEFT JOIN app.organization_memberships membership
    ON membership.user_id = identity.id
  WHERE identity.cognito_subject = p_cognito_subject
  ORDER BY membership.organization_id
$$;


--
-- Name: FUNCTION resolve_principal(p_cognito_subject text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.resolve_principal(p_cognito_subject text) IS 'Minimal SECURITY DEFINER lookup for a cryptographically verified Cognito subject; normal tenant queries remain under RLS.';


--
-- Name: resolve_user_dataset_repository_target(uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_user_dataset_repository_target(p_organization_id uuid, p_owner_user_id uuid, p_connection_id uuid) RETURNS TABLE(organization_id uuid, owner_user_id uuid, connection_id uuid, target_revision bigint, credential_revision bigint, bucket_name text, region_name text, object_prefix text, credential_mode text, role_arn text, secret_arn text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
  SELECT connection.organization_id,
         connection.owner_user_id,
         connection.id,
         connection.target_revision,
         connection.credential_revision,
         connection.bucket_name,
         connection.region_name,
         connection.object_prefix,
         connection.credential_mode::text,
         connection.role_arn,
         connection.secret_arn
  FROM app.user_dataset_connections connection
  WHERE p_organization_id IS NOT NULL
    AND p_owner_user_id IS NOT NULL
    AND p_connection_id IS NOT NULL
    AND connection.organization_id = p_organization_id
    AND connection.owner_user_id = p_owner_user_id
    AND connection.id = p_connection_id
    AND connection.provider = 's3'
    AND connection.status = 'verified'
    AND connection.last_verified_at IS NOT NULL
    AND (
      connection.credential_mode = 'workload_identity'
      OR (
        connection.credential_revision > 0
        AND connection.secret_arn IS NOT NULL
      )
    );
$$;


--
-- Name: FUNCTION resolve_user_dataset_repository_target(p_organization_id uuid, p_owner_user_id uuid, p_connection_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.resolve_user_dataset_repository_target(p_organization_id uuid, p_owner_user_id uuid, p_connection_id uuid) IS 'Returns one current verified caller-owned S3 target to the isolated metadata browser; unavailable targets return no row.';


--
-- Name: seal_map_render_composition(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.seal_map_render_composition(p_job_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_updated uuid;
BEGIN
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'invalid map render composition';
  END IF;
  UPDATE app.map_render_jobs
  SET composition_sealed = true
  WHERE id = p_job_id
    AND organization_id = app.current_organization_id()
    AND created_by = app.current_user_id()
    AND state = 'queued'
    AND NOT composition_sealed
  RETURNING id INTO v_updated;
  RETURN v_updated IS NOT NULL;
END;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = clock_timestamp();
  RETURN NEW;
END;
$$;


--
-- Name: spatial_catalog_text_array_is_unique(text[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.spatial_catalog_text_array_is_unique(p_values text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT count(*) = count(DISTINCT value) FROM unnest(p_values) value
$$;


--
-- Name: spatial_catalog_uuid_array_is_unique(uuid[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.spatial_catalog_uuid_array_is_unique(p_values uuid[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT count(*) = count(DISTINCT value) FROM unnest(p_values) value
$$;


--
-- Name: start_spatial_coverage_derivative_delete(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.start_spatial_coverage_derivative_delete(p_reclamation_id uuid, p_worker_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
BEGIN
  UPDATE app.spatial_coverage_derivative_reclamations
  SET delete_started_at = COALESCE(delete_started_at, clock_timestamp()),
      last_heartbeat_at = clock_timestamp()
  WHERE id = p_reclamation_id AND state = 'running'
    AND worker_token = p_worker_token AND lease_expires_at > clock_timestamp()
    AND NOT app.coverage_derivative_object_is_referenced(
      organization_id, output_object_id
    );
  RETURN FOUND;
END;
$$;


--
-- Name: start_spatial_tile_cache_reclamation_item_delete(uuid, integer, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.start_spatial_tile_cache_reclamation_item_delete(p_reclamation_id uuid, p_item_position integer, p_worker_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_item app.spatial_tile_cache_reclamation_items%ROWTYPE;
BEGIN
  SELECT item.* INTO v_item
  FROM app.spatial_tile_cache_reclamations reclamation
  JOIN app.spatial_tile_cache_reclamation_items item
    ON item.organization_id = reclamation.organization_id
   AND item.reclamation_id = reclamation.id
  WHERE reclamation.id = p_reclamation_id
    AND reclamation.state = 'running'
    AND reclamation.worker_token = p_worker_token
    AND reclamation.lease_expires_at > clock_timestamp()
    AND item.position = p_item_position
    AND item.state IN ('queued', 'running')
  FOR UPDATE OF reclamation, item;
  IF NOT FOUND OR app.render_cache_output_is_referenced(
    v_item.organization_id, v_item.render_job_id, v_item.output_object_id
  ) THEN RETURN false; END IF;
  UPDATE app.spatial_tile_cache_reclamation_items
  SET state = 'running', delete_started_at = COALESCE(
        delete_started_at, clock_timestamp()
      )
  WHERE organization_id = v_item.organization_id
    AND reclamation_id = v_item.reclamation_id
    AND position = v_item.position;
  UPDATE app.spatial_tile_cache_reclamations
  SET last_heartbeat_at = clock_timestamp()
  WHERE id = p_reclamation_id AND worker_token = p_worker_token;
  RETURN true;
END;
$$;


--
-- Name: sync_spatial_tile_seed_render_state(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sync_spatial_tile_seed_render_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'app'
    AS $$
DECLARE
  target_plan uuid;
  next_item_state text;
  next_plan_state text;
BEGIN
  IF NEW.state IS NOT DISTINCT FROM OLD.state THEN RETURN NEW; END IF;
  next_item_state := CASE NEW.state::text
    WHEN 'queued' THEN 'queued'
    WHEN 'running' THEN 'running'
    WHEN 'completed' THEN 'completed'
    ELSE 'failed'
  END;
  FOR target_plan IN
    UPDATE app.spatial_tile_seed_plan_items
    SET state = next_item_state,
        error_code = CASE WHEN next_item_state = 'failed' THEN 'render_failed' END,
        started_at = CASE WHEN next_item_state IN ('running', 'completed', 'failed')
                          THEN COALESCE(started_at, NEW.started_at, clock_timestamp())
                          ELSE started_at END,
        finished_at = CASE WHEN next_item_state IN ('completed', 'failed')
                           THEN COALESCE(NEW.finished_at, clock_timestamp()) END
    WHERE organization_id = NEW.organization_id AND render_job_id = NEW.id
      AND state NOT IN ('cancelled', 'failed', 'completed')
    RETURNING plan_id
  LOOP
    SELECT CASE
      WHEN EXISTS (SELECT 1 FROM app.spatial_tile_seed_plan_items item
                   WHERE item.organization_id = NEW.organization_id
                     AND item.plan_id = target_plan AND item.state = 'failed') THEN 'failed'
      WHEN NOT EXISTS (SELECT 1 FROM app.spatial_tile_seed_plan_items item
                       WHERE item.organization_id = NEW.organization_id
                         AND item.plan_id = target_plan AND item.state <> 'completed') THEN 'completed'
      WHEN EXISTS (SELECT 1 FROM app.spatial_tile_seed_plan_items item
                   WHERE item.organization_id = NEW.organization_id
                     AND item.plan_id = target_plan AND item.state = 'running') THEN 'running'
      ELSE 'queued'
    END INTO next_plan_state;
    UPDATE app.spatial_tile_seed_plans
    SET state = next_plan_state,
        error_code = CASE WHEN next_plan_state = 'failed' THEN 'render_failed' END,
        started_at = CASE WHEN next_plan_state IN ('running', 'completed', 'failed')
                          THEN COALESCE(started_at, clock_timestamp()) ELSE started_at END,
        finished_at = CASE WHEN next_plan_state IN ('completed', 'failed')
                           THEN clock_timestamp() ELSE NULL END
    WHERE organization_id = NEW.organization_id AND id = target_plan
      AND dispatch_started_at IS NOT NULL AND state NOT IN ('cancelled', 'completed', 'failed');
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: valid_coverage_band_indexes(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.valid_coverage_band_indexes(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE
  v_item jsonb;
  v_index integer;
  v_previous integer := 0;
  v_count integer := 0;
BEGIN
  IF jsonb_typeof(p_value) <> 'array'
    OR jsonb_array_length(p_value) NOT BETWEEN 1 AND 64
  THEN
    RETURN false;
  END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_value)
  LOOP
    IF jsonb_typeof(v_item) <> 'number'
      OR (v_item #>> '{}') !~ '^[1-9][0-9]?$'
    THEN
      RETURN false;
    END IF;
    v_index := (v_item #>> '{}')::integer;
    IF v_index > 64 OR v_index <= v_previous THEN
      RETURN false;
    END IF;
    v_previous := v_index;
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count = jsonb_array_length(p_value);
END;
$_$;


--
-- Name: valid_coverage_resolution(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.valid_coverage_resolution(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $$
DECLARE
  v_item jsonb;
  v_number numeric;
BEGIN
  IF jsonb_typeof(p_value) <> 'array' OR jsonb_array_length(p_value) <> 2 THEN
    RETURN false;
  END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_value)
  LOOP
    IF jsonb_typeof(v_item) <> 'number' THEN RETURN false; END IF;
    BEGIN
      v_number := (v_item #>> '{}')::numeric;
    EXCEPTION WHEN numeric_value_out_of_range OR invalid_text_representation THEN
      RETURN false;
    END;
    IF v_number <= 0 OR v_number > 1e100 THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END;
$$;


--
-- Name: validate_project_discussion_assignment(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.validate_project_discussion_assignment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.assigned_to IS NULL THEN
    IF NEW.assigned_by IS NOT NULL OR NEW.assigned_at IS NOT NULL THEN
      RAISE EXCEPTION 'unassigned discussion cannot retain assignment attribution';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.assigned_by IS DISTINCT FROM app.current_user_id()
    OR NEW.assigned_at IS NULL
    OR NOT app.project_discussion_user_has_access(
      NEW.organization_id, NEW.project_id, NEW.assigned_to
    )
  THEN
    RAISE EXCEPTION 'discussion assignee must be an authorized project participant';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_project_discussion_mention(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.validate_project_discussion_mention() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.organization_id IS DISTINCT FROM app.current_organization_id()
    OR NEW.mentioned_by IS DISTINCT FROM app.current_user_id()
    OR NOT app.project_discussion_user_has_access(
      NEW.organization_id, NEW.project_id, NEW.mentioned_user_id
    )
  THEN
    RAISE EXCEPTION 'discussion mention must name an authorized project participant';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_project_discussion_target(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.validate_project_discussion_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_target_exists boolean;
BEGIN
  IF NEW.target_kind = 'project' THEN
    RETURN NEW;
  END IF;

  IF NEW.target_kind = 'feature' THEN
    SELECT EXISTS (
      SELECT 1
      FROM app.maps map
      JOIN app.map_versions map_version
        ON map_version.organization_id = map.organization_id
       AND map_version.map_id = map.id
       AND map_version.version = NEW.target_map_version
      JOIN app.project_datasets project_dataset
        ON project_dataset.organization_id = map.organization_id
       AND project_dataset.project_id = map.project_id
       AND project_dataset.dataset_id = NEW.target_dataset_id
      JOIN app.dataset_features feature
        ON feature.organization_id = project_dataset.organization_id
       AND feature.dataset_id = project_dataset.dataset_id
       AND feature.id = NEW.target_feature_id
       AND feature.deleted_at IS NULL
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(map_version.definition->'layers') = 'array'
            THEN map_version.definition->'layers'
          ELSE '[]'::jsonb
        END
      ) layer
      WHERE map.organization_id = NEW.organization_id
        AND map.project_id = NEW.project_id
        AND map.id = NEW.target_map_id
        AND map.status = 'active'
        AND layer->>'layerId' = NEW.target_layer_id
        AND layer->>'datasetId' = NEW.target_dataset_id::text
    ) INTO v_target_exists;
  ELSIF NEW.target_kind = 'map' THEN
    SELECT EXISTS (
      SELECT 1
      FROM app.maps map
      JOIN app.map_versions version
        ON version.organization_id = map.organization_id
       AND version.map_id = map.id
       AND version.version = NEW.target_object_version
      WHERE map.organization_id = NEW.organization_id
        AND map.project_id = NEW.project_id
        AND map.id = NEW.target_object_id
        AND map.version = NEW.target_object_version
        AND map.status = 'active'
    ) INTO v_target_exists;
  ELSIF NEW.target_kind = 'dataset' THEN
    SELECT EXISTS (
      SELECT 1
      FROM app.project_datasets project_dataset
      JOIN app.datasets dataset
        ON dataset.organization_id = project_dataset.organization_id
       AND dataset.id = project_dataset.dataset_id
      JOIN app.dataset_versions version
        ON version.organization_id = dataset.organization_id
       AND version.dataset_id = dataset.id
       AND version.id = dataset.current_version_id
       AND version.version_number = NEW.target_object_version
      WHERE project_dataset.organization_id = NEW.organization_id
        AND project_dataset.project_id = NEW.project_id
        AND project_dataset.dataset_id = NEW.target_object_id
        AND dataset.status <> 'archived'
    ) INTO v_target_exists;
  ELSIF NEW.target_kind = 'resource' THEN
    SELECT EXISTS (
      SELECT 1
      FROM app.governed_resources resource
      JOIN app.governed_resource_versions version
        ON version.organization_id = resource.organization_id
       AND version.resource_id = resource.id
       AND version.id = resource.current_version_id
       AND version.version_number = NEW.target_object_version
      WHERE resource.organization_id = NEW.organization_id
        AND resource.project_id = NEW.project_id
        AND resource.id = NEW.target_object_id
        AND resource.state <> 'archived'
    ) INTO v_target_exists;
  ELSIF NEW.target_kind = 'site' THEN
    SELECT EXISTS (
      SELECT 1
      FROM app.project_sites site
      JOIN app.project_site_versions version
        ON version.organization_id = site.organization_id
       AND version.project_id = site.project_id
       AND version.site_id = site.id
       AND version.id = site.current_version_id
       AND version.version_number = NEW.target_object_version
      WHERE site.organization_id = NEW.organization_id
        AND site.project_id = NEW.project_id
        AND site.id = NEW.target_object_id
        AND site.current_version_number = NEW.target_object_version
    ) INTO v_target_exists;
  END IF;

  IF NOT COALESCE(v_target_exists, false) THEN
    RAISE EXCEPTION
      'discussion target must reference one exact current object version in the project';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION validate_project_discussion_target(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.validate_project_discussion_target() IS 'Rejects forged, stale, deleted, cross-project, or layer/dataset-mismatched feature discussion targets.';


