--
-- Name: dataset_feature_revisions; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.dataset_feature_revisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    dataset_id uuid NOT NULL,
    feature_id uuid NOT NULL,
    version_number bigint NOT NULL,
    operation app.feature_revision_operation NOT NULL,
    geometry_type app.feature_geometry_type NOT NULL,
    properties jsonb NOT NULL,
    geometry_geojson jsonb NOT NULL,
    geometry public.geometry(Geometry,4326) NOT NULL,
    changed_by uuid NOT NULL,
    change_message text,
    request_id text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT dataset_feature_revisions_geojson_object CHECK (((jsonb_typeof(geometry_geojson) = 'object'::text) AND ((geometry_geojson ->> 'type'::text) = (geometry_type)::text) AND (jsonb_typeof((geometry_geojson -> 'coordinates'::text)) = 'array'::text) AND (pg_column_size(geometry_geojson) <= 262144))),
    CONSTRAINT dataset_feature_revisions_geometry_safe CHECK (((public.st_srid(geometry) = 4326) AND (public.st_ndims(geometry) = 2) AND (NOT public.st_isempty(geometry)) AND public.st_isvalid(geometry))),
    CONSTRAINT dataset_feature_revisions_geometry_type_match CHECK ((lower(public.geometrytype(geometry)) = lower((geometry_type)::text))),
    CONSTRAINT dataset_feature_revisions_message_bound CHECK (((change_message IS NULL) OR ((char_length(change_message) >= 1) AND (char_length(change_message) <= 500)))),
    CONSTRAINT dataset_feature_revisions_properties_object CHECK (((jsonb_typeof(properties) = 'object'::text) AND (pg_column_size(properties) <= 32768))),
    CONSTRAINT dataset_feature_revisions_request_id_bound CHECK (((char_length(request_id) >= 1) AND (char_length(request_id) <= 128))),
    CONSTRAINT dataset_feature_revisions_version_positive CHECK ((version_number > 0))
);

ALTER TABLE ONLY app.dataset_feature_revisions FORCE ROW LEVEL SECURITY;


