    CONSTRAINT dataset_features_geojson_object CHECK (((jsonb_typeof(geometry_geojson) = 'object'::text) AND ((geometry_geojson ->> 'type'::text) = (geometry_type)::text) AND (jsonb_typeof((geometry_geojson -> 'coordinates'::text)) = 'array'::text) AND (pg_column_size(geometry_geojson) <= 262144))),
    CONSTRAINT dataset_features_geometry_safe CHECK (((public.st_srid(geometry) = 4326) AND (public.st_ndims(geometry) = 2) AND (NOT public.st_isempty(geometry)) AND public.st_isvalid(geometry))),
    CONSTRAINT dataset_features_geometry_type_match CHECK ((lower(public.geometrytype(geometry)) = lower((geometry_type)::text))),
    CONSTRAINT dataset_features_properties_object CHECK (((jsonb_typeof(properties) = 'object'::text) AND (pg_column_size(properties) <= 32768))),
    CONSTRAINT dataset_features_version_positive CHECK ((version_number > 0))
);

