    search_document tsvector GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, ((COALESCE(name, ''::text) || ' '::text) || COALESCE(description, ''::text)))) STORED,
    CONSTRAINT datasets_name_not_blank CHECK ((name <> ''::text)),
    CONSTRAINT datasets_source_format_match CHECK ((((source_type = 'upload'::app.dataset_source_type) AND (format <> ALL (ARRAY['xyz'::app.dataset_format, 'wms'::app.dataset_format, 'arcgis'::app.dataset_format, 'wfs'::app.dataset_format]))) OR ((source_type = 'repository'::app.dataset_source_type) AND (format <> ALL (ARRAY['xyz'::app.dataset_format, 'wms'::app.dataset_format, 'arcgis'::app.dataset_format, 'wfs'::app.dataset_format]))) OR ((source_type = ANY (ARRAY['xyz'::app.dataset_source_type, 'wms'::app.dataset_source_type, 'pmtiles'::app.dataset_source_type, 'geojson'::app.dataset_source_type, 'arcgis'::app.dataset_source_type, 'wfs'::app.dataset_source_type])) AND ((source_type)::text = (format)::text))))
);

