    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    revision_number bigint NOT NULL,
    configuration jsonb NOT NULL,
    change_summary text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT external_connection_revisions_change_bounded CHECK (((change_summary = btrim(change_summary)) AND ((char_length(change_summary) >= 1) AND (char_length(change_summary) <= 500)))),
    CONSTRAINT external_connection_revisions_configuration_bounded CHECK (((jsonb_typeof(configuration) = 'object'::text) AND (octet_length((configuration)::text) <= 8192) AND (configuration ?& ARRAY['provider'::text, 'endpointHost'::text, 'endpointPort'::text, 'databaseName'::text, 'allowedSchemas'::text, 'readOnly'::text, 'tlsMode'::text, 'networkMode'::text]) AND ((configuration - ARRAY['provider'::text, 'endpointHost'::text, 'endpointPort'::text, 'databaseName'::text, 'allowedSchemas'::text, 'readOnly'::text, 'tlsMode'::text, 'networkMode'::text]) = '{}'::jsonb) AND ((configuration ->> 'provider'::text) = 'postgresql'::text) AND ((configuration ->> 'readOnly'::text) = 'true'::text) AND ((configuration ->> 'tlsMode'::text) = 'verify_full'::text) AND ((configuration ->> 'networkMode'::text) = 'public_internet'::text))),
    CONSTRAINT external_connection_revisions_number_positive CHECK ((revision_number > 0))
);

