--
-- Name: external_connection_verifications; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.external_connection_verifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    connection_revision_number bigint NOT NULL,
    state app.external_connection_verification_state DEFAULT 'queued'::app.external_connection_verification_state NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    worker_token uuid,
    lease_expires_at timestamp with time zone,
    requested_by uuid NOT NULL,
    request_id text NOT NULL,
    network_reachable boolean DEFAULT false NOT NULL,
    tls_verified boolean DEFAULT false NOT NULL,
    credentials_verified boolean DEFAULT false NOT NULL,
    postgis_verified boolean DEFAULT false NOT NULL,
    sanitized_error_code text,
    duration_ms integer,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    CONSTRAINT external_connection_verifications_attempt_bounded CHECK (((attempt_count >= 0) AND (attempt_count <= 3))),
    CONSTRAINT external_connection_verifications_error_allowlist CHECK (((sanitized_error_code IS NULL) OR (sanitized_error_code = ANY (ARRAY['credentials_rejected'::text, 'dns_resolution_failed'::text, 'postgis_required'::text, 'tls_verification_failed'::text, 'unsafe_network_target'::text, 'verification_cancelled'::text, 'verification_failed'::text, 'verification_timeout'::text])))),
    CONSTRAINT external_connection_verifications_lease_shape CHECK ((((state = 'queued'::app.external_connection_verification_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (started_at IS NULL) AND (finished_at IS NULL) AND (sanitized_error_code IS NULL) AND (duration_ms IS NULL) AND (NOT network_reachable) AND (NOT tls_verified) AND (NOT credentials_verified) AND (NOT postgis_verified)) OR ((state = 'running'::app.external_connection_verification_state) AND (worker_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (started_at IS NOT NULL) AND (finished_at IS NULL) AND (sanitized_error_code IS NULL) AND (duration_ms IS NULL)) OR ((state = 'succeeded'::app.external_connection_verification_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL) AND (sanitized_error_code IS NULL) AND (duration_ms IS NOT NULL) AND network_reachable AND tls_verified AND credentials_verified AND postgis_verified) OR ((state = 'failed'::app.external_connection_verification_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL) AND (sanitized_error_code IS NOT NULL) AND (duration_ms IS NOT NULL)) OR ((state = 'cancelled'::app.external_connection_verification_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (finished_at IS NOT NULL) AND (sanitized_error_code = 'verification_cancelled'::text)))),
    CONSTRAINT external_connection_verifications_request_bounded CHECK (((request_id = btrim(request_id)) AND ((char_length(request_id) >= 1) AND (char_length(request_id) <= 200)))),
    CONSTRAINT external_connection_verifications_result_shape CHECK (((duration_ms IS NULL) OR ((duration_ms >= 0) AND (duration_ms <= 20000)))),
    CONSTRAINT external_connection_verifications_revision_positive CHECK ((connection_revision_number > 0))
);

