--
-- Name: external_connections; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.external_connections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    provider app.external_connection_provider NOT NULL,
    display_name text NOT NULL,
    endpoint_host text NOT NULL,
    endpoint_port integer DEFAULT 5432 NOT NULL,
    database_name text NOT NULL,
    allowed_schemas text[] NOT NULL,
    read_only boolean DEFAULT true NOT NULL,
    tls_mode app.external_connection_tls_mode DEFAULT 'verify_full'::app.external_connection_tls_mode NOT NULL,
    network_mode app.external_connection_network_mode DEFAULT 'public_internet'::app.external_connection_network_mode NOT NULL,
    secret_arn text NOT NULL,
    configured_secret_fields text[] NOT NULL,
    status app.external_connection_status DEFAULT 'configuration_valid'::app.external_connection_status NOT NULL,
    current_revision_number bigint DEFAULT 1 NOT NULL,
    last_verified_at timestamp with time zone,
    schema_fingerprint_sha256 text,
    sanitized_error_code text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT external_connections_database_name_safe CHECK ((database_name ~ '^[A-Za-z_][A-Za-z0-9_$]{0,62}$'::text)),
    CONSTRAINT external_connections_display_name_bounded CHECK (((display_name = btrim(display_name)) AND ((char_length(display_name) >= 1) AND (char_length(display_name) <= 200)))),
    CONSTRAINT external_connections_endpoint_public_dns_shape CHECK (((endpoint_host = lower(endpoint_host)) AND ((char_length(endpoint_host) >= 4) AND (char_length(endpoint_host) <= 253)) AND (endpoint_host ~ '^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$'::text) AND (endpoint_host !~ '(^localhost$|\.localhost$|\.local$|\.internal$|\.home\.arpa$)'::text) AND (endpoint_host !~ '^[0-9.]+$'::text) AND ((endpoint_port >= 1) AND (endpoint_port <= 65535)))),
    CONSTRAINT external_connections_operational_boundary CHECK (((tls_mode = 'verify_full'::app.external_connection_tls_mode) AND (network_mode = 'public_internet'::app.external_connection_network_mode) AND (current_revision_number >= 1) AND (((status = 'configuration_valid'::app.external_connection_status) AND (last_verified_at IS NULL) AND (schema_fingerprint_sha256 IS NULL) AND (sanitized_error_code IS NULL)) OR ((status = 'credentials_verified'::app.external_connection_status) AND (last_verified_at IS NOT NULL) AND (schema_fingerprint_sha256 IS NULL) AND (sanitized_error_code IS NULL)) OR ((status = 'degraded'::app.external_connection_status) AND (schema_fingerprint_sha256 IS NULL) AND (sanitized_error_code IS NOT NULL)) OR (status = ANY (ARRAY['disabled'::app.external_connection_status, 'revoked'::app.external_connection_status]))))),
    CONSTRAINT external_connections_read_only CHECK (read_only),
    CONSTRAINT external_connections_schemas_safe CHECK (app.external_connection_schemas_are_safe(allowed_schemas)),
    CONSTRAINT external_connections_secret_reference_bounded CHECK (((char_length(secret_arn) >= 40) AND (char_length(secret_arn) <= 512) AND (secret_arn ~ '^arn:aws(?:-us-gov)?:secretsmanager:[a-z0-9-]+:[0-9]{12}:secret:opengeo/[A-Za-z0-9/_+=.@-]+$'::text) AND (configured_secret_fields = ARRAY['password'::text, 'username'::text])))
);

