    capture_scope jsonb NOT NULL,
    output_format app.dataset_format NOT NULL,
    output_content_type text NOT NULL,
    maximum_requests integer NOT NULL,
    maximum_output_bytes bigint NOT NULL,
    estimated_cost_usd numeric(12,6) NOT NULL,
    estimate_checksum_sha256 text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT external_source_copy_estimates_bytes_bounded CHECK (((maximum_output_bytes >= 1) AND (maximum_output_bytes <= 536870912))),
    CONSTRAINT external_source_copy_estimates_checksum_valid CHECK ((estimate_checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT external_source_copy_estimates_cost_bounded CHECK (((estimated_cost_usd >= (0)::numeric) AND (estimated_cost_usd <= (100)::numeric))),
    CONSTRAINT external_source_copy_estimates_expiry_bounded CHECK (((expires_at > created_at) AND (expires_at <= (created_at + '00:30:00'::interval)))),
    CONSTRAINT external_source_copy_estimates_method_known CHECK ((copy_method = ANY (ARRAY['exact_object_copy'::text, 'bounded_map_capture'::text, 'bounded_tile_capture'::text, 'bounded_feature_capture'::text]))),
    CONSTRAINT external_source_copy_estimates_output_known CHECK ((((copy_method = 'exact_object_copy'::text) AND (output_format = 'pmtiles'::app.dataset_format) AND (output_content_type = 'application/vnd.pmtiles'::text)) OR ((copy_method = 'bounded_map_capture'::text) AND (output_format = 'png'::app.dataset_format) AND (output_content_type = 'image/png'::text)) OR ((copy_method = 'bounded_tile_capture'::text) AND (output_format = 'pmtiles'::app.dataset_format) AND (output_content_type = 'application/vnd.pmtiles'::text)) OR ((copy_method = 'bounded_feature_capture'::text) AND (output_format = 'geojson'::app.dataset_format) AND (output_content_type = 'application/geo+json'::text)))),
    CONSTRAINT external_source_copy_estimates_requests_bounded CHECK (((maximum_requests >= 1) AND (maximum_requests <= 4096))),
    CONSTRAINT external_source_copy_estimates_revision_positive CHECK ((source_revision_number > 0)),
    CONSTRAINT external_source_copy_estimates_scope_bounded CHECK (((jsonb_typeof(capture_scope) = 'object'::text) AND (octet_length((capture_scope)::text) <= 8192)))
);

