--
-- Name: external_source_discovery_jobs; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.external_source_discovery_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    source_type text NOT NULL,
    discovery_kind text NOT NULL,
    service_url text NOT NULL,
    collection_ref text,
    request_checksum_sha256 text NOT NULL,
    idempotency_key uuid NOT NULL,
    request_id text NOT NULL,
    state app.processing_job_state DEFAULT 'queued'::app.processing_job_state NOT NULL,
    result jsonb,
    error_code text,
    worker_token uuid,
    lease_expires_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    CONSTRAINT external_source_discovery_attempt_bounded CHECK (((attempt_count >= 0) AND (attempt_count <= 3))),
    CONSTRAINT external_source_discovery_collection_shape CHECK ((((discovery_kind = 'catalog'::text) AND (collection_ref IS NULL)) OR ((discovery_kind = 'collection'::text) AND (collection_ref ~ '^[A-Za-z0-9_.:-]{1,200}$'::text) AND ((source_type <> 'arcgis'::text) OR (collection_ref ~ '^(0|[1-9][0-9]{0,4})$'::text))))),
    CONSTRAINT external_source_discovery_error_known CHECK (((error_code IS NULL) OR (error_code = ANY (ARRAY['archive_cancelled'::text, 'archive_timeout'::text, 'destination_unavailable'::text, 'discovery_collection_missing'::text, 'discovery_collection_unsupported'::text, 'discovery_geometry_unsupported'::text, 'discovery_identity_unsupported'::text, 'discovery_no_collections'::text, 'discovery_response_invalid'::text, 'discovery_response_too_large'::text, 'discovery_schema_unsupported'::text, 'discovery_upstream_rejected'::text, 'discovery_version_unsupported'::text, 'dns_resolution_failed'::text, 'redirect_rejected'::text, 'response_invalid'::text, 'response_media_rejected'::text, 'response_too_large'::text, 'retry_exhausted'::text, 'source_contract_invalid'::text, 'tls_verification_failed'::text, 'unsafe_network_target'::text, 'upstream_rejected'::text, 'upstream_unavailable'::text, 'cancelled_by_user'::text])))),
    CONSTRAINT external_source_discovery_kind_known CHECK ((discovery_kind = ANY (ARRAY['catalog'::text, 'collection'::text]))),
    CONSTRAINT external_source_discovery_lease_shape CHECK ((((state = 'running'::app.processing_job_state) AND (worker_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (started_at IS NOT NULL) AND (finished_at IS NULL)) OR ((state <> 'running'::app.processing_job_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT external_source_discovery_request_checksum_valid CHECK ((request_checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT external_source_discovery_request_id_bounded CHECK (((request_id = btrim(request_id)) AND (request_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'::text))),
    CONSTRAINT external_source_discovery_result_shape CHECK ((((state = 'completed'::app.processing_job_state) AND (result IS NOT NULL) AND (error_code IS NULL) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL)) OR ((state <> 'completed'::app.processing_job_state) AND (result IS NULL)))),
    CONSTRAINT external_source_discovery_source_known CHECK ((source_type = ANY (ARRAY['arcgis'::text, 'wfs'::text]))),
    CONSTRAINT external_source_discovery_terminal_shape CHECK ((((state = ANY (ARRAY['queued'::app.processing_job_state, 'running'::app.processing_job_state])) AND (finished_at IS NULL)) OR ((state = 'completed'::app.processing_job_state) AND (finished_at IS NOT NULL) AND (error_code IS NULL)) OR ((state = ANY (ARRAY['failed'::app.processing_job_state, 'cancelled'::app.processing_job_state])) AND (finished_at IS NOT NULL) AND (error_code IS NOT NULL)))),
    CONSTRAINT external_source_discovery_url_bounded CHECK (((service_url = btrim(service_url)) AND ((char_length(service_url) >= 12) AND (char_length(service_url) <= 2048)) AND (service_url ~ '^https://[A-Za-z0-9]'::text) AND (service_url !~ '[?#@[:cntrl:]]'::text) AND ((source_type <> 'arcgis'::text) OR (service_url ~ '/(FeatureServer|MapServer)/?$'::text))))
);

