    CONSTRAINT external_source_snapshot_error_bounded CHECK (((error_code IS NULL) OR ((error_code ~ '^[a-z0-9]+(?:[._-][a-z0-9]+)*$'::text) AND (char_length(error_code) <= 100)))),
    CONSTRAINT external_source_snapshot_lease_shape CHECK ((((state = 'running'::app.processing_job_state) AND (worker_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (last_heartbeat_at IS NOT NULL) AND (started_at IS NOT NULL) AND (finished_at IS NULL)) OR ((state <> 'running'::app.processing_job_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (last_heartbeat_at IS NULL)))),
    CONSTRAINT external_source_snapshot_request_checksum_valid CHECK ((request_checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
