    CONSTRAINT external_source_snapshot_result_shape CHECK ((((state = 'completed'::app.processing_job_state) AND (output_object_id IS NOT NULL) AND (output_dataset_version_id IS NOT NULL) AND (error_code IS NULL) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL)) OR ((state <> 'completed'::app.processing_job_state) AND (output_object_id IS NULL) AND (output_dataset_version_id IS NULL)))),
    CONSTRAINT external_source_snapshot_rights_bounded CHECK (((rights_basis = btrim(rights_basis)) AND ((char_length(rights_basis) >= 1) AND (char_length(rights_basis) <= 500)) AND (attribution = btrim(attribution)) AND ((char_length(attribution) >= 1) AND (char_length(attribution) <= 1000)))),
    CONSTRAINT external_source_snapshot_terminal_shape CHECK ((((state = ANY (ARRAY['queued'::app.processing_job_state, 'running'::app.processing_job_state])) AND (finished_at IS NULL)) OR ((state = 'completed'::app.processing_job_state) AND (finished_at IS NOT NULL) AND (error_code IS NULL)) OR ((state = ANY (ARRAY['failed'::app.processing_job_state, 'cancelled'::app.processing_job_state])) AND (finished_at IS NOT NULL) AND (error_code IS NOT NULL))))
);

