    request_id text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT field_submission_events_initial_shape CHECK ((((submission_version = 1) AND (from_state IS NULL) AND (to_state = 'submitted'::app.field_submission_state)) OR ((submission_version > 1) AND (from_state IS NOT NULL)))),
    CONSTRAINT field_submission_events_message_bound CHECK (((message IS NULL) OR ((char_length(message) >= 1) AND (char_length(message) <= 2000)))),
    CONSTRAINT field_submission_events_request_id_bound CHECK (((char_length(request_id) >= 1) AND (char_length(request_id) <= 128))),
    CONSTRAINT field_submission_events_version_positive CHECK ((submission_version > 0))
);

