--
-- Name: field_submissions; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.field_submissions (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    dataset_id uuid NOT NULL,
    form_id uuid NOT NULL,
    form_version bigint NOT NULL,
    supersedes_submission_id uuid,
    payload_sha256 text NOT NULL,
    geometry_type app.feature_geometry_type NOT NULL,
    properties jsonb NOT NULL,
    geometry_geojson jsonb NOT NULL,
    geometry public.geometry(Geometry,4326) NOT NULL,
    state app.field_submission_state DEFAULT 'submitted'::app.field_submission_state NOT NULL,
    review_version bigint DEFAULT 1 NOT NULL,
    submitted_by uuid NOT NULL,
    submitted_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    review_message text,
    promoted_feature_id uuid,
    operation app.field_submission_operation DEFAULT 'create'::app.field_submission_operation NOT NULL,
    target_feature_id uuid,
    target_feature_version bigint,
    CONSTRAINT field_submissions_geojson_object CHECK (((jsonb_typeof(geometry_geojson) = 'object'::text) AND ((geometry_geojson ->> 'type'::text) = (geometry_type)::text) AND (jsonb_typeof((geometry_geojson -> 'coordinates'::text)) = 'array'::text) AND (pg_column_size(geometry_geojson) <= 262144))),
    CONSTRAINT field_submissions_geometry_safe CHECK (((public.st_srid(geometry) = 4326) AND (public.st_ndims(geometry) = 2) AND (NOT public.st_isempty(geometry)) AND public.st_isvalid(geometry))),
    CONSTRAINT field_submissions_geometry_type_match CHECK ((lower(public.geometrytype(geometry)) = lower((geometry_type)::text))),
    CONSTRAINT field_submissions_operation_shape CHECK ((((operation = 'create'::app.field_submission_operation) AND (target_feature_id IS NULL) AND (target_feature_version IS NULL)) OR ((operation = 'update'::app.field_submission_operation) AND (target_feature_id IS NOT NULL) AND (target_feature_version IS NOT NULL)))),
    CONSTRAINT field_submissions_payload_sha256 CHECK (((payload_sha256 = lower(payload_sha256)) AND (payload_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT field_submissions_properties_object CHECK (((jsonb_typeof(properties) = 'object'::text) AND (pg_column_size(properties) <= 32768))),
    CONSTRAINT field_submissions_review_message_bound CHECK (((review_message IS NULL) OR ((char_length(review_message) >= 1) AND (char_length(review_message) <= 2000)))),
    CONSTRAINT field_submissions_review_shape CHECK ((((state = 'submitted'::app.field_submission_state) AND (reviewed_by IS NULL) AND (reviewed_at IS NULL) AND (review_message IS NULL) AND (promoted_feature_id IS NULL)) OR ((state = 'in_review'::app.field_submission_state) AND (reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL) AND (review_message IS NULL) AND (promoted_feature_id IS NULL)) OR ((state = ANY (ARRAY['changes_requested'::app.field_submission_state, 'rejected'::app.field_submission_state])) AND (reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL) AND (review_message IS NOT NULL) AND (promoted_feature_id IS NULL)) OR ((state = 'accepted'::app.field_submission_state) AND (reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL) AND (promoted_feature_id =
CASE
    WHEN (operation = 'create'::app.field_submission_operation) THEN id
    ELSE target_feature_id
END)))),
    CONSTRAINT field_submissions_review_version_positive CHECK ((review_version > 0)),
    CONSTRAINT field_submissions_target_version_positive CHECK (((target_feature_version IS NULL) OR (target_feature_version > 0)))
);

ALTER TABLE ONLY app.field_submissions FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE field_submissions; Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON TABLE app.field_submissions IS 'Idempotent quarantined create or exact-base update observations; acceptance alone mutates authoritative features.';


