    first_seen_at timestamp with time zone NOT NULL,
    last_refreshed_at timestamp with time zone NOT NULL,
    withdrawn_at timestamp with time zone,
    CONSTRAINT geonode_federated_freshness_ordered CHECK ((last_refreshed_at >= first_seen_at)),
    CONSTRAINT geonode_federated_payload_checksum_valid CHECK ((current_payload_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT geonode_federated_remote_identifier_uuid CHECK ((remote_identifier ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text)),
    CONSTRAINT geonode_federated_status_known CHECK ((status = ANY (ARRAY['current'::text, 'withdrawn'::text]))),
    CONSTRAINT geonode_federated_title_bounded CHECK (((title = btrim(title)) AND ((char_length(title) >= 1) AND (char_length(title) <= 500)) AND (title !~ '[[:cntrl:]]'::text))),
    CONSTRAINT geonode_federated_type_known CHECK ((resource_type = ANY (ARRAY['dataset'::text, 'document'::text, 'map'::text, 'geoapp'::text, 'service'::text]))),
    CONSTRAINT geonode_federated_version_positive CHECK ((current_version_number > 0)),
    CONSTRAINT geonode_federated_withdrawn_shape CHECK ((((status = 'current'::text) AND (withdrawn_at IS NULL)) OR ((status = 'withdrawn'::text) AND (withdrawn_at IS NOT NULL))))
);

