    CONSTRAINT geonode_federated_history_payload_shape CHECK ((((action = ANY (ARRAY['added'::text, 'updated'::text])) AND (jsonb_typeof(payload) = 'object'::text)) OR ((action = 'withdrawn'::text) AND (payload IS NULL)))),
    CONSTRAINT geonode_federated_history_version_positive CHECK ((version_number > 0))
);

