    disabled_at timestamp with time zone,
    CONSTRAINT geonode_federation_anonymous_only CHECK ((credential_mode = 'anonymous'::text)),
    CONSTRAINT geonode_federation_configuration_checksum_valid CHECK ((configuration_checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT geonode_federation_disabled_shape CHECK ((((status = 'active'::text) AND (disabled_at IS NULL)) OR ((status = 'disabled'::text) AND (disabled_at IS NOT NULL)))),
    CONSTRAINT geonode_federation_fingerprint_valid CHECK ((source_fingerprint_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT geonode_federation_name_bounded CHECK (((display_name = btrim(display_name)) AND ((char_length(display_name) >= 1) AND (char_length(display_name) <= 100)) AND (display_name !~ '[[:cntrl:]]'::text))),
    CONSTRAINT geonode_federation_refresh_bounded CHECK (((refresh_interval_minutes >= 60) AND (refresh_interval_minutes <= 10080))),
    CONSTRAINT geonode_federation_resources_bounded CHECK (((maximum_resources >= 1) AND (maximum_resources <= 100))),
    CONSTRAINT geonode_federation_status_known CHECK ((status = ANY (ARRAY['active'::text, 'disabled'::text]))),
    CONSTRAINT geonode_federation_url_bounded CHECK (((remote_url = btrim(remote_url)) AND ((char_length(remote_url) >= 12) AND (char_length(remote_url) <= 2048)) AND (remote_url ~ '^https://[a-z0-9]'::text) AND (remote_url !~ '[?#@[:space:][:cntrl:]]'::text) AND (remote_url !~ '/$'::text) AND (remote_url !~ '^https://localhost(?::[0-9]+)?(?:/|$)'::text) AND (remote_url !~ '^https://[^/]+\.local(?::[0-9]+)?(?:/|$)'::text))),
    CONSTRAINT geonode_federation_version_exact CHECK ((source_version = '5.1.0'::text))
);

