--

CREATE TABLE app.geonode_harvest_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    source_id uuid NOT NULL,
    source_configuration_checksum_sha256 text NOT NULL,
    request_checksum_sha256 text NOT NULL,
    idempotency_key uuid NOT NULL,
    request_id text NOT NULL,
    state app.processing_job_state DEFAULT 'queued'::app.processing_job_state NOT NULL,
    result jsonb,
    error_code text,
    worker_token uuid,
    lease_expires_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    CONSTRAINT geonode_harvest_attempt_bounded CHECK (((attempt_count >= 0) AND (attempt_count <= 3))),
    CONSTRAINT geonode_harvest_configuration_checksum_valid CHECK ((source_configuration_checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT geonode_harvest_error_known CHECK (((error_code IS NULL) OR (error_code = ANY (ARRAY['cancelled_by_user'::text, 'dns_resolution_failed'::text, 'geonode_harvest_identity_collision'::text, 'geonode_harvest_identity_invalid'::text, 'geonode_harvest_local_identity_collision'::text, 'geonode_harvest_response_invalid'::text, 'geonode_harvest_response_too_large'::text, 'geonode_harvest_response_unsafe'::text, 'geonode_harvest_timestamp_invalid'::text, 'geonode_harvest_total_invalid'::text, 'geonode_harvest_type_unsupported'::text, 'geonode_harvest_upstream_unavailable'::text, 'response_media_rejected'::text, 'retry_exhausted'::text, 'tls_verification_failed'::text, 'unsafe_network_target'::text, 'upstream_rejected'::text])))),
    CONSTRAINT geonode_harvest_lease_shape CHECK ((((state = 'running'::app.processing_job_state) AND (worker_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (started_at IS NOT NULL) AND (finished_at IS NULL)) OR ((state <> 'running'::app.processing_job_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT geonode_harvest_request_checksum_valid CHECK ((request_checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT geonode_harvest_request_id_bounded CHECK (((request_id = btrim(request_id)) AND (request_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'::text))),
    CONSTRAINT geonode_harvest_result_shape CHECK ((((state = 'completed'::app.processing_job_state) AND (result IS NOT NULL) AND (error_code IS NULL) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL)) OR ((state <> 'completed'::app.processing_job_state) AND (result IS NULL)))),
    CONSTRAINT geonode_harvest_terminal_shape CHECK ((((state = ANY (ARRAY['queued'::app.processing_job_state, 'running'::app.processing_job_state])) AND (finished_at IS NULL)) OR ((state = 'completed'::app.processing_job_state) AND (finished_at IS NOT NULL) AND (error_code IS NULL)) OR ((state = ANY (ARRAY['failed'::app.processing_job_state, 'cancelled'::app.processing_job_state])) AND (finished_at IS NOT NULL) AND (error_code IS NOT NULL))))
);

