-- Name: governed_resource_versions; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.governed_resource_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    resource_id uuid NOT NULL,
    version_number bigint NOT NULL,
    title text NOT NULL,
    abstract text,
    language text DEFAULT 'en'::text NOT NULL,
    license text,
    attribution text,
    keywords text[] DEFAULT ARRAY[]::text[] NOT NULL,
    spatial_extent jsonb,
    temporal_start timestamp with time zone,
    temporal_end timestamp with time zone,
    metadata_profile text DEFAULT 'opengeo.core.v1'::text NOT NULL,
    metadata_extensions jsonb DEFAULT '{}'::jsonb NOT NULL,
    content jsonb DEFAULT '{"blocks": []}'::jsonb NOT NULL,
    provenance jsonb DEFAULT '{}'::jsonb NOT NULL,
    change_message text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    metadata_profile_id uuid,
    metadata_profile_version_id uuid,
    metadata_validation jsonb,
    localized_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    search_document tsvector GENERATED ALWAYS AS ((to_tsvector('simple'::regconfig, ((COALESCE(title, ''::text) || ' '::text) || COALESCE(abstract, ''::text))) || jsonb_to_tsvector('simple'::regconfig, localized_metadata, '["string"]'::jsonb))) STORED,
    CONSTRAINT governed_resource_versions_abstract_bounded CHECK (((abstract IS NULL) OR ((char_length(abstract) >= 1) AND (char_length(abstract) <= 8000)))),
    CONSTRAINT governed_resource_versions_change_bounded CHECK (((change_message IS NULL) OR ((char_length(change_message) >= 1) AND (char_length(change_message) <= 500)))),
    CONSTRAINT governed_resource_versions_documents_bounded CHECK (((jsonb_typeof(metadata_extensions) = 'object'::text) AND (octet_length((metadata_extensions)::text) <= 8192) AND (jsonb_typeof(content) = 'object'::text) AND (octet_length((content)::text) <= 16384) AND (jsonb_typeof(provenance) = 'object'::text) AND (octet_length((provenance)::text) <= 4096))),
