    CONSTRAINT map_render_jobs_error_bounded CHECK (((error_code IS NULL) OR ((error_code ~ '^[a-z0-9]+(?:[._-][a-z0-9]+)*$'::text) AND (char_length(error_code) <= 100)))),
    CONSTRAINT map_render_jobs_request_id_bounded CHECK ((request_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'::text)),
    CONSTRAINT map_render_jobs_state_shape CHECK ((((state = 'queued'::app.map_render_job_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (last_heartbeat_at IS NULL) AND (output_object_id IS NULL) AND (started_at IS NULL) AND (finished_at IS NULL)) OR ((state = 'running'::app.map_render_job_state) AND (worker_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (last_heartbeat_at IS NOT NULL) AND (output_object_id IS NULL) AND (started_at IS NOT NULL) AND (finished_at IS NULL)) OR ((state = 'completed'::app.map_render_job_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (last_heartbeat_at IS NULL) AND (output_object_id IS NOT NULL) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL) AND (error_code IS NULL)) OR ((state = ANY (ARRAY['failed'::app.map_render_job_state, 'cancelled'::app.map_render_job_state])) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (last_heartbeat_at IS NULL) AND (output_object_id IS NULL) AND (finished_at IS NOT NULL))))
);

