    CONSTRAINT pmtiles_derivative_attempt_bounded CHECK (((attempt_count >= 0) AND (attempt_count <= 3))),
    CONSTRAINT pmtiles_derivative_bounds_valid CHECK (((jsonb_typeof(bounds) = 'array'::text) AND (jsonb_array_length(bounds) = 4) AND (jsonb_typeof((bounds -> 0)) = 'number'::text) AND (jsonb_typeof((bounds -> 1)) = 'number'::text) AND (jsonb_typeof((bounds -> 2)) = 'number'::text) AND (jsonb_typeof((bounds -> 3)) = 'number'::text) AND ((((bounds ->> 0))::numeric >= ('-180'::integer)::numeric) AND (((bounds ->> 0))::numeric <= (180)::numeric)) AND ((((bounds ->> 1))::numeric >= ('-90'::integer)::numeric) AND (((bounds ->> 1))::numeric <= (90)::numeric)) AND ((((bounds ->> 2))::numeric >= ('-180'::integer)::numeric) AND (((bounds ->> 2))::numeric <= (180)::numeric)) AND ((((bounds ->> 3))::numeric >= ('-90'::integer)::numeric) AND (((bounds ->> 3))::numeric <= (90)::numeric)) AND (((bounds ->> 0))::numeric < ((bounds ->> 2))::numeric) AND (((bounds ->> 1))::numeric < ((bounds ->> 3))::numeric))),
