    CONSTRAINT pmtiles_derivative_layer_bounded CHECK (((source_layer = btrim(source_layer)) AND ((char_length(source_layer) >= 1) AND (char_length(source_layer) <= 200)) AND (source_layer !~ '[[:cntrl:]]'::text))),
