    CONSTRAINT pmtiles_derivative_request_id_bounded CHECK (((request_id = btrim(request_id)) AND ((char_length(request_id) >= 1) AND (char_length(request_id) <= 200)))),
    CONSTRAINT pmtiles_derivative_result_shape CHECK ((((state = 'completed'::app.processing_job_state) AND (output_object_id IS NOT NULL) AND (output_size_bytes IS NOT NULL) AND (output_checksum_sha256 ~ '^[0-9a-f]{64}$'::text) AND (error_code IS NULL) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL)) OR ((state <> 'completed'::app.processing_job_state) AND (output_object_id IS NULL) AND (output_size_bytes IS NULL) AND (output_checksum_sha256 IS NULL)))),
    CONSTRAINT pmtiles_derivative_terminal_shape CHECK ((((state = ANY (ARRAY['queued'::app.processing_job_state, 'running'::app.processing_job_state])) AND (finished_at IS NULL)) OR ((state = 'completed'::app.processing_job_state) AND (finished_at IS NOT NULL) AND (error_code IS NULL)) OR ((state = ANY (ARRAY['failed'::app.processing_job_state, 'cancelled'::app.processing_job_state])) AND (finished_at IS NOT NULL) AND (error_code IS NOT NULL)))),
    CONSTRAINT pmtiles_derivative_zoom_bounded CHECK (((minimum_zoom >= 0) AND (minimum_zoom <= 22) AND ((maximum_zoom >= minimum_zoom) AND (maximum_zoom <= 22))))
);

