    output_object_id uuid NOT NULL,
    output_checksum_sha256 text NOT NULL,
    software jsonb NOT NULL,
    logs jsonb NOT NULL,
    verification_status text NOT NULL,
    receipt_checksum_sha256 text NOT NULL,
    initiated_by uuid NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT processing_execution_receipt_checksum_matches CHECK ((receipt_checksum_sha256 = app.processing_execution_receipt_checksum(job_kind, coverage_job_id, pmtiles_job_id, tool_id, tool_version, request_checksum_sha256, source_object_id, output_object_id, output_checksum_sha256, software, logs, verification_status))),
    CONSTRAINT processing_execution_receipt_checksums_valid CHECK (((request_checksum_sha256 ~ '^[0-9a-f]{64}$'::text) AND (output_checksum_sha256 ~ '^[0-9a-f]{64}$'::text) AND (receipt_checksum_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT processing_execution_receipt_job_shape CHECK ((((job_kind = 'coverage-derivative'::text) AND (coverage_job_id IS NOT NULL) AND (pmtiles_job_id IS NULL) AND (tool_id = 'raster-to-cog'::text)) OR ((job_kind = 'pmtiles-derivative'::text) AND (coverage_job_id IS NULL) AND (pmtiles_job_id IS NOT NULL) AND (tool_id = 'vector-to-pmtiles'::text)))),
    CONSTRAINT processing_execution_receipt_logs_valid CHECK (app.processing_receipt_logs_valid(logs)),
    CONSTRAINT processing_execution_receipt_software_bounded CHECK (((jsonb_typeof(software) = 'object'::text) AND (octet_length((software)::text) <= 8192) AND (((verification_status = 'pinned'::text) AND ((software ->> 'workerBaseImage'::text) = 'ghcr.io/osgeo/gdal:ubuntu-full-3.13.0@sha256:83d114a6891ae18aa175d81a14c92a96d23944667b36fde9c15c4a10215d8939'::text) AND ((software ->> 'gdal'::text) = '3.13.0'::text) AND ((software ->> 'projNetwork'::text) = 'disabled'::text) AND ((job_kind <> 'pmtiles-derivative'::text) OR ((software ->> 'tippecanoe'::text) = '2.79.0'::text))) OR ((verification_status = 'legacy-unverified'::text) AND ((software ->> 'verification'::text) = 'legacy-unverified'::text))))),
    CONSTRAINT processing_execution_receipt_version_bounded CHECK (((tool_version ~ '^[0-9]+\.[0-9]+\.[0-9]+$'::text) AND (char_length(tool_version) <= 40)))
);

