CREATE TABLE app.project_discussions (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    project_id uuid NOT NULL,
    initial_comment_id uuid NOT NULL,
    title text NOT NULL,
    state app.project_discussion_state DEFAULT 'open'::app.project_discussion_state NOT NULL,
    version_number integer DEFAULT 1 NOT NULL,
    created_by uuid NOT NULL,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    target_kind app.project_discussion_target_kind DEFAULT 'project'::app.project_discussion_target_kind NOT NULL,
