    target_map_version bigint,
    target_layer_id text,
    target_dataset_id uuid,
    target_feature_id uuid,
    target_object_id uuid,
    target_object_version bigint,
    assigned_to uuid,
    assigned_by uuid,
    assigned_at timestamp with time zone,
    CONSTRAINT project_discussions_assignment_consistent CHECK ((((assigned_to IS NULL) AND (assigned_by IS NULL) AND (assigned_at IS NULL)) OR ((assigned_to IS NOT NULL) AND (assigned_by IS NOT NULL) AND (assigned_at IS NOT NULL)))),
    CONSTRAINT project_discussions_resolution_consistent CHECK ((((state = 'open'::app.project_discussion_state) AND (resolved_by IS NULL) AND (resolved_at IS NULL)) OR ((state = 'resolved'::app.project_discussion_state) AND (resolved_by IS NOT NULL) AND (resolved_at IS NOT NULL)))),
    CONSTRAINT project_discussions_target_layer_id_bounded CHECK (((target_layer_id IS NULL) OR ((char_length(target_layer_id) >= 1) AND (char_length(target_layer_id) <= 160) AND (target_layer_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'::text)))),
    CONSTRAINT project_discussions_target_map_version_positive CHECK (((target_map_version IS NULL) OR (target_map_version > 0))),
    CONSTRAINT project_discussions_target_object_version_positive CHECK (((target_object_version IS NULL) OR (target_object_version > 0))),
    CONSTRAINT project_discussions_target_shape CHECK ((((target_kind = 'project'::app.project_discussion_target_kind) AND (target_map_id IS NULL) AND (target_map_version IS NULL) AND (target_layer_id IS NULL) AND (target_dataset_id IS NULL) AND (target_feature_id IS NULL) AND (target_object_id IS NULL) AND (target_object_version IS NULL)) OR ((target_kind = 'feature'::app.project_discussion_target_kind) AND (target_map_id IS NOT NULL) AND (target_map_version IS NOT NULL) AND (target_layer_id IS NOT NULL) AND (target_dataset_id IS NOT NULL) AND (target_feature_id IS NOT NULL) AND (target_object_id IS NULL) AND (target_object_version IS NULL)) OR ((target_kind = ANY (ARRAY['map'::app.project_discussion_target_kind, 'dataset'::app.project_discussion_target_kind, 'resource'::app.project_discussion_target_kind, 'site'::app.project_discussion_target_kind])) AND (target_map_id IS NULL) AND (target_map_version IS NULL) AND (target_layer_id IS NULL) AND (target_dataset_id IS NULL) AND (target_feature_id IS NULL) AND (target_object_id IS NOT NULL) AND (target_object_version IS NOT NULL)))),
    CONSTRAINT project_discussions_title_bounded CHECK (((title = btrim(title)) AND ((char_length(title) >= 1) AND (char_length(title) <= 200)) AND (octet_length(title) <= 800))),
    CONSTRAINT project_discussions_version_positive CHECK (((version_number >= 1) AND (version_number <= 2147483647)))
);

