    publication_reach app.project_site_publication_reach DEFAULT 'listed'::app.project_site_publication_reach NOT NULL,
    listed_slug text,
    unlisted_token text,
    is_primary boolean DEFAULT false NOT NULL,
    CONSTRAINT project_site_editions_manifest_bounded CHECK (((jsonb_typeof(manifest) = 'object'::text) AND (octet_length((manifest)::text) <= 131072) AND (jsonb_typeof((manifest -> 'references'::text)) = 'array'::text) AND (jsonb_array_length((manifest -> 'references'::text)) <= 128) AND (manifest_checksum_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT project_site_editions_numbers_positive CHECK (((site_version_number > 0) AND (edition_number > 0))),
    CONSTRAINT project_site_editions_primary_listed CHECK (((NOT is_primary) OR (publication_reach = 'listed'::app.project_site_publication_reach))),
    CONSTRAINT project_site_editions_publication_destination_shape CHECK ((((publication_reach = 'unpublished'::app.project_site_publication_reach) AND (listed_slug IS NULL) AND (unlisted_token IS NULL) AND (NOT is_primary)) OR ((publication_reach = 'unlisted'::app.project_site_publication_reach) AND (listed_slug IS NULL) AND (unlisted_token ~ '^[0-9a-f]{32}$'::text) AND (NOT is_primary)) OR ((publication_reach = 'listed'::app.project_site_publication_reach) AND (listed_slug ~ '^[a-z0-9](?:[a-z0-9-]{0,158}[a-z0-9])?$'::text) AND (unlisted_token IS NULL)))),
    CONSTRAINT project_site_editions_revocation_shape CHECK ((((revoked_by IS NULL) AND (revoked_at IS NULL)) OR ((revoked_by IS NOT NULL) AND (revoked_at IS NOT NULL) AND (revoked_at >= published_at))))
);

