    attribution text NOT NULL,
    request_checksum_sha256 text NOT NULL,
    idempotency_key uuid NOT NULL,
    request_id text NOT NULL,
    state app.processing_job_state DEFAULT 'queued'::app.processing_job_state NOT NULL,
    output_object_id uuid,
    output_dataset_version_id uuid,
    error_code text,
    worker_token uuid,
    lease_expires_at timestamp with time zone,
    last_heartbeat_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    CONSTRAINT repository_copy_job_attempt_bounded CHECK (((attempt_count >= 0) AND (attempt_count <= 3))),
    CONSTRAINT repository_copy_job_bucket_bounded CHECK (((char_length(destination_bucket) >= 3) AND (char_length(destination_bucket) <= 63) AND (destination_bucket ~ '^[a-z0-9][a-z0-9.-]+[a-z0-9]$'::text))),
    CONSTRAINT repository_copy_job_error_bounded CHECK (((error_code IS NULL) OR ((error_code ~ '^[a-z0-9]+(?:[._-][a-z0-9]+)*$'::text) AND (char_length(error_code) <= 100)))),
    CONSTRAINT repository_copy_job_lease_shape CHECK ((((state = 'running'::app.processing_job_state) AND (worker_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (last_heartbeat_at IS NOT NULL) AND (started_at IS NOT NULL) AND (finished_at IS NULL)) OR ((state <> 'running'::app.processing_job_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (last_heartbeat_at IS NULL)))),
    CONSTRAINT repository_copy_job_request_checksum_valid CHECK ((request_checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT repository_copy_job_request_id_bounded CHECK (((request_id = btrim(request_id)) AND ((char_length(request_id) >= 1) AND (char_length(request_id) <= 128)) AND (request_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'::text))),
    CONSTRAINT repository_copy_job_result_shape CHECK ((((state = 'completed'::app.processing_job_state) AND (output_object_id IS NOT NULL) AND (output_dataset_version_id IS NOT NULL) AND (error_code IS NULL) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL)) OR ((state <> 'completed'::app.processing_job_state) AND (output_object_id IS NULL) AND (output_dataset_version_id IS NULL)))),
    CONSTRAINT repository_copy_job_rights_bounded CHECK (((rights_basis = btrim(rights_basis)) AND ((char_length(rights_basis) >= 1) AND (char_length(rights_basis) <= 500)) AND (attribution = btrim(attribution)) AND ((char_length(attribution) >= 1) AND (char_length(attribution) <= 1000)))),
    CONSTRAINT repository_copy_job_terminal_shape CHECK ((((state = ANY (ARRAY['queued'::app.processing_job_state, 'running'::app.processing_job_state])) AND (finished_at IS NULL)) OR ((state = 'completed'::app.processing_job_state) AND (finished_at IS NOT NULL) AND (error_code IS NULL)) OR ((state = ANY (ARRAY['failed'::app.processing_job_state, 'cancelled'::app.processing_job_state])) AND (finished_at IS NOT NULL) AND (error_code IS NOT NULL))))
);

