--
-- Name: repository_object_sources; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.repository_object_sources (
    organization_id uuid NOT NULL,
    dataset_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    connection_target_revision bigint NOT NULL,
    provider app.dataset_connection_provider NOT NULL,
    bucket_name text NOT NULL,
    region_name text NOT NULL,
    object_prefix text NOT NULL,
    relative_path text NOT NULL,
    provider_version_id text NOT NULL,
    size_bytes bigint NOT NULL,
    last_modified timestamp with time zone NOT NULL,
    content_type text,
    etag text NOT NULL,
    storage_class text,
    provider_checksum_sha256 text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT repository_object_sources_bucket_snapshot_safe CHECK (((bucket_name = lower(bucket_name)) AND ((char_length(bucket_name) >= 3) AND (char_length(bucket_name) <= 63)) AND (bucket_name ~ '^[a-z0-9][a-z0-9.-]*[a-z0-9]$'::text) AND (bucket_name !~ '(\.\.|\.-|-\.)'::text) AND (bucket_name !~ '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$'::text))),
    CONSTRAINT repository_object_sources_checksum_sha256_valid CHECK (((provider_checksum_sha256 IS NULL) OR (provider_checksum_sha256 ~ '^[A-Za-z0-9+/]{43}=$'::text))),
    CONSTRAINT repository_object_sources_content_type_bounded CHECK (((content_type IS NULL) OR ((octet_length(content_type) >= 1) AND (octet_length(content_type) <= 255) AND (content_type !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT repository_object_sources_etag_bounded CHECK (((octet_length(etag) >= 1) AND (octet_length(etag) <= 1024) AND (etag !~ '[[:cntrl:]]'::text))),
    CONSTRAINT repository_object_sources_exact_version_required CHECK (((octet_length(provider_version_id) >= 1) AND (octet_length(provider_version_id) <= 1024) AND (provider_version_id <> 'null'::text) AND (provider_version_id !~ '[[:cntrl:]]'::text))),
    CONSTRAINT repository_object_sources_object_nonempty CHECK (((size_bytes >= 1) AND (size_bytes <= '5497558138880'::bigint))),
    CONSTRAINT repository_object_sources_prefix_snapshot_safe CHECK (((octet_length(object_prefix) <= 1024) AND (object_prefix !~ '^[\\/]'::text) AND (object_prefix !~ '[\\[:cntrl:]]'::text))),
    CONSTRAINT repository_object_sources_region_snapshot_safe CHECK (((region_name = lower(region_name)) AND ((char_length(region_name) >= 3) AND (char_length(region_name) <= 32)) AND (region_name ~ '^[a-z]{2}(?:-gov)?-[a-z0-9-]+-[0-9]+$'::text))),
    CONSTRAINT repository_object_sources_relative_path_safe CHECK (((octet_length(relative_path) >= 1) AND (octet_length(relative_path) <= 1024) AND (relative_path !~ '^[\\/]'::text) AND (relative_path !~ '[\\[:cntrl:]]'::text) AND (relative_path !~ '(^|/)\.\.?(/|$)'::text) AND ("right"(relative_path, 1) <> '/'::text) AND (octet_length((object_prefix || relative_path)) <= 1024))),
    CONSTRAINT repository_object_sources_s3_only CHECK ((provider = 's3'::app.dataset_connection_provider)),
    CONSTRAINT repository_object_sources_storage_class_bounded CHECK (((storage_class IS NULL) OR ((octet_length(storage_class) >= 1) AND (octet_length(storage_class) <= 100) AND (storage_class ~ '^[A-Z0-9_-]+$'::text)))),
    CONSTRAINT repository_object_sources_target_revision_positive CHECK ((connection_target_revision > 0))
);

ALTER TABLE ONLY app.repository_object_sources FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE repository_object_sources; Type: COMMENT; Schema: app; Owner: -
--

