    CONSTRAINT spatial_coverage_derivatives_lease_shape CHECK ((((state = 'running'::app.processing_job_state) AND (worker_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (last_heartbeat_at IS NOT NULL) AND (started_at IS NOT NULL) AND (finished_at IS NULL)) OR ((state <> 'running'::app.processing_job_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (last_heartbeat_at IS NULL)))),
    CONSTRAINT spatial_coverage_derivatives_request_checksum CHECK ((request_checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
