    CONSTRAINT spatial_tile_cache_reclamation_item_target_shape CHECK (((sealed_bucket <> ''::text) AND (sealed_object_key ~ '^organizations/[0-9a-f-]{36}/projects/[0-9a-f-]{36}/datasets/[0-9a-f-]{36}/versions/[0-9a-f-]{36}/derivatives/renders/[0-9a-f-]{36}\.(svg|png)$'::text) AND (sealed_storage_version_id <> ALL (ARRAY[''::text, 'null'::text])) AND (sealed_etag ~ '^[A-Fa-f0-9]{16,128}$'::text) AND (sealed_content_type = ANY (ARRAY['image/svg+xml'::text, 'image/png'::text])) AND ((sealed_size_bytes >= 1) AND (sealed_size_bytes <= 20971520)) AND (sealed_checksum_sha256 ~ '^[0-9a-f]{64}$'::text)))
);

