    CONSTRAINT user_dataset_connection_verifications_objects_bounded CHECK (((objects_observed >= 0) AND (objects_observed <= 1))),
    CONSTRAINT user_dataset_connection_verifications_request_bounded CHECK (((request_id = btrim(request_id)) AND ((char_length(request_id) >= 1) AND (char_length(request_id) <= 200)))),
    CONSTRAINT user_dataset_connection_verifications_result_shape CHECK ((((state = 'queued'::app.user_dataset_verification_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (started_at IS NULL) AND (finished_at IS NULL) AND (sanitized_error_code IS NULL) AND (duration_ms IS NULL) AND (NOT bucket_access_confirmed) AND (NOT object_access_confirmed) AND (NOT deny_canaries_confirmed) AND (objects_observed = 0)) OR ((state = 'running'::app.user_dataset_verification_state) AND (worker_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (started_at IS NOT NULL) AND (finished_at IS NULL) AND (sanitized_error_code IS NULL) AND (duration_ms IS NULL)) OR ((state = 'succeeded'::app.user_dataset_verification_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL) AND (sanitized_error_code IS NULL) AND (duration_ms IS NOT NULL) AND bucket_access_confirmed AND deny_canaries_confirmed AND object_access_confirmed AND (objects_observed = 1)) OR ((state = 'failed'::app.user_dataset_verification_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL) AND (sanitized_error_code IS NOT NULL) AND (duration_ms IS NOT NULL)) OR ((state = 'cancelled'::app.user_dataset_verification_state) AND (worker_token IS NULL) AND (lease_expires_at IS NULL) AND (finished_at IS NOT NULL) AND (sanitized_error_code = 'verification_cancelled'::text)))),
    CONSTRAINT user_dataset_connection_verifications_revision_shape CHECK (((target_revision > 0) AND (credential_revision >= 0)))
);

ALTER TABLE ONLY app.user_dataset_connection_verifications FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE user_dataset_connection_verifications; Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON TABLE app.user_dataset_connection_verifications IS 'Secret-free leased S3 connection verification attempts; object keys and credentials are never persisted.';


--
-- Name: user_dataset_connections; Type: TABLE; Schema: app; Owner: -
--

CREATE TABLE app.user_dataset_connections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    owner_user_id uuid NOT NULL,
    provider app.dataset_connection_provider NOT NULL,
    display_name text NOT NULL,
    bucket_name text NOT NULL,
    region_name text NOT NULL,
    object_prefix text DEFAULT ''::text NOT NULL,
    credential_mode app.dataset_connection_credential_mode NOT NULL,
    role_arn text,
    secret_arn text,
    configured_secret_fields text[] DEFAULT ARRAY[]::text[] NOT NULL,
    credential_revision bigint DEFAULT 0 NOT NULL,
    status app.dataset_connection_status DEFAULT 'draft'::app.dataset_connection_status NOT NULL,
    last_verified_at timestamp with time zone,
    sanitized_error_code text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    target_revision bigint DEFAULT 1 NOT NULL,
    CONSTRAINT user_dataset_connections_name_bounded CHECK (((display_name = btrim(display_name)) AND ((char_length(display_name) >= 1) AND (char_length(display_name) <= 200)))),
    CONSTRAINT user_dataset_connections_prefix_safe CHECK (((octet_length(object_prefix) <= 1024) AND (object_prefix !~ '^[\/]'::text) AND (object_prefix !~ '[\\[:cntrl:]]'::text))),
    CONSTRAINT user_dataset_connections_region_safe CHECK (((region_name = lower(region_name)) AND ((char_length(region_name) >= 3) AND (char_length(region_name) <= 32)) AND (region_name ~ '^[a-z]{2}(?:-gov)?-[a-z0-9-]+-[0-9]+$'::text))),
    CONSTRAINT user_dataset_connections_role_mode CHECK ((((credential_mode = 'assume_role'::app.dataset_connection_credential_mode) AND ((char_length(role_arn) >= 32) AND (char_length(role_arn) <= 2048)) AND (role_arn ~ '^arn:aws(?:-us-gov)?:iam::[0-9]{12}:role/[A-Za-z0-9_+=,.@/-]+$'::text)) OR ((credential_mode <> 'assume_role'::app.dataset_connection_credential_mode) AND (role_arn IS NULL)))),
    CONSTRAINT user_dataset_connections_s3_bucket_safe CHECK (((bucket_name = lower(bucket_name)) AND ((char_length(bucket_name) >= 3) AND (char_length(bucket_name) <= 63)) AND (bucket_name ~ '^[a-z0-9][a-z0-9.-]*[a-z0-9]$'::text) AND (bucket_name !~ '(\.\.|\.-|-\.)'::text) AND (bucket_name !~ '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$'::text))),
    CONSTRAINT user_dataset_connections_secret_reference_safe CHECK ((((secret_arn IS NULL) AND (configured_secret_fields = ARRAY[]::text[]) AND (credential_revision = 0)) OR ((secret_arn ~ '^arn:aws(?:-us-gov)?:secretsmanager:[a-z0-9-]+:[0-9]{12}:secret:opengeo/[A-Za-z0-9/_+=.@-]+$'::text) AND (credential_revision > 0) AND (credential_mode <> 'workload_identity'::app.dataset_connection_credential_mode) AND (((credential_mode = 'assume_role'::app.dataset_connection_credential_mode) AND (configured_secret_fields = ARRAY['external_id'::text])) OR ((credential_mode = 'access_key'::app.dataset_connection_credential_mode) AND ((configured_secret_fields = ARRAY['access_key_id'::text, 'secret_access_key'::text]) OR (configured_secret_fields = ARRAY['access_key_id'::text, 'secret_access_key'::text, 'session_token'::text]))))))),
    CONSTRAINT user_dataset_connections_state_consistent CHECK ((((credential_mode = 'access_key'::app.dataset_connection_credential_mode) AND (secret_arn IS NULL) AND (status = 'draft'::app.dataset_connection_status)) OR ((NOT ((credential_mode = 'access_key'::app.dataset_connection_credential_mode) AND (secret_arn IS NULL))) AND (status <> 'draft'::app.dataset_connection_status)))),
    CONSTRAINT user_dataset_connections_target_revision_positive CHECK ((target_revision > 0)),
    CONSTRAINT user_dataset_connections_verification_consistent CHECK ((((status = 'verified'::app.dataset_connection_status) AND (last_verified_at IS NOT NULL) AND (sanitized_error_code IS NULL)) OR ((status = 'error'::app.dataset_connection_status) AND (sanitized_error_code IS NOT NULL)) OR (status = ANY (ARRAY['draft'::app.dataset_connection_status, 'unverified'::app.dataset_connection_status, 'disabled'::app.dataset_connection_status]))))
);

ALTER TABLE ONLY app.user_dataset_connections FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE user_dataset_connections; Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON TABLE app.user_dataset_connections IS 'Reusable user-owned dataset connection metadata. Credential values live only in Secrets Manager.';


