    withdrawn_by uuid,
    withdrawn_at timestamp with time zone,
    CONSTRAINT wms_layer_publications_name_bounded CHECK (((char_length(wms_name) >= 1) AND (char_length(wms_name) <= 127) AND (wms_name ~ '^[A-Za-z][A-Za-z0-9._-]{0,62}(:[A-Za-z][A-Za-z0-9._-]{0,62})?$'::text))),
    CONSTRAINT wms_layer_publications_withdrawal_shape CHECK ((((withdrawn_by IS NULL) AND (withdrawn_at IS NULL)) OR ((withdrawn_by IS NOT NULL) AND (withdrawn_at IS NOT NULL) AND (withdrawn_at >= created_at))))
);

