--
-- Name: data_objects data_objects_tenant_isolation; Type: POLICY; Schema: app; Owner: -
--

CREATE POLICY data_objects_tenant_isolation ON app.data_objects USING (((organization_id = app.current_organization_id()) AND (NOT (EXISTS ( SELECT 1
   FROM app.spatial_coverage_derivative_reclamations reclamation
  WHERE ((reclamation.organization_id = data_objects.organization_id) AND (reclamation.output_object_id = data_objects.id) AND (reclamation.state = ANY (ARRAY['queued'::app.processing_job_state, 'running'::app.processing_job_state, 'completed'::app.processing_job_state])))))) AND (NOT (EXISTS ( SELECT 1
   FROM app.spatial_tile_cache_reclamation_items item
  WHERE ((item.organization_id = data_objects.organization_id) AND (item.output_object_id = data_objects.id) AND (item.state = ANY (ARRAY['queued'::app.processing_job_state, 'running'::app.processing_job_state, 'completed'::app.processing_job_state])))))))) WITH CHECK ((organization_id = app.current_organization_id()));


