CREATE POLICY user_basemap_connections_select ON app.user_basemap_connections FOR SELECT USING (((organization_id = app.current_organization_id()) AND ((owner_user_id = app.current_user_id()) OR app.current_user_is_organization_admin() OR (EXISTS ( SELECT 1
   FROM app.project_basemap_connection_bindings binding
  WHERE ((binding.organization_id = user_basemap_connections.organization_id) AND (binding.connection_id = user_basemap_connections.id) AND (app.effective_project_role(binding.project_id) IS NOT NULL)))))));


